const HSK4B_DATA = {"lessons":[{"id":11,"title_cn":"活到老学到老","title_pinyin":"","title_vn":"Sống đến già, học đến già","goals":["Có thể nghe hiểu và trao đổi về các chủ đề như giáo dục suốt đời, dạy học trực tuyến, học qua mạng.","Có thể trình bày bằng lời hoặc văn bản về ý nghĩa của giáo dục suốt đời và học tập qua mạng.","Hiểu được quan niệm giáo dục của người Trung Quốc."],"vocab":[{"hanzi":"老年","pinyin":"lǎonián","pos":"dt.","vn":"tuổi già, người cao tuổi","examples":[{"cn":"小区里有不少老年人每天早上散步。","pinyin":"Xiǎoqū lǐ yǒu bùshǎo lǎonián rén měitiān zǎoshang sànbù.","vn":"Trong khu dân cư có khá nhiều người cao tuổi đi dạo mỗi sáng."},{"cn":"我奶奶已经进入老年了，但身体还很好。","pinyin":"Wǒ nǎinai yǐjīng jìnrù lǎonián le, dàn shēntǐ hái hěn hǎo.","vn":"Bà tôi đã bước vào tuổi già nhưng sức khỏe vẫn rất tốt."},{"cn":"老年生活应该过得丰富一些。","pinyin":"Lǎonián shēnghuó yīnggāi guò de fēngfù yìxiē.","vn":"Cuộc sống tuổi già nên sống cho phong phú một chút."}]},{"hanzi":"散步","pinyin":"sànbù","pos":"dgt.","vn":"đi dạo, tản bộ","examples":[{"cn":"吃完晚饭，我们去公园散步吧。","pinyin":"Chīwán wǎnfàn, wǒmen qù gōngyuán sànbù ba.","vn":"Ăn tối xong chúng ta đi dạo công viên nhé."},{"cn":"他每天都要在小区里散散步。","pinyin":"Tā měitiān dōu yào zài xiǎoqū lǐ sànsan bù.","vn":"Anh ấy ngày nào cũng đi tản bộ trong khu dân cư."},{"cn":"散步是一种很简单的运动方式。","pinyin":"Sànbù shì yì zhǒng hěn jiǎndān de yùndòng fāngshì.","vn":"Đi dạo là một hình thức vận động rất đơn giản."}]},{"hanzi":"丰富","pinyin":"fēngfù","pos":"tt.","vn":"phong phú","examples":[{"cn":"退休以后，他的生活变得更加丰富了。","pinyin":"Tuìxiū yǐhòu, tā de shēnghuó biàn de gèngjiā fēngfù le.","vn":"Sau khi nghỉ hưu, cuộc sống của ông ấy trở nên phong phú hơn."},{"cn":"这本书的内容很丰富。","pinyin":"Zhè běn shū de nèiróng hěn fēngfù.","vn":"Nội dung cuốn sách này rất phong phú."},{"cn":"学校组织了丰富多彩的活动。","pinyin":"Xuéxiào zǔzhī le fēngfù duōcǎi de huódòng.","vn":"Nhà trường đã tổ chức các hoạt động phong phú, đa dạng."}]},{"hanzi":"羡慕","pinyin":"xiànmù","pos":"dgt.","vn":"ngưỡng mộ","examples":[{"cn":"大家都很羡慕他的生活。","pinyin":"Dàjiā dōu hěn xiànmù tā de shēnghuó.","vn":"Mọi người đều rất ngưỡng mộ cuộc sống của anh ấy."},{"cn":"我羡慕你会说这么多种语言。","pinyin":"Wǒ xiànmù nǐ huì shuō zhème duō zhǒng yǔyán.","vn":"Tôi ngưỡng mộ vì bạn biết nói nhiều ngôn ngữ như vậy."},{"cn":"她的工作让很多人羡慕。","pinyin":"Tā de gōngzuò ràng hěn duō rén xiànmù.","vn":"Công việc của cô ấy khiến nhiều người ngưỡng mộ."}]},{"hanzi":"即使","pinyin":"jíshǐ","pos":"liên.","vn":"dù, cho dù, ngay cả khi","examples":[{"cn":"即使下雨，我们也要出发。","pinyin":"Jíshǐ xiàyǔ, wǒmen yě yào chūfā.","vn":"Dù trời mưa, chúng tôi cũng phải xuất phát."},{"cn":"即使再忙，他也坚持锻炼身体。","pinyin":"Jíshǐ zài máng, tā yě jiānchí duànliàn shēntǐ.","vn":"Dù bận đến đâu, anh ấy vẫn kiên trì tập thể dục."},{"cn":"即使没人帮忙，我也能完成。","pinyin":"Jíshǐ méi rén bāngmáng, wǒ yě néng wánchéng.","vn":"Dù không có ai giúp, tôi cũng có thể hoàn thành."}]},{"hanzi":"活","pinyin":"huó","pos":"dgt./tt.","vn":"sống; sôi nổi, linh hoạt","examples":[{"cn":"他活到了九十多岁。","pinyin":"Tā huódào le jiǔshí duō suì.","vn":"Ông ấy đã sống đến hơn chín mươi tuổi."},{"cn":"这孩子性格很活，大家都喜欢他。","pinyin":"Zhè háizi xìnggé hěn huó, dàjiā dōu xǐhuan tā.","vn":"Đứa trẻ này tính cách rất hoạt bát, mọi người đều thích nó."},{"cn":"人要活到老学到老。","pinyin":"Rén yào huódào lǎo xuédào lǎo.","vn":"Con người phải sống đến già, học đến già."}]},{"hanzi":"继续","pinyin":"jìxù","pos":"dgt.","vn":"tiếp tục","examples":[{"cn":"休息一下，我们继续工作吧。","pinyin":"Xiūxi yíxià, wǒmen jìxù gōngzuò ba.","vn":"Nghỉ một chút rồi chúng ta tiếp tục làm việc nhé."},{"cn":"他毕业以后继续读研究生。","pinyin":"Tā bìyè yǐhòu jìxù dú yánjiūshēng.","vn":"Sau khi tốt nghiệp anh ấy tiếp tục học lên thạc sĩ."},{"cn":"老年人也要继续学习新知识。","pinyin":"Lǎonián rén yě yào jìxù xuéxí xīn zhīshi.","vn":"Người cao tuổi cũng cần tiếp tục học kiến thức mới."}]},{"hanzi":"网友","pinyin":"wǎngyǒu","pos":"dt.","vn":"bạn qua mạng, bạn online","examples":[{"cn":"他和一位网友约好周末见面。","pinyin":"Tā hé yí wèi wǎngyǒu yuēhǎo zhōumò jiànmiàn.","vn":"Anh ấy hẹn với một người bạn qua mạng gặp mặt vào cuối tuần."},{"cn":"我爷爷也有几个聊得来的网友。","pinyin":"Wǒ yéye yě yǒu jǐ ge liáo de lái de wǎngyǒu.","vn":"Ông tôi cũng có vài người bạn qua mạng hợp chuyện."},{"cn":"网友们都在讨论这件事。","pinyin":"Wǎngyǒumen dōu zài tǎolùn zhè jiàn shì.","vn":"Các bạn mạng đều đang bàn luận về việc này."}]},{"hanzi":"无聊","pinyin":"wúliáo","pos":"tt.","vn":"buồn chán, nhàm chán","examples":[{"cn":"一个人在家太无聊了。","pinyin":"Yí ge rén zài jiā tài wúliáo le.","vn":"Ở nhà một mình thật buồn chán."},{"cn":"他觉得这部电影有点儿无聊。","pinyin":"Tā juéde zhè bù diànyǐng yǒudiǎnr wúliáo.","vn":"Anh ấy thấy bộ phim này hơi nhàm chán."},{"cn":"退休后生活一点儿都不无聊。","pinyin":"Tuìxiū hòu shēnghuó yìdiǎnr dōu bù wúliáo.","vn":"Sau khi nghỉ hưu cuộc sống chẳng hề nhàm chán chút nào."}]},{"hanzi":"数字","pinyin":"shùzì","pos":"dt./tt.","vn":"con số; kỹ thuật số","examples":[{"cn":"请把这些数字加起来。","pinyin":"Qǐng bǎ zhèxiē shùzì jiā qǐlai.","vn":"Hãy cộng những con số này lại."},{"cn":"现在很多学校都有数字教室。","pinyin":"Xiànzài hěn duō xuéxiào dōu yǒu shùzì jiàoshì.","vn":"Hiện nay nhiều trường học đều có phòng học kỹ thuật số."},{"cn":"数字技术正在改变我们的生活。","pinyin":"Shùzì jìshù zhèngzài gǎibiàn wǒmen de shēnghuó.","vn":"Công nghệ kỹ thuật số đang thay đổi cuộc sống của chúng ta."}]},{"hanzi":"点名","pinyin":"diǎnmíng","pos":"dgt.","vn":"điểm danh","examples":[{"cn":"上课前老师先点名。","pinyin":"Shàngkè qián lǎoshī xiān diǎnmíng.","vn":"Trước khi vào học giáo viên điểm danh trước."},{"cn":"今天的会议没有点名。","pinyin":"Jīntiān de huìyì méiyǒu diǎnmíng.","vn":"Cuộc họp hôm nay không điểm danh."},{"cn":"教授在线上给学生点名。","pinyin":"Jiàoshòu zài xiànshàng gěi xuésheng diǎnmíng.","vn":"Giáo sư điểm danh sinh viên trực tuyến."}]},{"hanzi":"教授","pinyin":"jiàoshòu","pos":"dt.","vn":"giáo sư","examples":[{"cn":"这位教授讲课讲得很好。","pinyin":"Zhè wèi jiàoshòu jiǎngkè jiǎng de hěn hǎo.","vn":"Vị giáo sư này giảng bài rất hay."},{"cn":"我想请教授帮我看看论文。","pinyin":"Wǒ xiǎng qǐng jiàoshòu bāng wǒ kànkan lùnwén.","vn":"Tôi muốn nhờ giáo sư xem giúp luận văn."},{"cn":"他是我们学校最年轻的教授。","pinyin":"Tā shì wǒmen xuéxiào zuì niánqīng de jiàoshòu.","vn":"Ông ấy là giáo sư trẻ nhất trường chúng tôi."}]},{"hanzi":"线上","pinyin":"xiànshàng","pos":"dt.","vn":"trực tuyến, online","examples":[{"cn":"这学期我们都是线上上课。","pinyin":"Zhè xuéqī wǒmen dōu shì xiànshàng shàngkè.","vn":"Học kỳ này chúng tôi đều học trực tuyến."},{"cn":"你可以线上预约挂号。","pinyin":"Nǐ kěyǐ xiànshàng yùyuē guàhào.","vn":"Bạn có thể đặt lịch khám trực tuyến."},{"cn":"线上购物越来越方便了。","pinyin":"Xiànshàng gòuwù yuè lái yuè fāngbiàn le.","vn":"Mua sắm trực tuyến ngày càng tiện lợi hơn."}]},{"hanzi":"线下","pinyin":"xiànxià","pos":"dt.","vn":"ngoại tuyến, offline","examples":[{"cn":"我们下周线下见面聊聊吧。","pinyin":"Wǒmen xià zhōu xiànxià jiànmiàn liáoliao ba.","vn":"Tuần sau chúng ta gặp mặt trực tiếp nói chuyện nhé."},{"cn":"这家店只能线下购买。","pinyin":"Zhè jiā diàn zhǐ néng xiànxià gòumǎi.","vn":"Cửa hàng này chỉ có thể mua trực tiếp."},{"cn":"线下活动比线上更有气氛。","pinyin":"Xiànxià huódòng bǐ xiànshàng gèng yǒu qìfēn.","vn":"Hoạt động trực tiếp có không khí hơn trực tuyến."}]},{"hanzi":"视频","pinyin":"shìpín","pos":"dt.","vn":"video","examples":[{"cn":"老师把上课视频发到了群里。","pinyin":"Lǎoshī bǎ shàngkè shìpín fādào le qún lǐ.","vn":"Giáo viên đã gửi video buổi học vào nhóm."},{"cn":"我喜欢看做饭的视频。","pinyin":"Wǒ xǐhuan kàn zuòfàn de shìpín.","vn":"Tôi thích xem video nấu ăn."},{"cn":"这个视频点赞的人很多。","pinyin":"Zhège shìpín diǎnzàn de rén hěn duō.","vn":"Video này có rất nhiều người thích."}]},{"hanzi":"记录","pinyin":"jìlù","pos":"dt.","vn":"ghi chép, bản ghi","examples":[{"cn":"课后还能在网上找到视频记录。","pinyin":"Kèhòu hái néng zài wǎng shàng zhǎodào shìpín jìlù.","vn":"Sau giờ học vẫn có thể tìm thấy bản ghi video trên mạng."},{"cn":"医生看了一下我的健康记录。","pinyin":"Yīshēng kàn le yíxià wǒ de jiànkāng jìlù.","vn":"Bác sĩ đã xem qua hồ sơ sức khỏe của tôi."},{"cn":"他每天都写学习记录。","pinyin":"Tā měitiān dōu xiě xuéxí jìlù.","vn":"Anh ấy ngày nào cũng viết nhật ký học tập."}]},{"hanzi":"资料","pinyin":"zīliào","pos":"dt.","vn":"tài liệu","examples":[{"cn":"网上到处是学习资料。","pinyin":"Wǎng shàng dàochù shì xuéxí zīliào.","vn":"Trên mạng khắp nơi đều là tài liệu học tập."},{"cn":"写论文前要先查资料。","pinyin":"Xiě lùnwén qián yào xiān chá zīliào.","vn":"Trước khi viết luận văn phải tra tài liệu trước."},{"cn":"这些资料对我很有帮助。","pinyin":"Zhèxiē zīliào duì wǒ hěn yǒu bāngzhù.","vn":"Những tài liệu này rất hữu ích với tôi."}]},{"hanzi":"自学","pinyin":"zìxué","pos":"dgt.","vn":"tự học","examples":[{"cn":"他是靠自学学会弹钢琴的。","pinyin":"Tā shì kào zìxué xuéhuì tán gāngqín de.","vn":"Anh ấy tự học mà biết chơi đàn piano."},{"cn":"现在自学中文也更方便了。","pinyin":"Xiànzài zìxué Zhōngwén yě gèng fāngbiàn le.","vn":"Bây giờ tự học tiếng Trung cũng tiện hơn rồi."},{"cn":"她每天晚上都自学一小时英语。","pinyin":"Tā měitiān wǎnshang dōu zìxué yì xiǎoshí Yīngyǔ.","vn":"Tối nào cô ấy cũng tự học tiếng Anh một tiếng."}]},{"hanzi":"口语","pinyin":"kǒuyǔ","pos":"dt.","vn":"khẩu ngữ, kỹ năng nói","examples":[{"cn":"我想找人练习口语。","pinyin":"Wǒ xiǎng zhǎo rén liànxí kǒuyǔ.","vn":"Tôi muốn tìm người luyện kỹ năng nói."},{"cn":"他的口语说得非常流利。","pinyin":"Tā de kǒuyǔ shuō de fēicháng liúlì.","vn":"Khẩu ngữ của anh ấy nói rất trôi chảy."},{"cn":"学口语最好的办法就是多说。","pinyin":"Xué kǒuyǔ zuì hǎo de bànfǎ jiùshì duō shuō.","vn":"Cách học khẩu ngữ tốt nhất chính là nói nhiều."}]},{"hanzi":"科技","pinyin":"kējì","pos":"dt.","vn":"khoa học công nghệ","examples":[{"cn":"科技让获取知识变得更简单了。","pinyin":"Kējì ràng huòqǔ zhīshi biàn de gèng jiǎndān le.","vn":"Khoa học công nghệ khiến việc thu nhận kiến thức trở nên đơn giản hơn."},{"cn":"这是一家科技公司。","pinyin":"Zhè shì yì jiā kējì gōngsī.","vn":"Đây là một công ty công nghệ."},{"cn":"科技发展得非常快。","pinyin":"Kējì fāzhǎn de fēicháng kuài.","vn":"Khoa học công nghệ phát triển rất nhanh."}]},{"hanzi":"获取","pinyin":"huòqǔ","pos":"dgt.","vn":"đạt được, có được","examples":[{"cn":"我们可以通过网络获取各种知识。","pinyin":"Wǒmen kěyǐ tōngguò wǎngluò huòqǔ gèzhǒng zhīshi.","vn":"Chúng ta có thể thu nhận đủ loại kiến thức qua mạng."},{"cn":"他获取了很多宝贵的经验。","pinyin":"Tā huòqǔ le hěn duō bǎoguì de jīngyàn.","vn":"Anh ấy đã có được rất nhiều kinh nghiệm quý báu."},{"cn":"这样做可以获取更多信息。","pinyin":"Zhèyàng zuò kěyǐ huòqǔ gèng duō xìnxī.","vn":"Làm như vậy có thể thu được nhiều thông tin hơn."}]},{"hanzi":"礼貌","pinyin":"lǐmào","pos":"dt./tt.","vn":"lễ phép, lịch sự","examples":[{"cn":"这个孩子对人很有礼貌。","pinyin":"Zhège háizi duì rén hěn yǒu lǐmào.","vn":"Đứa trẻ này đối với người khác rất lễ phép."},{"cn":"见面打招呼是一种礼貌。","pinyin":"Jiànmiàn dǎ zhāohu shì yì zhǒng lǐmào.","vn":"Chào hỏi khi gặp mặt là một phép lịch sự."},{"cn":"他说话很礼貌。","pinyin":"Tā shuōhuà hěn lǐmào.","vn":"Anh ấy nói chuyện rất lịch sự."}]},{"hanzi":"打招呼","pinyin":"dǎ zhāohu","pos":"dgt.","vn":"chào hỏi","examples":[{"cn":"看到老师要主动打招呼。","pinyin":"Kàndào lǎoshī yào zhǔdòng dǎ zhāohu.","vn":"Nhìn thấy giáo viên phải chủ động chào hỏi."},{"cn":"他朝我笑了笑，打了个招呼。","pinyin":"Tā cháo wǒ xiào le xiào, dǎ le ge zhāohu.","vn":"Anh ấy cười với tôi một cái, chào hỏi một tiếng."},{"cn":"孩子们一进门就和我们打招呼。","pinyin":"Háizimen yí jìnmén jiù hé wǒmen dǎ zhāohu.","vn":"Bọn trẻ vừa vào cửa đã chào hỏi chúng tôi."}]},{"hanzi":"家长","pinyin":"jiāzhǎng","pos":"dt.","vn":"phụ huynh","examples":[{"cn":"明天下午要开家长会。","pinyin":"Míngtiān xiàwǔ yào kāi jiāzhǎng huì.","vn":"Chiều mai sẽ họp phụ huynh."},{"cn":"很多家长都很关心孩子的分数。","pinyin":"Hěn duō jiāzhǎng dōu hěn guānxīn háizi de fēnshù.","vn":"Nhiều phụ huynh đều rất quan tâm đến điểm số của con cái."},{"cn":"老师经常和家长沟通。","pinyin":"Lǎoshī jīngcháng hé jiāzhǎng gōutōng.","vn":"Giáo viên thường xuyên trao đổi với phụ huynh."}]},{"hanzi":"成功","pinyin":"chénggōng","pos":"tt./dgt.","vn":"thành công","examples":[{"cn":"他终于成功了。","pinyin":"Tā zhōngyú chénggōng le.","vn":"Cuối cùng anh ấy đã thành công."},{"cn":"成功需要不断努力。","pinyin":"Chénggōng xūyào búduàn nǔlì.","vn":"Thành công cần phải không ngừng nỗ lực."},{"cn":"这次活动办得很成功。","pinyin":"Zhè cì huódòng bàn de hěn chénggōng.","vn":"Hoạt động lần này tổ chức rất thành công."}]},{"hanzi":"分数","pinyin":"fēnshù","pos":"dt.","vn":"điểm số","examples":[{"cn":"这次考试他的分数很高。","pinyin":"Zhè cì kǎoshì tā de fēnshù hěn gāo.","vn":"Kỳ thi lần này điểm số của cậu ấy rất cao."},{"cn":"家长不应该只关心孩子的分数。","pinyin":"Jiāzhǎng bù yīnggāi zhǐ guānxīn háizi de fēnshù.","vn":"Phụ huynh không nên chỉ quan tâm điểm số của con."},{"cn":"分数不能代表一切。","pinyin":"Fēnshù bù néng dàibiǎo yíqiè.","vn":"Điểm số không thể đại diện cho tất cả."}]},{"hanzi":"目的","pinyin":"mùdì","pos":"dt.","vn":"mục đích","examples":[{"cn":"教育的目的是帮助孩子养成好习惯。","pinyin":"Jiàoyù de mùdì shì bāngzhù háizi yǎngchéng hǎo xíguàn.","vn":"Mục đích của giáo dục là giúp trẻ hình thành thói quen tốt."},{"cn":"他学习中文的目的是去中国工作。","pinyin":"Tā xuéxí Zhōngwén de mùdì shì qù Zhōngguó gōngzuò.","vn":"Mục đích anh ấy học tiếng Trung là để sang Trung Quốc làm việc."},{"cn":"我们这次会议的目的很明确。","pinyin":"Wǒmen zhè cì huìyì de mùdì hěn míngquè.","vn":"Mục đích cuộc họp lần này của chúng ta rất rõ ràng."}]},{"hanzi":"养成","pinyin":"yǎngchéng","pos":"dgt.","vn":"hình thành, rèn luyện (thói quen)","examples":[{"cn":"从小就要养成好习惯。","pinyin":"Cóngxiǎo jiù yào yǎngchéng hǎo xíguàn.","vn":"Phải hình thành thói quen tốt từ nhỏ."},{"cn":"他养成了每天运动的习惯。","pinyin":"Tā yǎngchéng le měitiān yùndòng de xíguàn.","vn":"Anh ấy đã rèn được thói quen vận động mỗi ngày."},{"cn":"养成好习惯不是一天就能做到的。","pinyin":"Yǎngchéng hǎo xíguàn búshì yì tiān jiù néng zuòdào de.","vn":"Hình thành thói quen tốt không phải một ngày là làm được."}]},{"hanzi":"留","pinyin":"liú","pos":"dgt.","vn":"dành ra, giữ lại, ở lại","examples":[{"cn":"每天给孩子留出时间运动。","pinyin":"Měitiān gěi háizi liúchū shíjiān yùndòng.","vn":"Mỗi ngày dành ra thời gian cho con vận động."},{"cn":"他毕业以后留在了北京工作。","pinyin":"Tā bìyè yǐhòu liúzài le Běijīng gōngzuò.","vn":"Sau khi tốt nghiệp anh ấy ở lại Bắc Kinh làm việc."},{"cn":"老师给我们留了一些作业。","pinyin":"Lǎoshī gěi wǒmen liú le yìxiē zuòyè.","vn":"Giáo viên giao cho chúng tôi một ít bài tập."}]},{"hanzi":"做法","pinyin":"zuòfǎ","pos":"dt.","vn":"cách làm","examples":[{"cn":"我觉得他们的做法真棒。","pinyin":"Wǒ juéde tāmen de zuòfǎ zhēn bàng.","vn":"Tôi thấy cách làm của họ thật tuyệt."},{"cn":"这种做法值得大家学习。","pinyin":"Zhè zhǒng zuòfǎ zhíde dàjiā xuéxí.","vn":"Cách làm này đáng để mọi người học hỏi."},{"cn":"你对这个做法有什么看法？","pinyin":"Nǐ duì zhège zuòfǎ yǒu shénme kànfǎ?","vn":"Bạn có ý kiến gì về cách làm này?"}]},{"hanzi":"棒","pinyin":"bàng","pos":"tt.","vn":"tuyệt vời, giỏi","examples":[{"cn":"你弹钢琴弹得真棒！","pinyin":"Nǐ tán gāngqín tán de zhēn bàng!","vn":"Bạn chơi piano thật tuyệt!"},{"cn":"这个主意太棒了。","pinyin":"Zhège zhǔyi tài bàng le.","vn":"Ý tưởng này quá tuyệt."},{"cn":"他的口语说得很棒。","pinyin":"Tā de kǒuyǔ shuō de hěn bàng.","vn":"Anh ấy nói khẩu ngữ rất giỏi."}]},{"hanzi":"一生","pinyin":"yìshēng","pos":"dt.","vn":"cả đời, cả cuộc đời","examples":[{"cn":"学习是人一生的事情。","pinyin":"Xuéxí shì rén yìshēng de shìqing.","vn":"Học tập là việc của cả đời người."},{"cn":"他一生都在研究历史。","pinyin":"Tā yìshēng dōu zài yánjiū lìshǐ.","vn":"Cả đời ông ấy đều nghiên cứu lịch sử."},{"cn":"这是我一生难忘的经历。","pinyin":"Zhè shì wǒ yìshēng nánwàng de jīnglì.","vn":"Đây là trải nghiệm cả đời tôi khó quên."}]},{"hanzi":"快速","pinyin":"kuàisù","pos":"tt.","vn":"nhanh chóng","examples":[{"cn":"世界正在快速变化。","pinyin":"Shìjiè zhèngzài kuàisù biànhuà.","vn":"Thế giới đang thay đổi nhanh chóng."},{"cn":"科技快速发展，给生活带来很多方便。","pinyin":"Kējì kuàisù fāzhǎn, gěi shēnghuó dàilái hěn duō fāngbiàn.","vn":"Khoa học công nghệ phát triển nhanh chóng, mang lại nhiều tiện ích cho cuộc sống."},{"cn":"他快速地读完了这篇文章。","pinyin":"Tā kuàisù de dú wán le zhè piān wénzhāng.","vn":"Anh ấy nhanh chóng đọc xong bài viết này."}]},{"hanzi":"优秀","pinyin":"yōuxiù","pos":"tt.","vn":"ưu tú, xuất sắc","examples":[{"cn":"他是一位很优秀的律师。","pinyin":"Tā shì yí wèi hěn yōuxiù de lǜshī.","vn":"Anh ấy là một luật sư rất ưu tú."},{"cn":"这个班的学生都很优秀。","pinyin":"Zhège bān de xuésheng dōu hěn yōuxiù.","vn":"Học sinh lớp này đều rất xuất sắc."},{"cn":"她获得了优秀员工的称号。","pinyin":"Tā huòdé le yōuxiù yuángōng de chēnghào.","vn":"Cô ấy đã nhận được danh hiệu nhân viên xuất sắc."}]},{"hanzi":"律师","pinyin":"lǜshī","pos":"dt.","vn":"luật sư","examples":[{"cn":"他想当一名律师。","pinyin":"Tā xiǎng dāng yì míng lǜshī.","vn":"Anh ấy muốn trở thành một luật sư."},{"cn":"这位律师一直在学习新的法律知识。","pinyin":"Zhè wèi lǜshī yìzhí zài xuéxí xīn de fǎlǜ zhīshi.","vn":"Vị luật sư này luôn học hỏi kiến thức pháp luật mới."},{"cn":"遇到这种问题最好问问律师。","pinyin":"Yùdào zhè zhǒng wèntí zuìhǎo wènwen lǜshī.","vn":"Gặp vấn đề kiểu này tốt nhất nên hỏi luật sư."}]},{"hanzi":"仍","pinyin":"réng","pos":"phó.","vn":"vẫn","examples":[{"cn":"虽然很累，他仍坚持工作。","pinyin":"Suīrán hěn lèi, tā réng jiānchí gōngzuò.","vn":"Dù rất mệt, anh ấy vẫn kiên trì làm việc."},{"cn":"他仍住在以前那个小区。","pinyin":"Tā réng zhù zài yǐqián nàge xiǎoqū.","vn":"Anh ấy vẫn sống ở khu dân cư trước kia."},{"cn":"坚持学习仍很重要。","pinyin":"Jiānchí xuéxí réng hěn zhòngyào.","vn":"Kiên trì học tập vẫn rất quan trọng."}]},{"hanzi":"准时","pinyin":"zhǔnshí","pos":"tt.","vn":"đúng giờ","examples":[{"cn":"他每天都准时去上课。","pinyin":"Tā měitiān dōu zhǔnshí qù shàngkè.","vn":"Ngày nào anh ấy cũng đi học đúng giờ."},{"cn":"会议九点准时开始。","pinyin":"Huìyì jiǔ diǎn zhǔnshí kāishǐ.","vn":"Cuộc họp bắt đầu đúng giờ lúc 9 giờ."},{"cn":"爷爷每天准时去老年大学上课。","pinyin":"Yéye měitiān zhǔnshí qù lǎonián dàxué shàngkè.","vn":"Ông tôi ngày nào cũng đi học đúng giờ ở trường đại học dành cho người cao tuổi."}]},{"hanzi":"网页","pinyin":"wǎngyè","pos":"dt.","vn":"trang web","examples":[{"cn":"他正在学习做网页。","pinyin":"Tā zhèngzài xuéxí zuò wǎngyè.","vn":"Ông ấy đang học làm trang web."},{"cn":"这个网页打不开了。","pinyin":"Zhège wǎngyè dǎ bù kāi le.","vn":"Trang web này không mở được nữa."},{"cn":"你可以在这个网页上查到资料。","pinyin":"Nǐ kěyǐ zài zhège wǎngyè shang chádào zīliào.","vn":"Bạn có thể tra tài liệu trên trang web này."}]},{"hanzi":"弹","pinyin":"tán","pos":"dgt.","vn":"chơi, đánh (đàn)","examples":[{"cn":"她从小就学弹钢琴。","pinyin":"Tā cóngxiǎo jiù xué tán gāngqín.","vn":"Cô ấy học chơi piano từ nhỏ."},{"cn":"爷爷喜欢弹钢琴。","pinyin":"Yéye xǐhuan tán gāngqín.","vn":"Ông thích chơi đàn piano."},{"cn":"他弹了一首很好听的曲子。","pinyin":"Tā tán le yì shǒu hěn hǎotīng de qǔzi.","vn":"Anh ấy đã đánh một bản nhạc rất hay."}]},{"hanzi":"钢琴","pinyin":"gāngqín","pos":"dt.","vn":"đàn piano","examples":[{"cn":"这是一架很贵的钢琴。","pinyin":"Zhè shì yí jià hěn guì de gāngqín.","vn":"Đây là một cây đàn piano rất đắt."},{"cn":"她每天练习一个小时钢琴。","pinyin":"Tā měitiān liànxí yí ge xiǎoshí gāngqín.","vn":"Mỗi ngày cô ấy luyện piano một tiếng."},{"cn":"爷爷重新学起了钢琴。","pinyin":"Yéye chóngxīn xué qǐ le gāngqín.","vn":"Ông lại bắt đầu học đàn piano."}]},{"hanzi":"重新","pinyin":"chóngxīn","pos":"phó.","vn":"lại, một lần nữa","examples":[{"cn":"这个计划需要重新安排。","pinyin":"Zhège jìhuà xūyào chóngxīn ānpái.","vn":"Kế hoạch này cần sắp xếp lại."},{"cn":"他重新当了一回学生。","pinyin":"Tā chóngxīn dāng le yì huí xuésheng.","vn":"Ông ấy lại một lần nữa trở thành học sinh."},{"cn":"如果不对，就重新做一遍。","pinyin":"Rúguǒ bú duì, jiù chóngxīn zuò yí biàn.","vn":"Nếu không đúng thì làm lại một lần nữa."}]}],"proper_nouns":[{"hanzi":"太极拳","pinyin":"Tàijíquán","vn":"Thái Cực Quyền"},{"hanzi":"孔子","pinyin":"Kǒngzǐ","vn":"Khổng Tử"}],"grammar":[{"title":"让步复句 \"即使……，也……\"","explanation_vn":"Câu phức nhượng bộ \"即使……，也……\" (ngay cả khi... thì cũng...): vế trước đưa ra một giả thiết, thường là tình huống bất lợi hoặc cực đoan, vế sau cho biết kết quả vẫn không thay đổi hay không bị ảnh hưởng.","examples":[{"cn":"有些人即使年龄大了，也坚持去老年班学习。","pinyin":"","vn":"Có những người dù tuổi đã cao vẫn kiên trì đi học lớp dành cho người cao tuổi."},{"cn":"即使明天下大雨，我们也会按时出发。","pinyin":"","vn":"Dù ngày mai mưa to, chúng tôi vẫn sẽ xuất phát đúng giờ."},{"cn":"即使大家都说很难，我也要试一试。","pinyin":"","vn":"Dù mọi người đều nói là khó, tôi cũng muốn thử xem sao."}]},{"title":"让步复句 \"就是……，也……\"","explanation_vn":"Câu phức nhượng bộ \"就是……，也……\", trong đó \"就是\" là liên từ, thường dùng trong khẩu ngữ. Vế trước đưa ra một giả thiết hoặc điều kiện nhượng bộ cực đoan, vế sau cho biết trong điều kiện đó kết quả vẫn không đổi, hoặc vẫn giữ một thái độ, hành động nào đó.","examples":[{"cn":"我就是不在教室，也可以学习中文，和同学一起练口语。","pinyin":"","vn":"Tôi dù không ở trong lớp, cũng có thể học tiếng Trung, cùng bạn học luyện khẩu ngữ."},{"cn":"锻炼身体很重要，就是再忙，也要坚持运动。","pinyin":"","vn":"Rèn luyện sức khỏe rất quan trọng, dù có bận đến đâu cũng phải kiên trì vận động."},{"cn":"明天开会需要这份材料，我就是今晚不睡觉，也要把它改完。","pinyin":"","vn":"Ngày mai họp cần tài liệu này, dù tối nay không ngủ tôi cũng phải sửa xong nó."}]},{"title":"并列复句 \"不是……，而是……\"","explanation_vn":"Câu phức song song \"不是……，而是……\" phủ định vế trước, khẳng định vế sau, nhấn mạnh sự khác biệt hoặc đối lập giữa hai vế.","examples":[{"cn":"教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","pinyin":"","vn":"Mục đích của giáo dục không phải là để trẻ đạt điểm cao, mà là giúp trẻ hình thành thói quen tốt."},{"cn":"我不是想喝茶，而是想喝水。","pinyin":"","vn":"Tôi không phải muốn uống trà, mà là muốn uống nước."},{"cn":"我放学后不是直接回家，而是先去超市买笔。","pinyin":"","vn":"Tan học tôi không về nhà ngay, mà đi siêu thị mua bút trước."}]},{"title":"固定短语 \"就是说\"","explanation_vn":"Cụm cố định \"就是说\" dùng để giải thích thêm hoặc nói theo một cách khác cho nội dung phía trước.","examples":[{"cn":"人要一直坚持学习，就是说，学习是人一生的事情，要活到老学到老。","pinyin":"","vn":"Con người phải luôn kiên trì học tập, tức là, học tập là việc của cả đời người, phải sống đến già học đến già."},{"cn":"别着急写，就是说，别着急动笔，想好后再写。","pinyin":"","vn":"Đừng vội viết, tức là, đừng vội cầm bút, nghĩ kỹ rồi hãy viết."},{"cn":"这份工作的工资是根据你工作的完成情况来发的，就是说，你完成得越多，工资越高。","pinyin":"","vn":"Lương của công việc này được trả theo tình hình hoàn thành công việc của bạn, tức là, bạn hoàn thành càng nhiều thì lương càng cao."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"这里的老年人真不少。","pinyin":""},{"speaker":"李文","cn":"嗯，住在附近的老年人都会来这儿，有的散步，有的唱歌、跳舞，还有的打太极拳。","pinyin":""},{"speaker":"白家月","cn":"他们的生活真丰富，让人羡慕。","pinyin":""},{"speaker":"李文","cn":"是的。有些人即使年龄大了，也坚持去老年班学习。","pinyin":""},{"speaker":"白家月","cn":"真是活到老学到老啊。","pinyin":""},{"speaker":"李文","cn":"对，我爷爷就每周都去老年班学电脑。他总说，老年人也要继续学习，\"你看，我都七八十岁了，还上网和网友们聊天儿呢，生活一点儿都不无聊。\"","pinyin":""}],"translation_vn":"Bạch Gia Nguyệt: Người già ở đây thật là nhiều nhỉ.\nLý Văn: Ừ, người già sống gần đây đều hay ra đây, có người đi dạo, có người hát, nhảy múa, còn có người đánh Thái Cực Quyền nữa.\nBạch Gia Nguyệt: Cuộc sống của họ thật phong phú, khiến người ta ngưỡng mộ.\nLý Văn: Đúng vậy. Có những người dù tuổi đã cao vẫn kiên trì đi học lớp dành cho người cao tuổi.\nBạch Gia Nguyệt: Đúng là sống đến già, học đến già mà.\nLý Văn: Đúng vậy, ông mình thì tuần nào cũng đi học lớp người cao tuổi để học máy tính. Ông luôn nói, người già cũng phải tiếp tục học tập, \"Cháu xem, ông đã bảy tám mươi tuổi rồi, vẫn lên mạng trò chuyện với bạn bè trên mạng, cuộc sống chẳng hề nhàm chán chút nào.\"","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"在公园里，老年人都会做些什么活动？","q_vn":"Ở trong công viên, người già thường làm những hoạt động gì?","a_cn":"他们有的散步，有的唱歌、跳舞，还有的打太极拳。","a_vn":"Có người đi dạo, có người hát, nhảy múa, còn có người đánh Thái Cực Quyền."},{"q_cn":"李文的爷爷为什么去老年班学习？","q_vn":"Vì sao ông của Lý Văn đi học lớp người cao tuổi?","a_cn":"因为他认为老年人也要继续学习，所以每周都去老年班学电脑。","a_vn":"Vì ông cho rằng người già cũng phải tiếp tục học tập, nên tuần nào cũng đi học lớp người cao tuổi để học máy tính."},{"q_cn":"白家月听了李文的话后有什么感受？","q_vn":"Sau khi nghe Lý Văn nói, Bạch Gia Nguyệt cảm thấy thế nào?","a_cn":"她觉得真是活到老学到老，对老年人的生活态度感到很佩服。","a_vn":"Cô ấy cảm thấy đúng là sống đến già học đến già, rất khâm phục thái độ sống của người già."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"家月，我们今天的课是在数字教室上的，感觉挺不一样的。","pinyin":""},{"speaker":"白家月","cn":"是的，数字教室可以拍照点名，教授在线上点名，不用像线下那样一个个叫名字，特别节约时间。","pinyin":""},{"speaker":"李文","cn":"最方便的是，课上没听明白时，课后还能在学校网站上找到视频记录看。","pinyin":""},{"speaker":"安妮","cn":"对，上课我都不用着急记笔记了。","pinyin":""},{"speaker":"李文","cn":"不仅数字教室很方便，现在网上到处是学习资料，想查什么都能查到，自学也更方便了。","pinyin":""},{"speaker":"白家月","cn":"是的，只要有手机或电脑，我就是不在教室，也可以学习中文，和同学一起练口语。","pinyin":""},{"speaker":"安妮","cn":"科技真是让获取知识变得简单多了。","pinyin":""}],"translation_vn":"Annie: Gia Nguyệt, hôm nay tiết học của chúng ta học ở phòng học kỹ thuật số, cảm giác khác hẳn nhỉ.\nBạch Gia Nguyệt: Đúng vậy, phòng học kỹ thuật số có thể chụp ảnh điểm danh, giáo sư điểm danh trực tuyến, không cần gọi tên từng người như học trực tiếp, tiết kiệm thời gian lắm.\nLý Văn: Tiện nhất là, khi trên lớp nghe chưa hiểu, sau giờ học vẫn có thể tìm bản ghi video trên trang web của trường để xem.\nAnnie: Đúng vậy, học tôi cũng không cần vội vàng ghi chép nữa.\nLý Văn: Không chỉ phòng học kỹ thuật số tiện lợi, bây giờ trên mạng khắp nơi đều là tài liệu học tập, muốn tra gì cũng tra được, tự học cũng tiện hơn rồi.\nBạch Gia Nguyệt: Đúng vậy, chỉ cần có điện thoại hoặc máy tính, tôi dù không ở trong lớp, cũng có thể học tiếng Trung, cùng bạn học luyện khẩu ngữ.\nAnnie: Khoa học công nghệ đúng là khiến việc thu nhận kiến thức trở nên đơn giản hơn nhiều.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"数字教室点名方式有什么好处？","q_vn":"Cách điểm danh ở phòng học kỹ thuật số có lợi ích gì?","a_cn":"可以拍照或线上点名，不用一个个叫名字，特别节约时间。","a_vn":"Có thể chụp ảnh hoặc điểm danh trực tuyến, không cần gọi tên từng người, rất tiết kiệm thời gian."},{"q_cn":"李文说，课上没听明白时课后可以怎么办？","q_vn":"Lý Văn nói, khi trên lớp chưa nghe hiểu thì sau giờ học có thể làm gì?","a_cn":"可以在学校网站上找到视频记录再看一遍。","a_vn":"Có thể tìm bản ghi video trên trang web của trường để xem lại."},{"q_cn":"白家月说，就算不在教室也能做什么？","q_vn":"Bạch Gia Nguyệt nói, dù không ở trong lớp cũng có thể làm gì?","a_cn":"只要有手机或电脑，她就是不在教室，也可以学习中文，和同学一起练口语。","a_vn":"Chỉ cần có điện thoại hoặc máy tính, dù không ở trong lớp cô ấy cũng có thể học tiếng Trung, luyện khẩu ngữ cùng bạn học."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"今天星期六，我们去了一雪姐姐家。姐姐家的两个孩子很有礼貌，我们一进门，就马上和我们打招呼。在姐姐家，我们也聊到了孩子的教育。姐姐说，以前他们和很多家长一样，觉得孩子上个好大学，人生才是成功的。所以，他们只关心孩子的分数，结果孩子压力特别大，每天都很不开心。后来，他们认识到，教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。于是，他们做出改变，每天都给孩子留出时间外出锻炼身体，或者看些自己感兴趣的书。我觉得他们的做法真棒。","pinyin":""}],"translation_vn":"Hôm nay là thứ Bảy, chúng tôi đến nhà chị Nhất Tuyết. Hai đứa con nhà chị rất lễ phép, chúng tôi vừa vào cửa, chúng đã lập tức chào hỏi chúng tôi. Ở nhà chị, chúng tôi cũng nói chuyện về việc giáo dục con cái. Chị kể, trước đây họ cũng giống như nhiều bậc phụ huynh khác, cho rằng con cái vào được đại học tốt thì cuộc đời mới thành công. Vì vậy, họ chỉ quan tâm đến điểm số của con, kết quả là con cái áp lực rất lớn, ngày nào cũng không vui. Sau đó, họ nhận ra rằng, mục đích của giáo dục không phải là để con đạt điểm cao, mà là giúp con hình thành thói quen tốt. Thế là, họ đã thay đổi, mỗi ngày đều dành thời gian cho con ra ngoài vận động, hoặc đọc những cuốn sách mà con thích. Tôi thấy cách làm của họ thật tuyệt.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"以前，王一雪和刘明觉得孩子怎样才算人生成功？","q_vn":"Trước đây, Vương Nhất Tuyết và Lưu Minh cho rằng con cái như thế nào mới là thành công trong cuộc đời?","a_cn":"他们觉得孩子上个好大学，人生才是成功的。","a_vn":"Họ cho rằng con cái vào được đại học tốt thì cuộc đời mới thành công."},{"q_cn":"后来他们对教育的目的有了什么新的认识？","q_vn":"Sau đó họ đã có nhận thức mới gì về mục đích giáo dục?","a_cn":"他们认识到，教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","a_vn":"Họ nhận ra rằng mục đích của giáo dục không phải là để con đạt điểm cao, mà là giúp con hình thành thói quen tốt."},{"q_cn":"他们做出了什么样的改变？","q_vn":"Họ đã có những thay đổi như thế nào?","a_cn":"他们每天都给孩子留出时间外出锻炼身体，或者看些自己感兴趣的书。","a_vn":"Họ mỗi ngày đều dành thời gian cho con ra ngoài vận động, hoặc đọc những cuốn sách con thích."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"\"学而不厌\"是两千多年前中国教育家孔子说过的话，意思是人要一直坚持学习，就是说，学习是人一生的事情，要活到老学到老。在世界快速变化的今天，\"学而不厌\"变得更加重要。我有一位很优秀的律师朋友，他一直在学习新的法律知识。他说，这不仅是律师的要求和责任，也是提高自己能力的重要方法。同时我也认为，人就是不再工作了，坚持学习仍很重要。就像我爷爷，虽然七十多岁了，每天还准时去老年大学上课，学习做网页、弹钢琴。他说，重新当一回学生，生活更有意思了，也感觉自己变年轻了。","pinyin":""}],"translation_vn":"\"Học mà không chán\" là câu nói của nhà giáo dục Khổng Tử Trung Quốc từ hơn hai nghìn năm trước, có nghĩa là con người phải luôn kiên trì học tập, tức là, học tập là việc của cả đời người, phải sống đến già học đến già. Trong thời đại thế giới thay đổi nhanh chóng ngày nay, \"học mà không chán\" càng trở nên quan trọng hơn. Tôi có một người bạn luật sư rất ưu tú, anh ấy luôn học hỏi những kiến thức pháp luật mới. Anh ấy nói, đây không chỉ là yêu cầu và trách nhiệm của luật sư, mà còn là phương pháp quan trọng để nâng cao năng lực bản thân. Đồng thời tôi cũng cho rằng, dù con người không còn làm việc nữa thì việc kiên trì học tập vẫn rất quan trọng. Giống như ông tôi, tuy đã hơn bảy mươi tuổi, nhưng ngày nào cũng đúng giờ đến trường đại học dành cho người cao tuổi để học làm trang web, chơi đàn piano. Ông nói, một lần nữa trở thành học sinh khiến cuộc sống thú vị hơn, cũng cảm thấy bản thân trẻ lại.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"\"学而不厌\"是什么意思？","q_vn":"\"Học mà không chán\" có nghĩa là gì?","a_cn":"意思是人要一直坚持学习，学习是人一生的事情，要活到老学到老。","a_vn":"Nghĩa là con người phải luôn kiên trì học tập, học tập là việc của cả đời người, phải sống đến già học đến già."},{"q_cn":"作者的律师朋友为什么一直学习新的法律知识？","q_vn":"Vì sao người bạn luật sư của tác giả luôn học hỏi kiến thức pháp luật mới?","a_cn":"因为这不仅是律师的要求和责任，也是提高自己能力的重要方法。","a_vn":"Vì đây không chỉ là yêu cầu và trách nhiệm của luật sư, mà còn là phương pháp quan trọng để nâng cao năng lực bản thân."},{"q_cn":"作者的爷爷重新当学生后感觉怎么样？","q_vn":"Ông của tác giả cảm thấy thế nào sau khi lại trở thành học sinh?","a_cn":"他觉得生活更有意思了，也感觉自己变年轻了。","a_vn":"Ông cảm thấy cuộc sống thú vị hơn, cũng cảm thấy bản thân trẻ lại."}]}]},{"id":12,"title_cn":"幸福的家庭","title_pinyin":"","title_vn":"Gia đình hạnh phúc","goals":["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến gia đình hạnh phúc.","Có thể trình bày bằng lời hoặc bằng văn bản câu chuyện cuộc sống của một gia đình hạnh phúc.","Hiểu được đặc điểm văn hóa tình thân của người Trung Quốc."],"vocab":[{"hanzi":"毛衣","pinyin":"máoyī","pos":"dt.","vn":"áo len","examples":[{"cn":"妈妈给我织了一件毛衣。","pinyin":"Māma gěi wǒ zhīle yí jiàn máoyī.","vn":"Mẹ đan cho tôi một chiếc áo len."},{"cn":"冬天穿毛衣很暖和。","pinyin":"Dōngtiān chuān máoyī hěn nuǎnhuo.","vn":"Mùa đông mặc áo len rất ấm."},{"cn":"这件毛衣的颜色很好看。","pinyin":"Zhè jiàn máoyī de yánsè hěn hǎokàn.","vn":"Màu của chiếc áo len này rất đẹp."}]},{"hanzi":"样子","pinyin":"yàngzi","pos":"dt.","vn":"kiểu dáng, vẻ ngoài","examples":[{"cn":"这件衣服的样子很特别。","pinyin":"Zhè jiàn yīfu de yàngzi hěn tèbié.","vn":"Kiểu dáng của chiếc áo này rất đặc biệt."},{"cn":"我喜欢这个手机的样子。","pinyin":"Wǒ xǐhuan zhège shǒujī de yàngzi.","vn":"Tôi thích kiểu dáng của chiếc điện thoại này."},{"cn":"他长得什么样子，我都忘了。","pinyin":"Tā zhǎng de shénme yàngzi, wǒ dōu wàng le.","vn":"Anh ấy trông như thế nào, tôi đều quên rồi."}]},{"hanzi":"适合","pinyin":"shìhé","pos":"dgt.","vn":"phù hợp","examples":[{"cn":"这个颜色很适合你。","pinyin":"Zhège yánsè hěn shìhé nǐ.","vn":"Màu này rất hợp với bạn."},{"cn":"老年人穿这种鞋比较适合。","pinyin":"Lǎonián rén chuān zhè zhǒng xié bǐjiào shìhé.","vn":"Người già đi loại giày này khá phù hợp."},{"cn":"这份工作很适合她。","pinyin":"Zhè fèn gōngzuò hěn shìhé tā.","vn":"Công việc này rất hợp với cô ấy."}]},{"hanzi":"售货员","pinyin":"shòuhuòyuán","pos":"dt.","vn":"nhân viên bán hàng","examples":[{"cn":"售货员很热情地给我介绍商品。","pinyin":"Shòuhuòyuán hěn rèqíng de gěi wǒ jièshào shāngpǐn.","vn":"Nhân viên bán hàng nhiệt tình giới thiệu sản phẩm cho tôi."},{"cn":"那位售货员说这件衣服质量很好。","pinyin":"Nà wèi shòuhuòyuán shuō zhè jiàn yīfu zhìliàng hěn hǎo.","vn":"Nhân viên bán hàng đó nói chiếc áo này chất lượng rất tốt."},{"cn":"她以前是商场的售货员。","pinyin":"Tā yǐqián shì shāngchǎng de shòuhuòyuán.","vn":"Trước đây cô ấy là nhân viên bán hàng ở trung tâm thương mại."}]},{"hanzi":"质量","pinyin":"zhìliàng","pos":"dt.","vn":"chất lượng","examples":[{"cn":"这家店的东西质量都很好。","pinyin":"Zhè jiā diàn de dōngxi zhìliàng dōu hěn hǎo.","vn":"Đồ ở cửa hàng này chất lượng đều rất tốt."},{"cn":"买东西不能只看价格，还要看质量。","pinyin":"Mǎi dōngxi bùnéng zhǐ kàn jiàgé, hái yào kàn zhìliàng.","vn":"Mua đồ không thể chỉ nhìn giá, còn phải xem chất lượng."},{"cn":"这双鞋质量不太好，穿了两次就坏了。","pinyin":"Zhè shuāng xié zhìliàng bú tài hǎo, chuānle liǎng cì jiù huàile.","vn":"Đôi giày này chất lượng không tốt lắm, mới đi hai lần đã hỏng."}]},{"hanzi":"强","pinyin":"qiáng","pos":"tt.","vn":"mạnh, hơn, vượt trội","examples":[{"cn":"他的身体比以前强多了。","pinyin":"Tā de shēntǐ bǐ yǐqián qiáng duōle.","vn":"Sức khỏe của anh ấy khỏe hơn trước nhiều."},{"cn":"老妈高兴比什么都强。","pinyin":"Lǎomā gāoxìng bǐ shénme dōu qiáng.","vn":"Mẹ vui vẻ thì hơn tất cả mọi thứ."},{"cn":"这个队的实力比那个队强。","pinyin":"Zhège duì de shílì bǐ nàge duì qiáng.","vn":"Thực lực của đội này mạnh hơn đội kia."}]},{"hanzi":"年底","pinyin":"niándǐ","pos":"dt.","vn":"cuối năm","examples":[{"cn":"商场年底有很多打折活动。","pinyin":"Shāngchǎng niándǐ yǒu hěn duō dǎzhé huódòng.","vn":"Cuối năm trung tâm thương mại có nhiều hoạt động giảm giá."},{"cn":"他打算年底回老家看父母。","pinyin":"Tā dǎsuàn niándǐ huí lǎojiā kàn fùmǔ.","vn":"Anh ấy định cuối năm về quê thăm cha mẹ."},{"cn":"公司年底要开一次大会。","pinyin":"Gōngsī niándǐ yào kāi yí cì dàhuì.","vn":"Cuối năm công ty sẽ tổ chức một cuộc họp lớn."}]},{"hanzi":"全","pinyin":"quán","pos":"tt./phó.","vn":"toàn bộ; hoàn toàn","examples":[{"cn":"这家店全场商品都打折。","pinyin":"Zhè jiā diàn quánchǎng shāngpǐn dōu dǎzhé.","vn":"Cửa hàng này toàn bộ sản phẩm đều giảm giá."},{"cn":"他全忘了昨天说的话。","pinyin":"Tā quán wàngle zuótiān shuō de huà.","vn":"Anh ấy quên hết sạch những gì nói hôm qua."},{"cn":"全家人都喜欢这个礼物。","pinyin":"Quán jiā rén dōu xǐhuan zhège lǐwù.","vn":"Cả nhà đều thích món quà này."}]},{"hanzi":"打折","pinyin":"dǎzhé","pos":"dgt.","vn":"giảm giá, chiết khấu","examples":[{"cn":"这家店今天全场打七折。","pinyin":"Zhè jiā diàn jīntiān quánchǎng dǎ qī zhé.","vn":"Cửa hàng này hôm nay toàn bộ giảm giá còn 70%."},{"cn":"周末商场经常打折。","pinyin":"Zhōumò shāngchǎng jīngcháng dǎzhé.","vn":"Cuối tuần trung tâm thương mại thường giảm giá."},{"cn":"这件毛衣打折以后便宜了不少。","pinyin":"Zhè jiàn máoyī dǎzhé yǐhòu piányile bù shǎo.","vn":"Chiếc áo len này sau khi giảm giá rẻ hơn khá nhiều."}]},{"hanzi":"值","pinyin":"zhí","pos":"tt./dgt.","vn":"đáng giá; có giá trị","examples":[{"cn":"这件衣服质量很好，价格也合适，挺值的。","pinyin":"Zhè jiàn yīfu zhìliàng hěn hǎo, jiàgé yě héshì, tǐng zhí de.","vn":"Chiếc áo này chất lượng tốt, giá cũng hợp lý, rất đáng mua."},{"cn":"为了父母开心，花多少钱都值。","pinyin":"Wèile fùmǔ kāixīn, huā duōshao qián dōu zhí.","vn":"Vì để cha mẹ vui, tốn bao nhiêu tiền cũng đáng."},{"cn":"这次旅行很值，我们看到了很多美景。","pinyin":"Zhè cì lǚxíng hěn zhí, wǒmen kàndàole hěn duō měijǐng.","vn":"Chuyến du lịch này rất đáng, chúng tôi đã thấy nhiều cảnh đẹp."}]},{"hanzi":"估计","pinyin":"gūjì","pos":"dgt.","vn":"ước tính, đoán","examples":[{"cn":"我估计他们快回来了。","pinyin":"Wǒ gūjì tāmen kuài huílái le.","vn":"Tôi đoán họ sắp về rồi."},{"cn":"估计今天会下雨。","pinyin":"Gūjì jīntiān huì xiàyǔ.","vn":"Ước tính hôm nay sẽ mưa."},{"cn":"他估计明天能做完这个工作。","pinyin":"Tā gūjì míngtiān néng zuòwán zhège gōngzuò.","vn":"Anh ấy đoán ngày mai có thể hoàn thành công việc này."}]},{"hanzi":"期","pinyin":"qī","pos":"lượng.","vn":"kỳ, khóa","examples":[{"cn":"老年班这期活动很丰富。","pinyin":"Lǎoniánbān zhè qī huódòng hěn fēngfù.","vn":"Kỳ hoạt động này của lớp người cao tuổi rất phong phú."},{"cn":"这是我们学习班的第三期。","pinyin":"Zhè shì wǒmen xuéxíbān de dì-sān qī.","vn":"Đây là kỳ thứ ba của lớp học chúng tôi."},{"cn":"下一期活动什么时候开始？","pinyin":"Xià yì qī huódòng shénme shíhou kāishǐ?","vn":"Kỳ hoạt động tiếp theo khi nào bắt đầu?"}]},{"hanzi":"听力","pinyin":"tīnglì","pos":"dt.","vn":"thính lực, khả năng nghe","examples":[{"cn":"爷爷最近听力不太好。","pinyin":"Yéye zuìjìn tīnglì bú tài hǎo.","vn":"Gần đây thính lực của ông không tốt lắm."},{"cn":"这个活动是帮助老人保护听力的。","pinyin":"Zhège huódòng shì bāngzhù lǎorén bǎohù tīnglì de.","vn":"Hoạt động này là để giúp người già bảo vệ thính lực."},{"cn":"我的听力考试考得不错。","pinyin":"Wǒ de tīnglì kǎoshì kǎo de búcuò.","vn":"Bài thi nghe của tôi làm khá tốt."}]},{"hanzi":"烦","pinyin":"fán","pos":"tt./dgt.","vn":"chán, bực; làm phiền","examples":[{"cn":"最近工作太多，他心里有点儿烦。","pinyin":"Zuìjìn gōngzuò tài duō, tā xīnlǐ yǒudiǎnr fán.","vn":"Gần đây công việc quá nhiều, trong lòng anh ấy khá bực."},{"cn":"别老说这件事了，听着都烦。","pinyin":"Bié lǎo shuō zhè jiàn shì le, tīngzhe dōu fán.","vn":"Đừng cứ nhắc chuyện này nữa, nghe mà bực."},{"cn":"这个问题一直没解决，真烦人。","pinyin":"Zhège wèntí yìzhí méi jiějué, zhēn fánrén.","vn":"Vấn đề này cứ chưa giải quyết được, thật phiền."}]},{"hanzi":"脱","pinyin":"tuō","pos":"dgt.","vn":"cởi (bỏ)","examples":[{"cn":"进屋要脱鞋。","pinyin":"Jìn wū yào tuō xié.","vn":"Vào nhà phải cởi giày."},{"cn":"他脱了外套挂在门后。","pinyin":"Tā tuōle wàitào guà zài mén hòu.","vn":"Anh ấy cởi áo khoác treo sau cửa."},{"cn":"天气热了，可以脱掉厚衣服了。","pinyin":"Tiānqì rè le, kěyǐ tuōdiào hòu yīfu le.","vn":"Trời nóng rồi, có thể cởi bỏ áo dày."}]},{"hanzi":"挂","pinyin":"guà","pos":"dgt.","vn":"treo","examples":[{"cn":"把衣服挂在衣柜里。","pinyin":"Bǎ yīfu guà zài yīguì lǐ.","vn":"Treo quần áo vào tủ."},{"cn":"墙上挂着一张照片。","pinyin":"Qiáng shàng guàzhe yì zhāng zhàopiàn.","vn":"Trên tường treo một tấm ảnh."},{"cn":"他每次都忘了把钥匙挂好。","pinyin":"Tā měi cì dōu wàngle bǎ yàoshi guàhǎo.","vn":"Lần nào anh ấy cũng quên treo chìa khóa cho ngay ngắn."}]},{"hanzi":"脾气","pinyin":"píqi","pos":"dt.","vn":"tính khí","examples":[{"cn":"他的脾气很好，从不发火。","pinyin":"Tā de píqi hěn hǎo, cóng bù fāhuǒ.","vn":"Tính khí anh ấy rất tốt, không bao giờ nổi giận."},{"cn":"小明最近脾气不太好。","pinyin":"Xiǎomíng zuìjìn píqi bú tài hǎo.","vn":"Gần đây Tiểu Minh tính khí không tốt lắm."},{"cn":"奶奶的脾气特别好，很少生气。","pinyin":"Nǎinai de píqi tèbié hǎo, hěn shǎo shēngqì.","vn":"Tính khí của bà rất tốt, hiếm khi tức giận."}]},{"hanzi":"伤心","pinyin":"shāngxīn","pos":"tt.","vn":"đau lòng, buồn","examples":[{"cn":"听到这个消息，她很伤心。","pinyin":"Tīngdào zhège xiāoxi, tā hěn shāngxīn.","vn":"Nghe tin này, cô ấy rất buồn."},{"cn":"别让奶奶伤心了。","pinyin":"Bié ràng nǎinai shāngxīn le.","vn":"Đừng làm bà buồn lòng."},{"cn":"他因为考试没考好而伤心。","pinyin":"Tā yīnwèi kǎoshì méi kǎohǎo ér shāngxīn.","vn":"Anh ấy buồn vì thi không tốt."}]},{"hanzi":"批评","pinyin":"pīpíng","pos":"dgt.","vn":"phê bình","examples":[{"cn":"妈妈批评了他的坏脾气。","pinyin":"Māma pīpíngle tā de huài píqi.","vn":"Mẹ phê bình tính khí xấu của anh ấy."},{"cn":"老师批评了迟到的学生。","pinyin":"Lǎoshī pīpíngle chídào de xuésheng.","vn":"Thầy giáo phê bình học sinh đi muộn."},{"cn":"他接受了父母的批评。","pinyin":"Tā jiēshòule fùmǔ de pīpíng.","vn":"Anh ấy đã tiếp nhận sự phê bình của cha mẹ."}]},{"hanzi":"道歉","pinyin":"dàoqiàn","pos":"dgt.","vn":"xin lỗi","examples":[{"cn":"他主动向奶奶道歉了。","pinyin":"Tā zhǔdòng xiàng nǎinai dàoqiàn le.","vn":"Anh ấy chủ động xin lỗi bà."},{"cn":"做错了事就应该道歉。","pinyin":"Zuò cuò le shì jiù yīnggāi dàoqiàn.","vn":"Làm sai việc thì nên xin lỗi."},{"cn":"她向朋友道歉后，两人又和好了。","pinyin":"Tā xiàng péngyou dàoqiàn hòu, liǎng rén yòu héhǎo le.","vn":"Sau khi cô ấy xin lỗi bạn, hai người lại làm hòa."}]},{"hanzi":"老家","pinyin":"lǎojiā","pos":"dt.","vn":"quê nhà","examples":[{"cn":"他的老家在上海。","pinyin":"Tā de lǎojiā zài Shànghǎi.","vn":"Quê anh ấy ở Thượng Hải."},{"cn":"过年时他要回老家。","pinyin":"Guònián shí tā yào huí lǎojiā.","vn":"Khi ăn Tết anh ấy phải về quê."},{"cn":"老家的味道让人怀念。","pinyin":"Lǎojiā de wèidào ràng rén huáiniàn.","vn":"Hương vị quê nhà khiến người ta hoài niệm."}]},{"hanzi":"自","pinyin":"zì","pos":"giới.","vn":"từ (khi)","examples":[{"cn":"他自毕业后一直在北京工作。","pinyin":"Tā zì bìyè hòu yìzhí zài Běijīng gōngzuò.","vn":"Từ khi tốt nghiệp anh ấy luôn làm việc ở Bắc Kinh."},{"cn":"自那以后，他们再也没见过面。","pinyin":"Zì nà yǐhòu, tāmen zài yě méi jiànguò miàn.","vn":"Từ đó về sau, họ không còn gặp nhau nữa."},{"cn":"自小，他就喜欢画画。","pinyin":"Zì xiǎo, tā jiù xǐhuan huàhuà.","vn":"Từ nhỏ, anh ấy đã thích vẽ tranh."}]},{"hanzi":"父母","pinyin":"fùmǔ","pos":"dt.","vn":"cha mẹ","examples":[{"cn":"父母很关心孩子的生活。","pinyin":"Fùmǔ hěn guānxīn háizi de shēnghuó.","vn":"Cha mẹ rất quan tâm đến cuộc sống của con."},{"cn":"我每个周末都给父母打电话。","pinyin":"Wǒ měi ge zhōumò dōu gěi fùmǔ dǎ diànhuà.","vn":"Mỗi cuối tuần tôi đều gọi điện cho cha mẹ."},{"cn":"父母希望我们过得幸福。","pinyin":"Fùmǔ xīwàng wǒmen guò de xìngfú.","vn":"Cha mẹ mong chúng ta sống hạnh phúc."}]},{"hanzi":"父子","pinyin":"fùzǐ","pos":"dt.","vn":"cha con","examples":[{"cn":"他们父子关系特别好。","pinyin":"Tāmen fùzǐ guānxì tèbié hǎo.","vn":"Quan hệ cha con của họ rất tốt."},{"cn":"这对父子长得很像。","pinyin":"Zhè duì fùzǐ zhǎng de hěn xiàng.","vn":"Hai cha con này trông rất giống nhau."},{"cn":"父子俩一起去钓鱼。","pinyin":"Fùzǐ liǎ yìqǐ qù diàoyú.","vn":"Hai cha con cùng đi câu cá."}]},{"hanzi":"母子","pinyin":"mǔzǐ","pos":"dt.","vn":"mẹ con","examples":[{"cn":"母子俩的感情很深。","pinyin":"Mǔzǐ liǎ de gǎnqíng hěn shēn.","vn":"Tình cảm của hai mẹ con rất sâu đậm."},{"cn":"这对母子一直生活在一起。","pinyin":"Zhè duì mǔzǐ yìzhí shēnghuó zài yìqǐ.","vn":"Hai mẹ con này luôn sống cùng nhau."},{"cn":"母子之间应该多沟通。","pinyin":"Mǔzǐ zhījiān yīnggāi duō gōutōng.","vn":"Giữa mẹ và con nên trao đổi nhiều hơn."}]},{"hanzi":"无论","pinyin":"wúlùn","pos":"liên.","vn":"dù, bất luận","examples":[{"cn":"无论多忙，他都会给父母打电话。","pinyin":"Wúlùn duō máng, tā dōu huì gěi fùmǔ dǎ diànhuà.","vn":"Dù bận đến đâu, anh ấy cũng gọi điện cho cha mẹ."},{"cn":"无论遇到什么困难，我们都要坚持。","pinyin":"Wúlùn yùdào shénme kùnnan, wǒmen dōu yào jiānchí.","vn":"Dù gặp khó khăn gì, chúng ta đều phải kiên trì."},{"cn":"无论天气怎么样，他都坚持跑步。","pinyin":"Wúlùn tiānqì zěnmeyàng, tā dōu jiānchí pǎobù.","vn":"Dù thời tiết thế nào, anh ấy vẫn kiên trì chạy bộ."}]},{"hanzi":"条件","pinyin":"tiáojiàn","pos":"dt.","vn":"điều kiện","examples":[{"cn":"条件允许的话，我们就去旅行。","pinyin":"Tiáojiàn yǔnxǔ dehuà, wǒmen jiù qù lǚxíng.","vn":"Nếu điều kiện cho phép, chúng ta sẽ đi du lịch."},{"cn":"这里的生活条件越来越好。","pinyin":"Zhèlǐ de shēnghuó tiáojiàn yuèláiyuè hǎo.","vn":"Điều kiện sống ở đây ngày càng tốt hơn."},{"cn":"他找工作的条件很高。","pinyin":"Tā zhǎo gōngzuò de tiáojiàn hěn gāo.","vn":"Điều kiện tìm việc của anh ấy khá cao."}]},{"hanzi":"允许","pinyin":"yǔnxǔ","pos":"dgt.","vn":"cho phép","examples":[{"cn":"老师允许我们提前下课。","pinyin":"Lǎoshī yǔnxǔ wǒmen tíqián xiàkè.","vn":"Thầy giáo cho phép chúng tôi nghỉ học sớm."},{"cn":"父母不允许他一个人出去旅行。","pinyin":"Fùmǔ bù yǔnxǔ tā yí ge rén chūqù lǚxíng.","vn":"Cha mẹ không cho phép anh ấy đi du lịch một mình."},{"cn":"条件允许时，我会回老家看父母。","pinyin":"Tiáojiàn yǔnxǔ shí, wǒ huì huí lǎojiā kàn fùmǔ.","vn":"Khi điều kiện cho phép, tôi sẽ về quê thăm cha mẹ."}]},{"hanzi":"另外","pinyin":"lìngwài","pos":"phó./đt./liên.","vn":"ngoài ra; riêng; khác","examples":[{"cn":"他们另外找时间去看父母。","pinyin":"Tāmen lìngwài zhǎo shíjiān qù kàn fùmǔ.","vn":"Họ tìm riêng thời gian khác để đi thăm cha mẹ."},{"cn":"这是我的意见，另外我还有个建议。","pinyin":"Zhè shì wǒ de yìjiàn, lìngwài wǒ hái yǒu ge jiànyì.","vn":"Đây là ý kiến của tôi, ngoài ra tôi còn có một kiến nghị."},{"cn":"我买了一件毛衣，另外还买了一条裤子。","pinyin":"Wǒ mǎile yí jiàn máoyī, lìngwài hái mǎile yì tiáo kùzi.","vn":"Tôi mua một chiếc áo len, ngoài ra còn mua một cái quần."}]},{"hanzi":"卫生","pinyin":"wèishēng","pos":"dt./tt.","vn":"vệ sinh","examples":[{"cn":"他们帮父母打扫卫生。","pinyin":"Tāmen bāng fùmǔ dǎsǎo wèishēng.","vn":"Họ giúp cha mẹ dọn dẹp vệ sinh."},{"cn":"这家餐厅的卫生做得很好。","pinyin":"Zhè jiā cāntīng de wèishēng zuò de hěn hǎo.","vn":"Vệ sinh của nhà hàng này làm rất tốt."},{"cn":"要养成讲卫生的好习惯。","pinyin":"Yào yǎngchéng jiǎng wèishēng de hǎo xíguàn.","vn":"Phải hình thành thói quen giữ vệ sinh tốt."}]},{"hanzi":"母亲","pinyin":"mǔqīn","pos":"dt.","vn":"mẹ","examples":[{"cn":"母亲为我做了一桌好菜。","pinyin":"Mǔqīn wèi wǒ zuòle yì zhuō hǎo cài.","vn":"Mẹ đã làm cho tôi một bàn thức ăn ngon."},{"cn":"母亲身体不太好，我们很担心。","pinyin":"Mǔqīn shēntǐ bú tài hǎo, wǒmen hěn dānxīn.","vn":"Sức khỏe của mẹ không tốt lắm, chúng tôi rất lo lắng."},{"cn":"他很爱自己的母亲。","pinyin":"Tā hěn ài zìjǐ de mǔqīn.","vn":"Anh ấy rất yêu mẹ của mình."}]},{"hanzi":"待","pinyin":"dāi","pos":"dgt.","vn":"ở, lưu lại","examples":[{"cn":"父母待在他们身边，大家都很开心。","pinyin":"Fùmǔ dāi zài tāmen shēnbiān, dàjiā dōu hěn kāixīn.","vn":"Cha mẹ ở bên cạnh họ, mọi người đều rất vui."},{"cn":"周末我喜欢在家待着。","pinyin":"Zhōumò wǒ xǐhuan zài jiā dāizhe.","vn":"Cuối tuần tôi thích ở nhà."},{"cn":"他在上海待了三年。","pinyin":"Tā zài Shànghǎi dāile sān nián.","vn":"Anh ấy đã ở Thượng Hải ba năm."}]},{"hanzi":"将","pinyin":"jiāng","pos":"giới.","vn":"đem, lấy (giống 把)","examples":[{"cn":"她将父母寄来的鸡汤热了热。","pinyin":"Tā jiāng fùmǔ jì lái de jītāng rèle rè.","vn":"Cô ấy hâm nóng món canh gà mà cha mẹ gửi đến."},{"cn":"请将这些东西放进盒子里。","pinyin":"Qǐng jiāng zhèxiē dōngxi fàng jìn hézi lǐ.","vn":"Xin hãy để những thứ này vào trong hộp."},{"cn":"他将这个消息告诉了大家。","pinyin":"Tā jiāng zhège xiāoxi gàosu le dàjiā.","vn":"Anh ấy đã báo tin này cho mọi người."}]},{"hanzi":"闻","pinyin":"wén","pos":"dgt.","vn":"ngửi, nghe (mùi)","examples":[{"cn":"她闻到了熟悉的味道。","pinyin":"Tā wéndàole shúxī de wèidào.","vn":"Cô ấy đã ngửi thấy mùi vị quen thuộc."},{"cn":"我闻到了饭菜的香味。","pinyin":"Wǒ wéndàole fàncài de xiāngwèi.","vn":"Tôi ngửi thấy mùi thơm của thức ăn."},{"cn":"这茶闻着真香。","pinyin":"Zhè chá wénzhe zhēn xiāng.","vn":"Trà này ngửi thơm thật."}]},{"hanzi":"味道","pinyin":"wèidào","pos":"dt.","vn":"mùi vị","examples":[{"cn":"这个汤的味道很鲜。","pinyin":"Zhège tāng de wèidào hěn xiān.","vn":"Vị của món canh này rất ngon."},{"cn":"老家的味道让她想起了童年。","pinyin":"Lǎojiā de wèidào ràng tā xiǎngqǐle tóngnián.","vn":"Hương vị quê nhà khiến cô nhớ lại tuổi thơ."},{"cn":"这家店的菜味道怎么样？","pinyin":"Zhè jiā diàn de cài wèidào zěnmeyàng?","vn":"Thức ăn của quán này vị thế nào?"}]},{"hanzi":"冷静","pinyin":"lěngjìng","pos":"tt.","vn":"bình tĩnh","examples":[{"cn":"遇到问题要冷静思考。","pinyin":"Yùdào wèntí yào lěngjìng sīkǎo.","vn":"Gặp vấn đề phải bình tĩnh suy nghĩ."},{"cn":"她平时很冷静，很少发脾气。","pinyin":"Tā píngshí hěn lěngjìng, hěn shǎo fā píqi.","vn":"Bình thường cô ấy rất bình tĩnh, hiếm khi nổi nóng."},{"cn":"遇到危险，大家都要保持冷静。","pinyin":"Yùdào wēixiǎn, dàjiā dōu yào bǎochí lěngjìng.","vn":"Gặp nguy hiểm, mọi người đều phải giữ bình tĩnh."}]},{"hanzi":"鼻子","pinyin":"bízi","pos":"dt.","vn":"mũi","examples":[{"cn":"她的鼻子有点儿酸。","pinyin":"Tā de bízi yǒudiǎnr suān.","vn":"Mũi cô ấy cay cay."},{"cn":"他感冒了，鼻子不太舒服。","pinyin":"Tā gǎnmào le, bízi bú tài shūfu.","vn":"Anh ấy bị cảm, mũi không được thoải mái."},{"cn":"小狗的鼻子特别灵。","pinyin":"Xiǎogǒu de bízi tèbié líng.","vn":"Mũi của chó con rất nhạy."}]},{"hanzi":"父亲","pinyin":"fùqīn","pos":"dt.","vn":"bố","examples":[{"cn":"父亲为了让食物新鲜选择了快递。","pinyin":"Fùqīn wèile ràng shíwù xīnxiān xuǎnzéle kuàidì.","vn":"Bố đã chọn chuyển phát nhanh để giữ cho thực phẩm được tươi."},{"cn":"父亲教会了我很多道理。","pinyin":"Fùqīn jiàohuìle wǒ hěn duō dàolǐ.","vn":"Bố đã dạy cho tôi nhiều điều."},{"cn":"他和父亲的关系一直很好。","pinyin":"Tā hé fùqīn de guānxì yìzhí hěn hǎo.","vn":"Quan hệ của anh ấy với bố luôn rất tốt."}]},{"hanzi":"城","pinyin":"chéng","pos":"dt.","vn":"thành phố, thành","examples":[{"cn":"父亲选择了城里最快的快递。","pinyin":"Fùqīn xuǎnzéle chéng lǐ zuì kuài de kuàidì.","vn":"Bố đã chọn dịch vụ chuyển phát nhanh nhất trong thành phố."},{"cn":"这座城很古老，有很多历史故事。","pinyin":"Zhè zuò chéng hěn gǔlǎo, yǒu hěn duō lìshǐ gùshi.","vn":"Thành phố này rất cổ xưa, có nhiều câu chuyện lịch sử."},{"cn":"他从小城搬到了大城市生活。","pinyin":"Tā cóng xiǎo chéng bāndàole dà chéngshì shēnghuó.","vn":"Anh ấy đã dọn từ thành phố nhỏ đến sống ở thành phố lớn."}]},{"hanzi":"鲜","pinyin":"xiān","pos":"tt.","vn":"tươi, ngon","examples":[{"cn":"这个鸡汤很鲜。","pinyin":"Zhège jītāng hěn xiān.","vn":"Canh gà này rất ngon, tươi."},{"cn":"新鲜的鱼做出来的汤特别鲜。","pinyin":"Xīnxiān de yú zuò chūlái de tāng tèbié xiān.","vn":"Canh nấu từ cá tươi đặc biệt ngon."},{"cn":"妈妈做的菜总是又香又鲜。","pinyin":"Māma zuò de cài zǒngshì yòu xiāng yòu xiān.","vn":"Món ăn mẹ làm luôn vừa thơm vừa ngon."}]},{"hanzi":"暖","pinyin":"nuǎn","pos":"tt.","vn":"ấm","examples":[{"cn":"喝了热汤，她心里更暖了。","pinyin":"Hēle rè tāng, tā xīnlǐ gèng nuǎn le.","vn":"Uống canh nóng xong, lòng cô ấy càng ấm hơn."},{"cn":"今天天气很暖，适合出去走走。","pinyin":"Jīntiān tiānqì hěn nuǎn, shìhé chūqù zǒuzou.","vn":"Hôm nay thời tiết ấm, thích hợp ra ngoài đi dạo."},{"cn":"父母的关心让他心里很暖。","pinyin":"Fùmǔ de guānxīn ràng tā xīnlǐ hěn nuǎn.","vn":"Sự quan tâm của cha mẹ làm lòng anh ấy rất ấm."}]},{"hanzi":"勇敢","pinyin":"yǒnggǎn","pos":"tt.","vn":"dũng cảm","examples":[{"cn":"遇到困难要勇敢面对。","pinyin":"Yùdào kùnnan yào yǒnggǎn miànduì.","vn":"Gặp khó khăn phải can đảm đối mặt."},{"cn":"她是一个很勇敢的女孩。","pinyin":"Tā shì yí ge hěn yǒnggǎn de nǔhái.","vn":"Cô ấy là một cô gái rất can đảm."},{"cn":"父母总是鼓励孩子要勇敢。","pinyin":"Fùmǔ zǒngshì gǔlì háizi yào yǒnggǎn.","vn":"Cha mẹ luôn khuyến khích con phải can đảm."}]},{"hanzi":"商量","pinyin":"shāngliang","pos":"dgt.","vn":"bàn bạc","examples":[{"cn":"任何时候都可以和父母商量。","pinyin":"Rènhé shíhou dōu kěyǐ hé fùmǔ shāngliang.","vn":"Bất cứ khi nào cũng có thể bàn bạc với cha mẹ."},{"cn":"我们商量一下周末去哪里玩。","pinyin":"Wǒmen shāngliang yíxià zhōumò qù nǎlǐ wán.","vn":"Chúng ta bàn bạc xem cuối tuần đi đâu chơi."},{"cn":"这件事我得跟家人商量商量。","pinyin":"Zhè jiàn shì wǒ děi gēn jiārén shāngliang shāngliang.","vn":"Việc này tôi phải bàn bạc với người nhà."}]}],"grammar":[{"title":"固定短语\"不怎么\"","explanation_vn":"Cụm từ cố định \"不怎么\" biểu thị mức độ thấp, có nghĩa là \"không quá, không lắm, không thường\".","examples":[{"cn":"样子不错，就是颜色好像不怎么适合她。","pinyin":"","vn":"Kiểu dáng thì không tệ, chỉ là màu sắc có vẻ không hợp với bà lắm."},{"cn":"他总是在图书馆看书，不怎么出去玩。","pinyin":"","vn":"Anh ấy luôn đọc sách trong thư viện, không thường ra ngoài chơi."},{"cn":"我爱吃饺子、包子，不怎么喜欢吃米饭。","pinyin":"","vn":"Tôi thích ăn sủi cảo, bánh bao, không thích ăn cơm lắm."}]},{"title":"双重否定","explanation_vn":"Phủ định hai lần biểu thị ý khẳng định, ngữ khí mạnh hơn khẳng định thông thường. Cấu trúc phủ định hai lần thường gặp có \"不是不、不能不、不得不\" v.v.","examples":[{"cn":"他也不是不知道自己错了，我批评他以后，他马上说放学回来就向奶奶道歉。","pinyin":"","vn":"Anh ấy cũng không phải là không biết mình sai, sau khi tôi phê bình, anh ấy liền nói tan học về sẽ xin lỗi bà ngay."},{"cn":"今天是我们毕业后第一次同学聚餐，你又是班长，不能不来啊！","pinyin":"","vn":"Hôm nay là lần đầu tiên các bạn học họp mặt ăn uống sau khi tốt nghiệp, bạn lại là lớp trưởng, không thể không đến được!"},{"cn":"由于天气不好，飞机不能起飞，爸爸不得不改变计划，明天再去上海。","pinyin":"","vn":"Do thời tiết không tốt, máy bay không thể cất cánh, bố buộc phải thay đổi kế hoạch, ngày mai mới đi Thượng Hải."}]},{"title":"条件复句\"无论……，都/也……\"","explanation_vn":"Câu phức điều kiện \"无论……，都/也……\" biểu thị trong bất kỳ điều kiện nào, kết quả đều không thay đổi.","examples":[{"cn":"杨同乐很关心父母，无论平时工作有多忙，他每个周末都会给父母打电话。","pinyin":"","vn":"Dương Đồng Lạc rất quan tâm đến cha mẹ, dù công việc hàng ngày có bận đến đâu, mỗi cuối tuần anh ấy đều gọi điện cho cha mẹ."},{"cn":"只要你努力了，无论你考多少分，你在我们眼里都是最优秀的。","pinyin":"","vn":"Chỉ cần bạn đã cố gắng, dù bạn thi được bao nhiêu điểm, trong mắt chúng tôi bạn đều là người xuất sắc nhất."},{"cn":"无论你遇到什么困难，我都会在你身边。","pinyin":"","vn":"Dù bạn gặp phải khó khăn gì, tôi đều sẽ ở bên bạn."}]},{"title":"固定格式\"为了……而……\"","explanation_vn":"Cấu trúc cố định \"为了……而……\" trong đó \"为了……\" biểu thị mục đích hoặc mục tiêu, \"而……\" là hành động được thực hiện để đạt được mục đích hoặc mục tiêu đó.","examples":[{"cn":"父母总是担心她为了节约时间而不好好吃饭。","pinyin":"","vn":"Cha mẹ luôn lo lắng cô ấy vì tiết kiệm thời gian mà không ăn uống đàng hoàng."},{"cn":"我们都在为了生活幸福而努力工作着。","pinyin":"","vn":"Chúng ta đều đang vì cuộc sống hạnh phúc mà nỗ lực làm việc."},{"cn":"他们为了保护环境而拒绝使用纸杯。","pinyin":"","vn":"Họ vì bảo vệ môi trường mà từ chối sử dụng cốc giấy."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一飞","cn":"你觉得老妈穿这件毛衣怎么样？","pinyin":""},{"speaker":"杨同乐","cn":"样子不错，就是颜色好像不怎么适合她。","pinyin":""},{"speaker":"售货员","cn":"老年人穿这种颜色的衣服正合适，颜色不深，质量还特别好。您看那位阿姨正试着呢，是不是很好看？","pinyin":""},{"speaker":"王一飞","cn":"嗯，是挺不错的。同乐，我印象中，老妈也常穿这种颜色的衣服，她应该会喜欢的，买一件吧。","pinyin":""},{"speaker":"杨同乐","cn":"好的，老妈高兴比什么都强。","pinyin":""},{"speaker":"售货员","cn":"就是，老人开心最重要。我们店正好年底有活动，全场打七折呢，挺值的。","pinyin":""}],"translation_vn":"Vương Nhất Phi: Anh thấy mẹ mặc chiếc áo len này thế nào?\nDương Đồng Lạc: Kiểu dáng thì không tệ, chỉ là màu sắc có vẻ không hợp với bà lắm.\nNhân viên bán hàng: Người già mặc loại màu này là vừa, màu không đậm, chất lượng cũng đặc biệt tốt. Anh xem cô kia đang thử đấy, có đẹp không?\nVương Nhất Phi: Ừ, cũng khá đẹp đấy. Đồng Lạc, theo tôi nhớ, mẹ cũng thường mặc loại màu này, chắc bà sẽ thích, mua một chiếc đi.\nDương Đồng Lạc: Được, mẹ vui là hơn tất cả.\nNhân viên bán hàng: Đúng vậy, người già vui vẻ là quan trọng nhất. Cửa hàng chúng tôi đúng lúc cuối năm có chương trình, toàn bộ giảm giá còn 70%, rất đáng mua.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"王一飞和杨同乐在商场做什么？","q_vn":"Vương Nhất Phi và Dương Đồng Lạc đang làm gì ở trung tâm thương mại？","a_cn":"他们在给父母买衣服，正在挑选一件适合老妈穿的毛衣。","a_vn":"Họ đang mua quần áo cho cha mẹ, đang chọn một chiếc áo len hợp với mẹ."},{"q_cn":"售货员是怎么介绍这件毛衣的？","q_vn":"Nhân viên bán hàng đã giới thiệu chiếc áo len này như thế nào？","a_cn":"售货员说老年人穿这种颜色的衣服正合适，颜色不深，质量特别好，而且店里年底有活动，全场打七折。","a_vn":"Nhân viên bán hàng nói người già mặc màu này là vừa, màu không đậm, chất lượng đặc biệt tốt, hơn nữa cửa hàng cuối năm có chương trình giảm giá còn 70%."},{"q_cn":"杨同乐对给老妈买毛衣这件事是什么态度？","q_vn":"Dương Đồng Lạc có thái độ thế nào về việc mua áo len cho mẹ？","a_cn":"他觉得老妈高兴比什么都重要，所以愿意买这件毛衣给她。","a_vn":"Anh ấy cảm thấy mẹ vui vẻ là quan trọng hơn tất cả, nên sẵn lòng mua chiếc áo len này cho bà."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘明","cn":"爷爷、奶奶还没回来呢？","pinyin":""},{"speaker":"王一雪","cn":"没呢，估计快了。下午老年班举办一期听力保护活动，他们去参加活动了。","pinyin":""},{"speaker":"刘明","cn":"他们的活动还挺丰富的！","pinyin":""},{"speaker":"王一雪","cn":"嗯。小明最近要考试，心里有点儿烦，昨天因为脱、挂衣服这点儿小事，就对奶奶发脾气了。","pinyin":""},{"speaker":"刘明","cn":"是吗？他这样做老人该伤心了。","pinyin":""},{"speaker":"王一雪","cn":"就是啊。他也不是不知道自己错了，我批评他以后，他马上说放学回来就向奶奶道歉。","pinyin":""},{"speaker":"刘明","cn":"好的，我也再跟他聊聊。","pinyin":""},{"speaker":"王一雪","cn":"那就更好了。","pinyin":""}],"translation_vn":"Lưu Minh: Ông bà vẫn chưa về sao?\nVương Nhất Tuyết: Chưa đâu, ước tính sắp rồi. Chiều nay lớp người cao tuổi tổ chức một kỳ hoạt động bảo vệ thính lực, ông bà đi tham gia hoạt động rồi.\nLưu Minh: Hoạt động của ông bà cũng khá phong phú đấy!\nVương Nhất Tuyết: Ừ. Tiểu Minh gần đây phải thi, trong lòng có chút bực bội, hôm qua vì chuyện cởi, treo áo nhỏ nhặt mà nổi nóng với bà.\nLưu Minh: Thật sao? Nó làm vậy chắc ông bà buồn lòng rồi.\nVương Nhất Tuyết: Đúng vậy đấy. Nó cũng không phải là không biết mình sai, sau khi tôi phê bình nó, nó liền nói tan học về sẽ xin lỗi bà ngay.\nLưu Minh: Được, anh cũng sẽ nói chuyện thêm với nó.\nVương Nhất Tuyết: Vậy thì càng tốt.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"爷爷奶奶下午去做什么了？","q_vn":"Chiều nay ông bà đã đi làm gì？","a_cn":"他们去参加老年班举办的一期听力保护活动了。","a_vn":"Ông bà đi tham gia một kỳ hoạt động bảo vệ thính lực do lớp người cao tuổi tổ chức."},{"q_cn":"小明为什么对奶奶发脾气？","q_vn":"Vì sao Tiểu Minh nổi nóng với bà？","a_cn":"因为他最近要考试，心里有点儿烦，昨天因为脱、挂衣服这点儿小事就对奶奶发了脾气。","a_vn":"Vì gần đây cậu bé phải thi, trong lòng có chút bực bội, hôm qua vì chuyện cởi, treo áo nhỏ nhặt mà nổi nóng với bà."},{"q_cn":"小明知道自己做错了以后打算怎么做？","q_vn":"Sau khi biết mình làm sai, Tiểu Minh định làm gì？","a_cn":"他打算放学回来就向奶奶道歉。","a_vn":"Cậu định tan học về sẽ xin lỗi bà ngay."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"杨同乐的老家在上海，他自毕业后一直在北京工作。虽然没和父母生活在一起，但父子、母子关系特别好。杨同乐很关心父母，无论平时工作有多忙，他每个周末都会给父母打电话。条件允许时，他会回上海看父母。","pinyin":""},{"speaker":"","cn":"刘明和王一雪结婚后，一直没有和父母生活在一起，他们平时会另外找时间去看父母，帮父母做做饭，打扫打扫卫生。这两年，刘明的母亲身体不太好，他们很担心，就把父母接到了自己家里照顾。父母待在他们身边，他们也终于能放心地去工作了。","pinyin":""}],"translation_vn":"Quê của Dương Đồng Lạc ở Thượng Hải, từ khi tốt nghiệp anh luôn làm việc ở Bắc Kinh. Mặc dù không sống cùng cha mẹ, nhưng quan hệ cha con, mẹ con đều rất tốt. Dương Đồng Lạc rất quan tâm đến cha mẹ, dù công việc hàng ngày có bận đến đâu, mỗi cuối tuần anh đều gọi điện cho cha mẹ. Khi điều kiện cho phép, anh sẽ về Thượng Hải thăm cha mẹ.\nLưu Minh và Vương Nhất Tuyết sau khi kết hôn, vẫn không sống cùng cha mẹ, bình thường họ sẽ tìm thời gian riêng để đi thăm cha mẹ, giúp cha mẹ nấu cơm, dọn dẹp vệ sinh. Hai năm nay, sức khỏe của mẹ Lưu Minh không tốt lắm, họ rất lo lắng, nên đã đón cha mẹ về sống cùng nhà để chăm sóc. Có cha mẹ ở bên cạnh, họ cũng rốt cuộc có thể yên tâm đi làm.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"杨同乐是怎么表达对父母的关心的？","q_vn":"Dương Đồng Lạc thể hiện sự quan tâm đến cha mẹ như thế nào？","a_cn":"无论平时工作有多忙，他每个周末都会给父母打电话，条件允许时还会回上海看父母。","a_vn":"Dù công việc hàng ngày có bận đến đâu, mỗi cuối tuần anh đều gọi điện cho cha mẹ, khi điều kiện cho phép còn về Thượng Hải thăm cha mẹ."},{"q_cn":"刘明和王一雪为什么把父母接到自己家里照顾？","q_vn":"Vì sao Lưu Minh và Vương Nhất Tuyết đón cha mẹ về nhà mình chăm sóc？","a_cn":"因为这两年刘明母亲身体不太好，他们很担心，所以把父母接到自己家里照顾。","a_vn":"Vì hai năm nay sức khỏe của mẹ Lưu Minh không tốt lắm, họ rất lo lắng, nên đã đón cha mẹ về nhà mình chăm sóc."},{"q_cn":"父母搬去和刘明、王一雪一起住后，给他们带来了什么变化？","q_vn":"Sau khi cha mẹ dọn đến sống cùng Lưu Minh và Vương Nhất Tuyết, điều đó mang lại thay đổi gì cho họ？","a_cn":"父母待在他们身边，他们终于能放心地去工作了。","a_vn":"Có cha mẹ ở bên cạnh, họ cuối cùng có thể yên tâm đi làm."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"下班回家，林静静将父母从老家寄来的鸡汤热了热，当闻到从小就熟悉的味道时，平时冷静的她鼻子还是酸了。","pinyin":""},{"speaker":"","cn":"林静静一个人来北京工作三年了，父母总是担心她为了节约时间而不好好吃饭，所以每个月都给她寄各种好吃的。这次母亲专门做了林静静最爱喝的鸡汤，为了让食物新鲜，父亲选择了城里最快的快递，上午寄出，下午就能收到。","pinyin":""},{"speaker":"","cn":"鸡汤很鲜，林静静心里更暖，她觉得父母好像就在身边。都说\"儿行千里母担忧\"，父母总对她说：\"遇到困难别害怕，要勇敢面对，任何时候都可以和父母商量。\"尽管在大城市生活压力有些大，但每当想到父母的这些话，尝到来自老家熟悉的味道，她就觉得又能笑着面对生活了。","pinyin":""}],"translation_vn":"Tan làm về nhà, Lâm Tĩnh Tĩnh hâm nóng lại món canh gà mà cha mẹ từ quê gửi đến, khi ngửi thấy mùi vị quen thuộc từ nhỏ, cô vốn luôn bình tĩnh mà mũi vẫn cay cay.\nLâm Tĩnh Tĩnh một mình đến Bắc Kinh làm việc đã ba năm, cha mẹ luôn lo lắng cô vì tiết kiệm thời gian mà không ăn uống đàng hoàng, nên mỗi tháng đều gửi cho cô các loại đồ ăn ngon. Lần này mẹ đặc biệt làm món canh gà mà Lâm Tĩnh Tĩnh thích uống nhất, để giữ cho thực phẩm được tươi, bố đã chọn dịch vụ chuyển phát nhanh nhất trong thành phố, gửi vào buổi sáng, buổi chiều đã nhận được.\nCanh gà rất ngon, lòng Lâm Tĩnh Tĩnh càng thêm ấm áp, cô cảm thấy như cha mẹ đang ở bên cạnh. Người ta vẫn nói \"con đi xa ngàn dặm mẹ lo âu\", cha mẹ luôn nói với cô: \"Gặp khó khăn đừng sợ, phải can đảm đối mặt, bất cứ khi nào cũng có thể bàn bạc với cha mẹ.\" Dù sống ở thành phố lớn áp lực có phần lớn, nhưng mỗi khi nhớ đến những lời cha mẹ nói, nếm được hương vị quen thuộc từ quê nhà, cô lại cảm thấy có thể mỉm cười đối mặt với cuộc sống.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"林静静下班回家后做了什么，她当时的心情怎么样？","q_vn":"Sau khi tan làm về nhà, Lâm Tĩnh Tĩnh đã làm gì, tâm trạng của cô lúc đó thế nào？","a_cn":"她把父母从老家寄来的鸡汤热了热，闻到熟悉的味道时，平时冷静的她鼻子还是酸了，心里很感动。","a_vn":"Cô hâm nóng lại món canh gà mà cha mẹ từ quê gửi đến, khi ngửi thấy mùi vị quen thuộc, cô vốn luôn bình tĩnh mà mũi vẫn cay cay, trong lòng rất xúc động."},{"q_cn":"父母为什么每个月都给林静静寄好吃的？","q_vn":"Vì sao mỗi tháng cha mẹ đều gửi đồ ăn ngon cho Lâm Tĩnh Tĩnh？","a_cn":"因为父母担心她一个人在北京工作，为了节约时间而不好好吃饭，所以每个月都给她寄各种好吃的。","a_vn":"Vì cha mẹ lo lắng cô một mình làm việc ở Bắc Kinh, vì tiết kiệm thời gian mà không ăn uống đàng hoàng, nên mỗi tháng đều gửi cho cô các loại đồ ăn ngon."},{"q_cn":"父母常对林静静说的话对她有什么影响？","q_vn":"Những lời cha mẹ thường nói với Lâm Tĩnh Tĩnh có ảnh hưởng gì đến cô？","a_cn":"父母常说遇到困难别害怕，要勇敢面对，任何时候都可以和父母商量，这些话让她在生活压力大时还能笑着面对生活。","a_vn":"Cha mẹ thường nói gặp khó khăn đừng sợ, phải can đảm đối mặt, bất cứ khi nào cũng có thể bàn bạc với cha mẹ, những lời này giúp cô dù áp lực sống lớn vẫn có thể mỉm cười đối mặt với cuộc sống."}]}]},{"id":13,"title_cn":"美好的日子","title_pinyin":"","title_vn":"Những ngày tháng tươi đẹp","goals":["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến đời sống ngày lễ.","Có thể trình bày bằng lời hoặc văn bản về đặc điểm ngày lễ, hoạt động ngày lễ.","Hiểu được nội hàm văn hóa phía sau sự coi trọng đặc biệt của người Trung Quốc đối với các ngày lễ truyền thống."],"vocab":[{"hanzi":"熊","pinyin":"xióng","pos":"dt.","vn":"gấu","examples":[{"cn":"动物园里有好几只熊。","pinyin":"Dòngwùyuán lǐ yǒu hǎo jǐ zhī xióng.","vn":"Trong sở thú có mấy con gấu."},{"cn":"那只熊正在吃东西。","pinyin":"Nà zhī xióng zhèngzài chī dōngxi.","vn":"Con gấu đó đang ăn."},{"cn":"孩子们看到熊都很兴奋。","pinyin":"Háizimen kàndào xióng dōu hěn xīngfèn.","vn":"Lũ trẻ nhìn thấy gấu đều rất phấn khích."}]},{"hanzi":"老虎","pinyin":"lǎohǔ","pos":"dt.","vn":"hổ","examples":[{"cn":"老虎是森林里最厉害的动物之一。","pinyin":"Lǎohǔ shì sēnlín lǐ zuì lìhai de dòngwù zhīyī.","vn":"Hổ là một trong những loài động vật mạnh nhất trong rừng."},{"cn":"这只老虎是国家一级保护动物。","pinyin":"Zhè zhī lǎohǔ shì guójiā yī jí bǎohù dòngwù.","vn":"Con hổ này là động vật được bảo vệ cấp quốc gia hạng một."},{"cn":"孩子们第一次近距离看到老虎，特别激动。","pinyin":"Háizimen dì-yī cì jìn jùlí kàndào lǎohǔ, tèbié jīdòng.","vn":"Lần đầu tiên nhìn thấy hổ gần như vậy, các em rất xúc động."}]},{"hanzi":"喊","pinyin":"hǎn","pos":"dgt.","vn":"hô to, la hét","examples":[{"cn":"他大声喊了妈妈的名字。","pinyin":"Tā dàshēng hǎnle māma de míngzi.","vn":"Anh ấy hô to tên của mẹ."},{"cn":"别在景区里大喊大叫。","pinyin":"Bié zài jǐngqū lǐ dà hǎn dà jiào.","vn":"Đừng hò hét lớn trong khu du lịch."},{"cn":"她在人群中喊了一声朋友的名字。","pinyin":"Tā zài rénqún zhōng hǎnle yì shēng péngyou de míngzi.","vn":"Cô ấy gọi to tên của người bạn trong đám người."}]},{"hanzi":"级","pinyin":"jí","pos":"lượng.","vn":"cấp, bậc","examples":[{"cn":"这是国家一级保护动物。","pinyin":"Zhè shì guójiā yī jí bǎohù dòngwù.","vn":"Đây là động vật bảo vệ cấp quốc gia hạng một."},{"cn":"他的汉语水平已经到了高级。","pinyin":"Tā de Hànyǔ shuǐpíng yǐjīng dàole gāojí.","vn":"Trình độ tiếng Trung của anh ấy đã đạt bậc cao."},{"cn":"这家酒店是五星级的。","pinyin":"Zhè jiā jiǔdiàn shì wǔ xīngjí de.","vn":"Khách sạn này là năm sao."}]},{"hanzi":"树林","pinyin":"shùlín","pos":"dt.","vn":"rừng cây","examples":[{"cn":"树林里有很多鸟。","pinyin":"Shùlín lǐ yǒu hěn duō niǎo.","vn":"Trong rừng cây có nhiều chim."},{"cn":"他们在树林里散步。","pinyin":"Tāmen zài shùlín lǐ sànbù.","vn":"Họ đi dạo trong rừng cây."},{"cn":"树林里住着很多动物。","pinyin":"Shùlín lǐ zhùzhe hěn duō dòngwù.","vn":"Trong rừng cây có nhiều động vật sinh sống."}]},{"hanzi":"景区","pinyin":"jǐngqū","pos":"dt.","vn":"khu du lịch, khu cảnh quan","examples":[{"cn":"这个景区很大，也很美。","pinyin":"Zhège jǐngqū hěn dà, yě hěn měi.","vn":"Khu du lịch này rất lớn, cũng rất đẹp."},{"cn":"节假日景区的游客特别多。","pinyin":"Jiéjiàrì jǐngqū de yóukè tèbié duō.","vn":"Dịp lễ khách du lịch ở khu du lịch rất đông."},{"cn":"这个景区里有很多野生动物。","pinyin":"Zhège jǐngqū lǐ yǒu hěn duō yěshēng dòngwù.","vn":"Khu du lịch này có rất nhiều động vật hoang dã."}]},{"hanzi":"区","pinyin":"qū","pos":"dt.","vn":"khu, vùng","examples":[{"cn":"这里是猛兽区。","pinyin":"Zhèlǐ shì měngshòu qū.","vn":"Đây là khu thú dữ."},{"cn":"商业区的人总是很多。","pinyin":"Shāngyè qū de rén zǒngshì hěn duō.","vn":"Khu thương mại luôn có rất nhiều người."},{"cn":"他住在城市的北区。","pinyin":"Tā zhù zài chéngshì de běi qū.","vn":"Anh ấy sống ở khu bắc của thành phố."}]},{"hanzi":"美","pinyin":"měi","pos":"tt.","vn":"đẹp","examples":[{"cn":"这里的风景真美！","pinyin":"Zhèlǐ de fēngjǐng zhēn měi!","vn":"Cảnh ở đây thật đẹp!"},{"cn":"她长得很美。","pinyin":"Tā zhǎng de hěn měi.","vn":"Cô ấy trông rất đẹp."},{"cn":"秋天的树林特别美。","pinyin":"Qiūtiān de shùlín tèbié měi.","vn":"Rừng cây mùa thu đặc biệt đẹp."}]},{"hanzi":"节假日","pinyin":"jiéjiàrì","pos":"dt.","vn":"ngày lễ, ngày nghỉ","examples":[{"cn":"节假日景区的人很多。","pinyin":"Jiéjiàrì jǐngqū de rén hěn duō.","vn":"Ngày lễ ở khu du lịch có rất nhiều người."},{"cn":"他打算节假日去看父母。","pinyin":"Tā dǎsuàn jiéjiàrì qù kàn fùmǔ.","vn":"Anh ấy định ngày lễ sẽ đi thăm cha mẹ."},{"cn":"节假日商场经常打折。","pinyin":"Jiéjiàrì shāngchǎng jīngcháng dǎzhé.","vn":"Ngày lễ trung tâm thương mại thường giảm giá."}]},{"hanzi":"千万","pinyin":"qiānwàn","pos":"phó.","vn":"nhất định, ngàn vạn lần","examples":[{"cn":"一会儿千万别跑丢了。","pinyin":"Yíhuìr qiānwàn bié pǎo diū le.","vn":"Lúc nữa nhất định đừng chạy đi lạc đấy."},{"cn":"你千万要注意安全。","pinyin":"Nǐ qiānwàn yào zhùyì ānquán.","vn":"Bạn nhất định phải chú ý an toàn."},{"cn":"这件事千万不能告诉别人。","pinyin":"Zhè jiàn shì qiānwàn bùnéng gàosu biérén.","vn":"Việc này nhất định không được nói cho người khác."}]},{"hanzi":"开玩笑","pinyin":"kāi wánxiào","pos":"dgt.","vn":"nói đùa, nói chơi","examples":[{"cn":"我不是开玩笑，是真的。","pinyin":"Wǒ búshì kāi wánxiào, shì zhēn de.","vn":"Tôi không nói đùa, là thật đấy."},{"cn":"他喜欢跟朋友开玩笑。","pinyin":"Tā xǐhuan gēn péngyou kāi wánxiào.","vn":"Anh ấy thích nói đùa với bạn bè."},{"cn":"别开玩笑了，快点儿准备吧。","pinyin":"Bié kāi wánxiào le, kuài diǎnr zhǔnbèi ba.","vn":"Đừng đùa nữa, chuẩn bị nhanh lên."}]},{"hanzi":"月饼","pinyin":"yuèbing","pos":"dt.","vn":"bánh trung thu","examples":[{"cn":"中秋节人们都会吃月饼。","pinyin":"Zhōngqiūjié rénmen dōu huì chī yuèbing.","vn":"Tết Trung thu người ta đều ăn bánh trung thu."},{"cn":"这家店的月饼很有名。","pinyin":"Zhè jiā diàn de yuèbing hěn yǒumíng.","vn":"Bánh trung thu của tiệm này rất nổi tiếng."},{"cn":"她给朋友送了一盒月饼。","pinyin":"Tā gěi péngyou sòngle yì hé yuèbing.","vn":"Cô ấy gửi cho bạn một hộp bánh trung thu."}]},{"hanzi":"葡萄","pinyin":"pútao","pos":"dt.","vn":"nho","examples":[{"cn":"桌上放着新鲜的葡萄。","pinyin":"Zhuōshàng fàngzhe xīnxiān de pútao.","vn":"Trên bàn để nho tươi."},{"cn":"这种葡萄很甜。","pinyin":"Zhè zhǒng pútao hěn tián.","vn":"Loại nho này rất ngọt."},{"cn":"她喜欢吃葡萄。","pinyin":"Tā xǐhuan chī pútao.","vn":"Cô ấy thích ăn nho."}]},{"hanzi":"香","pinyin":"xiāng","pos":"tt.","vn":"thơm","examples":[{"cn":"这茶闻着真香。","pinyin":"Zhè chá wénzhe zhēn xiāng.","vn":"Trà này ngửi thơm thật."},{"cn":"妈妈做的饭菜特别香。","pinyin":"Māma zuò de fàncài tèbié xiāng.","vn":"Món ăn mẹ làm đặc biệt thơm."},{"cn":"厨房里飘出一阵香味。","pinyin":"Chúfáng lǐ piāochū yí zhèn xiāngwèi.","vn":"Từ bếp tỏa ra mùi thơm."}]},{"hanzi":"街道","pinyin":"jiēdào","pos":"dt.","vn":"đường phố","examples":[{"cn":"节日的街道上很热闹。","pinyin":"Jiérì de jiēdào shàng hěn rènao.","vn":"Ngày lễ trên đường phố rất náo nhiệt."},{"cn":"这条街道两边都是商店。","pinyin":"Zhè tiáo jiēdào liǎngbiān dōu shì shāngdiàn.","vn":"Hai bên con đường này đều là cửa hàng."},{"cn":"街道上挂满了灯。","pinyin":"Jiēdào shàng guàmǎnle dēng.","vn":"Trên phố treo đầy đèn."}]},{"hanzi":"剧院","pinyin":"jùyuàn","pos":"dt.","vn":"nhà hát","examples":[{"cn":"他们晚上去剧院看演出。","pinyin":"Tāmen wǎnshàng qù jùyuàn kàn yǎnchū.","vn":"Buổi tối họ đi nhà hát xem biểu diễn."},{"cn":"这个剧院能坐一千多人。","pinyin":"Zhège jùyuàn néng zuò yìqiān duō rén.","vn":"Nhà hát này có thể chứa hơn một nghìn người."},{"cn":"剧院门口排了很长的队。","pinyin":"Jùyuàn ménkǒu páile hěn cháng de duì.","vn":"Trước cửa nhà hát xếp hàng rất dài."}]},{"hanzi":"演出","pinyin":"yǎnchū","pos":"dgt.","vn":"diễn, biểu diễn","examples":[{"cn":"中秋节有很多演出活动。","pinyin":"Zhōngqiūjié yǒu hěn duō yǎnchū huódòng.","vn":"Tết Trung thu có rất nhiều hoạt động biểu diễn."},{"cn":"她在晚会上演出了一首歌。","pinyin":"Tā zài wǎnhuì shàng yǎnchūle yì shǒu gē.","vn":"Cô ấy đã biểu diễn một bài hát trong buổi tối văn nghệ."},{"cn":"今晚的演出非常精彩。","pinyin":"Jīnwǎn de yǎnchū fēicháng jīngcǎi.","vn":"Buổi diễn tối nay rất đặc sắc."}]},{"hanzi":"赶","pinyin":"gǎn","pos":"dgt.","vn":"trùng, gặp","examples":[{"cn":"中秋节和生日赶在了一块儿。","pinyin":"Zhōngqiūjié hé shēngrì gǎn zài le yíkuàir.","vn":"Tết Trung thu và sinh nhật trùng vào đúng cùng một ngày."},{"cn":"我们正好赶上了最后一班车。","pinyin":"Wǒmen zhènghǎo gǎnshàngle zuìhòu yì bān chē.","vn":"Chúng tôi vừa kịp bắt được chuyến xe cuối."},{"cn":"他赶着去开会，没来得及吃饭。","pinyin":"Tā gǎnzhe qù kāihuì, méi láidejí chīfàn.","vn":"Anh ấy vội đi họp, không kịp ăn cơm."}]},{"hanzi":"巧","pinyin":"qiǎo","pos":"tt.","vn":"trùng hợp, khéo","examples":[{"cn":"中秋节和生日赶在了一块儿，真巧！","pinyin":"Zhōngqiūjié hé shēngrì gǎn zài le yíkuàir, zhēn qiǎo!","vn":"Tết Trung thu và sinh nhật trùng vào một ngày, thật trùng hợp!"},{"cn":"没想到在这里碰到你，真巧。","pinyin":"Méi xiǎngdào zài zhèlǐ pèngdào nǐ, zhēn qiǎo.","vn":"Không ngờ gặp bạn ở đây, thật trùng hợp."},{"cn":"这事儿来得真巧。","pinyin":"Zhè shìr lái de zhēn qiǎo.","vn":"Việc này đến thật đúng lúc."}]},{"hanzi":"之中","pinyin":"zhīzhōng","pos":"dt.","vn":"trong số, ở giữa","examples":[{"cn":"周力就是这些人之中的一位。","pinyin":"Zhōu Lì jiùshì zhèxiē rén zhīzhōng de yí wèi.","vn":"Châu Lực chính là một trong số những người đó."},{"cn":"在众多选手之中，他表现得最好。","pinyin":"Zài zhòngduō xuǎnshǒu zhīzhōng, tā biǎoxiàn de zuì hǎo.","vn":"Trong số rất nhiều vận động viên, anh ấy thể hiện tốt nhất."},{"cn":"这件事就发生在我们之中。","pinyin":"Zhè jiàn shì jiù fāshēng zài wǒmen zhīzhōng.","vn":"Việc này xảy ra ngay trong số chúng ta."}]},{"hanzi":"铁路","pinyin":"tiělù","pos":"dt.","vn":"đường sắt","examples":[{"cn":"他是一名铁路工作人员。","pinyin":"Tā shì yì míng tiělù gōngzuò rényuán.","vn":"Anh ấy là một nhân viên đường sắt."},{"cn":"这条铁路连接了两个城市。","pinyin":"Zhè tiáo tiělù liánjiēle liǎng ge chéngshì.","vn":"Tuyến đường sắt này kết nối hai thành phố."},{"cn":"中国的铁路发展得很快。","pinyin":"Zhōngguó de tiělù fāzhǎn de hěn kuài.","vn":"Đường sắt Trung Quốc phát triển rất nhanh."}]},{"hanzi":"人员","pinyin":"rényuán","pos":"dt.","vn":"nhân viên","examples":[{"cn":"铁路工作人员每天都很忙。","pinyin":"Tiělù gōngzuò rényuán měitiān dōu hěn máng.","vn":"Nhân viên đường sắt hằng ngày đều rất bận."},{"cn":"医院里有很多医护人员。","pinyin":"Yīyuàn lǐ yǒu hěn duō yīhù rényuán.","vn":"Trong bệnh viện có nhiều nhân viên y tế."},{"cn":"这次活动需要不少工作人员。","pinyin":"Zhè cì huódòng xūyào bùshǎo gōngzuò rényuán.","vn":"Hoạt động lần này cần không ít nhân viên."}]},{"hanzi":"反向","pinyin":"fǎnxiàng","pos":"dgt.","vn":"ngược hướng","examples":[{"cn":"他们决定来一次反向团圆。","pinyin":"Tāmen juédìng lái yí cì fǎnxiàng tuányuán.","vn":"Họ quyết định làm một lần đoàn viên theo hướng ngược lại."},{"cn":"那辆车突然反向开了过去。","pinyin":"Nà liàng chē tūrán fǎnxiàng kāile guòqù.","vn":"Chiếc xe đó bất ngờ chạy theo hướng ngược lại."},{"cn":"这条路是反向单行道。","pinyin":"Zhè tiáo lù shì fǎnxiàng dānxíngdào.","vn":"Con đường này là đường một chiều theo hướng ngược."}]},{"hanzi":"团圆","pinyin":"tuányuán","pos":"dgt.","vn":"đoàn viên, sum họp","examples":[{"cn":"中秋节是一家人团圆的节日。","pinyin":"Zhōngqiūjié shì yì jiā rén tuányuán de jiérì.","vn":"Tết Trung thu là ngày lễ đoàn viên của cả gia đình."},{"cn":"过年时全家人都想团圆。","pinyin":"Guònián shí quán jiā rén dōu xiǎng tuányuán.","vn":"Khi ăn Tết cả nhà đều muốn đoàn viên."},{"cn":"他们终于团圆了。","pinyin":"Tāmen zhōngyú tuányuán le.","vn":"Cuối cùng họ đã được đoàn viên."}]},{"hanzi":"左右","pinyin":"zuǒyòu","pos":"dt.","vn":"khoảng, xung quanh","examples":[{"cn":"早上五点左右他们就出发了。","pinyin":"Zǎoshang wǔ diǎn zuǒyòu tāmen jiù chūfā le.","vn":"Khoảng năm giờ sáng họ đã xuất phát."},{"cn":"这件衣服一百块左右。","pinyin":"Zhè jiàn yīfu yìbǎi kuài zuǒyòu.","vn":"Chiếc áo này khoảng một trăm đồng."},{"cn":"他每天工作八个小时左右。","pinyin":"Tā měitiān gōngzuò bā ge xiǎoshí zuǒyòu.","vn":"Mỗi ngày anh ấy làm việc khoảng tám giờ."}]},{"hanzi":"大约","pinyin":"dàyuē","pos":"phó.","vn":"khoảng, ước chừng","examples":[{"cn":"大约七点他们就到了。","pinyin":"Dàyuē qī diǎn tāmen jiù dào le.","vn":"Khoảng bảy giờ họ đã đến."},{"cn":"这条路大约有十公里。","pinyin":"Zhè tiáo lù dàyuē yǒu shí gōnglǐ.","vn":"Con đường này khoảng dài mười ki-lô-mét."},{"cn":"大约有一百人参加了这次活动。","pinyin":"Dàyuē yǒu yìbǎi rén cānjiāle zhè cì huódòng.","vn":"Khoảng một trăm người đã tham gia hoạt động này."}]},{"hanzi":"烤","pinyin":"kǎo","pos":"dgt.","vn":"nướng","examples":[{"cn":"他们做了烤肉、烤鱼。","pinyin":"Tāmen zuòle kǎoròu, kǎoyú.","vn":"Họ đã làm thịt nướng, cá nướng."},{"cn":"周末我们一起去烤肉吧。","pinyin":"Zhōumò wǒmen yìqǐ qù kǎoròu ba.","vn":"Cuối tuần chúng ta cùng đi nướng thịt đi."},{"cn":"这个面包是刚烤出来的。","pinyin":"Zhège miànbāo shì gāng kǎo chūlái de.","vn":"Bánh mì này vừa mới được nướng ra."}]},{"hanzi":"西红柿","pinyin":"xīhóngshì","pos":"dt.","vn":"cà chua","examples":[{"cn":"妈妈做了西红柿鸡蛋汤。","pinyin":"Māma zuòle xīhóngshì jīdàn tāng.","vn":"Mẹ đã làm canh cà chua trứng."},{"cn":"这个菜用了很多西红柿。","pinyin":"Zhège cài yòngle hěn duō xīhóngshì.","vn":"Món này dùng rất nhiều cà chua."},{"cn":"我喜欢吃西红柿炒鸡蛋。","pinyin":"Wǒ xǐhuan chī xīhóngshì chǎo jīdàn.","vn":"Tôi thích ăn trứng xào cà chua."}]},{"hanzi":"出现","pinyin":"chūxiàn","pos":"dgt.","vn":"xuất hiện","examples":[{"cn":"父母突然出现在他家门口。","pinyin":"Fùmǔ tūrán chūxiàn zài tā jiā ménkǒu.","vn":"Cha mẹ bất ngờ xuất hiện trước cửa nhà anh."},{"cn":"这个问题经常出现。","pinyin":"Zhège wèntí jīngcháng chūxiàn.","vn":"Vấn đề này thường xuyên xuất hiện."},{"cn":"天空中出现了一道彩虹。","pinyin":"Tiānkōng zhōng chūxiànle yì dào cǎihóng.","vn":"Trên trời xuất hiện một cầu vòng."}]},{"hanzi":"作为","pinyin":"zuòwéi","pos":"giới./dgt.","vn":"là, với vai trò là","examples":[{"cn":"作为学生，我们应该好好学习。","pinyin":"Zuòwéi xuésheng, wǒmen yīnggāi hǎohāo xuéxí.","vn":"Là học sinh, chúng ta nên học tập chăm chỉ."},{"cn":"春节作为最重要的传统节日，受到大家的重视。","pinyin":"Chūnjié zuòwéi zuì zhòngyào de chuántǒng jiérì, shòudào dàjiā de zhòngshì.","vn":"Tết Nguyên đán với vai trò là ngày lễ truyền thống quan trọng nhất, được mọi người coi trọng."},{"cn":"作为朋友，我希望你能幸福。","pinyin":"Zuòwéi péngyou, wǒ xīwàng nǐ néng xìngfú.","vn":"Là một người bạn, tôi mong bạn được hạnh phúc."}]},{"hanzi":"传统","pinyin":"chuántǒng","pos":"tt./dt.","vn":"truyền thống","examples":[{"cn":"春节是中国最重要的传统节日。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de chuántǒng jiérì.","vn":"Tết Nguyên đán là ngày lễ truyền thống quan trọng nhất của Trung Quốc."},{"cn":"这是一种传统的做法。","pinyin":"Zhè shì yì zhǒng chuántǒng de zuòfǎ.","vn":"Đây là một cách làm truyền thống."},{"cn":"我们应该保护好传统文化。","pinyin":"Wǒmen yīnggāi bǎohù hǎo chuántǒng wénhuà.","vn":"Chúng ta nên bảo vệ tốt văn hóa truyền thống."}]},{"hanzi":"有着","pinyin":"yǒuzhe","pos":"dgt.","vn":"có","examples":[{"cn":"春节对中国人来说有着特别的意义。","pinyin":"Chūnjié duì Zhōngguó rén lái shuō yǒuzhe tèbié de yìyì.","vn":"Tết Nguyên đán đối với người Trung Quốc có ý nghĩa đặc biệt."},{"cn":"这座城市有着悠久的历史。","pinyin":"Zhè zuò chéngshì yǒuzhe yōujiǔ de lìshǐ.","vn":"Thành phố này có lịch sử lâu đời."},{"cn":"他们之间有着深厚的感情。","pinyin":"Tāmen zhījiān yǒuzhe shēnhòu de gǎnqíng.","vn":"Giữa họ có tình cảm sâu đậm."}]},{"hanzi":"意义","pinyin":"yìyì","pos":"dt.","vn":"ý nghĩa","examples":[{"cn":"这件事对他有特别的意义。","pinyin":"Zhè jiàn shì duì tā yǒu tèbié de yìyì.","vn":"Việc này có ý nghĩa đặc biệt đối với anh ấy."},{"cn":"这次旅行很有意义。","pinyin":"Zhè cì lǚxíng hěn yǒu yìyì.","vn":"Chuyến du lịch lần này rất có ý nghĩa."},{"cn":"他不明白这个词的意义。","pinyin":"Tā bù míngbai zhège cí de yìyì.","vn":"Anh ấy không hiểu ý nghĩa của từ này."}]},{"hanzi":"到来","pinyin":"dàolái","pos":"dgt.","vn":"đến, tới","examples":[{"cn":"春节到来时，大家都很开心。","pinyin":"Chūnjié dàolái shí, dàjiā dōu hěn kāixīn.","vn":"Khi Tết Nguyên đán đến, mọi người đều rất vui."},{"cn":"大家都在期待假期的到来。","pinyin":"Dàjiā dōu zài qídài jiàqī de dàolái.","vn":"Mọi người đều đang mong chờ kỳ nghỉ đến."},{"cn":"春天的到来让人心情变好。","pinyin":"Chūntiān de dàolái ràng rén xīnqíng biàn hǎo.","vn":"Mùa xuân đến làm cho lòng người vui vẻ hơn."}]},{"hanzi":"美食","pinyin":"měishí","pos":"dt.","vn":"món ăn ngon","examples":[{"cn":"春节前大家都会准备各种美食。","pinyin":"Chūnjié qián dàjiā dōu huì zhǔnbèi gèzhǒng měishí.","vn":"Trước Tết mọi người đều chuẩn bị các loại món ăn ngon."},{"cn":"这个城市有很多有名的美食。","pinyin":"Zhège chéngshì yǒu hěn duō yǒumíng de měishí.","vn":"Thành phố này có nhiều món ăn ngon nổi tiếng."},{"cn":"她很喜欢尝试各地的美食。","pinyin":"Tā hěn xǐhuan chángshì gèdì de měishí.","vn":"Cô ấy rất thích thử món ăn ngon ở các vùng."}]},{"hanzi":"年夜饭","pinyin":"niányèfàn","pos":"dt.","vn":"bữa cơm tối đêm giao thừa","examples":[{"cn":"除夕这天晚上，一家人一起吃年夜饭。","pinyin":"Chúxī zhè tiān wǎnshàng, yì jiā rén yìqǐ chī niányèfàn.","vn":"Tối hôm trừ tịch, cả nhà cùng ăn bữa cơm tối đêm giao thừa."},{"cn":"妈妈做了一桌丰富的年夜饭。","pinyin":"Māma zuòle yì zhuō fēngfù de niányèfàn.","vn":"Mẹ đã làm một bàn cơm giao thừa thịnh soạn."},{"cn":"年夜饭是春节最重要的一餐。","pinyin":"Niányèfàn shì Chūnjié zuì zhòngyào de yì cān.","vn":"Bữa cơm giao thừa là bữa ăn quan trọng nhất của Tết."}]},{"hanzi":"回忆","pinyin":"huíyì","pos":"dgt.","vn":"hồi tưởng, nhớ lại","examples":[{"cn":"每当回忆起童年，他就觉得很幸福。","pinyin":"Měi dāng huíyìqǐ tóngnián, tā jiù juéde hěn xìngfú.","vn":"Mỗi khi nhớ lại thời thơ ấu, anh ấy lại cảm thấy rất hạnh phúc."},{"cn":"她常常回忆起老家的生活。","pinyin":"Tā chángcháng huíyìqǐ lǎojiā de shēnghuó.","vn":"Cô ấy thường nhớ lại cuộc sống ở quê nhà."},{"cn":"这张照片让我回忆起了很多事情。","pinyin":"Zhè zhāng zhàopiàn ràng wǒ huíyìqǐle hěn duō shìqing.","vn":"Tấm ảnh này khiến tôi nhớ lại rất nhiều chuyện."}]},{"hanzi":"童年","pinyin":"tóngnián","pos":"dt.","vn":"thời thơ ấu","examples":[{"cn":"他的童年过得很快乐。","pinyin":"Tā de tóngnián guò de hěn kuàilè.","vn":"Thời thơ ấu của anh ấy trôi qua rất vui vẻ."},{"cn":"童年的记忆总是很美好。","pinyin":"Tóngnián de jìyì zǒngshì hěn měihǎo.","vn":"Kỷ niệm thời thơ ấu luôn rất đẹp."},{"cn":"她常常想起童年的朋友。","pinyin":"Tā chángcháng xiǎngqǐ tóngnián de péngyou.","vn":"Cô ấy thường nhớ đến những người bạn thời thơ ấu."}]},{"hanzi":"记忆","pinyin":"jìyì","pos":"dt.","vn":"trí nhớ, kỷ niệm","examples":[{"cn":"这是我最美好的记忆。","pinyin":"Zhè shì wǒ zuì měihǎo de jìyì.","vn":"Đây là kỷ niệm đẹp nhất của tôi."},{"cn":"他的记忆力特别好。","pinyin":"Tā de jìyìlì tèbié hǎo.","vn":"Trí nhớ của anh ấy đặc biệt tốt."},{"cn":"那段记忆让她一直难忘。","pinyin":"Nà duàn jìyì ràng tā yìzhí nánwàng.","vn":"Đoạn kỷ niệm đó khiến cô mãi không quên."}]},{"hanzi":"已","pinyin":"yǐ","pos":"phó.","vn":"đã","examples":[{"cn":"他已人到中年，还是很喜欢过年。","pinyin":"Tā yǐ rén dào zhōngnián, háishi hěn xǐhuan guònián.","vn":"Anh ấy đã bước vào tuổi trung niên, vẫn rất thích ăn Tết."},{"cn":"时间已不早了，我们该走了。","pinyin":"Shíjiān yǐ bù zǎo le, wǒmen gāi zǒu le.","vn":"Thời gian đã không còn sớm, chúng ta nên đi rồi."},{"cn":"他已离开这个城市很多年了。","pinyin":"Tā yǐ líkāi zhège chéngshì hěn duō nián le.","vn":"Anh ấy đã rời khỏi thành phố này nhiều năm rồi."}]},{"hanzi":"中年","pinyin":"zhōngnián","pos":"dt.","vn":"tuổi trung niên","examples":[{"cn":"他现在已人到中年。","pinyin":"Tā xiànzài yǐ rén dào zhōngnián.","vn":"Anh ấy giờ đã bước vào tuổi trung niên."},{"cn":"中年人的生活压力一般比较大。","pinyin":"Zhōngnián rén de shēnghuó yālì yìbān bǐjiào dà.","vn":"Người trung niên thường có áp lực sống khá lớn."},{"cn":"他是一位中年男子。","pinyin":"Tā shì yí wèi zhōngnián nánzǐ.","vn":"Anh ấy là một người đàn ông trung niên."}]},{"hanzi":"仍然","pinyin":"réngrán","pos":"phó.","vn":"vẫn","examples":[{"cn":"春节仍然是我最喜欢的节日。","pinyin":"Chūnjié réngrán shì wǒ zuì xǐhuan de jiérì.","vn":"Tết Nguyên đán vẫn là ngày lễ tôi yêu thích nhất."},{"cn":"虽然离开家很久了，他仍然想着父母。","pinyin":"Suīrán líkāi jiā hěn jiǔ le, tā réngrán xiǎngzhe fùmǔ.","vn":"Dù đã xa nhà rất lâu, anh ấy vẫn luôn nhớ đến cha mẹ."},{"cn":"她仍然记得童年的那些事。","pinyin":"Tā réngrán jìde tóngnián de nàxiē shì.","vn":"Cô ấy vẫn nhớ những việc thời thơ ấu."}]},{"hanzi":"兄弟","pinyin":"xiōngdì","pos":"dt.","vn":"anh em","examples":[{"cn":"过节时更想父母、兄弟姐妹。","pinyin":"Guòjié shí gèng xiǎng fùmǔ, xiōngdì jiěmèi.","vn":"Khi đến ngày lễ càng nhớ cha mẹ, anh chị em."},{"cn":"他们俩从小就是好兄弟。","pinyin":"Tāmen liǎ cóngxiǎo jiùshì hǎo xiōngdì.","vn":"Hai người họ từ nhỏ đã là anh em tốt."},{"cn":"我有两个兄弟。","pinyin":"Wǒ yǒu liǎng ge xiōngdì.","vn":"Tôi có hai anh em trai."}]}],"proper_nouns":[{"hanzi":"东北虎","pinyin":"Dōngběihǔ","vn":"Hổ Siberia (Hổ Đông Bắc)"},{"hanzi":"北京野生动物园","pinyin":"Běijīng Yěshēng Dòngwùyuán","vn":"Vườn thú hoang dã Bắc Kinh"},{"hanzi":"中秋节","pinyin":"Zhōngqiūjié","vn":"Tết Trung thu"},{"hanzi":"加拿大","pinyin":"Jiānádà","vn":"Canada"},{"hanzi":"元宵节","pinyin":"Yuánxiāojié","vn":"Tết Nguyên Tiêu"},{"hanzi":"端午节","pinyin":"Duānwǔjié","vn":"Tết Đoan Ngọ"},{"hanzi":"除夕","pinyin":"Chúxī","vn":"Đêm giao thừa (Trừ tịch)"},{"hanzi":"春晚","pinyin":"Chūnwǎn","vn":"Gala mừng xuân (Xuân Vãn)"}],"grammar":[{"title":"固定格式\"怎么都/也+不/没……\"","explanation_vn":"Cấu trúc cố định \"怎么都/也+不/没……\" biểu thị dù dùng mọi cách cũng không đạt được kết quả nào đó, có khi còn dùng để biểu thị sự ngạc nhiên, không ngờ tới.","examples":[{"cn":"我知道北京野生动物园很大，可怎么也没想到这么大！","pinyin":"","vn":"Tôi biết Vườn thú hoang dã Bắc Kinh rất lớn, nhưng không ngờ lại lớn đến thế!"},{"cn":"她在包里找了半天，怎么都没找到，真奇怪。","pinyin":"","vn":"Cô ấy tìm trong túi mãi, mà tìm thế nào cũng không thấy, thật lạ."},{"cn":"我们想看那只熊猫，在动物园等了两个多小时，可是它怎么都不出来。","pinyin":"","vn":"Chúng tôi muốn xem con gấu trúc đó, đã đợi ở sở thú hơn hai giờ, nhưng nó thế nào cũng không ra."}]},{"title":"固定格式\"一+量词+比+一+量词\"","explanation_vn":"Cấu trúc cố định \"一+lượng từ+比+一+lượng từ\" biểu thị sự so sánh. Hai hoặc nhiều sự vật được so sánh với nhau, nhấn mạnh cái sau có mức độ sâu hơn cái trước. Thường kết hợp với tính từ, tạo thành cấu trúc \"一+lượng từ+比+一+lượng từ+tính từ\".","examples":[{"cn":"在中国，每年中秋节都会举办很多活动，而且这几年一年比一年热闹。","pinyin":"","vn":"Ở Trung Quốc, mỗi năm Tết Trung thu đều tổ chức nhiều hoạt động, mà mấy năm nay năm nào cũng náo nhiệt hơn năm trước."},{"cn":"夏天快到了，天气也一天比一天热。","pinyin":"","vn":"Mùa hè gần đến rồi, thời tiết cũng mỗi ngày một nóng hơn."},{"cn":"这家店里的杯子一个比一个漂亮，我都不知道选哪个了。","pinyin":"","vn":"Những chiếc cốc trong tiệm này cái nào cũng đẹp hơn cái trước, tôi không biết chọn cái nào nữa."}]},{"title":"用\"大约\"\"左右\"表示概数","explanation_vn":"\"大约\" và \"左右\" biểu thị sự ước chừng, không chắc chắn, có nhiều cách dùng, trong bài này dùng trước hoặc sau từ chỉ thời gian để biểu thị số lượng ước chừng về thời gian. \"大约\" đặt trước từ chỉ thời gian, \"左右\" đặt sau từ chỉ thời gian.","examples":[{"cn":"早上五点左右他们就坐上了高铁，大约七点就来到了儿子工作的城市。","pinyin":"","vn":"Khoảng năm giờ sáng họ đã lên tàu cao tốc, khoảng bảy giờ đã đến thành phố nơi con trai làm việc."},{"cn":"我中午十二点左右到你们学校，和大家一起去食堂吃饭。","pinyin":"","vn":"Khoảng mười hai giờ trưa tôi sẽ đến trường các bạn, cùng mọi người đi nhà ăn."},{"cn":"昨天飞机晚点，我晚上大约十点半才到家。","pinyin":"","vn":"Hôm qua máy bay trễ giờ, khoảng mười giờ rưỡi tối tôi mới về đến nhà."}]},{"title":"介词\"作为\"","explanation_vn":"Giới từ \"作为\" biểu thị một thân phận nào đó của người hoặc một tính chất nào đó của sự vật, nó không thể đứng một mình làm thành phần câu, phải kết hợp với từ ngữ phía sau.","examples":[{"cn":"作为一年里最重要的传统节日，春节对中国人来说有着特别的意义。","pinyin":"","vn":"Là ngày lễ truyền thống quan trọng nhất trong năm, Tết Nguyên đán có ý nghĩa đặc biệt đối với người Trung Quốc."},{"cn":"作为新产品，这个手机不仅样子好看，价格也不高。","pinyin":"","vn":"Là một sản phẩm mới, chiếc điện thoại này không chỉ có kiểu dáng đẹp mà giá cũng không cao."},{"cn":"作为好朋友，我们一直互相关心、互相帮助。","pinyin":"","vn":"Là những người bạn tốt, chúng tôi luôn quan tâm và giúp đỡ nhau."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘小明","cn":"爸爸、妈妈，快看，熊和老虎都在这儿呢！","pinyin":""},{"speaker":"王一雪","cn":"小明，注意安全，不要一直大喊！","pinyin":""},{"speaker":"刘明","cn":"你们看，那个叫东北虎，是国家一级保护动物。那边树林里还有很多动物呢。","pinyin":""},{"speaker":"刘小明","cn":"咱们都能看到吧？","pinyin":""},{"speaker":"王一雪","cn":"对。景区的车每到一个动物区都会停一会儿，让人们能近距离看看这些动物。","pinyin":""},{"speaker":"刘明","cn":"真不错，这景区真大、真美！我知道北京野生动物园很大，可怎么也没想到这么大！","pinyin":""},{"speaker":"王一雪","cn":"这里有几千只动物呢，能不大吗？现在是节假日，人多。小明，一会儿千万别跑丢了，我可不是开玩笑呢。","pinyin":""}],"translation_vn":"Lưu Tiểu Minh: Bố, mẹ, nhìn nhanh, gấu và hổ đều ở đây này!\nVương Nhất Tuyết: Tiểu Minh, chú ý an toàn, đừng cứ hò hét!\nLưu Minh: Các con xem, con đó gọi là hổ Đông Bắc, là động vật được bảo vệ cấp quốc gia hạng một. Đằng kia trong rừng cây còn có nhiều động vật nữa.\nLưu Tiểu Minh: Chúng ta đều có thể nhìn thấy hết chứ?\nVương Nhất Tuyết: Đúng vậy. Xe của khu du lịch mỗi lần đến một khu động vật đều sẽ dừng một lúc, để mọi người có thể nhìn gần những con vật này.\nLưu Minh: Thật tuyệt, khu du lịch này thật lớn, thật đẹp! Bố biết Vườn thú hoang dã Bắc Kinh rất lớn, nhưng không ngờ lại lớn đến thế!\nVương Nhất Tuyết: Ở đây có đến mấy nghìn con động vật, sao mà không lớn được? Giờ đang là ngày lễ, người đông. Tiểu Minh, lúc nữa nhất định đừng chạy đi lạc đấy, mẹ không đùa đâu.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"刘明一家去北京野生动物园的哪个区看动物？他们看到了什么？","q_vn":"Gia đình Lưu Minh đến khu nào của Vườn thú hoang dã Bắc Kinh để xem động vật? Họ đã nhìn thấy gì？","a_cn":"他们先去了猛兽区，看到了熊和东北虎等动物。","a_vn":"Họ đã đến khu thú dữ trước, nhìn thấy gấu, hổ Đông Bắc và các động vật khác."},{"q_cn":"景区的车是怎么安排游客看动物的？","q_vn":"Xe của khu du lịch bố trí cho khách du lịch xem động vật như thế nào？","a_cn":"景区的车每到一个动物区都会停一会儿，让人们能近距离看看这些动物。","a_vn":"Xe của khu du lịch mỗi lần đến một khu động vật đều dừng lại một lúc, để mọi người có thể nhìn gần những con vật này."},{"q_cn":"王一雪为什么提醒小明别跑丢了？","q_vn":"Vì sao Vương Nhất Tuyết nhắc Tiểu Minh đừng chạy đi lạc？","a_cn":"因为当时是节假日，景区里人很多，她担心小明走丢，所以特别提醒他注意安全。","a_vn":"Vì lúc đó là ngày lễ, trong khu du lịch rất đông người, cô lo Tiểu Minh bị lạc nên đặc biệt nhắc cậu chú ý an toàn."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞","cn":"来，大家快吃月饼，这儿还有葡萄、西瓜。","pinyin":""},{"speaker":"杨同乐","cn":"这是今年的新茶，你们也尝尝。","pinyin":""},{"speaker":"陈天中","cn":"好的。这茶闻着真香！","pinyin":""},{"speaker":"白家月","cn":"我还是第一次在中国过中秋节呢。","pinyin":""},{"speaker":"安妮","cn":"我在加拿大时和中国朋友一起过过中秋节。我记得那天，外面的街道、剧院有很多演出活动。","pinyin":""},{"speaker":"王一飞","cn":"在中国，每年中秋节都会举办很多活动，而且这几年一年比一年热闹。对了，家月，今天是李文爷爷的生日，李文来不了了，你就多吃一块月饼吧。","pinyin":""},{"speaker":"白家月","cn":"谢谢，那我就不客气了。","pinyin":""},{"speaker":"杨同乐","cn":"中秋节和生日赶在了一块儿，真巧、真好！中秋节多陪陪家人也是应该的。","pinyin":""}],"translation_vn":"Vương Nhất Phi: Nào, mọi người ăn bánh trung thu nhanh đi, đây còn có nho, dưa hấu.\nDương Đồng Lạc: Đây là trà mới của năm nay, mọi người cũng nếm thử xem.\nTrần Thiên Trung: Được. Trà này ngửi thơm thật!\nBạch Gia Nguyệt: Đây là lần đầu tiên mình đón Tết Trung thu ở Trung Quốc đấy.\nAnnie: Khi ở Canada mình đã từng đón Tết Trung thu cùng bạn Trung Quốc. Mình nhớ ngày đó, ngoài đường phố, nhà hát có rất nhiều hoạt động biểu diễn.\nVương Nhất Phi: Ở Trung Quốc, mỗi năm Tết Trung thu đều tổ chức nhiều hoạt động, mà mấy năm nay năm nào cũng náo nhiệt hơn. À đúng rồi, Gia Nguyệt, hôm nay là sinh nhật ông của Lý Văn, Lý Văn không đến được, cậu ăn thêm một miếng bánh trung thu đi.\nBạch Gia Nguyệt: Cảm ơn, vậy mình không khách sáo nữa.\nDương Đồng Lạc: Tết Trung thu và sinh nhật trùng vào đúng một ngày, thật trùng hợp, thật tuyệt! Tết Trung thu dành nhiều thời gian cho gia đình cũng là điều nên làm.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"这次聚会大家一起过的是什么节日？他们准备了哪些食物？","q_vn":"Buổi tụ họp lần này mọi người cùng đón ngày lễ gì? Họ đã chuẩn bị những món ăn gì？","a_cn":"大家一起过中秋节，准备了月饼、葡萄、西瓜和新茶。","a_vn":"Mọi người cùng đón Tết Trung thu, đã chuẩn bị bánh trung thu, nho, dưa hấu và trà mới."},{"q_cn":"安妮在加拿大是怎么过中秋节的？","q_vn":"Annie đã đón Tết Trung thu ở Canada như thế nào？","a_cn":"她和中国朋友一起过中秋节，那天外面的街道、剧院有很多演出活动。","a_vn":"Cô đón Tết Trung thu cùng bạn Trung Quốc, ngày đó ngoài đường phố, nhà hát có rất nhiều hoạt động biểu diễn."},{"q_cn":"为什么杨同乐说“中秋节和生日赶在了一块儿，真巧、真好”？","q_vn":"Vì sao Dương Đồng Lạc nói \"Tết Trung thu và sinh nhật trùng vào đúng một ngày, thật trùng hợp, thật tuyệt\"？","a_cn":"因为这天正好是李文爷爷的生日，又赶上中秋节，一家人能多在一起，所以杨同乐这样说。","a_vn":"Vì ngày đó vừa đúng là sinh nhật ông của Lý Văn, lại trùng với Tết Trung thu, cả nhà được ở cùng nhau nhiều hơn, nên Dương Đồng Lạc nói vậy."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"中秋节时中国人一般都会回家过节。但是有些人由于工作需要，不能回家，只能一个人留在工作的地方过节。周力就是这些人之中的一位。他是一名铁路工作人员，今年中秋假期，要负责铁路安全检查。","pinyin":""},{"speaker":"","cn":"周力的父母知道儿子这次不能回家后，就决定来一次\"反向团圆\"。早上五点左右他们就坐上了高铁，大约七点就来到了儿子工作的城市。在儿子家，他们做了一桌儿子爱吃的饭菜，有烤肉、烤鱼、饺子等等，还有西红柿鸡蛋汤。周力下班回家，看到一桌子饭菜和突然出现的父母，他感觉特别幸福。","pinyin":""},{"speaker":"","cn":"这个中秋节，地点变了，但爱没变。","pinyin":""}],"translation_vn":"Vào Tết Trung thu, người Trung Quốc thường về nhà để đón lễ. Nhưng có một số người do yêu cầu công việc, không thể về nhà, chỉ có thể một mình ở lại nơi làm việc để đón lễ. Châu Lực chính là một trong số những người đó. Anh là một nhân viên đường sắt, Tết Trung thu năm nay, anh phải phụ trách kiểm tra an toàn đường sắt.\nSau khi biết con trai lần này không thể về nhà, cha mẹ Châu Lực quyết định làm một lần \"đoàn viên theo hướng ngược lại\". Khoảng năm giờ sáng họ đã lên tàu cao tốc, khoảng bảy giờ đã đến thành phố nơi con trai làm việc. Ở nhà con trai, họ đã làm một bàn những món ăn con trai thích, có thịt nướng, cá nướng, sủi cảo, v.v., còn có canh cà chua trứng. Châu Lực tan làm về nhà, nhìn thấy một bàn thức ăn và cha mẹ bất ngờ xuất hiện, anh cảm thấy vô cùng hạnh phúc.\nTết Trung thu năm nay, địa điểm đã thay đổi, nhưng tình yêu thương không thay đổi.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"周力为什么今年中秋节不能回家过节？","q_vn":"Vì sao Châu Lực năm nay không thể về nhà đón Tết Trung thu？","a_cn":"因为他是铁路工作人员，今年中秋假期要负责铁路安全检查，所以不能回家。","a_vn":"Vì anh là nhân viên đường sắt, kỳ nghỉ Trung thu năm nay phải phụ trách kiểm tra an toàn đường sắt, nên không thể về nhà."},{"q_cn":"周力的父母是怎么和儿子“团圆”的？","q_vn":"Cha mẹ Châu Lực đã \"đoàn viên\" với con trai như thế nào？","a_cn":"他们早上五点左右坐上高铁，大约七点到了儿子工作的城市，来到儿子家为他做了一桌爱吃的饭菜。","a_vn":"Họ khoảng năm giờ sáng lên tàu cao tốc, khoảng bảy giờ đến thành phố nơi con trai làm việc, đến nhà con trai làm cho anh một bàn thức ăn anh thích."},{"q_cn":"周力看到父母出现在家里时的心情是怎样的？","q_vn":"Tâm trạng của Châu Lực khi nhìn thấy cha mẹ xuất hiện ở nhà là như thế nào？","a_cn":"他看到一桌子饭菜和突然出现的父母，感觉特别幸福。","a_vn":"Anh nhìn thấy một bàn thức ăn và cha mẹ bất ngờ xuất hiện, cảm thấy vô cùng hạnh phúc."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"中国有很多节日，比如春节、元宵节、端午节、中秋节等。","pinyin":""},{"speaker":"","cn":"作为一年里最重要的传统节日，春节对中国人来说有着特别的意义。春节到来时，人们不管在哪里，都想回家过年。春节前也最忙，既要收拾房子、打扫卫生，又要准备各种美食。除夕这天晚上，一家人一边吃年夜饭，一边看春晚。零点一到，大家互相祝新年快乐，到处都是幸福的笑声。","pinyin":""},{"speaker":"","cn":"每当回忆起童年，我最美好的记忆很多也发生在过年时。虽然现在已人到中年，离开了家，但是春节仍然是我最喜欢的节日，过节时也更想父母、兄弟姐妹。","pinyin":""}],"translation_vn":"Trung Quốc có rất nhiều ngày lễ, ví dụ như Tết Nguyên đán, Tết Nguyên Tiêu, Tết Đoan Ngọ, Tết Trung thu, v.v.\nLà ngày lễ truyền thống quan trọng nhất trong năm, Tết Nguyên đán có ý nghĩa đặc biệt đối với người Trung Quốc. Khi Tết Nguyên đán đến, dù ở đâu, người ta đều muốn về nhà ăn Tết. Trước Tết cũng là lúc bận rộn nhất, vừa phải dọn dẹp nhà cửa, lau chùi vệ sinh, vừa phải chuẩn bị các loại món ăn ngon. Tối hôm trừ tịch, cả nhà vừa ăn bữa cơm giao thừa vừa xem Gala mừng xuân. Vừa đến giao thừa (0 giờ), mọi người chúc nhau năm mới vui vẻ, khắp nơi đều là tiếng cười hạnh phúc.\nMỗi khi nhớ lại thời thơ ấu, rất nhiều kỷ niệm đẹp nhất của tôi cũng xảy ra vào lúc ăn Tết. Dù hiện nay đã bước vào tuổi trung niên, đã xa nhà, nhưng Tết Nguyên đán vẫn là ngày lễ tôi yêu thích nhất, khi đến ngày lễ tôi càng nhớ cha mẹ, anh chị em.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"春节前人们一般要做哪些准备？","q_vn":"Trước Tết Nguyên đán người ta thường phải chuẩn bị những gì？","a_cn":"春节前人们既要收拾房子、打扫卫生，又要准备各种美食。","a_vn":"Trước Tết người ta vừa phải dọn dẹp nhà cửa, lau chùi vệ sinh, vừa phải chuẩn bị các loại món ăn ngon."},{"q_cn":"除夕晚上，一家人一般会做什么？","q_vn":"Tối trừ tịch, cả nhà thường làm gì？","a_cn":"除夕晚上，一家人一边吃年夜饭，一边看春晚，零点一到还会互相祝新年快乐。","a_vn":"Tối trừ tịch, cả nhà vừa ăn bữa cơm giao thừa vừa xem Gala mừng xuân, vừa đến giao thừa còn chúc nhau năm mới vui vẻ."},{"q_cn":"作者现在人到中年，为什么仍然很喜欢春节？","q_vn":"Hiện nay tác giả đã bước vào tuổi trung niên, vì sao vẫn rất yêu thích Tết Nguyên đán？","a_cn":"因为春节承载着他童年最美好的记忆，过节时让他更想念父母和兄弟姐妹，所以他仍然最喜欢春节。","a_vn":"Vì Tết Nguyên đán mang trong mình những kỷ niệm đẹp nhất thời thơ ấu của anh, khi đến ngày lễ khiến anh càng nhớ cha mẹ và anh chị em, nên anh vẫn yêu thích Tết Nguyên đán nhất."}]}]},{"id":14,"title_cn":"合适才买","title_pinyin":"","title_vn":"Phù hợp mới mua","goals":["Có thể nghe hiểu và trao đổi các thông tin liên quan đến giảm giá, so sánh hàng hóa khi mua sắm trực tiếp.","Có thể trình bày bằng lời hoặc văn bản về nguyện vọng mua hàng.","Hiểu được quan niệm tiêu dùng của người Trung Quốc."],"vocab":[{"hanzi":"茶叶","pinyin":"cháyè","pos":"dt.","vn":"lá trà, trà","examples":[{"cn":"这里的茶叶种类很多。","pinyin":"Zhèlǐ de cháyè zhǒnglèi hěn duō.","vn":"Lá trà ở đây có nhiều loại."},{"cn":"他送了朋友一盒茶叶。","pinyin":"Tā sòngle péngyou yì hé cháyè.","vn":"Anh ấy tặng bạn một hộp trà."},{"cn":"这种茶叶闻起来很香。","pinyin":"Zhè zhǒng cháyè wén qǐlái hěn xiāng.","vn":"Loại trà này ngửi rất thơm."}]},{"hanzi":"究竟","pinyin":"jiūjìng","pos":"phó.","vn":"rốt cuộc","examples":[{"cn":"这里茶叶这么多，究竟买哪种好呢？","pinyin":"Zhèlǐ cháyè zhème duō, jiūjìng mǎi nǎ zhǒng hǎo ne?","vn":"Trà ở đây nhiều như vậy, rốt cuộc nên mua loại nào?"},{"cn":"你究竟想不想去？","pinyin":"Nǐ jiūjìng xiǎng bu xiǎng qù?","vn":"Rốt cuộc bạn có muốn đi không?"},{"cn":"这件事究竟是怎么发生的？","pinyin":"Zhè jiàn shì jiūjìng shì zěnme fāshēng de?","vn":"Việc này rốt cuộc đã xảy ra như thế nào?"}]},{"hanzi":"分为","pinyin":"fēnwéi","pos":"dgt.","vn":"chia thành","examples":[{"cn":"茶叶主要分为红茶、绿茶等。","pinyin":"Cháyè zhǔyào fēnwéi hóngchá, lǜchá děng.","vn":"Trà chủ yếu chia thành hồng trà, lục trà, v.v."},{"cn":"这个课程分为三个部分。","pinyin":"Zhège kèchéng fēnwéi sān ge bùfen.","vn":"Khóa học này chia thành ba phần."},{"cn":"商品可以分为很多种类。","pinyin":"Shāngpǐn kěyǐ fēnwéi hěn duō zhǒnglèi.","vn":"Hàng hóa có thể chia thành nhiều loại."}]},{"hanzi":"抱歉","pinyin":"bàoqiàn","pos":"tt.","vn":"xin lỗi, lấy làm tiếc","examples":[{"cn":"抱歉，这种绿茶暂时没有了。","pinyin":"Bàoqiàn, zhè zhǒng lǜchá zànshí méiyǒu le.","vn":"Xin lỗi, loại lục trà này tạm thời hết rồi."},{"cn":"真抱歉，让你等了这么久。","pinyin":"Zhēn bàoqiàn, ràng nǐ děngle zhème jiǔ.","vn":"Thật xin lỗi vì để bạn đợi lâu như vậy."},{"cn":"他为自己的迟到感到很抱歉。","pinyin":"Tā wèi zìjǐ de chídào gǎndào hěn bàoqiàn.","vn":"Anh ấy cảm thấy rất xin lỗi vì mình đến muộn."}]},{"hanzi":"暂时","pinyin":"zànshí","pos":"tt.","vn":"tạm thời","examples":[{"cn":"这种茶暂时没有货。","pinyin":"Zhè zhǒng chá zànshí méiyǒu huò.","vn":"Loại trà này tạm thời không có hàng."},{"cn":"这个问题我们暂时先放一放。","pinyin":"Zhège wèntí wǒmen zànshí xiān fàng yi fàng.","vn":"Vấn đề này chúng ta tạm thời gác lại trước."},{"cn":"他暂时还不能回答这个问题。","pinyin":"Tā zànshí hái bùnéng huídá zhège wèntí.","vn":"Anh ấy tạm thời chưa thể trả lời vấn đề này."}]},{"hanzi":"满","pinyin":"mǎn","pos":"dgt./tt.","vn":"đầy, đạt đến (mức)","examples":[{"cn":"今天满二两送半两。","pinyin":"Jīntiān mǎn èr liǎng sòng bàn liǎng.","vn":"Hôm nay mua đủ hai lạng tặng thêm nửa lạng."},{"cn":"这个杯子已经满了。","pinyin":"Zhège bēizi yǐjīng mǎn le.","vn":"Cái cốc này đã đầy rồi."},{"cn":"满一百元就可以免运费。","pinyin":"Mǎn yìbǎi yuán jiù kěyǐ miǎn yùnfèi.","vn":"Đủ một trăm đồng thì được miễn phí vận chuyển."}]},{"hanzi":"两","pinyin":"liǎng","pos":"lượng.","vn":"lạng (50g)","examples":[{"cn":"我想买六两这种绿茶。","pinyin":"Wǒ xiǎng mǎi liù liǎng zhè zhǒng lǜchá.","vn":"Tôi muốn mua sáu lạng loại lục trà này."},{"cn":"这个茶一共三两。","pinyin":"Zhège chá yígòng sān liǎng.","vn":"Trà này tổng cộng ba lạng."},{"cn":"他每次只买二两茶叶。","pinyin":"Tā měi cì zhǐ mǎi èr liǎng cháyè.","vn":"Mỗi lần anh ấy chỉ mua hai lạng trà."}]},{"hanzi":"超过","pinyin":"chāoguò","pos":"dgt.","vn":"vượt quá","examples":[{"cn":"超过半斤再送小礼物。","pinyin":"Chāoguò bàn jīn zài sòng xiǎo lǐwù.","vn":"Vượt quá nửa cân thì tặng thêm món quà nhỏ."},{"cn":"这次活动参加的人数超过了一百人。","pinyin":"Zhè cì huódòng cānjiā de rénshù chāoguòle yìbǎi rén.","vn":"Số người tham gia hoạt động lần này vượt quá một trăm người."},{"cn":"他的成绩超过了我们所有人。","pinyin":"Tā de chéngjì chāoguòle wǒmen suǒyǒu rén.","vn":"Thành tích của anh ấy vượt qua tất cả chúng tôi."}]},{"hanzi":"盒子","pinyin":"hézi","pos":"dt.","vn":"cái hộp","examples":[{"cn":"她买了一个盒子来装茶叶。","pinyin":"Tā mǎile yí ge hézi lái zhuāng cháyè.","vn":"Cô ấy mua một cái hộp để đựng trà."},{"cn":"这个盒子里装的是月饼。","pinyin":"Zhège hézi lǐ zhuāng de shì yuèbing.","vn":"Trong hộp này đựng bánh trung thu."},{"cn":"他把钥匙放进了盒子里。","pinyin":"Tā bǎ yàoshi fàng jìnle hézi lǐ.","vn":"Anh ấy đã để chìa khóa vào hộp."}]},{"hanzi":"装","pinyin":"zhuāng","pos":"dgt.","vn":"đóng, đựng, lắp","examples":[{"cn":"请帮我分着装进盒子里。","pinyin":"Qǐng bāng wǒ fēnzhe zhuāng jìn hézi lǐ.","vn":"Xin hãy giúp tôi chia ra đóng vào hộp."},{"cn":"这些书太多了，装不进这个箱子。","pinyin":"Zhèxiē shū tài duō le, zhuāng bú jìn zhège xiāngzi.","vn":"Những cuốn sách này nhiều quá, không đựng hết vào cái hộp này."},{"cn":"他把行李都装好了。","pinyin":"Tā bǎ xíngli dōu zhuānghǎo le.","vn":"Anh ấy đã đóng gói xong hành lý."}]},{"hanzi":"各位","pinyin":"gèwèi","pos":"đt.","vn":"các vị, mọi người","examples":[{"cn":"各位顾客请注意。","pinyin":"Gèwèi gùkè qǐng zhùyì.","vn":"Xin các vị khách hàng chú ý."},{"cn":"各位，欢迎来到我们商场。","pinyin":"Gèwèi, huānyíng lái dào wǒmen shāngchǎng.","vn":"Xin chào các vị, hoan nghênh đến với trung tâm thương mại của chúng tôi."},{"cn":"感谢各位的支持。","pinyin":"Gǎnxiè gèwèi de zhīchí.","vn":"Xin cảm ơn sự ủng hộ của các vị."}]},{"hanzi":"顾客","pinyin":"gùkè","pos":"dt.","vn":"khách hàng","examples":[{"cn":"这家店的顾客特别多。","pinyin":"Zhè jiā diàn de gùkè tèbié duō.","vn":"Cửa hàng này có rất nhiều khách hàng."},{"cn":"售货员对顾客很有礼貌。","pinyin":"Shòuhuòyuán duì gùkè hěn yǒu lǐmào.","vn":"Nhân viên bán hàng rất lễ phép với khách hàng."},{"cn":"很多顾客都喜欢这个牌子。","pinyin":"Hěn duō gùkè dōu xǐhuan zhège páizi.","vn":"Rất nhiều khách hàng thích nhãn hiệu này."}]},{"hanzi":"本","pinyin":"běn","pos":"đt.","vn":"này, của mình (bản thân)","examples":[{"cn":"本商场正在举办促销活动。","pinyin":"Běn shāngchǎng zhèngzài jǔbàn cùxiāo huódòng.","vn":"Trung tâm thương mại này đang tổ chức hoạt động khuyến mại."},{"cn":"本店今天全场打五折。","pinyin":"Běn diàn jīntiān quánchǎng dǎ wǔ zhé.","vn":"Cửa hàng này hôm nay toàn bộ giảm giá còn 50%."},{"cn":"本公司欢迎各位前来参观。","pinyin":"Běn gōngsī huānyíng gèwèi qián lái cānguān.","vn":"Công ty này hoan nghênh mọi người đến tham quan."}]},{"hanzi":"假日","pinyin":"jiàrì","pos":"dt.","vn":"ngày nghỉ, ngày lễ","examples":[{"cn":"商场正举办假日促销活动。","pinyin":"Shāngchǎng zhèng jǔbàn jiàrì cùxiāo huódòng.","vn":"Trung tâm thương mại đang tổ chức hoạt động khuyến mại ngày nghỉ."},{"cn":"假日里商场人特别多。","pinyin":"Jiàrì lǐ shāngchǎng rén tèbié duō.","vn":"Vào ngày nghỉ trung tâm thương mại rất đông người."},{"cn":"他打算假日去旅行。","pinyin":"Tā dǎsuàn jiàrì qù lǚxíng.","vn":"Anh ấy định đi du lịch vào ngày nghỉ."}]},{"hanzi":"低价","pinyin":"dījià","pos":"dt.","vn":"giá thấp","examples":[{"cn":"本商场正举办运动鞋低价促销活动。","pinyin":"Běn shāngchǎng zhèng jǔbàn yùndòngxié dījià cùxiāo huódòng.","vn":"Trung tâm thương mại này đang tổ chức khuyến mại giá thấp cho giày thể thao."},{"cn":"他喜欢买低价的东西。","pinyin":"Tā xǐhuan mǎi dījià de dōngxi.","vn":"Anh ấy thích mua những thứ giá thấp."},{"cn":"这家店以低价吸引了很多顾客。","pinyin":"Zhè jiā diàn yǐ dījià xīyǐnle hěn duō gùkè.","vn":"Cửa hàng này thu hút nhiều khách hàng bằng giá thấp."}]},{"hanzi":"促销","pinyin":"cùxiāo","pos":"dgt.","vn":"khuyến mại, thúc đẩy bán hàng","examples":[{"cn":"商场正在举办促销活动。","pinyin":"Shāngchǎng zhèngzài jǔbàn cùxiāo huódòng.","vn":"Trung tâm thương mại đang tổ chức hoạt động khuyến mại."},{"cn":"促销期间商品价格会降低。","pinyin":"Cùxiāo qījiān shāngpǐn jiàgé huì jiàngdī.","vn":"Trong thời gian khuyến mại giá hàng hóa sẽ giảm."},{"cn":"很多顾客是为了促销活动才来的。","pinyin":"Hěn duō gùkè shì wèile cùxiāo huódòng cái lái de.","vn":"Nhiều khách hàng đến vì hoạt động khuyến mại."}]},{"hanzi":"广播","pinyin":"guǎngbō","pos":"dt./dgt.","vn":"phát thanh, loa thông báo","examples":[{"cn":"广播里说价格减了一半。","pinyin":"Guǎngbō lǐ shuō jiàgé jiǎnle yíbàn.","vn":"Loa phát thanh nói giá đã giảm một nửa."},{"cn":"他每天早上听广播。","pinyin":"Tā měitiān zǎoshang tīng guǎngbō.","vn":"Mỗi sáng anh ấy nghe radio."},{"cn":"广播员正在播报今天的活动安排。","pinyin":"Guǎngbōyuán zhèngzài bōbào jīntiān de huódòng ānpái.","vn":"Người phát thanh đang thông báo chương trình hoạt động hôm nay."}]},{"hanzi":"减","pinyin":"jiǎn","pos":"dgt.","vn":"giảm","examples":[{"cn":"这双鞋一双减三百块。","pinyin":"Zhè shuāng xié yì shuāng jiǎn sānbǎi kuài.","vn":"Đôi giày này mỗi đôi giảm ba trăm đồng."},{"cn":"价格已经减了不少。","pinyin":"Jiàgé yǐjīng jiǎnle bùshǎo.","vn":"Giá đã giảm khá nhiều."},{"cn":"老师给他减了一些作业。","pinyin":"Lǎoshī gěi tā jiǎnle yìxiē zuòyè.","vn":"Thầy giáo đã giảm cho anh ấy một ít bài tập."}]},{"hanzi":"广告","pinyin":"guǎnggào","pos":"dt.","vn":"quảng cáo","examples":[{"cn":"不能只听广告说什么。","pinyin":"Bùnéng zhǐ tīng guǎnggào shuō shénme.","vn":"Không thể chỉ nghe quảng cáo nói gì."},{"cn":"这个广告做得很有意思。","pinyin":"Zhège guǎnggào zuò de hěn yǒu yìsi.","vn":"Quảng cáo này làm rất thú vị."},{"cn":"她在电视上看到了这个产品的广告。","pinyin":"Tā zài diànshì shàng kàndàole zhège chǎnpǐn de guǎnggào.","vn":"Cô ấy xem quảng cáo sản phẩm này trên tivi."}]},{"hanzi":"首先","pinyin":"shǒuxiān","pos":"phó.","vn":"trước tiên","examples":[{"cn":"首先看样子喜不喜欢。","pinyin":"Shǒuxiān kàn yàngzi xǐ bu xǐhuan.","vn":"Trước tiên xem kiểu dáng có thích không."},{"cn":"首先，我们要感谢大家的支持。","pinyin":"Shǒuxiān, wǒmen yào gǎnxiè dàjiā de zhīchí.","vn":"Trước tiên, chúng tôi muốn cảm ơn sự ủng hộ của mọi người."},{"cn":"做这件事首先要有耐心。","pinyin":"Zuò zhè jiàn shì shǒuxiān yào yǒu nàixīn.","vn":"Làm việc này trước tiên phải có sự kiên nhẫn."}]},{"hanzi":"牌子","pinyin":"páizi","pos":"dt.","vn":"nhãn hiệu, thương hiệu","examples":[{"cn":"这个牌子质量很好。","pinyin":"Zhège páizi zhìliàng hěn hǎo.","vn":"Nhãn hiệu này chất lượng rất tốt."},{"cn":"我一直用这个牌子的手机。","pinyin":"Wǒ yìzhí yòng zhège páizi de shǒujī.","vn":"Tôi vẫn luôn dùng điện thoại của nhãn hiệu này."},{"cn":"她喜欢买有名的牌子。","pinyin":"Tā xǐhuan mǎi yǒumíng de páizi.","vn":"Cô ấy thích mua những nhãn hiệu nổi tiếng."}]},{"hanzi":"降价","pinyin":"jiàngjià","pos":"dgt.","vn":"giảm giá","examples":[{"cn":"这双鞋今天又降价了。","pinyin":"Zhè shuāng xié jīntiān yòu jiàngjià le.","vn":"Đôi giày này hôm nay lại giảm giá nữa."},{"cn":"商场年底经常降价促销。","pinyin":"Shāngchǎng niándǐ jīngcháng jiàngjià cùxiāo.","vn":"Cuối năm trung tâm thương mại thường giảm giá khuyến mại."},{"cn":"这个产品降价以后卖得特别好。","pinyin":"Zhège chǎnpǐn jiàngjià yǐhòu mài de tèbié hǎo.","vn":"Sản phẩm này sau khi giảm giá bán rất tốt."}]},{"hanzi":"样式","pinyin":"yàngshì","pos":"dt.","vn":"kiểu dáng","examples":[{"cn":"这个鞋的样式很新。","pinyin":"Zhège xié de yàngshì hěn xīn.","vn":"Kiểu dáng của đôi giày này rất mới."},{"cn":"她喜欢简单的样式。","pinyin":"Tā xǐhuan jiǎndān de yàngshì.","vn":"Cô ấy thích kiểu dáng đơn giản."},{"cn":"这家店的衣服样式很多。","pinyin":"Zhè jiā diàn de yīfu yàngshì hěn duō.","vn":"Cửa hàng này có rất nhiều kiểu dáng áo."}]},{"hanzi":"价钱","pinyin":"jiàqián","pos":"dt.","vn":"giá cả","examples":[{"cn":"这个价钱不高。","pinyin":"Zhège jiàqián bù gāo.","vn":"Giá này không cao."},{"cn":"我们先问问价钱吧。","pinyin":"Wǒmen xiān wènwen jiàqián ba.","vn":"Chúng ta hỏi giá trước đi."},{"cn":"这双鞋的价钱挺合适的。","pinyin":"Zhè shuāng xié de jiàqián tǐng héshì de.","vn":"Giá của đôi giày này khá hợp lý."}]},{"hanzi":"商业","pinyin":"shāngyè","pos":"dt.","vn":"thương mại, kinh doanh","examples":[{"cn":"徐前在商业区开了一家小店。","pinyin":"Xú Qián zài shāngyè qū kāile yì jiā xiǎo diàn.","vn":"Từ Tiền mở một cửa hàng nhỏ ở khu thương mại."},{"cn":"这里是城市最大的商业中心。","pinyin":"Zhèlǐ shì chéngshì zuì dà de shāngyè zhōngxīn.","vn":"Đây là trung tâm thương mại lớn nhất của thành phố."},{"cn":"他对商业很感兴趣。","pinyin":"Tā duì shāngyè hěn gǎn xìngqù.","vn":"Anh ấy rất có hứng thú với kinh doanh."}]},{"hanzi":"商品","pinyin":"shāngpǐn","pos":"dt.","vn":"hàng hóa","examples":[{"cn":"这家店的商品种类不少。","pinyin":"Zhè jiā diàn de shāngpǐn zhǒnglèi bùshǎo.","vn":"Hàng hóa của cửa hàng này có không ít loại."},{"cn":"这些商品都是新到的。","pinyin":"Zhèxiē shāngpǐn dōu shì xīn dào de.","vn":"Những hàng hóa này đều mới về."},{"cn":"商场里的商品种类很丰富。","pinyin":"Shāngchǎng lǐ de shāngpǐn zhǒnglèi hěn fēngfù.","vn":"Hàng hóa trong trung tâm thương mại rất phong phú."}]},{"hanzi":"种类","pinyin":"zhǒnglèi","pos":"dt.","vn":"loại, chủng loại","examples":[{"cn":"这里的商品种类很多。","pinyin":"Zhèlǐ de shāngpǐn zhǒnglèi hěn duō.","vn":"Hàng hóa ở đây có rất nhiều loại."},{"cn":"水果的种类越来越丰富了。","pinyin":"Shuǐguǒ de zhǒnglèi yuèláiyuè fēngfù le.","vn":"Chủng loại trái cây ngày càng phong phú hơn."},{"cn":"这家图书馆的书种类齐全。","pinyin":"Zhè jiā túshūguǎn de shū zhǒnglèi qíquán.","vn":"Sách ở thư viện này có đủ các loại."}]},{"hanzi":"盲盒","pinyin":"mánghé","pos":"dt.","vn":"hộp mù (blind box)","examples":[{"cn":"最近流行的盲盒很吸引年轻人。","pinyin":"Zuìjìn liúxíng de mánghé hěn xīyǐn niánqīngrén.","vn":"Hộp mù đang thịnh hành gần đây rất thu hút các bạn trẻ."},{"cn":"她买了一个盲盒，不知道里面是什么。","pinyin":"Tā mǎile yí ge mánghé, bù zhīdào lǐmiàn shì shénme.","vn":"Cô ấy mua một hộp mù, không biết bên trong là gì."},{"cn":"这家店的盲盒卖得很快。","pinyin":"Zhè jiā diàn de mánghé mài de hěn kuài.","vn":"Hộp mù của cửa hàng này bán rất nhanh."}]},{"hanzi":"缺","pinyin":"quē","pos":"dgt.","vn":"thiếu","examples":[{"cn":"盲盒很快就卖到了缺货。","pinyin":"Mánghé hěn kuài jiù màidàole quēhuò.","vn":"Hộp mù rất nhanh đã bán đến mức thiếu hàng."},{"cn":"我们缺一个人手。","pinyin":"Wǒmen quē yí ge rénshǒu.","vn":"Chúng tôi thiếu một người làm."},{"cn":"这篇文章缺了一个重要的部分。","pinyin":"Zhè piān wénzhāng quēle yí ge zhòngyào de bùfen.","vn":"Bài viết này thiếu một phần quan trọng."}]},{"hanzi":"许多","pinyin":"xǔduō","pos":"số.","vn":"rất nhiều","examples":[{"cn":"许多年轻人喜欢逛这家店。","pinyin":"Xǔduō niánqīngrén xǐhuan guàng zhè jiā diàn.","vn":"Nhiều bạn trẻ thích đi dạo cửa hàng này."},{"cn":"他去过许多国家。","pinyin":"Tā qùguò xǔduō guójiā.","vn":"Anh ấy đã đi qua nhiều quốc gia."},{"cn":"这个问题有许多种答案。","pinyin":"Zhège wèntí yǒu xǔduō zhǒng dá'àn.","vn":"Vấn đề này có nhiều cách trả lời."}]},{"hanzi":"表示","pinyin":"biǎoshì","pos":"dgt.","vn":"biểu thị, cho biết","examples":[{"cn":"许多年轻人表示很喜欢这家店。","pinyin":"Xǔduō niánqīngrén biǎoshì hěn xǐhuan zhè jiā diàn.","vn":"Nhiều bạn trẻ cho biết rất thích cửa hàng này."},{"cn":"他表示会支持这个计划。","pinyin":"Tā biǎoshì huì zhīchí zhège jìhuà.","vn":"Anh ấy cho biết sẽ ủng hộ kế hoạch này."},{"cn":"老板对员工的努力表示感谢。","pinyin":"Lǎobǎn duì yuángōng de nǔlì biǎoshì gǎnxiè.","vn":"Ông chủ thể hiện lòng biết ơn đối với sự nỗ lực của nhân viên."}]},{"hanzi":"加上","pinyin":"jiāshàng","pos":"liên.","vn":"hơn nữa, thêm vào đó","examples":[{"cn":"东西适合年轻人，加上店员态度友好。","pinyin":"Dōngxi shìhé niánqīngrén, jiāshàng diànyuán tàidu yǒuhǎo.","vn":"Đồ hợp với người trẻ, thêm vào đó nhân viên thái độ thân thiện."},{"cn":"房租便宜，加上交通方便，很多人搬到这里住。","pinyin":"Fángzū piányi, jiāshàng jiāotōng fāngbiàn, hěn duō rén bāndào zhèlǐ zhù.","vn":"Tiền nhà rẻ, thêm vào đó giao thông thuận tiện, nhiều người dọn đến đây sống."},{"cn":"他很努力，加上运气好，最后成功了。","pinyin":"Tā hěn nǔlì, jiāshàng yùnqi hǎo, zuìhòu chénggōng le.","vn":"Anh ấy rất nỗ lực, thêm vào đó may mắn tốt, cuối cùng thành công."}]},{"hanzi":"态度","pinyin":"tàidù","pos":"dt.","vn":"thái độ","examples":[{"cn":"这家店店员的态度特别好。","pinyin":"Zhè jiā diàn diànyuán de tàidù tèbié hǎo.","vn":"Thái độ của nhân viên cửa hàng này đặc biệt tốt."},{"cn":"他对工作的态度很认真。","pinyin":"Tā duì gōngzuò de tàidù hěn rènzhēn.","vn":"Thái độ của anh ấy đối với công việc rất nghiêm túc."},{"cn":"良好的服务态度很重要。","pinyin":"Liánghǎo de fúwù tàidù hěn zhòngyào.","vn":"Thái độ phục vụ tốt rất quan trọng."}]},{"hanzi":"友好","pinyin":"yǒuhǎo","pos":"tt.","vn":"thân thiện","examples":[{"cn":"店员态度友好，顾客都很满意。","pinyin":"Diànyuán tàidu yǒuhǎo, gùkè dōu hěn mǎnyì.","vn":"Nhân viên thái độ thân thiện, khách hàng đều rất hài lòng."},{"cn":"他对每个人都很友好。","pinyin":"Tā duì měi ge rén dōu hěn yǒuhǎo.","vn":"Anh ấy đối xử thân thiện với mọi người."},{"cn":"两国关系一直很友好。","pinyin":"Liǎng guó guānxì yìzhí hěn yǒuhǎo.","vn":"Quan hệ giữa hai nước luôn rất hữu nghị."}]},{"hanzi":"使得","pinyin":"shǐde","pos":"dgt.","vn":"làm cho, khiến cho","examples":[{"cn":"店员态度友好，使得生意越来越好。","pinyin":"Diànyuán tàidu yǒuhǎo, shǐde shēngyi yuèláiyuè hǎo.","vn":"Nhân viên thái độ thân thiện, làm cho việc kinh doanh ngày càng tốt."},{"cn":"这个决定使得大家都很开心。","pinyin":"Zhège juédìng shǐde dàjiā dōu hěn kāixīn.","vn":"Quyết định này làm cho mọi người đều rất vui."},{"cn":"天气不好使得活动取消了。","pinyin":"Tiānqì bù hǎo shǐde huódòng qǔxiāo le.","vn":"Thời tiết không tốt khiến hoạt động bị hủy."}]},{"hanzi":"者","pinyin":"zhě","pos":"trợ.","vn":"người (làm việc gì)","examples":[{"cn":"他是一位冷静的购物者。","pinyin":"Tā shì yí wèi lěngjìng de gòuwù zhě.","vn":"Anh ấy là một người mua hàng bình tĩnh."},{"cn":"这篇文章的作者写得很好。","pinyin":"Zhè piān wénzhāng de zuòzhě xiě de hěn hǎo.","vn":"Tác giả của bài viết này viết rất tốt."},{"cn":"参与者需要提前报名。","pinyin":"Cānyùzhě xūyào tíqián bàomíng.","vn":"Người tham gia cần đăng ký trước."}]},{"hanzi":"仔细","pinyin":"zǐxì","pos":"tt.","vn":"cẩn thận, kỹ càng","examples":[{"cn":"买东西前要仔细比较质量和价格。","pinyin":"Mǎi dōngxi qián yào zǐxì bǐjiào zhìliàng hé jiàgé.","vn":"Trước khi mua đồ phải so sánh kỹ chất lượng và giá cả."},{"cn":"他仔细检查了每一件商品。","pinyin":"Tā zǐxì jiǎnchále měi yí jiàn shāngpǐn.","vn":"Anh ấy đã kiểm tra kỹ từng sản phẩm."},{"cn":"请仔细阅读说明书。","pinyin":"Qǐng zǐxì yuèdú shuōmíngshū.","vn":"Xin hãy đọc kỹ hướng dẫn sử dụng."}]},{"hanzi":"对于","pinyin":"duìyú","pos":"giới.","vn":"đối với","examples":[{"cn":"对于想买的东西，她不光看质量，还看价格。","pinyin":"Duìyú xiǎng mǎi de dōngxi, tā bùguāng kàn zhìliàng, hái kàn jiàgé.","vn":"Đối với những thứ muốn mua, cô ấy không chỉ xem chất lượng, còn xem giá cả."},{"cn":"对于这个问题，大家的看法不一样。","pinyin":"Duìyú zhège wèntí, dàjiā de kànfǎ bù yíyàng.","vn":"Đối với vấn đề này, mọi người có cách nhìn khác nhau."},{"cn":"对于年轻人来说，这个工作很有挑战性。","pinyin":"Duìyú niánqīngrén láishuō, zhège gōngzuò hěn yǒu tiǎozhànxìng.","vn":"Đối với người trẻ, công việc này rất có tính thử thách."}]},{"hanzi":"不光","pinyin":"bùguāng","pos":"liên./phó.","vn":"không chỉ","examples":[{"cn":"她不光看质量，还看价格。","pinyin":"Tā bùguāng kàn zhìliàng, hái kàn jiàgé.","vn":"Cô ấy không chỉ xem chất lượng, còn xem giá cả."},{"cn":"这个小店不光卖游戏机，还卖盲盒。","pinyin":"Zhège xiǎo diàn bùguāng mài yóuxìjī, hái mài mánghé.","vn":"Cửa hàng nhỏ này không chỉ bán máy chơi game, còn bán hộp mù."},{"cn":"他不光会说汉语，还会说英语。","pinyin":"Tā bùguāng huì shuō Hànyǔ, hái huì shuō Yīngyǔ.","vn":"Anh ấy không chỉ biết nói tiếng Trung, còn biết nói tiếng Anh."}]},{"hanzi":"外套","pinyin":"wàitào","pos":"dt.","vn":"áo khoác","examples":[{"cn":"她买了一件新外套。","pinyin":"Tā mǎile yí jiàn xīn wàitào.","vn":"Cô ấy mua một chiếc áo khoác mới."},{"cn":"天冷了，记得穿外套。","pinyin":"Tiān lěng le, jìde chuān wàitào.","vn":"Trời lạnh rồi, nhớ mặc áo khoác."},{"cn":"这件外套的样式很好看。","pinyin":"Zhè jiàn wàitào de yàngshì hěn hǎokàn.","vn":"Kiểu dáng của chiếc áo khoác này rất đẹp."}]},{"hanzi":"袜子","pinyin":"wàzi","pos":"dt.","vn":"vớ, tất","examples":[{"cn":"她买了一双袜子。","pinyin":"Tā mǎile yì shuāng wàzi.","vn":"Cô ấy mua một đôi vớ."},{"cn":"冬天要穿厚一点的袜子。","pinyin":"Dōngtiān yào chuān hòu yìdiǎn de wàzi.","vn":"Mùa đông phải mang vớ dày hơn."},{"cn":"这双袜子的颜色很特别。","pinyin":"Zhè shuāng wàzi de yánsè hěn tèbié.","vn":"Màu của đôi vớ này rất đặc biệt."}]}],"grammar":[{"title":"语气副词\"究竟\"","explanation_vn":"Phó từ ngữ khí \"究竟\" dùng trong câu hỏi, biểu thị sự truy hỏi đến cùng, mong muốn làm rõ sự thật.","examples":[{"cn":"这里茶叶这么多，究竟买哪种好呢？","pinyin":"","vn":"Trà ở đây nhiều như vậy, rốt cuộc nên mua loại nào đây?"},{"cn":"我一直没找到他，他究竟去哪里了呢？","pinyin":"","vn":"Tôi vẫn chưa tìm được anh ấy, rốt cuộc anh ấy đã đi đâu rồi?"},{"cn":"究竟是对还是错？我现在也不清楚。","pinyin":"","vn":"Rốt cuộc là đúng hay sai? Bây giờ tôi cũng không rõ."}]},{"title":"承接复句\"首先……，然后/其次……\"","explanation_vn":"Câu phức tiếp nối \"首先……，然后/其次……\" biểu thị trình tự trước sau hoặc sự phân biệt chính phụ.","examples":[{"cn":"首先看样子喜不喜欢，然后再看质量怎么样、价格合适不合适。","pinyin":"","vn":"Trước tiên xem kiểu dáng có thích không, sau đó mới xem chất lượng thế nào, giá cả có hợp lý không."},{"cn":"遇到问题，首先想想问题为什么出现，然后再积极想办法解决。","pinyin":"","vn":"Gặp vấn đề, trước tiên nghĩ xem vấn đề vì sao xuất hiện, sau đó mới tích cực tìm cách giải quyết."},{"cn":"请大家首先读一遍课文，然后根据课文完成课后练习。","pinyin":"","vn":"Mời mọi người trước tiên đọc một lượt bài khóa, sau đó dựa vào bài khóa hoàn thành bài tập sau bài."}]},{"title":"连词\"加上\"","explanation_vn":"Liên từ \"加上\" tiếp nối câu trước, biểu thị sự bổ sung thêm, câu sau sẽ nêu ra kết quả.","examples":[{"cn":"小店虽然小，但东西适合年轻人，加上店员态度友好，使得小店的生意越来越好。","pinyin":"","vn":"Cửa hàng nhỏ tuy nhỏ, nhưng đồ hợp với người trẻ, thêm vào đó nhân viên thái độ thân thiện, khiến việc kinh doanh của cửa hàng ngày càng tốt."},{"cn":"虽然这里是郊区，但周围交通很方便，加上房租便宜，所以很多年轻人都在这里租房子。","pinyin":"","vn":"Dù đây là vùng ngoại ô, nhưng giao thông xung quanh rất thuận tiện, thêm vào đó tiền nhà rẻ, nên rất nhiều người trẻ đều thuê nhà ở đây."},{"cn":"他很聪明，加上一直非常努力，所以最后考上了理想的大学。","pinyin":"","vn":"Anh ấy rất thông minh, thêm vào đó luôn nỗ lực không ngừng, nên cuối cùng đã thi đỗ vào trường đại học mơ ước."}]},{"title":"介词\"对于\"","explanation_vn":"Giới từ \"对于\" dùng để nêu ra đối tượng người, việc, vật cụ thể liên quan đến hành động.","examples":[{"cn":"对于想买的东西，她不光看质量，还看价格。","pinyin":"","vn":"Đối với những thứ muốn mua, cô ấy không chỉ xem chất lượng, còn xem giá cả."},{"cn":"对于他的做法，大家都很支持。","pinyin":"","vn":"Đối với cách làm của anh ấy, mọi người đều rất ủng hộ."},{"cn":"对于你们提的这个建议，我们一定好好研究。","pinyin":"","vn":"Đối với kiến nghị mà các bạn đưa ra, chúng tôi chắc chắn sẽ nghiên cứu kỹ."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"售货员","cn":"您要什么茶？","pinyin":""},{"speaker":"安妮","cn":"我先看看。这里茶叶这么多，究竟买哪种好呢？","pinyin":""},{"speaker":"售货员","cn":"茶叶主要分为红茶、绿茶等，看您喜欢喝哪种。","pinyin":""},{"speaker":"安妮","cn":"我想买一些自己喝，再买些送人。这种绿茶还有吗？","pinyin":""},{"speaker":"售货员","cn":"抱歉，暂时没有。如果自己喝，可以买这个绿茶，今天满二两送半两，超过半斤再送小礼物；如果是送人，可以买个盒子装进去。","pinyin":""},{"speaker":"安妮","cn":"嗯。那就先买六两这种绿茶吧，再买一个盒子。请帮我分着装，盒子里装半斤，剩下的用纸包一下就行。","pinyin":""}],"translation_vn":"Nhân viên bán hàng: Chị cần loại trà nào?\nAnnie: Tôi xem trước đã. Trà ở đây nhiều như vậy, rốt cuộc nên mua loại nào đây?\nNhân viên bán hàng: Trà chủ yếu chia thành hồng trà, lục trà, v.v., tùy chị thích uống loại nào.\nAnnie: Tôi muốn mua một ít để tự uống, rồi mua thêm chút để tặng người khác. Loại lục trà này còn không?\nNhân viên bán hàng: Xin lỗi, tạm thời hết rồi. Nếu để tự uống, có thể mua loại lục trà này, hôm nay mua đủ hai lạng tặng thêm nửa lạng, vượt quá nửa cân còn tặng thêm quà nhỏ; nếu để tặng người khác, có thể mua một cái hộp để đóng vào.\nAnnie: Ừm. Vậy tôi mua trước sáu lạng loại lục trà này, rồi mua thêm một cái hộp. Xin hãy giúp tôi chia ra đóng gói, trong hộp đóng nửa cân, phần còn lại dùng giấy gói lại là được.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"安妮去茶叶店买茶叶是为了什么？","q_vn":"Annie đến tiệm trà mua trà để làm gì？","a_cn":"她想买一些自己喝，再买一些送给别人。","a_vn":"Cô muốn mua một ít để tự uống, rồi mua thêm một ít để tặng người khác."},{"q_cn":"售货员向安妮介绍了茶叶的哪些优惠活动？","q_vn":"Nhân viên bán hàng đã giới thiệu cho Annie những ưu đãi gì của trà？","a_cn":"今天满二两送半两，超过半斤再送小礼物。","a_vn":"Hôm nay mua đủ hai lạng tặng thêm nửa lạng, vượt quá nửa cân còn tặng thêm quà nhỏ."},{"q_cn":"安妮最后决定怎么买这些茶叶？","q_vn":"Cuối cùng Annie quyết định mua trà như thế nào？","a_cn":"她决定买六两这种绿茶，再买一个盒子，让售货员分着装，盒子里装半斤，剩下的用纸包起来。","a_vn":"Cô quyết định mua sáu lạng loại lục trà này, mua thêm một cái hộp, để nhân viên chia ra đóng gói, trong hộp đóng nửa cân, phần còn lại dùng giấy gói lại."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"广播员","cn":"各位顾客，本商场正在举办运动鞋假日低价促销活动，全场五折。","pinyin":""},{"speaker":"王一雪","cn":"一飞，广播里说价格减了一半呢，咱们过去看看？","pinyin":""},{"speaker":"王一飞","cn":"好的。不过咱们也不能只听广告说什么，还得看质量。","pinyin":""},{"speaker":"王一雪","cn":"对，首先看样子喜不喜欢，然后再看质量怎么样、价格合适不合适。","pinyin":""},{"speaker":"售货员","cn":"二位看看喜欢哪双？这个牌子质量很好，今天又降价，一双减300块。","pinyin":""},{"speaker":"王一雪","cn":"嗯，我知道这个牌子。一飞，你喜欢吗？你看，这个鞋的样式很新，价钱也不高。","pinyin":""},{"speaker":"王一飞","cn":"你喜欢就买吧。我再看看别的。","pinyin":""},{"speaker":"王一雪","cn":"好的。请给我拿一双37号的吧。","pinyin":""}],"translation_vn":"Người phát thanh: Xin các vị khách hàng chú ý, trung tâm thương mại này đang tổ chức hoạt động khuyến mại giá thấp ngày nghỉ cho giày thể thao, toàn bộ giảm giá còn 50%.\nVương Nhất Tuyết: Nhất Phi, loa nói giá đã giảm một nửa rồi, chúng ta qua xem thử đi?\nVương Nhất Phi: Được. Nhưng chúng ta cũng không thể chỉ nghe quảng cáo nói gì, còn phải xem chất lượng nữa.\nVương Nhất Tuyết: Đúng vậy, trước tiên xem kiểu dáng có thích không, sau đó mới xem chất lượng thế nào, giá cả có hợp lý không.\nNhân viên bán hàng: Hai anh chị xem thích đôi nào? Nhãn hiệu này chất lượng rất tốt, hôm nay lại giảm giá, mỗi đôi giảm 300 đồng.\nVương Nhất Tuyết: Ừm, em biết nhãn hiệu này. Nhất Phi, anh có thích không? Anh xem, kiểu dáng của đôi giày này rất mới, giá cũng không cao.\nVương Nhất Phi: Em thích thì mua đi. Anh xem thêm đôi khác.\nVương Nhất Tuyết: Được. Làm ơn lấy cho tôi một đôi số 37.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"商场广播里说的促销活动内容是什么？","q_vn":"Nội dung hoạt động khuyến mại trong loa phát thanh của trung tâm thương mại là gì？","a_cn":"本商场正在举办运动鞋假日低价促销活动，全场五折。","a_vn":"Trung tâm thương mại này đang tổ chức hoạt động khuyến mại giá thấp ngày nghỉ cho giày thể thao, toàn bộ giảm giá còn 50%."},{"q_cn":"王一飞认为买东西除了听广告，还应该看什么？","q_vn":"Vương Nhất Phi cho rằng mua đồ ngoài nghe quảng cáo, còn nên xem gì？","a_cn":"他认为还得看质量，首先看样子喜不喜欢，然后再看质量怎么样、价格合适不合适。","a_vn":"Anh cho rằng còn phải xem chất lượng, trước tiên xem kiểu dáng có thích không, sau đó mới xem chất lượng thế nào, giá cả có hợp lý không."},{"q_cn":"王一雪最后选择的是什么样的鞋？","q_vn":"Cuối cùng Vương Nhất Tuyết chọn đôi giày như thế nào？","a_cn":"她选择了售货员推荐的那个牌子的鞋，鞋的样式很新，价钱也不高，还要了一双37号的。","a_vn":"Cô chọn đôi giày của nhãn hiệu mà nhân viên bán hàng giới thiệu, kiểu dáng rất mới, giá cũng không cao, và lấy một đôi số 37."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"李文的朋友徐前在商业区开了家小店，专门卖年轻人喜欢的东西。他的店里商品种类不少，既有几十年前的老游戏机，也有最近流行的盲盒等等，很吸引年轻人。","pinyin":""},{"speaker":"","cn":"徐前说，自己就是年轻人，知道年轻人喜欢什么。他也常和来店里的年轻顾客聊天儿，了解他们的兴趣爱好。前段时间刚进的盲盒很快就卖到了缺货。许多年轻人表示，在徐前的店里能感受到快乐。小店虽然小，但东西适合年轻人，加上店员态度友好，使得小店的生意越来越好。李文觉得自己的朋友真会做生意。","pinyin":""}],"translation_vn":"Bạn của Lý Văn là Từ Tiền đã mở một cửa hàng nhỏ ở khu thương mại, chuyên bán những thứ người trẻ thích. Hàng hóa trong cửa hàng của anh có không ít loại, có cả máy chơi game cũ từ mấy chục năm trước, cũng có cả hộp mù thịnh hành gần đây, rất thu hút các bạn trẻ.\nTừ Tiền nói, bản thân anh chính là người trẻ, biết người trẻ thích gì. Anh cũng thường nói chuyện với những khách hàng trẻ đến cửa hàng, để hiểu sở thích của họ. Thời gian trước lô hộp mù vừa nhập vào đã rất nhanh bán đến mức thiếu hàng. Nhiều bạn trẻ cho biết, ở cửa hàng của Từ Tiền có thể cảm nhận được niềm vui. Cửa hàng nhỏ tuy nhỏ, nhưng đồ hợp với người trẻ, thêm vào đó nhân viên thái độ thân thiện, khiến việc kinh doanh của cửa hàng ngày càng tốt. Lý Văn cảm thấy người bạn của mình thật biết cách kinh doanh.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"徐前的小店主要卖什么样的商品？","q_vn":"Cửa hàng nhỏ của Từ Tiền chủ yếu bán loại hàng hóa gì？","a_cn":"他的店里卖年轻人喜欢的东西，既有几十年前的老游戏机，也有最近流行的盲盒等等。","a_vn":"Cửa hàng của anh bán những thứ người trẻ thích, có cả máy chơi game cũ từ mấy chục năm trước, cũng có cả hộp mù thịnh hành gần đây."},{"q_cn":"徐前是怎么了解年轻顾客的兴趣爱好的？","q_vn":"Từ Tiền tìm hiểu sở thích của khách hàng trẻ bằng cách nào？","a_cn":"他常和来店里的年轻顾客聊天儿，从中了解他们的兴趣爱好。","a_vn":"Anh thường nói chuyện với những khách hàng trẻ đến cửa hàng, qua đó hiểu sở thích của họ."},{"q_cn":"徐前的小店生意越来越好的原因是什么？","q_vn":"Nguyên nhân khiến việc kinh doanh của cửa hàng Từ Tiền ngày càng tốt là gì？","a_cn":"因为店里的东西适合年轻人，加上店员态度友好，使得小店的生意越来越好。","a_vn":"Vì đồ trong cửa hàng hợp với người trẻ, thêm vào đó nhân viên thái độ thân thiện, khiến việc kinh doanh của cửa hàng ngày càng tốt."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"关于购物，你是一位冷静购物者，还是不冷静购物者？一般来说，冷静购物者往往是真正需要一件东西时才买。购买时，还会从质量、价格等各方面仔细比较。不冷静购物者看见一个东西时，只要感觉喜欢就买，不管需要不需要，结果常常买完就后悔，买的东西也成了\"垃圾\"，还不环保。王一飞说，她从来不随便买东西。对于想买的东西，她不光看质量，还看价格。无论是一件外套，还是一条裤子，甚至一双袜子，都是仔细比较后才决定买不买。","pinyin":""},{"speaker":"","cn":"其实，不仅是买东西，人生的很多事情都一样，选择合适的才是最好的。","pinyin":""}],"translation_vn":"Về việc mua sắm, bạn là một người mua hàng bình tĩnh, hay một người mua hàng không bình tĩnh? Nói chung, người mua hàng bình tĩnh thường chỉ mua khi thực sự cần một thứ gì đó. Khi mua, họ còn so sánh kỹ các mặt như chất lượng, giá cả. Người mua hàng không bình tĩnh khi nhìn thấy một thứ gì đó, chỉ cần cảm thấy thích là mua, không quan tâm có cần hay không, kết quả thường là mua xong lại hối hận, thứ mua được cũng trở thành \"rác\", lại không thân thiện với môi trường. Vương Nhất Phi nói, cô ấy chưa bao giờ mua đồ một cách tùy tiện. Đối với những thứ muốn mua, cô ấy không chỉ xem chất lượng, còn xem giá cả. Dù là một chiếc áo khoác, hay một cái quần, thậm chí một đôi vớ, đều phải so sánh kỹ rồi mới quyết định mua hay không.\nThực ra, không chỉ việc mua đồ, rất nhiều việc trong đời cũng như vậy, chọn thứ phù hợp mới là tốt nhất.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"冷静购物者和不冷静购物者在购物习惯上有什么不同？","q_vn":"Người mua hàng bình tĩnh và người mua hàng không bình tĩnh khác nhau như thế nào trong thói quen mua sắm？","a_cn":"冷静购物者往往是真正需要时才买，还会仔细比较质量、价格；不冷静购物者只要感觉喜欢就买，不管需要不需要，常常买完就后悔。","a_vn":"Người mua hàng bình tĩnh thường chỉ mua khi thực sự cần, còn so sánh kỹ chất lượng, giá cả; người mua hàng không bình tĩnh chỉ cần cảm thấy thích là mua, không quan tâm có cần hay không, thường mua xong lại hối hận."},{"q_cn":"王一飞买东西时会考虑哪些因素？","q_vn":"Khi mua đồ Vương Nhất Phi sẽ xem xét những yếu tố gì？","a_cn":"她不光看质量，还看价格，无论是外套、裤子还是袜子，都要仔细比较后才决定买不买。","a_vn":"Cô không chỉ xem chất lượng, còn xem giá cả, dù là áo khoác, quần hay vớ, đều phải so sánh kỹ rồi mới quyết định mua hay không."},{"q_cn":"这篇文章最后想告诉我们什么道理？","q_vn":"Cuối bài viết này muốn nói với chúng ta đạo lý gì？","a_cn":"想告诉我们不仅买东西，人生的很多事情都一样，选择合适的才是最好的。","a_vn":"Muốn nói với chúng ta rằng không chỉ việc mua đồ, rất nhiều việc trong đời cũng như vậy, chọn thứ phù hợp mới là tốt nhất."}]}]},{"id":15,"title_cn":"我去应聘了","title_pinyin":"","title_vn":"Tôi đã đi ứng tuyển","goals":["Có thể nghe hiểu và trao đổi các thông tin về ứng tuyển, phỏng vấn, thực tập.","Có thể trình bày bằng lời hoặc văn bản về kinh nghiệm xin việc của bản thân.","Hiểu được tình hình và ý nghĩa của việc thực tập đối với sinh viên đại học Trung Quốc."],"vocab":[{"hanzi":"期中","pinyin":"qīzhōng","pos":"dt.","vn":"giữa kỳ","examples":[{"cn":"期中考试快到了，大家都在认真复习。","pinyin":"Qīzhōng kǎoshì kuài dào le, dàjiā dōu zài rènzhēn fùxí.","vn":"Kỳ thi giữa kỳ sắp đến rồi, mọi người đều đang ôn tập chăm chỉ."},{"cn":"这是我们这学期的期中成绩。","pinyin":"Zhè shì wǒmen zhè xuéqī de qīzhōng chéngjì.","vn":"Đây là điểm giữa kỳ của học kỳ này của chúng tôi."},{"cn":"期中考试后，老师给我们讲了很多重点。","pinyin":"Qīzhōng kǎoshì hòu, lǎoshī gěi wǒmen jiǎng le hěn duō zhòngdiǎn.","vn":"Sau kỳ thi giữa kỳ, giáo viên đã giảng cho chúng tôi nhiều trọng điểm."}]},{"hanzi":"医药","pinyin":"yīyào","pos":"dt.","vn":"y dược, thuốc men","examples":[{"cn":"他在一家医药公司工作。","pinyin":"Tā zài yì jiā yīyào gōngsī gōngzuò.","vn":"Anh ấy làm việc ở một công ty y dược."},{"cn":"这个城市有很多医药企业。","pinyin":"Zhège chéngshì yǒu hěn duō yīyào qǐyè.","vn":"Thành phố này có rất nhiều doanh nghiệp y dược."},{"cn":"医药行业发展得很快。","pinyin":"Yīyào hángyè fāzhǎn de hěn kuài.","vn":"Ngành y dược phát triển rất nhanh."}]},{"hanzi":"应聘","pinyin":"yìngpìn","pos":"dgt.","vn":"ứng tuyển, dự tuyển","examples":[{"cn":"他去一家公司应聘销售的工作。","pinyin":"Tā qù yì jiā gōngsī yìngpìn xiāoshòu de gōngzuò.","vn":"Anh ấy đến một công ty ứng tuyển vị trí bán hàng."},{"cn":"我打算下个月去应聘实习生。","pinyin":"Wǒ dǎsuan xià ge yuè qù yìngpìn shíxíshēng.","vn":"Tôi định tháng sau đi ứng tuyển vị trí thực tập sinh."},{"cn":"应聘前要先准备好简历。","pinyin":"Yìngpìn qián yào xiān zhǔnbèi hǎo jiǎnlì.","vn":"Trước khi ứng tuyển phải chuẩn bị sẵn sơ yếu lý lịch."}]},{"hanzi":"招聘","pinyin":"zhāopìn","pos":"dgt.","vn":"tuyển dụng","examples":[{"cn":"这家公司正在招聘新员工。","pinyin":"Zhè jiā gōngsī zhèngzài zhāopìn xīn yuángōng.","vn":"Công ty này đang tuyển dụng nhân viên mới."},{"cn":"学校里贴着招聘启示。","pinyin":"Xuéxiào lǐ tiē zhe zhāopìn qǐshì.","vn":"Trong trường dán thông báo tuyển dụng."},{"cn":"很多公司都喜欢在网上招聘。","pinyin":"Hěn duō gōngsī dōu xǐhuan zài wǎng shàng zhāopìn.","vn":"Nhiều công ty thích tuyển dụng qua mạng."}]},{"hanzi":"实习","pinyin":"shíxí","pos":"dgt.","vn":"thực tập","examples":[{"cn":"暑假我去一家公司实习了。","pinyin":"Shǔjià wǒ qù yì jiā gōngsī shíxí le.","vn":"Kỳ nghỉ hè tôi đã đi thực tập ở một công ty."},{"cn":"实习能让我们积累工作经验。","pinyin":"Shíxí néng ràng wǒmen jīlěi gōngzuò jīngyàn.","vn":"Thực tập có thể giúp chúng ta tích lũy kinh nghiệm làm việc."},{"cn":"他在医院实习了三个月。","pinyin":"Tā zài yīyuàn shíxí le sān ge yuè.","vn":"Anh ấy đã thực tập ở bệnh viện ba tháng."}]},{"hanzi":"考虑","pinyin":"kǎolǜ","pos":"dgt.","vn":"xem xét, cân nhắc","examples":[{"cn":"我正在考虑要不要换工作。","pinyin":"Wǒ zhèngzài kǎolǜ yào bu yào huàn gōngzuò.","vn":"Tôi đang cân nhắc có nên đổi việc hay không."},{"cn":"这个问题需要好好考虑。","pinyin":"Zhège wèntí xūyào hǎohǎo kǎolǜ.","vn":"Vấn đề này cần phải cân nhắc kỹ."},{"cn":"他考虑了很久才做出决定。","pinyin":"Tā kǎolǜ le hěn jiǔ cái zuò chū juédìng.","vn":"Anh ấy đã cân nhắc rất lâu mới đưa ra quyết định."}]},{"hanzi":"单位","pinyin":"dānwèi","pos":"dt.","vn":"cơ quan, đơn vị công tác","examples":[{"cn":"他在一个国家单位工作。","pinyin":"Tā zài yí ge guójiā dānwèi gōngzuò.","vn":"Anh ấy làm việc ở một cơ quan nhà nước."},{"cn":"你们单位最近招人吗？","pinyin":"Nǐmen dānwèi zuìjìn zhāo rén ma?","vn":"Đơn vị của bạn gần đây có tuyển người không?"},{"cn":"这家单位的福利很好。","pinyin":"Zhè jiā dānwèi de fúlì hěn hǎo.","vn":"Chế độ phúc lợi của đơn vị này rất tốt."}]},{"hanzi":"毕业生","pinyin":"bìyèshēng","pos":"dt.","vn":"sinh viên tốt nghiệp","examples":[{"cn":"今年的毕业生找工作不太容易。","pinyin":"Jīnnián de bìyèshēng zhǎo gōngzuò bú tài róngyì.","vn":"Sinh viên tốt nghiệp năm nay tìm việc không dễ lắm."},{"cn":"很多毕业生选择继续读研究生。","pinyin":"Hěn duō bìyèshēng xuǎnzé jìxù dú yánjiūshēng.","vn":"Nhiều sinh viên tốt nghiệp chọn tiếp tục học thạc sĩ."},{"cn":"这家公司每年都招聘毕业生。","pinyin":"Zhè jiā gōngsī měinián dōu zhāopìn bìyèshēng.","vn":"Công ty này hàng năm đều tuyển dụng sinh viên mới ra trường."}]},{"hanzi":"经历","pinyin":"jīnglì","pos":"dt./dgt.","vn":"kinh nghiệm, trải qua","examples":[{"cn":"这是我第一次面试的经历。","pinyin":"Zhè shì wǒ dì yī cì miànshì de jīnglì.","vn":"Đây là lần đầu tiên tôi có kinh nghiệm phỏng vấn."},{"cn":"他经历了很多困难才成功。","pinyin":"Tā jīnglì le hěn duō kùnnan cái chénggōng.","vn":"Anh ấy đã trải qua nhiều khó khăn mới thành công."},{"cn":"实习经历对找工作很有帮助。","pinyin":"Shíxí jīnglì duì zhǎo gōngzuò hěn yǒu bāngzhù.","vn":"Kinh nghiệm thực tập rất có ích cho việc tìm việc."}]},{"hanzi":"消息","pinyin":"xiāoxi","pos":"dt.","vn":"tin tức, tin nhắn","examples":[{"cn":"我还没收到公司的消息。","pinyin":"Wǒ hái méi shōudào gōngsī de xiāoxi.","vn":"Tôi vẫn chưa nhận được tin tức từ công ty."},{"cn":"他告诉了我一个好消息。","pinyin":"Tā gàosù le wǒ yí ge hǎo xiāoxi.","vn":"Anh ấy báo cho tôi một tin tốt."},{"cn":"希望明天能有好消息。","pinyin":"Xīwàng míngtiān néng yǒu hǎo xiāoxi.","vn":"Hy vọng ngày mai sẽ có tin tốt."}]},{"hanzi":"报名","pinyin":"bàomíng","pos":"dgt.","vn":"đăng ký","examples":[{"cn":"我已经在网上报名了。","pinyin":"Wǒ yǐjīng zài wǎng shàng bàomíng le.","vn":"Tôi đã đăng ký trên mạng rồi."},{"cn":"报名的人很多，竞争很激烈。","pinyin":"Bàomíng de rén hěn duō, jìngzhēng hěn jīliè.","vn":"Người đăng ký rất nhiều, cạnh tranh rất gay gắt."},{"cn":"报名截止时间是这周五。","pinyin":"Bàomíng jiézhǐ shíjiān shì zhè zhōu wǔ.","vn":"Thời gian hết hạn đăng ký là thứ Sáu tuần này."}]},{"hanzi":"填写","pinyin":"tiánxiě","pos":"dgt.","vn":"điền, viết vào","examples":[{"cn":"请填写这张表格。","pinyin":"Qǐng tiánxiě zhè zhāng biǎogé.","vn":"Xin hãy điền vào tờ phiếu này."},{"cn":"我填写了个人信息后就提交了。","pinyin":"Wǒ tiánxiě le gèrén xìnxī hòu jiù tíjiāo le.","vn":"Tôi điền thông tin cá nhân xong là nộp luôn."},{"cn":"这里需要填写你的联系方式。","pinyin":"Zhèlǐ xūyào tiánxiě nǐ de liánxì fāngshì.","vn":"Ở đây cần điền thông tin liên hệ của bạn."}]},{"hanzi":"笔试","pinyin":"bǐshì","pos":"dgt.","vn":"thi viết","examples":[{"cn":"明天上午要进行笔试。","pinyin":"Míngtiān shàngwǔ yào jìnxíng bǐshì.","vn":"Sáng mai sẽ tiến hành thi viết."},{"cn":"笔试的内容主要是专业知识。","pinyin":"Bǐshì de nèiróng zhǔyào shì zhuānyè zhīshi.","vn":"Nội dung thi viết chủ yếu là kiến thức chuyên môn."},{"cn":"他笔试通过了，接下来要面试。","pinyin":"Tā bǐshì tōngguò le, jiē xiàlái yào miànshì.","vn":"Anh ấy đã đỗ thi viết, tiếp theo phải phỏng vấn."}]},{"hanzi":"面试","pinyin":"miànshì","pos":"dgt.","vn":"phỏng vấn","examples":[{"cn":"我下周要去面试。","pinyin":"Wǒ xià zhōu yào qù miànshì.","vn":"Tuần sau tôi phải đi phỏng vấn."},{"cn":"面试的时候要穿正式一点儿。","pinyin":"Miànshì de shíhou yào chuān zhèngshì yìdiǎnr.","vn":"Khi phỏng vấn phải ăn mặc chỉnh tề hơn một chút."},{"cn":"他面试的表现很好。","pinyin":"Tā miànshì de biǎoxiàn hěn hǎo.","vn":"Anh ấy thể hiện rất tốt khi phỏng vấn."}]},{"hanzi":"答","pinyin":"dá","pos":"dgt.","vn":"trả lời, đáp","examples":[{"cn":"老师问的问题他都答对了。","pinyin":"Lǎoshī wèn de wèntí tā dōu dá duì le.","vn":"Những câu hỏi giáo viên đặt ra anh ấy đều trả lời đúng."},{"cn":"这道题我不知道怎么答。","pinyin":"Zhè dào tí wǒ bù zhīdào zěnme dá.","vn":"Câu hỏi này tôi không biết trả lời thế nào."},{"cn":"他答得很认真。","pinyin":"Tā dá de hěn rènzhēn.","vn":"Anh ấy trả lời rất nghiêm túc."}]},{"hanzi":"由","pinyin":"yóu","pos":"giới.","vn":"do, bởi","examples":[{"cn":"这件事由他来负责。","pinyin":"Zhè jiàn shì yóu tā lái fùzé.","vn":"Việc này do anh ấy phụ trách."},{"cn":"这个项目是由我们公司完成的。","pinyin":"Zhège xiàngmù shì yóu wǒmen gōngsī wánchéng de.","vn":"Dự án này do công ty chúng tôi hoàn thành."},{"cn":"晚会由学生会组织。","pinyin":"Wǎnhuì yóu xuéshēnghuì zǔzhī.","vn":"Dạ hội do hội sinh viên tổ chức."}]},{"hanzi":"部门","pinyin":"bùmén","pos":"dt.","vn":"bộ phận, phòng ban","examples":[{"cn":"我在销售部门工作。","pinyin":"Wǒ zài xiāoshòu bùmén gōngzuò.","vn":"Tôi làm việc ở bộ phận bán hàng."},{"cn":"这个部门最近很忙。","pinyin":"Zhège bùmén zuìjìn hěn máng.","vn":"Bộ phận này gần đây rất bận."},{"cn":"他调到了另一个部门。","pinyin":"Tā diàodào le lìng yí ge bùmén.","vn":"Anh ấy đã chuyển sang một bộ phận khác."}]},{"hanzi":"负责人","pinyin":"fùzérén","pos":"dt.","vn":"người phụ trách","examples":[{"cn":"他是这个项目的负责人。","pinyin":"Tā shì zhège xiàngmù de fùzérén.","vn":"Anh ấy là người phụ trách dự án này."},{"cn":"你可以直接找部门负责人。","pinyin":"Nǐ kěyǐ zhíjiē zhǎo bùmén fùzérén.","vn":"Bạn có thể trực tiếp tìm người phụ trách bộ phận."},{"cn":"负责人对这次活动很满意。","pinyin":"Fùzérén duì zhè cì huódòng hěn mǎnyì.","vn":"Người phụ trách rất hài lòng về hoạt động lần này."}]},{"hanzi":"不论","pinyin":"búlùn","pos":"liên.","vn":"bất kể, không kể","examples":[{"cn":"不论结果怎么样，我都尽力了。","pinyin":"Búlùn jiéguǒ zěnmeyàng, wǒ dōu jìnlì le.","vn":"Bất kể kết quả thế nào, tôi đều đã cố gắng hết sức."},{"cn":"不论天气好不好，他都会去跑步。","pinyin":"Búlùn tiānqì hǎo bu hǎo, tā dōu huì qù pǎobù.","vn":"Bất kể thời tiết thế nào, anh ấy đều đi chạy bộ."},{"cn":"不论遇到什么困难，我们都要坚持。","pinyin":"Búlùn yùdào shénme kùnnan, wǒmen dōu yào jiānchí.","vn":"Bất kể gặp khó khăn gì, chúng ta đều phải kiên trì."}]},{"hanzi":"肯定","pinyin":"kěndìng","pos":"phó./tt.","vn":"chắc chắn, khẳng định","examples":[{"cn":"他肯定会来参加比赛。","pinyin":"Tā kěndìng huì lái cānjiā bǐsài.","vn":"Anh ấy chắc chắn sẽ đến tham gia thi đấu."},{"cn":"老师肯定了我们的努力。","pinyin":"Lǎoshī kěndìng le wǒmen de nǔlì.","vn":"Giáo viên đã khẳng định sự cố gắng của chúng tôi."},{"cn":"这件事肯定对你有帮助。","pinyin":"Zhè jiàn shì kěndìng duì nǐ yǒu bāngzhù.","vn":"Việc này chắc chắn có ích cho bạn."}]},{"hanzi":"短信","pinyin":"duǎnxìn","pos":"dt.","vn":"tin nhắn (điện thoại)","examples":[{"cn":"他给我发了一条短信。","pinyin":"Tā gěi wǒ fā le yì tiáo duǎnxìn.","vn":"Anh ấy gửi cho tôi một tin nhắn."},{"cn":"我看到短信后立刻回复了。","pinyin":"Wǒ kàndào duǎnxìn hòu lìkè huífù le.","vn":"Tôi nhìn thấy tin nhắn liền trả lời ngay."},{"cn":"公司通过短信通知了面试结果。","pinyin":"Gōngsī tōngguò duǎnxìn tōngzhī le miànshì jiéguǒ.","vn":"Công ty thông báo kết quả phỏng vấn qua tin nhắn."}]},{"hanzi":"激动","pinyin":"jīdòng","pos":"tt./dgt.","vn":"xúc động, hào hứng","examples":[{"cn":"听到这个好消息，我特别激动。","pinyin":"Tīngdào zhège hǎo xiāoxi, wǒ tèbié jīdòng.","vn":"Nghe được tin tốt này, tôi vô cùng xúc động."},{"cn":"他说话的声音很激动。","pinyin":"Tā shuōhuà de shēngyīn hěn jīdòng.","vn":"Giọng nói của anh ấy rất xúc động."},{"cn":"比赛结果让大家都很激动。","pinyin":"Bǐsài jiéguǒ ràng dàjiā dōu hěn jīdòng.","vn":"Kết quả thi đấu khiến mọi người đều rất xúc động."}]},{"hanzi":"扔","pinyin":"rēng","pos":"dgt.","vn":"vứt, ném","examples":[{"cn":"别把垃圾扔在地上。","pinyin":"Bié bǎ lājī rēng zài dìshang.","vn":"Đừng vứt rác xuống đất."},{"cn":"他把球扔给了我。","pinyin":"Tā bǎ qiú rēng gěi le wǒ.","vn":"Anh ấy ném quả bóng cho tôi."},{"cn":"她激动得把帽子扔了起来。","pinyin":"Tā jīdòng de bǎ màozi rēng le qǐlái.","vn":"Cô ấy xúc động đến mức tung mũ lên."}]},{"hanzi":"理发","pinyin":"lǐfà","pos":"dgt.","vn":"cắt tóc","examples":[{"cn":"我周末要去理发。","pinyin":"Wǒ zhōumò yào qù lǐfà.","vn":"Cuối tuần tôi phải đi cắt tóc."},{"cn":"这家理发店的师傅手艺很好。","pinyin":"Zhè jiā lǐfà diàn de shīfu shǒuyì hěn hǎo.","vn":"Thợ của tiệm cắt tóc này rất khéo tay."},{"cn":"面试前他特意去理发了。","pinyin":"Miànshì qián tā tèyì qù lǐfà le.","vn":"Trước khi phỏng vấn anh ấy đặc biệt đi cắt tóc."}]},{"hanzi":"镜子","pinyin":"jìngzi","pos":"dt.","vn":"cái gương","examples":[{"cn":"她站在镜子前看了看自己。","pinyin":"Tā zhàn zài jìngzi qián kàn le kàn zìjǐ.","vn":"Cô ấy đứng trước gương nhìn mình một chút."},{"cn":"这面镜子很大。","pinyin":"Zhè miàn jìngzi hěn dà.","vn":"Cái gương này rất lớn."},{"cn":"他对着镜子练习自我介绍。","pinyin":"Tā duì zhe jìngzi liànxí zìwǒ jièshào.","vn":"Anh ấy đối diện với gương luyện tập tự giới thiệu."}]},{"hanzi":"自我","pinyin":"zìwǒ","pos":"đt.","vn":"tự mình, bản thân","examples":[{"cn":"面试时要先做自我介绍。","pinyin":"Miànshì shí yào xiān zuò zìwǒ jièshào.","vn":"Khi phỏng vấn phải tự giới thiệu bản thân trước."},{"cn":"他很会自我调整心态。","pinyin":"Tā hěn huì zìwǒ tiáozhěng xīntài.","vn":"Anh ấy rất biết tự điều chỉnh tâm lý bản thân."},{"cn":"我们要学会自我管理。","pinyin":"Wǒmen yào xuéhuì zìwǒ guǎnlǐ.","vn":"Chúng ta phải học cách tự quản lý bản thân."}]},{"hanzi":"能够","pinyin":"nénggòu","pos":"dgt.","vn":"có thể","examples":[{"cn":"我希望能够通过这次考试。","pinyin":"Wǒ xīwàng nénggòu tōngguò zhè cì kǎoshì.","vn":"Tôi hy vọng có thể vượt qua kỳ thi này."},{"cn":"他能够熟练地使用这个软件。","pinyin":"Tā nénggòu shúliàn de shǐyòng zhège ruǎnjiàn.","vn":"Anh ấy có thể sử dụng thành thục phần mềm này."},{"cn":"希望大家都能够顺利毕业。","pinyin":"Xīwàng dàjiā dōu nénggòu shùnlì bìyè.","vn":"Hy vọng mọi người đều có thể tốt nghiệp thuận lợi."}]},{"hanzi":"运用","pinyin":"yùnyòng","pos":"dgt.","vn":"vận dụng","examples":[{"cn":"他能很好地运用所学的知识。","pinyin":"Tā néng hěn hǎo de yùnyòng suǒ xué de zhīshi.","vn":"Anh ấy có thể vận dụng tốt những kiến thức đã học."},{"cn":"这篇文章运用了很多例子。","pinyin":"Zhè piān wénzhāng yùnyòng le hěn duō lìzi.","vn":"Bài viết này vận dụng rất nhiều ví dụ."},{"cn":"实习能让我们运用理论知识。","pinyin":"Shíxí néng ràng wǒmen yùnyòng lǐlùn zhīshi.","vn":"Thực tập có thể giúp chúng ta vận dụng kiến thức lý thuyết."}]},{"hanzi":"工厂","pinyin":"gōngchǎng","pos":"dt.","vn":"nhà máy, xí nghiệp","examples":[{"cn":"他在一家工厂上班。","pinyin":"Tā zài yì jiā gōngchǎng shàngbān.","vn":"Anh ấy làm việc ở một nhà máy."},{"cn":"这个工厂生产手机零件。","pinyin":"Zhège gōngchǎng shēngchǎn shǒujī língjiàn.","vn":"Nhà máy này sản xuất linh kiện điện thoại."},{"cn":"工厂里的工作比较辛苦。","pinyin":"Gōngchǎng lǐ de gōngzuò bǐjiào xīnkǔ.","vn":"Công việc trong nhà máy khá vất vả."}]},{"hanzi":"规定","pinyin":"guīdìng","pos":"dt./dgt.","vn":"quy định","examples":[{"cn":"公司有很多规定。","pinyin":"Gōngsī yǒu hěn duō guīdìng.","vn":"Công ty có rất nhiều quy định."},{"cn":"学校规定八点上课。","pinyin":"Xuéxiào guīdìng bā diǎn shàngkè.","vn":"Nhà trường quy định tám giờ vào học."},{"cn":"我们要遵守单位的规定。","pinyin":"Wǒmen yào zūnshǒu dānwèi de guīdìng.","vn":"Chúng ta phải tuân thủ quy định của đơn vị."}]},{"hanzi":"课堂","pinyin":"kètáng","pos":"dt.","vn":"lớp học, giờ học","examples":[{"cn":"课堂上他总是认真听讲。","pinyin":"Kètáng shàng tā zǒngshì rènzhēn tīngjiǎng.","vn":"Trong giờ học anh ấy luôn nghe giảng rất chăm chú."},{"cn":"这是一堂很有趣的课堂。","pinyin":"Zhè shì yí táng hěn yǒuqù de kètáng.","vn":"Đây là một giờ học rất thú vị."},{"cn":"课堂上学的知识要多运用。","pinyin":"Kètáng shàng xué de zhīshi yào duō yùnyòng.","vn":"Kiến thức học trong giờ học cần vận dụng nhiều."}]},{"hanzi":"完全","pinyin":"wánquán","pos":"phó./tt.","vn":"hoàn toàn","examples":[{"cn":"我完全同意你的看法。","pinyin":"Wǒ wánquán tóngyì nǐ de kànfǎ.","vn":"Tôi hoàn toàn đồng ý với quan điểm của bạn."},{"cn":"这两件事完全不一样。","pinyin":"Zhè liǎng jiàn shì wánquán bù yíyàng.","vn":"Hai việc này hoàn toàn khác nhau."},{"cn":"他完全理解了这个问题。","pinyin":"Tā wánquán lǐjiě le zhège wèntí.","vn":"Anh ấy đã hoàn toàn hiểu vấn đề này."}]},{"hanzi":"例如","pinyin":"lìrú","pos":"dgt.","vn":"ví dụ như","examples":[{"cn":"很多水果都很有营养，例如苹果、香蕉。","pinyin":"Hěn duō shuǐguǒ dōu hěn yǒu yíngyǎng, lìrú píngguǒ, xiāngjiāo.","vn":"Nhiều loại hoa quả rất bổ dưỡng, ví dụ như táo, chuối."},{"cn":"这个城市有很多有名的地方，例如长城。","pinyin":"Zhège chéngshì yǒu hěn duō yǒumíng de dìfang, lìrú Chángchéng.","vn":"Thành phố này có nhiều nơi nổi tiếng, ví dụ như Trường Thành."},{"cn":"学习方法有很多种，例如多读多写。","pinyin":"Xuéxí fāngfǎ yǒu hěn duō zhǒng, lìrú duō dú duō xiě.","vn":"Có nhiều phương pháp học tập, ví dụ như đọc nhiều viết nhiều."}]},{"hanzi":"不如","pinyin":"bùrú","pos":"dgt.","vn":"không bằng, chẳng bằng","examples":[{"cn":"坐地铁不如坐公交方便。","pinyin":"Zuò dìtiě bùrú zuò gōngjiāo fāngbiàn.","vn":"Đi tàu điện ngầm không tiện bằng đi xe buýt."},{"cn":"这家餐厅的味道不如那家。","pinyin":"Zhè jiā cāntīng de wèidào bùrú nà jiā.","vn":"Vị của nhà hàng này không ngon bằng nhà hàng đó."},{"cn":"光看书不如自己动手试一试。","pinyin":"Guāng kànshū bùrú zìjǐ dòngshǒu shì yi shì.","vn":"Chỉ đọc sách không bằng tự mình thử làm."}]},{"hanzi":"细节","pinyin":"xìjié","pos":"dt.","vn":"chi tiết","examples":[{"cn":"做事一定要注意细节。","pinyin":"Zuòshì yídìng yào zhùyì xìjié.","vn":"Làm việc nhất định phải chú ý chi tiết."},{"cn":"他把每一个细节都记下来了。","pinyin":"Tā bǎ měi yí ge xìjié dōu jìxiàlái le.","vn":"Anh ấy ghi lại mọi chi tiết."},{"cn":"这份报告的细节写得很清楚。","pinyin":"Zhè fèn bàogào de xìjié xiě de hěn qīngchu.","vn":"Chi tiết trong báo cáo này viết rất rõ ràng."}]},{"hanzi":"答案","pinyin":"dá'àn","pos":"dt.","vn":"đáp án, câu trả lời","examples":[{"cn":"这道题的答案是什么？","pinyin":"Zhè dào tí de dá'àn shì shénme?","vn":"Đáp án của câu hỏi này là gì?"},{"cn":"老师还没公布答案。","pinyin":"Lǎoshī hái méi gōngbù dá'àn.","vn":"Giáo viên vẫn chưa công bố đáp án."},{"cn":"有些问题没有标准答案。","pinyin":"Yǒuxiē wèntí méiyǒu biāozhǔn dá'àn.","vn":"Có những vấn đề không có đáp án chuẩn."}]},{"hanzi":"职业","pinyin":"zhíyè","pos":"dt.","vn":"nghề nghiệp","examples":[{"cn":"他对未来的职业有自己的规划。","pinyin":"Tā duì wèilái de zhíyè yǒu zìjǐ de guīhuà.","vn":"Anh ấy có kế hoạch riêng cho nghề nghiệp tương lai."},{"cn":"医生是一个很受人尊重的职业。","pinyin":"Yīshēng shì yí ge hěn shòu rén zūnzhòng de zhíyè.","vn":"Bác sĩ là một nghề được mọi người tôn trọng."},{"cn":"这次实习帮他明确了职业方向。","pinyin":"Zhè cì shíxí bāng tā míngquè le zhíyè fāngxiàng.","vn":"Lần thực tập này đã giúp anh ấy xác định rõ hướng nghề nghiệp."}]}],"grammar":[{"title":"固定格式 \"再也不/没……\"","explanation_vn":"Cấu trúc cố định \"再也不\" biểu thị trong tương lai sẽ không xảy ra việc gì đó nữa; \"再也没\" biểu thị từ trong quá khứ đến hiện tại chưa từng xảy ra lại việc gì đó.","examples":[{"cn":"期中考试后就再也没见过你了。","pinyin":"","vn":"Sau kỳ thi giữa kỳ là tôi không gặp lại bạn nữa."},{"cn":"对不起，我以后再也不迟到了。","pinyin":"","vn":"Xin lỗi, sau này tôi sẽ không bao giờ đến muộn nữa."},{"cn":"我出国以后就再也没给他打过电话。","pinyin":"","vn":"Sau khi ra nước ngoài tôi không còn gọi điện cho anh ấy nữa."}]},{"title":"介词 \"由\"","explanation_vn":"Giới từ \"由\" trong bài học này dùng để đưa ra người thực hiện hành động.","examples":[{"cn":"那天是由部门负责人来面试的，我有点儿紧张。","pinyin":"","vn":"Hôm đó là do người phụ trách bộ phận trực tiếp phỏng vấn, tôi có chút hồi hộp."},{"cn":"这个问题究竟由谁来负责解决？","pinyin":"","vn":"Rốt cuộc vấn đề này do ai phụ trách giải quyết?"},{"cn":"这次活动是由他们公司来安排的。","pinyin":"","vn":"Hoạt động lần này do công ty họ sắp xếp."}]},{"title":"\"把\"字句 \"主语+把+宾语+动词（+一/了）+动词\"","explanation_vn":"Trong câu chữ \"把\" này, động từ có thể lặp lại theo hình thức \"VV\", \"V一V\" hoặc \"V了V\", biểu thị hành động diễn ra trong thời gian ngắn, mức độ nhẹ.","examples":[{"cn":"他去理发店把头发理了理。","pinyin":"","vn":"Anh ấy đến tiệm cắt tóc cắt lại tóc một chút."},{"cn":"你先把作业检查检查，然后再交给老师。","pinyin":"","vn":"Bạn kiểm tra lại bài tập một chút rồi mới nộp cho giáo viên."},{"cn":"上课前，我把今天要学习的内容看了看。","pinyin":"","vn":"Trước khi vào học, tôi xem qua một chút nội dung cần học hôm nay."}]},{"title":"比较句 \"A不如B（+形容词）\"","explanation_vn":"Câu so sánh \"A不如B（+形容词）\" biểu thị A không tốt bằng B. Nếu trong câu có tính từ thì biểu thị A kém hơn B ở một phương diện nào đó.","examples":[{"cn":"有些事情，在课本上学不如自己做一遍。","pinyin":"","vn":"Có những việc, học trên sách không bằng tự mình làm thử một lần."},{"cn":"这家店不如那家店环境好。","pinyin":"","vn":"Môi trường của tiệm này không tốt bằng tiệm kia."},{"cn":"我觉得坐公交不如坐地铁方便。","pinyin":"","vn":"Tôi thấy đi xe buýt không tiện bằng đi tàu điện ngầm."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"陈天中","cn":"李文，期中考试后就再也没见过你了，你这段时间在忙什么呢？","pinyin":""},{"speaker":"李文","cn":"我最近去一家医药公司应聘了，他们正在招聘实习生。","pinyin":""},{"speaker":"陈天中","cn":"你这么早就考虑实习了？","pinyin":""},{"speaker":"李文","cn":"现在很多单位在招聘毕业生时，都很重视有没有实习经历，所以我想提前去锻炼一下，积累一些经验。","pinyin":""},{"speaker":"陈天中","cn":"那现在有结果了吗？","pinyin":""},{"speaker":"李文","cn":"我还在等消息，希望能有好结果。","pinyin":""}],"translation_vn":"Trần Thiên Trung: Lý Văn, sau kỳ thi giữa kỳ là tôi không gặp lại bạn nữa, thời gian này bạn đang bận gì vậy?\nLý Văn: Gần đây tôi đã đến ứng tuyển ở một công ty y dược, họ đang tuyển thực tập sinh.\nTrần Thiên Trung: Bạn đã tính đến thực tập sớm vậy sao?\nLý Văn: Hiện nay nhiều đơn vị khi tuyển sinh viên tốt nghiệp đều rất coi trọng việc có kinh nghiệm thực tập hay không, vì vậy tôi muốn đi rèn luyện trước, tích lũy một số kinh nghiệm.\nTrần Thiên Trung: Vậy giờ đã có kết quả chưa?\nLý Văn: Tôi vẫn đang chờ tin, hy vọng sẽ có kết quả tốt.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"李文最近在忙什么？","q_vn":"Gần đây Lý Văn đang bận việc gì?","a_cn":"他最近去一家医药公司应聘实习生。","a_vn":"Gần đây anh ấy đã đến ứng tuyển vị trí thực tập sinh ở một công ty y dược."},{"q_cn":"李文为什么这么早就考虑实习？","q_vn":"Vì sao Lý Văn đã tính đến việc thực tập từ sớm?","a_cn":"因为很多单位在招聘毕业生时很重视有没有实习经历，他想提前锻炼、积累经验。","a_vn":"Vì nhiều đơn vị khi tuyển sinh viên tốt nghiệp rất coi trọng kinh nghiệm thực tập, anh muốn rèn luyện và tích lũy kinh nghiệm trước."},{"q_cn":"李文现在的应聘结果怎么样？","q_vn":"Kết quả ứng tuyển hiện tại của Lý Văn thế nào?","a_cn":"他还在等消息，希望能有好结果。","a_vn":"Anh ấy vẫn đang chờ tin, hy vọng sẽ có kết quả tốt."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"李文，你是怎么应聘的？","pinyin":""},{"speaker":"李文","cn":"我先在网上报名，填写个人信息，然后等公司通知我去参加笔试。","pinyin":""},{"speaker":"陈天中","cn":"笔试都考些什么？","pinyin":""},{"speaker":"李文","cn":"主要是一些专业知识。考完没多久，他们就让我去面试了。","pinyin":""},{"speaker":"陈天中","cn":"看来你笔试答得不错，那你面试得怎么样？","pinyin":""},{"speaker":"李文","cn":"那天是由部门负责人来面试的，我有点儿紧张。他让我介绍了自己的学习经历、兴趣爱好和对工作的想法。","pinyin":""},{"speaker":"陈天中","cn":"听起来挺正式的。","pinyin":""},{"speaker":"李文","cn":"是啊，我觉得这次经历很有用。不论结果怎么样，对我以后找工作肯定有帮助。","pinyin":""}],"translation_vn":"Trần Thiên Trung: Lý Văn, bạn đã ứng tuyển như thế nào?\nLý Văn: Tôi trước tiên đăng ký trên mạng, điền thông tin cá nhân, sau đó chờ công ty thông báo đi tham gia thi viết.\nTrần Thiên Trung: Thi viết thi những gì?\nLý Văn: Chủ yếu là một số kiến thức chuyên môn. Thi xong không lâu, họ đã cho tôi đi phỏng vấn.\nTrần Thiên Trung: Xem ra bạn thi viết làm khá tốt, vậy phỏng vấn của bạn thế nào?\nLý Văn: Hôm đó là do người phụ trách bộ phận trực tiếp phỏng vấn, tôi có chút hồi hộp. Anh ấy cho tôi giới thiệu về kinh nghiệm học tập, sở thích và suy nghĩ của mình về công việc.\nTrần Thiên Trung: Nghe có vẻ khá trang trọng.\nLý Văn: Đúng vậy, tôi thấy lần trải nghiệm này rất có ích. Bất kể kết quả thế nào, nó chắc chắn sẽ có ích cho việc tìm việc của tôi sau này.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"李文应聘的流程是怎样的？","q_vn":"Quy trình ứng tuyển của Lý Văn diễn ra như thế nào?","a_cn":"他先在网上报名、填写个人信息，然后参加笔试，笔试通过后参加面试。","a_vn":"Anh trước tiên đăng ký và điền thông tin cá nhân trên mạng, sau đó tham gia thi viết, thi viết đỗ thì tham gia phỏng vấn."},{"q_cn":"面试时负责人让李文做了什么？","q_vn":"Khi phỏng vấn, người phụ trách đã yêu cầu Lý Văn làm gì?","a_cn":"负责人让他介绍了自己的学习经历、兴趣爱好和对工作的想法。","a_vn":"Người phụ trách yêu cầu anh giới thiệu kinh nghiệm học tập, sở thích và suy nghĩ về công việc của mình."},{"q_cn":"李文怎么看待这次应聘经历？","q_vn":"Lý Văn nhìn nhận trải nghiệm ứng tuyển lần này như thế nào?","a_cn":"他觉得这次经历很有用，不论结果怎么样，对他以后找工作肯定有帮助。","a_vn":"Anh thấy trải nghiệm lần này rất có ích, bất kể kết quả thế nào nó cũng chắc chắn giúp được cho việc tìm việc của anh sau này."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"一天下午，李文突然收到一条短信，说他通过了面试，让他下周一到公司实习。李文看到信息后，激动得把手机扔到床上，在屋子里跳了起来。之后的几天，李文忙着做各种准备。为了给大家留个好印象，他去理发店把头发理了理，又去商店买了一身正式的衣服，还打算在镜子前把自我介绍练一练。","pinyin":""},{"speaker":"","cn":"在他看来，这次实习是一个新的开始。他希望不仅能够运用专业知识完成任务，还能够积累更多经验，为将来找工作打下基础。","pinyin":""}],"translation_vn":"Một buổi chiều, Lý Văn bất ngờ nhận được một tin nhắn, báo rằng anh đã qua được phỏng vấn, yêu cầu anh thứ Hai tuần sau đến công ty thực tập. Sau khi xem tin, Lý Văn xúc động đến mức vứt điện thoại lên giường, nhảy lên trong phòng. Những ngày sau đó, Lý Văn bận rộn chuẩn bị đủ thứ. Để gây ấn tượng tốt với mọi người, anh đến tiệm cắt tóc cắt lại tóc một chút, lại đến cửa hàng mua một bộ quần áo chỉnh tề, còn định đứng trước gương luyện tập phần tự giới thiệu bản thân.\nTheo anh, lần thực tập này là một khởi đầu mới. Anh hy vọng không chỉ có thể vận dụng kiến thức chuyên môn để hoàn thành nhiệm vụ, mà còn có thể tích lũy thêm nhiều kinh nghiệm, đặt nền tảng cho việc tìm việc trong tương lai.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"李文收到短信后是什么反应？","q_vn":"Sau khi nhận được tin nhắn, Lý Văn có phản ứng gì?","a_cn":"他激动得把手机扔到床上，在屋子里跳了起来。","a_vn":"Anh xúc động đến mức vứt điện thoại lên giường, nhảy lên trong phòng."},{"q_cn":"为了给大家留个好印象，李文做了哪些准备？","q_vn":"Để gây ấn tượng tốt với mọi người, Lý Văn đã chuẩn bị những gì?","a_cn":"他去理发店把头发理了理，买了一身正式的衣服，还打算在镜子前练习自我介绍。","a_vn":"Anh đến tiệm cắt tóc cắt lại tóc, mua một bộ quần áo chỉnh tề, còn định luyện tập tự giới thiệu trước gương."},{"q_cn":"李文对这次实习有什么期待？","q_vn":"Lý Văn có kỳ vọng gì về lần thực tập này?","a_cn":"他希望能够运用专业知识完成任务，还能积累更多经验，为将来找工作打下基础。","a_vn":"Anh hy vọng có thể vận dụng kiến thức chuyên môn hoàn thành nhiệm vụ, tích lũy thêm kinh nghiệm, đặt nền tảng cho việc tìm việc tương lai."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"在中国，很多大学生在毕业前都会去实习。实习的地方有公司、工厂，也有学校和医院。学生们通过实习，可以积累工作经验，熟悉工作内容和单位的管理规定，提前了解并适应社会。","pinyin":""},{"speaker":"","cn":"在实习中，学生常常会发现，课堂上学到的知识和实际工作并不完全一样。例如：有些事情，在课本上学不如自己做一遍，因为只有在做的时候，才会发现有很多细节需要注意；还有一些问题，在书上找不到答案，只能通过日常工作慢慢理解。在这样的过程中，学生能够对学到的知识有更好的认识，也更清楚自己的职业发展方向。","pinyin":""}],"translation_vn":"Ở Trung Quốc, nhiều sinh viên đại học trước khi tốt nghiệp đều sẽ đi thực tập. Nơi thực tập có thể là công ty, nhà máy, cũng có thể là trường học và bệnh viện. Thông qua thực tập, sinh viên có thể tích lũy kinh nghiệm làm việc, làm quen với nội dung công việc và quy định quản lý của đơn vị, hiểu và thích nghi với xã hội từ sớm.\nTrong quá trình thực tập, sinh viên thường phát hiện ra rằng kiến thức học trên lớp và công việc thực tế không hoàn toàn giống nhau. Ví dụ: có những việc, học trên sách không bằng tự mình làm thử một lần, vì chỉ khi làm mới phát hiện ra có rất nhiều chi tiết cần chú ý; còn có những vấn đề, tìm trong sách không thấy đáp án, chỉ có thể dần dần hiểu được qua công việc hàng ngày. Trong quá trình như vậy, sinh viên có thể có nhận thức tốt hơn về kiến thức đã học, cũng hiểu rõ hơn hướng phát triển nghề nghiệp của bản thân.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"学生通过实习可以得到哪些收获？","q_vn":"Sinh viên có thể thu được những gì qua việc thực tập?","a_cn":"可以积累工作经验，熟悉工作内容和单位的管理规定，提前了解并适应社会。","a_vn":"Có thể tích lũy kinh nghiệm làm việc, làm quen với nội dung công việc và quy định quản lý của đơn vị, hiểu và thích nghi với xã hội từ sớm."},{"q_cn":"为什么说课堂上学到的知识和实际工作不完全一样？","q_vn":"Vì sao nói kiến thức học trên lớp và công việc thực tế không hoàn toàn giống nhau?","a_cn":"因为有些事情在课本上学不如自己做一遍，很多细节和问题只有在实际工作中才能发现和理解。","a_vn":"Vì có những việc học trên sách không bằng tự mình làm, nhiều chi tiết và vấn đề chỉ có thể phát hiện và hiểu được qua công việc thực tế."},{"q_cn":"实习对学生的职业发展有什么意义？","q_vn":"Thực tập có ý nghĩa gì đối với sự phát triển nghề nghiệp của sinh viên?","a_cn":"实习能让学生对学到的知识有更好的认识，也更清楚自己的职业发展方向。","a_vn":"Thực tập giúp sinh viên có nhận thức tốt hơn về kiến thức đã học, cũng hiểu rõ hơn hướng phát triển nghề nghiệp của bản thân."}]}]},{"id":16,"title_cn":"计划赶不上变化","title_pinyin":"","title_vn":"Kế hoạch không theo kịp sự thay đổi","goals":["Có thể nghe hiểu và trao đổi về kế hoạch và sự thay đổi trong cuộc sống và công việc.","Có thể trình bày bằng lời hoặc văn bản về cách mình lập kế hoạch và điều chỉnh kế hoạch.","Hiểu được những quan điểm khác nhau của mọi người về việc lập kế hoạch và cách ứng phó với sự thay đổi."],"vocab":[{"hanzi":"本来","pinyin":"běnlái","pos":"phó./tt.","vn":"vốn, ban đầu","examples":[{"cn":"我本来打算周末去爬山的。","pinyin":"Wǒ běnlái dǎsuan zhōumò qù páshān de.","vn":"Ban đầu tôi định cuối tuần đi leo núi."},{"cn":"这件事本来不是这样的。","pinyin":"Zhè jiàn shì běnlái bú shì zhèyàng de.","vn":"Việc này ban đầu không phải như vậy."},{"cn":"本来的计划被取消了。","pinyin":"Běnlái de jìhuà bèi qǔxiāo le.","vn":"Kế hoạch ban đầu đã bị hủy."}]},{"hanzi":"只好","pinyin":"zhǐhǎo","pos":"phó.","vn":"chỉ còn cách, đành phải","examples":[{"cn":"外面下雨，我们只好留在家里。","pinyin":"Wàimiàn xiàyǔ, wǒmen zhǐhǎo liú zài jiālǐ.","vn":"Bên ngoài mưa, chúng tôi đành phải ở nhà."},{"cn":"车坏了，他只好走路去学校。","pinyin":"Chē huài le, tā zhǐhǎo zǒulù qù xuéxiào.","vn":"Xe hỏng rồi, anh ấy đành phải đi bộ đến trường."},{"cn":"票卖完了，我们只好改天再去。","pinyin":"Piào màiwán le, wǒmen zhǐhǎo gǎitiān zài qù.","vn":"Vé bán hết rồi, chúng tôi đành phải hôm khác đi."}]},{"hanzi":"赶上","pinyin":"gǎnshàng","pos":"dgt.","vn":"kịp, theo kịp","examples":[{"cn":"我差点儿没赶上公交车。","pinyin":"Wǒ chàdiǎnr méi gǎnshàng gōngjiāochē.","vn":"Tôi suýt không kịp lên xe buýt."},{"cn":"他努力学习，想赶上同学们的进度。","pinyin":"Tā nǔlì xuéxí, xiǎng gǎnshàng tóngxuémen de jìndù.","vn":"Anh ấy học chăm chỉ, muốn theo kịp tiến độ của các bạn."},{"cn":"快走吧，不然赶不上火车了。","pinyin":"Kuài zǒu ba, bùrán gǎn bu shàng huǒchē le.","vn":"Đi nhanh thôi, không thì không kịp tàu nữa."}]},{"hanzi":"旅行","pinyin":"lǚxíng","pos":"dgt.","vn":"du lịch","examples":[{"cn":"暑假我们打算去云南旅行。","pinyin":"Shǔjià wǒmen dǎsuan qù Yúnnán lǚxíng.","vn":"Kỳ nghỉ hè chúng tôi định đi du lịch Vân Nam."},{"cn":"旅行能让人放松心情。","pinyin":"Lǚxíng néng ràng rén fàngsōng xīnqíng.","vn":"Du lịch có thể giúp con người thoải mái tâm trạng."},{"cn":"他每年都会出去旅行一次。","pinyin":"Tā měinián dōu huì chūqù lǚxíng yí cì.","vn":"Mỗi năm anh ấy đều đi du lịch một lần."}]},{"hanzi":"推迟","pinyin":"tuīchí","pos":"dgt.","vn":"trì hoãn, lùi lại","examples":[{"cn":"会议推迟到下午三点了。","pinyin":"Huìyì tuīchí dào xiàwǔ sān diǎn le.","vn":"Cuộc họp đã bị lùi đến 3 giờ chiều."},{"cn":"由于天气不好，比赛推迟了。","pinyin":"Yóuyú tiānqì bù hǎo, bǐsài tuīchí le.","vn":"Do thời tiết xấu, cuộc thi đã bị lùi lại."},{"cn":"我们只能把旅行计划推迟了。","pinyin":"Wǒmen zhǐ néng bǎ lǚxíng jìhuà tuīchí le.","vn":"Chúng tôi chỉ có thể trì hoãn kế hoạch du lịch."}]},{"hanzi":"取消","pinyin":"qǔxiāo","pos":"dgt.","vn":"hủy bỏ","examples":[{"cn":"因为下雨，活动取消了。","pinyin":"Yīnwèi xiàyǔ, huódòng qǔxiāo le.","vn":"Vì mưa nên hoạt động đã bị hủy."},{"cn":"他取消了今天的会议。","pinyin":"Tā qǔxiāo le jīntiān de huìyì.","vn":"Anh ấy đã hủy cuộc họp hôm nay."},{"cn":"我把酒店订单取消了。","pinyin":"Wǒ bǎ jiǔdiàn dìngdān qǔxiāo le.","vn":"Tôi đã hủy đơn đặt phòng khách sạn."}]},{"hanzi":"可惜","pinyin":"kěxī","pos":"tt.","vn":"đáng tiếc","examples":[{"cn":"没能参加这次比赛真可惜。","pinyin":"Méi néng cānjiā zhè cì bǐsài zhēn kěxī.","vn":"Không thể tham gia cuộc thi lần này thật đáng tiếc."},{"cn":"这么好的机会错过了，太可惜了。","pinyin":"Zhème hǎo de jīhuì cuòguò le, tài kěxī le.","vn":"Lỡ mất cơ hội tốt như vậy, quá đáng tiếc."},{"cn":"票已经卖完了，真是可惜。","pinyin":"Piào yǐjīng màiwán le, zhēnshi kěxī.","vn":"Vé đã bán hết rồi, thật đáng tiếc."}]},{"hanzi":"确实","pinyin":"quèshí","pos":"phó.","vn":"đúng là, thật là","examples":[{"cn":"这个办法确实很有效。","pinyin":"Zhège bànfǎ quèshí hěn yǒuxiào.","vn":"Cách này đúng là rất hiệu quả."},{"cn":"他确实很努力。","pinyin":"Tā quèshí hěn nǔlì.","vn":"Anh ấy đúng là rất chăm chỉ."},{"cn":"这件事确实不容易做到。","pinyin":"Zhè jiàn shì quèshí bù róngyì zuòdào.","vn":"Việc này đúng là không dễ làm được."}]},{"hanzi":"等到","pinyin":"děngdào","pos":"giới.","vn":"đợi đến khi","examples":[{"cn":"等到放假，我们就去旅行。","pinyin":"Děngdào fàngjià, wǒmen jiù qù lǚxíng.","vn":"Đợi đến khi nghỉ, chúng ta sẽ đi du lịch."},{"cn":"等到考试结束，他才放松下来。","pinyin":"Děngdào kǎoshì jiéshù, tā cái fàngsōng xiàlái.","vn":"Đợi đến khi thi xong, anh ấy mới thoải mái lại."},{"cn":"等到天气好一点儿再出门吧。","pinyin":"Děngdào tiānqì hǎo yìdiǎnr zài chūmén ba.","vn":"Đợi đến khi thời tiết tốt hơn một chút hãy ra ngoài."}]},{"hanzi":"早晨","pinyin":"zǎochen","pos":"dt.","vn":"buổi sáng sớm","examples":[{"cn":"他每天早晨都去跑步。","pinyin":"Tā měitiān zǎochen dōu qù pǎobù.","vn":"Mỗi sáng sớm anh ấy đều đi chạy bộ."},{"cn":"早晨的空气特别新鲜。","pinyin":"Zǎochen de kōngqì tèbié xīnxiān.","vn":"Không khí buổi sáng sớm rất trong lành."},{"cn":"会议改到早晨九点了。","pinyin":"Huìyì gǎidào zǎochen jiǔ diǎn le.","vn":"Cuộc họp đã đổi sang 9 giờ sáng."}]},{"hanzi":"忽然","pinyin":"hūrán","pos":"phó.","vn":"bất ngờ, bỗng nhiên","examples":[{"cn":"他忽然想起了一件重要的事。","pinyin":"Tā hūrán xiǎngqǐ le yí jiàn zhòngyào de shì.","vn":"Anh ấy bất ngờ nhớ ra một việc quan trọng."},{"cn":"天忽然下起了大雨。","pinyin":"Tiān hūrán xià qǐ le dàyǔ.","vn":"Trời bất ngờ đổ mưa to."},{"cn":"会议时间忽然改变了。","pinyin":"Huìyì shíjiān hūrán gǎibiàn le.","vn":"Thời gian họp bất ngờ thay đổi."}]},{"hanzi":"增加","pinyin":"zēngjiā","pos":"dgt.","vn":"tăng thêm","examples":[{"cn":"公司增加了很多新员工。","pinyin":"Gōngsī zēngjiā le hěn duō xīn yuángōng.","vn":"Công ty đã tuyển thêm nhiều nhân viên mới."},{"cn":"这学期课程增加了不少。","pinyin":"Zhè xuéqī kèchéng zēngjiā le bùshǎo.","vn":"Chương trình học kỳ này tăng thêm khá nhiều."},{"cn":"他想增加一些内容。","pinyin":"Tā xiǎng zēngjiā yìxiē nèiróng.","vn":"Anh ấy muốn bổ sung thêm một số nội dung."}]},{"hanzi":"调整","pinyin":"tiáozhěng","pos":"dgt.","vn":"điều chỉnh","examples":[{"cn":"我们需要调整一下计划。","pinyin":"Wǒmen xūyào tiáozhěng yíxià jìhuà.","vn":"Chúng ta cần điều chỉnh một chút kế hoạch."},{"cn":"他调整了自己的学习方法。","pinyin":"Tā tiáozhěng le zìjǐ de xuéxí fāngfǎ.","vn":"Anh ấy đã điều chỉnh phương pháp học tập của mình."},{"cn":"会议内容调整了一些。","pinyin":"Huìyì nèiróng tiáozhěng le yìxiē.","vn":"Nội dung cuộc họp đã được điều chỉnh một chút."}]},{"hanzi":"错误","pinyin":"cuòwù","pos":"dt./tt.","vn":"sai lầm, sai sót","examples":[{"cn":"这份材料里有一个错误。","pinyin":"Zhè fèn cáiliào lǐ yǒu yí ge cuòwù.","vn":"Trong tài liệu này có một lỗi sai."},{"cn":"他发现了自己的错误并及时改正。","pinyin":"Tā fāxiàn le zìjǐ de cuòwù bìng jíshí gǎizhèng.","vn":"Anh ấy phát hiện lỗi của mình và sửa kịp thời."},{"cn":"这个答案是错误的。","pinyin":"Zhège dá'àn shì cuòwù de.","vn":"Đáp án này là sai."}]},{"hanzi":"并且","pinyin":"bìngqiě","pos":"liên.","vn":"và, hơn nữa","examples":[{"cn":"他努力学习，并且取得了好成绩。","pinyin":"Tā nǔlì xuéxí, bìngqiě qǔdé le hǎo chéngjì.","vn":"Anh ấy học chăm chỉ, và đạt được thành tích tốt."},{"cn":"这个方法简单，并且很有效。","pinyin":"Zhège fāngfǎ jiǎndān, bìngqiě hěn yǒuxiào.","vn":"Phương pháp này đơn giản, và rất hiệu quả."},{"cn":"他完成了任务，并且做得很好。","pinyin":"Tā wánchéng le rènwù, bìngqiě zuò de hěn hǎo.","vn":"Anh ấy đã hoàn thành nhiệm vụ, và làm rất tốt."}]},{"hanzi":"例子","pinyin":"lìzi","pos":"dt.","vn":"ví dụ","examples":[{"cn":"老师举了一个很有意思的例子。","pinyin":"Lǎoshī jǔ le yí ge hěn yǒuyìsi de lìzi.","vn":"Giáo viên đã đưa ra một ví dụ rất thú vị."},{"cn":"你能不能再给我一个例子？","pinyin":"Nǐ néng bu néng zài gěi wǒ yí ge lìzi?","vn":"Bạn có thể cho tôi thêm một ví dụ nữa không?"},{"cn":"这篇文章用了很多例子来说明观点。","pinyin":"Zhè piān wénzhāng yòng le hěn duō lìzi lái shuōmíng guāndiǎn.","vn":"Bài viết này dùng nhiều ví dụ để giải thích quan điểm."}]},{"hanzi":"关键","pinyin":"guānjiàn","pos":"dt./tt.","vn":"mấu chốt, chủ chốt","examples":[{"cn":"成功的关键是坚持。","pinyin":"Chénggōng de guānjiàn shì jiānchí.","vn":"Mấu chốt của thành công là sự kiên trì."},{"cn":"这是一个很关键的问题。","pinyin":"Zhè shì yí ge hěn guānjiàn de wèntí.","vn":"Đây là một vấn đề rất quan trọng."},{"cn":"关键是我们怎么去面对困难。","pinyin":"Guānjiàn shì wǒmen zěnme qù miànduì kùnnan.","vn":"Mấu chốt là chúng ta đối mặt với khó khăn như thế nào."}]},{"hanzi":"详细","pinyin":"xiángxì","pos":"tt.","vn":"chi tiết, tỉ mỉ","examples":[{"cn":"请你详细介绍一下这个项目。","pinyin":"Qǐng nǐ xiángxì jièshào yíxià zhège xiàngmù.","vn":"Xin bạn hãy giới thiệu chi tiết dự án này."},{"cn":"他写了一份很详细的报告。","pinyin":"Tā xiě le yí fèn hěn xiángxì de bàogào.","vn":"Anh ấy đã viết một bản báo cáo rất chi tiết."},{"cn":"地图上标出了详细的路线。","pinyin":"Dìtú shang biāo chū le xiángxì de lùxiàn.","vn":"Trên bản đồ đã đánh dấu tuyến đường chi tiết."}]},{"hanzi":"时间表","pinyin":"shíjiānbiǎo","pos":"dt.","vn":"bảng thời gian, lịch trình","examples":[{"cn":"他每天都按照时间表做事。","pinyin":"Tā měitiān dōu ànzhào shíjiānbiǎo zuòshì.","vn":"Ngày nào anh ấy cũng làm việc theo lịch trình."},{"cn":"这是我们的旅行时间表。","pinyin":"Zhè shì wǒmen de lǚxíng shíjiānbiǎo.","vn":"Đây là lịch trình du lịch của chúng tôi."},{"cn":"老师给我们发了考试时间表。","pinyin":"Lǎoshī gěi wǒmen fā le kǎoshì shíjiānbiǎo.","vn":"Giáo viên đã phát cho chúng tôi lịch thi."}]},{"hanzi":"把握","pinyin":"bǎwò","pos":"dt.","vn":"sự chắc chắn, nắm chắc","examples":[{"cn":"这次考试我很有把握。","pinyin":"Zhè cì kǎoshì wǒ hěn yǒu bǎwò.","vn":"Kỳ thi lần này tôi rất chắc chắn."},{"cn":"他对完成这个任务没有把握。","pinyin":"Tā duì wánchéng zhège rènwù méiyǒu bǎwò.","vn":"Anh ấy không chắc chắn về việc hoàn thành nhiệm vụ này."},{"cn":"做好准备能让人更有把握。","pinyin":"Zuò hǎo zhǔnbèi néng ràng rén gèng yǒu bǎwò.","vn":"Chuẩn bị kỹ giúp người ta tự tin chắc chắn hơn."}]},{"hanzi":"相反","pinyin":"xiāngfǎn","pos":"liên./tt.","vn":"ngược lại, trái lại","examples":[{"cn":"他的想法和我的正好相反。","pinyin":"Tā de xiǎngfǎ hé wǒ de zhènghǎo xiāngfǎn.","vn":"Suy nghĩ của anh ấy và tôi hoàn toàn ngược nhau."},{"cn":"有人喜欢安静，相反，也有人喜欢热闹。","pinyin":"Yǒurén xǐhuan ānjìng, xiāngfǎn, yě yǒurén xǐhuan rènao.","vn":"Có người thích yên tĩnh, ngược lại cũng có người thích náo nhiệt."},{"cn":"结果和我们预想的完全相反。","pinyin":"Jiéguǒ hé wǒmen yùxiǎng de wánquán xiāngfǎn.","vn":"Kết quả hoàn toàn trái ngược với dự đoán của chúng tôi."}]},{"hanzi":"部分","pinyin":"bùfen","pos":"dt.","vn":"một phần, bộ phận","examples":[{"cn":"这只是计划的一部分。","pinyin":"Zhè zhǐshì jìhuà de yí bùfen.","vn":"Đây chỉ là một phần của kế hoạch."},{"cn":"一部分学生选择了继续读研。","pinyin":"Yí bùfen xuésheng xuǎnzé le jìxù dú yán.","vn":"Một phần sinh viên chọn tiếp tục học thạc sĩ."},{"cn":"大部分人都同意这个方案。","pinyin":"Dà bùfen rén dōu tóngyì zhège fāng'àn.","vn":"Phần lớn mọi người đều đồng ý với phương án này."}]},{"hanzi":"轻松","pinyin":"qīngsōng","pos":"tt.","vn":"thoải mái, nhẹ nhõm","examples":[{"cn":"考完试以后，他感觉很轻松。","pinyin":"Kǎowán shì yǐhòu, tā gǎnjué hěn qīngsōng.","vn":"Thi xong, anh ấy cảm thấy rất thoải mái."},{"cn":"这份工作不算轻松。","pinyin":"Zhè fèn gōngzuò bú suàn qīngsōng.","vn":"Công việc này không hề nhẹ nhàng."},{"cn":"周末出去走走能让人更轻松。","pinyin":"Zhōumò chūqù zǒuzou néng ràng rén gèng qīngsōng.","vn":"Cuối tuần ra ngoài đi dạo có thể khiến người ta thoải mái hơn."}]},{"hanzi":"标准","pinyin":"biāozhǔn","pos":"tt./dt.","vn":"chuẩn, tiêu chuẩn","examples":[{"cn":"这个问题没有标准答案。","pinyin":"Zhège wèntí méiyǒu biāozhǔn dá'àn.","vn":"Vấn đề này không có đáp án chuẩn."},{"cn":"他的普通话说得很标准。","pinyin":"Tā de pǔtōnghuà shuō de hěn biāozhǔn.","vn":"Anh ấy nói tiếng phổ thông rất chuẩn."},{"cn":"公司有自己的招聘标准。","pinyin":"Gōngsī yǒu zìjǐ de zhāopìn biāozhǔn.","vn":"Công ty có tiêu chuẩn tuyển dụng riêng."}]},{"hanzi":"严格","pinyin":"yángé","pos":"tt./dgt.","vn":"nghiêm khắc, chặt chẽ","examples":[{"cn":"老师对我们的要求很严格。","pinyin":"Lǎoshī duì wǒmen de yāoqiú hěn yángé.","vn":"Yêu cầu của giáo viên đối với chúng tôi rất nghiêm khắc."},{"cn":"他严格按照计划完成了任务。","pinyin":"Tā yángé ànzhào jìhuà wánchéng le rènwù.","vn":"Anh ấy hoàn thành nhiệm vụ nghiêm túc theo đúng kế hoạch."},{"cn":"公司对工作质量要求很严格。","pinyin":"Gōngsī duì gōngzuò zhìliàng yāoqiú hěn yángé.","vn":"Công ty yêu cầu rất nghiêm khắc về chất lượng công việc."}]},{"hanzi":"取得","pinyin":"qǔdé","pos":"dgt.","vn":"đạt được","examples":[{"cn":"他在比赛中取得了第一名。","pinyin":"Tā zài bǐsài zhōng qǔdé le dì yī míng.","vn":"Anh ấy đã đạt được giải nhất trong cuộc thi."},{"cn":"这学期他取得了不错的成绩。","pinyin":"Zhè xuéqī tā qǔdé le búcuò de chéngjì.","vn":"Học kỳ này anh ấy đạt được thành tích khá tốt."},{"cn":"公司今年取得了很大的进步。","pinyin":"Gōngsī jīnnián qǔdé le hěn dà de jìnbù.","vn":"Năm nay công ty đã đạt được những tiến bộ lớn."}]},{"hanzi":"说不定","pinyin":"shuōbudìng","pos":"phó.","vn":"có lẽ, không chừng","examples":[{"cn":"今天这么热，说不定晚上会下雨。","pinyin":"Jīntiān zhème rè, shuōbudìng wǎnshang huì xiàyǔ.","vn":"Hôm nay nóng thế này, không chừng tối sẽ mưa."},{"cn":"你再等一下，说不定他就来了。","pinyin":"Nǐ zài děng yíxià, shuōbudìng tā jiù lái le.","vn":"Bạn chờ thêm một chút, không chừng anh ấy sẽ đến."},{"cn":"多尝试几次，说不定就成功了。","pinyin":"Duō chángshì jǐ cì, shuōbudìng jiù chénggōng le.","vn":"Thử thêm vài lần, không chừng sẽ thành công."}]},{"hanzi":"灵活","pinyin":"línghuó","pos":"tt.","vn":"linh hoạt","examples":[{"cn":"遇到问题要灵活解决。","pinyin":"Yùdào wèntí yào línghuó jiějué.","vn":"Gặp vấn đề phải giải quyết linh hoạt."},{"cn":"他的工作时间比较灵活。","pinyin":"Tā de gōngzuò shíjiān bǐjiào línghuó.","vn":"Thời gian làm việc của anh ấy khá linh hoạt."},{"cn":"做计划也要灵活调整。","pinyin":"Zuò jìhuà yě yào línghuó tiáozhěng.","vn":"Lập kế hoạch cũng cần điều chỉnh linh hoạt."}]},{"hanzi":"一切","pinyin":"yíqiè","pos":"đt.","vn":"tất cả, mọi thứ","examples":[{"cn":"一切都准备好了。","pinyin":"Yíqiè dōu zhǔnbèi hǎo le.","vn":"Mọi thứ đều đã chuẩn bị xong."},{"cn":"他为了这次比赛付出了一切。","pinyin":"Tā wèile zhè cì bǐsài fùchū le yíqiè.","vn":"Anh ấy đã bỏ ra tất cả cho cuộc thi lần này."},{"cn":"一切都会变好的。","pinyin":"Yíqiè dōu huì biàn hǎo de.","vn":"Mọi thứ rồi sẽ tốt hơn."}]},{"hanzi":"却","pinyin":"què","pos":"phó.","vn":"nhưng, lại","examples":[{"cn":"他很努力，却没有得到好结果。","pinyin":"Tā hěn nǔlì, què méiyǒu dédào hǎo jiéguǒ.","vn":"Anh ấy rất cố gắng, nhưng lại không có được kết quả tốt."},{"cn":"天气预报说会晴天，却突然下雨了。","pinyin":"Tiānqì yùbào shuō huì qíngtiān, què tūrán xiàyǔ le.","vn":"Dự báo thời tiết nói trời sẽ nắng, nhưng lại bất ngờ đổ mưa."},{"cn":"他看起来很年轻，却已经四十岁了。","pinyin":"Tā kàn qǐlái hěn niánqīng, què yǐjīng sìshí suì le.","vn":"Anh ấy trông còn trẻ, nhưng lại đã bốn mươi tuổi rồi."}]},{"hanzi":"不得不","pinyin":"bùdébù","pos":"phó.","vn":"không thể không, buộc phải","examples":[{"cn":"因为下大雨，我们不得不取消旅行。","pinyin":"Yīnwèi xià dàyǔ, wǒmen bùdébù qǔxiāo lǚxíng.","vn":"Vì mưa to, chúng tôi buộc phải hủy chuyến du lịch."},{"cn":"他身体不好，不得不请假休息。","pinyin":"Tā shēntǐ bù hǎo, bùdébù qǐngjià xiūxi.","vn":"Sức khỏe anh ấy không tốt, buộc phải xin nghỉ."},{"cn":"情况变化，我们不得不改变计划。","pinyin":"Qíngkuàng biànhuà, wǒmen bùdébù gǎibiàn jìhuà.","vn":"Tình hình thay đổi, chúng tôi buộc phải thay đổi kế hoạch."}]},{"hanzi":"约","pinyin":"yuē","pos":"dgt./phó.","vn":"hẹn; khoảng","examples":[{"cn":"我和朋友约好周末见面。","pinyin":"Wǒ hé péngyou yuē hǎo zhōumò jiànmiàn.","vn":"Tôi đã hẹn với bạn gặp mặt vào cuối tuần."},{"cn":"从这里到学校约三公里。","pinyin":"Cóng zhèlǐ dào xuéxiào yuē sān gōnglǐ.","vn":"Từ đây đến trường khoảng ba cây số."},{"cn":"他约了几个朋友一起吃饭。","pinyin":"Tā yuē le jǐ ge péngyou yìqǐ chīfàn.","vn":"Anh ấy hẹn vài người bạn cùng ăn cơm."}]},{"hanzi":"不便","pinyin":"búbiàn","pos":"tt./dgt.","vn":"bất tiện","examples":[{"cn":"地铁停了，给大家出行带来不便。","pinyin":"Dìtiě tíng le, gěi dàjiā chūxíng dàilái búbiàn.","vn":"Tàu điện ngầm ngừng chạy, gây bất tiện cho việc đi lại của mọi người."},{"cn":"这个安排有点儿不便。","pinyin":"Zhège ānpái yǒudiǎnr búbiàn.","vn":"Cách sắp xếp này có chút bất tiện."},{"cn":"给您带来不便，我们感到很抱歉。","pinyin":"Gěi nín dàilái búbiàn, wǒmen gǎndào hěn bàoqiàn.","vn":"Gây bất tiện cho bạn, chúng tôi cảm thấy rất xin lỗi."}]},{"hanzi":"失望","pinyin":"shīwàng","pos":"tt./dgt.","vn":"thất vọng","examples":[{"cn":"考试没考好，他很失望。","pinyin":"Kǎoshì méi kǎo hǎo, tā hěn shīwàng.","vn":"Thi không tốt, anh ấy rất thất vọng."},{"cn":"这个结果让大家都很失望。","pinyin":"Zhège jiéguǒ ràng dàjiā dōu hěn shīwàng.","vn":"Kết quả này khiến mọi người đều thất vọng."},{"cn":"别让父母失望。","pinyin":"Bié ràng fùmǔ shīwàng.","vn":"Đừng để cha mẹ thất vọng."}]},{"hanzi":"也许","pinyin":"yěxǔ","pos":"phó.","vn":"có lẽ, có thể","examples":[{"cn":"他也许已经知道这件事了。","pinyin":"Tā yěxǔ yǐjīng zhīdào zhè jiàn shì le.","vn":"Có lẽ anh ấy đã biết việc này rồi."},{"cn":"明天也许会下雨。","pinyin":"Míngtiān yěxǔ huì xiàyǔ.","vn":"Ngày mai có lẽ sẽ mưa."},{"cn":"这件事也许没有那么简单。","pinyin":"Zhè jiàn shì yěxǔ méiyǒu nàme jiǎndān.","vn":"Việc này có lẽ không đơn giản như vậy."}]},{"hanzi":"逛","pinyin":"guàng","pos":"dgt.","vn":"đi dạo, đi chơi","examples":[{"cn":"周末我们去商场逛逛吧。","pinyin":"Zhōumò wǒmen qù shāngchǎng guàngguang ba.","vn":"Cuối tuần chúng ta đi dạo trung tâm thương mại nhé."},{"cn":"他喜欢一个人逛公园。","pinyin":"Tā xǐhuan yí ge rén guàng gōngyuán.","vn":"Anh ấy thích đi dạo công viên một mình."},{"cn":"我们在老街上逛了一下午。","pinyin":"Wǒmen zài lǎojiē shàng guàng le yí xiàwǔ.","vn":"Chúng tôi đi dạo ở phố cổ cả một buổi chiều."}]},{"hanzi":"有趣","pinyin":"yǒuqù","pos":"tt.","vn":"thú vị","examples":[{"cn":"这本书的故事很有趣。","pinyin":"Zhè běn shū de gùshi hěn yǒuqù.","vn":"Câu chuyện trong cuốn sách này rất thú vị."},{"cn":"这是一次非常有趣的经历。","pinyin":"Zhè shì yí cì fēicháng yǒuqù de jīnglì.","vn":"Đây là một trải nghiệm rất thú vị."},{"cn":"他讲的笑话很有趣。","pinyin":"Tā jiǎng de xiàohuà hěn yǒuqù.","vn":"Câu chuyện cười anh ấy kể rất thú vị."}]},{"hanzi":"观看","pinyin":"guānkàn","pos":"dgt.","vn":"xem, theo dõi","examples":[{"cn":"我们在家观看了一场比赛。","pinyin":"Wǒmen zài jiā guānkàn le yì chǎng bǐsài.","vn":"Chúng tôi đã xem một trận đấu ở nhà."},{"cn":"很多人去现场观看了演出。","pinyin":"Hěn duō rén qù xiànchǎng guānkàn le yǎnchū.","vn":"Nhiều người đã đến xem trực tiếp buổi diễn."},{"cn":"晚上我打算观看一部电影。","pinyin":"Wǎnshang wǒ dǎsuan guānkàn yí bù diànyǐng.","vn":"Tối nay tôi định xem một bộ phim."}]},{"hanzi":"部","pinyin":"bù","pos":"lượng.","vn":"bộ (dùng cho phim)","examples":[{"cn":"这部电影非常好看。","pinyin":"Zhè bù diànyǐng fēicháng hǎokàn.","vn":"Bộ phim này rất hay."},{"cn":"我昨天看了一部新电影。","pinyin":"Wǒ zuótiān kàn le yí bù xīn diànyǐng.","vn":"Hôm qua tôi đã xem một bộ phim mới."},{"cn":"他写了一部关于旅行的小说。","pinyin":"Tā xiě le yí bù guānyú lǚxíng de xiǎoshuō.","vn":"Anh ấy đã viết một cuốn tiểu thuyết về du lịch."}]},{"hanzi":"无法","pinyin":"wúfǎ","pos":"dgt.","vn":"không có cách nào, không thể","examples":[{"cn":"这件事他无法解决。","pinyin":"Zhè jiàn shì tā wúfǎ jiějué.","vn":"Việc này anh ấy không thể giải quyết được."},{"cn":"很多变化都是无法提前知道的。","pinyin":"Hěn duō biànhuà dōu shì wúfǎ tíqián zhīdào de.","vn":"Nhiều sự thay đổi đều không thể biết trước được."},{"cn":"我无法接受这个结果。","pinyin":"Wǒ wúfǎ jiēshòu zhège jiéguǒ.","vn":"Tôi không thể chấp nhận kết quả này."}]},{"hanzi":"接受","pinyin":"jiēshòu","pos":"dgt.","vn":"tiếp nhận, chấp nhận","examples":[{"cn":"他接受了这个工作机会。","pinyin":"Tā jiēshòu le zhège gōngzuò jīhuì.","vn":"Anh ấy đã chấp nhận cơ hội công việc này."},{"cn":"我们要学会接受变化。","pinyin":"Wǒmen yào xuéhuì jiēshòu biànhuà.","vn":"Chúng ta phải học cách chấp nhận sự thay đổi."},{"cn":"他接受了朋友的建议。","pinyin":"Tā jiēshòu le péngyou de jiànyì.","vn":"Anh ấy đã tiếp nhận lời khuyên của người bạn."}]}],"grammar":[{"title":"\"把\"字句 \"主语+把+宾语+动词+了\"","explanation_vn":"Câu chữ \"把\" \"主语+把+宾语+动词+了\" biểu thị việc xử lý một người hoặc sự việc xác định, và tạo ra một kết quả nhất định.","examples":[{"cn":"我已经把机票和酒店取消了。","pinyin":"","vn":"Tôi đã hủy vé máy bay và khách sạn rồi."},{"cn":"你把灯关了吧，我想睡觉了。","pinyin":"","vn":"Bạn tắt đèn đi, tôi muốn đi ngủ rồi."},{"cn":"你别忘了把衣服洗了，明天还得穿呢。","pinyin":"","vn":"Bạn đừng quên giặt quần áo nhé, ngày mai còn phải mặc đấy."}]},{"title":"递进复句 \"……，并且……\"","explanation_vn":"Câu phức tăng tiến \"……，并且……\", trong đó \"并且\" dùng để liên kết các hành động hoặc tình huống, biểu thị sự giải thích, bổ sung thêm.","examples":[{"cn":"再检查一下有没有细节上的错误，并且试着增加一些例子。","pinyin":"","vn":"Kiểm tra lại xem có lỗi chi tiết nào không, và thử bổ sung thêm một số ví dụ."},{"cn":"他按时完成了任务，并且做得很好。","pinyin":"","vn":"Anh ấy đã hoàn thành nhiệm vụ đúng giờ, và làm rất tốt."},{"cn":"人们的生活水平提高了，并且生活方式也发生了很大的变化。","pinyin":"","vn":"Mức sống của người dân đã được nâng cao, và phương thức sống cũng có nhiều thay đổi lớn."}]},{"title":"固定短语 \"说不定\"","explanation_vn":"Cụm từ cố định \"说不定\" biểu thị sự dự đoán, ước tính về một tình huống hoặc kết quả có thể xảy ra.","examples":[{"cn":"不做计划，说不定也会带来新的发现。","pinyin":"","vn":"Không lập kế hoạch, không chừng cũng sẽ mang lại những phát hiện mới."},{"cn":"今天这么阴，说不定会下雨。","pinyin":"","vn":"Hôm nay âm u thế này, không chừng sẽ mưa."},{"cn":"你再试一次，说不定就成功了。","pinyin":"","vn":"Bạn thử lại một lần nữa, không chừng sẽ thành công."}]},{"title":"关联副词 \"却\"","explanation_vn":"Phó từ liên kết \"却\" biểu thị sự chuyển ý, tương phản.","examples":[{"cn":"你准备好了一切，却突然出现了新情况，让你不得不改变计划。","pinyin":"","vn":"Bạn đã chuẩn bị xong mọi thứ, nhưng lại bất ngờ xuất hiện tình huống mới, khiến bạn buộc phải thay đổi kế hoạch."},{"cn":"他通过了面试，却一点儿也不激动。","pinyin":"","vn":"Anh ấy đã qua được phỏng vấn, nhưng lại chẳng hề xúc động."},{"cn":"她长得很像她姐姐，性格却完全不同。","pinyin":"","vn":"Cô ấy trông rất giống chị của mình, nhưng tính cách lại hoàn toàn khác."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"家月，周末你还打算去南京旅游吗？我去年去过那里，可以给你介绍一下。","pinyin":""},{"speaker":"白家月","cn":"本来都计划好了，可是昨天突然接到通知，下周学校要安排一次考试，所以周末只好在家复习了。","pinyin":""},{"speaker":"王一雪","cn":"真是计划赶不上变化啊！看来你的旅行计划只能推迟了。","pinyin":""},{"speaker":"白家月","cn":"是的，我已经把机票和酒店取消了。虽然有点儿可惜，但学习更重要。","pinyin":""},{"speaker":"王一雪","cn":"学习确实要放在第一位。等到考试结束后，你再找个时间去。","pinyin":""},{"speaker":"白家月","cn":"我也是这么想的，以后肯定还有很多机会。","pinyin":""}],"translation_vn":"Vương Nhất Tuyết: Gia Nguyệt, cuối tuần bạn vẫn định đi du lịch Nam Kinh chứ? Năm ngoái mình đã đến đó, có thể giới thiệu cho bạn một chút.\nBạch Gia Nguyệt: Ban đầu đều đã lên kế hoạch xong rồi, nhưng hôm qua bất ngờ nhận được thông báo, tuần sau trường sẽ tổ chức một kỳ thi, nên cuối tuần đành phải ở nhà ôn bài rồi.\nVương Nhất Tuyết: Đúng là kế hoạch không theo kịp sự thay đổi! Xem ra kế hoạch du lịch của bạn chỉ có thể lùi lại thôi.\nBạch Gia Nguyệt: Đúng vậy, mình đã hủy vé máy bay và khách sạn rồi. Tuy có chút đáng tiếc, nhưng học tập quan trọng hơn.\nVương Nhất Tuyết: Học tập đúng là phải đặt lên hàng đầu. Đợi đến khi thi xong, bạn tìm lúc khác đi vậy.\nBạch Gia Nguyệt: Mình cũng nghĩ vậy, sau này chắc chắn còn nhiều cơ hội khác.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"白家月为什么要取消周末的旅行计划？","q_vn":"Vì sao Bạch Gia Nguyệt phải hủy kế hoạch du lịch cuối tuần?","a_cn":"因为她突然接到通知，下周学校要安排一次考试，所以周末只好在家复习。","a_vn":"Vì cô bất ngờ nhận được thông báo tuần sau trường tổ chức thi, nên cuối tuần đành phải ở nhà ôn bài."},{"q_cn":"白家月对取消旅行计划有什么感受？","q_vn":"Bạch Gia Nguyệt cảm thấy thế nào về việc hủy kế hoạch du lịch?","a_cn":"她觉得有点儿可惜，但认为学习更重要。","a_vn":"Cô cảm thấy có chút đáng tiếc, nhưng cho rằng học tập quan trọng hơn."},{"q_cn":"王一雪给白家月提出了什么建议？","q_vn":"Vương Nhất Tuyết đã đưa ra lời khuyên gì cho Bạch Gia Nguyệt?","a_cn":"她建议白家月等考试结束后再找时间去旅行。","a_vn":"Cô khuyên Bạch Gia Nguyệt đợi thi xong rồi tìm thời gian khác đi du lịch."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"刚接到通知，明天早晨的会议，时间改到下周了。","pinyin":""},{"speaker":"王一雪","cn":"啊？时间都安排好了，怎么说变就变了？","pinyin":""},{"speaker":"杨同乐","cn":"是啊，没想到忽然要改时间。","pinyin":""},{"speaker":"王一雪","cn":"好吧，那再看看有没有新的安排，或者增加的会议内容。","pinyin":""},{"speaker":"杨同乐","cn":"好的。会议材料还需要调整吗？","pinyin":""},{"speaker":"王一雪","cn":"再检查一下有没有细节上的错误，并且试着增加一些例子，把内容准备得更全一些。","pinyin":""},{"speaker":"杨同乐","cn":"没问题，这样效果肯定会更好。","pinyin":""},{"speaker":"王一雪","cn":"看来有时候变化不一定是坏事，关键是我们怎么去适应变化。","pinyin":""}],"translation_vn":"Dương Đồng Lạc: Vừa nhận được thông báo, cuộc họp sáng mai đã đổi thời gian sang tuần sau rồi.\nVương Nhất Tuyết: Hả? Thời gian đã sắp xếp xong rồi, sao lại thay đổi dễ dàng vậy?\nDương Đồng Lạc: Đúng vậy, không ngờ lại bất ngờ phải đổi thời gian.\nVương Nhất Tuyết: Được rồi, vậy xem thử có sắp xếp mới nào không, hoặc có nội dung họp bổ sung không.\nDương Đồng Lạc: Được. Tài liệu họp có cần điều chỉnh không?\nVương Nhất Tuyết: Kiểm tra lại xem có lỗi chi tiết nào không, và thử bổ sung thêm một số ví dụ, chuẩn bị nội dung đầy đủ hơn một chút.\nDương Đồng Lạc: Không vấn đề gì, làm vậy hiệu quả chắc chắn sẽ tốt hơn.\nVương Nhất Tuyết: Xem ra có lúc sự thay đổi không hẳn là điều xấu, mấu chốt là chúng ta thích nghi với sự thay đổi như thế nào.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"明天早晨的会议发生了什么变化？","q_vn":"Cuộc họp sáng mai đã có thay đổi gì?","a_cn":"会议的时间改到下周了。","a_vn":"Thời gian cuộc họp đã được đổi sang tuần sau."},{"q_cn":"王一雪让杨同乐怎么调整会议材料？","q_vn":"Vương Nhất Tuyết yêu cầu Dương Đồng Lạc điều chỉnh tài liệu họp như thế nào?","a_cn":"她让杨同乐再检查细节上的错误，并且增加一些例子，把内容准备得更全一些。","a_vn":"Cô yêu cầu Dương Đồng Lạc kiểm tra lại các lỗi chi tiết, bổ sung thêm ví dụ, chuẩn bị nội dung đầy đủ hơn."},{"q_cn":"王一雪对变化有什么看法？","q_vn":"Vương Nhất Tuyết có quan điểm gì về sự thay đổi?","a_cn":"她认为变化不一定是坏事，关键是我们怎么去适应变化。","a_vn":"Cô cho rằng sự thay đổi không hẳn là điều xấu, mấu chốt là cách chúng ta thích nghi với nó."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"在生活和工作中，有的人喜欢做计划，他们会提前安排好每天要做的事情，然后按照详细的时间表去完成任务，觉得这样做更有把握。相反，也有一部分人不爱做计划，他们认为随意一些也很好，想到什么就去做什么，感觉这样比较轻松。","pinyin":""},{"speaker":"","cn":"其实，事前做计划是好是坏没有标准答案。严格按照计划做事，常常能取得不错的效果；而不做计划，说不定也会带来新的发现。无论做不做计划，只要既能按时完成任务，又能根据情况灵活调整，就是适合自己的方式。","pinyin":""}],"translation_vn":"Trong cuộc sống và công việc, có người thích lập kế hoạch, họ sẽ sắp xếp trước những việc cần làm mỗi ngày, rồi theo lịch trình chi tiết để hoàn thành nhiệm vụ, cho rằng làm như vậy sẽ chắc chắn hơn. Ngược lại, cũng có một số người không thích lập kế hoạch, họ cho rằng tùy ý một chút cũng tốt, nghĩ đến gì thì làm gì, cảm thấy như vậy thoải mái hơn.\nThực ra, lập kế hoạch trước là tốt hay xấu không có đáp án chuẩn. Làm việc nghiêm túc theo đúng kế hoạch, thường có thể đạt hiệu quả tốt; còn không lập kế hoạch, không chừng cũng mang lại những phát hiện mới. Bất kể có lập kế hoạch hay không, chỉ cần có thể hoàn thành nhiệm vụ đúng giờ, lại có thể điều chỉnh linh hoạt theo tình huống, thì đó chính là cách phù hợp với bản thân.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"喜欢做计划的人通常是怎样安排生活的？","q_vn":"Những người thích lập kế hoạch thường sắp xếp cuộc sống như thế nào?","a_cn":"他们会提前安排好每天要做的事情，然后按照详细的时间表去完成任务。","a_vn":"Họ sẽ sắp xếp trước những việc cần làm mỗi ngày, rồi theo lịch trình chi tiết để hoàn thành nhiệm vụ."},{"q_cn":"不爱做计划的人是怎么想的？","q_vn":"Những người không thích lập kế hoạch suy nghĩ thế nào?","a_cn":"他们认为随意一些也很好，想到什么就去做什么，感觉这样比较轻松。","a_vn":"Họ cho rằng tùy ý một chút cũng tốt, nghĩ đến gì thì làm gì, cảm thấy như vậy thoải mái hơn."},{"q_cn":"作者认为什么样的方式才适合自己？","q_vn":"Tác giả cho rằng cách nào mới phù hợp với bản thân?","a_cn":"只要既能按时完成任务，又能根据情况灵活调整，就是适合自己的方式。","a_vn":"Chỉ cần có thể hoàn thành nhiệm vụ đúng giờ, lại có thể điều chỉnh linh hoạt theo tình huống, thì đó chính là cách phù hợp với bản thân."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"人们常说\"计划赶不上变化\"。有时候，你准备好了一切，却突然出现了新情况，让你不得不改变计划。比如准备出去旅行，可能因为有事而取消；约好见朋友，可能因为天气不好而推迟。","pinyin":""},{"speaker":"","cn":"虽然变化经常打乱计划，给我们带来不便，甚至让人感到失望，但这些变化也许会给生活带来新的可能。比如没去成旅行，于是在家门口的小公园逛了逛，发现那里也很有趣；没见到朋友，于是在家观看了一部电影，心情也变得很愉快。","pinyin":""},{"speaker":"","cn":"生活中很多变化是无法提前知道的，我们要做的就是学会接受变化、适应变化，在变化中找到新的解决办法。这样不仅能锻炼自己在面对不同情况时解决问题的能力，也能让我们的生活更轻松。","pinyin":""}],"translation_vn":"Người ta thường nói \"kế hoạch không theo kịp sự thay đổi\". Có lúc, bạn đã chuẩn bị xong mọi thứ, nhưng lại bất ngờ xuất hiện tình huống mới, khiến bạn buộc phải thay đổi kế hoạch. Ví dụ định đi du lịch, có thể vì có việc mà phải hủy; hẹn gặp bạn, có thể vì thời tiết không tốt mà phải lùi lại.\nMặc dù sự thay đổi thường làm xáo trộn kế hoạch, gây bất tiện cho chúng ta, thậm chí khiến người ta thất vọng, nhưng những thay đổi này có lẽ sẽ mang đến cho cuộc sống những khả năng mới. Ví dụ không đi du lịch được, thế là đi dạo ở công viên nhỏ trước cửa nhà, phát hiện ra nơi đó cũng rất thú vị; không gặp được bạn, thế là ở nhà xem một bộ phim, tâm trạng cũng trở nên vui vẻ.\nNhiều sự thay đổi trong cuộc sống là không thể biết trước được, điều chúng ta cần làm chính là học cách chấp nhận sự thay đổi, thích nghi với sự thay đổi, tìm ra cách giải quyết mới trong sự thay đổi. Như vậy không chỉ có thể rèn luyện năng lực giải quyết vấn đề của bản thân khi đối mặt với các tình huống khác nhau, mà còn giúp cuộc sống của chúng ta thoải mái hơn.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"文中举了哪些计划被打乱的例子？","q_vn":"Trong bài có nêu những ví dụ nào về việc kế hoạch bị xáo trộn?","a_cn":"比如准备出去旅行可能因为有事而取消，约好见朋友可能因为天气不好而推迟。","a_vn":"Ví dụ như định đi du lịch có thể vì có việc mà phải hủy, hẹn gặp bạn có thể vì thời tiết không tốt mà phải lùi lại."},{"q_cn":"变化除了带来不便，也可能带来什么？","q_vn":"Ngoài gây bất tiện, sự thay đổi còn có thể mang lại điều gì?","a_cn":"变化也许会给生活带来新的可能，比如发现家门口的小公园很有趣，或者在家看电影也很愉快。","a_vn":"Sự thay đổi có lẽ sẽ mang đến cho cuộc sống những khả năng mới, như phát hiện công viên nhỏ trước cửa nhà rất thú vị, hoặc xem phim ở nhà cũng rất vui vẻ."},{"q_cn":"面对无法提前知道的变化，我们应该怎么做？","q_vn":"Đối mặt với những thay đổi không thể biết trước, chúng ta nên làm gì?","a_cn":"我们要学会接受变化、适应变化，在变化中找到新的解决办法。","a_vn":"Chúng ta phải học cách chấp nhận sự thay đổi, thích nghi với sự thay đổi, tìm ra cách giải quyết mới trong sự thay đổi."}]}]},{"id":17,"title_cn":"运动让我更健康","title_pinyin":"","title_vn":"Vận động giúp tôi khỏe mạnh hơn","goals":["Có thể nghe hiểu và trao đổi về các phương pháp rèn luyện thân thể, thói quen tập luyện.","Có thể trình bày bằng lời hoặc văn bản về kinh nghiệm rèn luyện thân thể và môn thể thao yêu thích của bản thân.","Hiểu được sự phát triển và ảnh hưởng của bóng bàn ở Trung Quốc."],"vocab":[{"hanzi":"路过","pinyin":"lùguò","pos":"dgt.","vn":"đi qua","examples":[{"cn":"我路过你家的时候看到你在门口。","pinyin":"Wǒ lùguò nǐ jiā de shíhou kàndào nǐ zài ménkǒu.","vn":"Lúc đi qua nhà bạn tôi thấy bạn đứng ở cửa."},{"cn":"他每天上班都会路过这家咖啡店。","pinyin":"Tā měitiān shàngbān dōu huì lùguò zhè jiā kāfēidiàn.","vn":"Ngày nào đi làm anh ấy cũng đi qua tiệm cà phê này."},{"cn":"路过超市的时候帮我买瓶水吧。","pinyin":"Lùguò chāoshì de shíhou bāng wǒ mǎi píng shuǐ ba.","vn":"Khi đi qua siêu thị thì mua giúp mình chai nước nhé."}]},{"hanzi":"趟","pinyin":"tàng","pos":"lượng.","vn":"lượt, chuyến","examples":[{"cn":"我今天要去一趟医院。","pinyin":"Wǒ jīntiān yào qù yí tàng yīyuàn.","vn":"Hôm nay tôi phải đi bệnh viện một chuyến."},{"cn":"他下午要去一趟银行。","pinyin":"Tā xiàwǔ yào qù yí tàng yínháng.","vn":"Chiều nay anh ấy phải đi ngân hàng một chuyến."},{"cn":"我每周都去一趟健身房。","pinyin":"Wǒ měi zhōu dōu qù yí tàng jiànshēnfáng.","vn":"Mỗi tuần tôi đều đi phòng gym một lần."}]},{"hanzi":"健身房","pinyin":"jiànshēnfáng","pos":"dt.","vn":"phòng tập gym","examples":[{"cn":"这个健身房设备很全。","pinyin":"Zhège jiànshēnfáng shèbèi hěn quán.","vn":"Phòng gym này trang thiết bị rất đầy đủ."},{"cn":"他下班后常去健身房锻炼。","pinyin":"Tā xiàbān hòu cháng qù jiànshēnfáng duànliàn.","vn":"Sau khi tan làm anh ấy thường đến phòng gym rèn luyện."},{"cn":"小区附近新开了一家健身房。","pinyin":"Xiǎoqū fùjìn xīn kāi le yì jiā jiànshēnfáng.","vn":"Gần khu dân cư mới mở một phòng gym."}]},{"hanzi":"健身","pinyin":"jiànshēn","pos":"dgt.","vn":"tập luyện thể hình, giữ gìn sức khỏe","examples":[{"cn":"他每天都会健身一个小时。","pinyin":"Tā měitiān dōu huì jiànshēn yí ge xiǎoshí.","vn":"Ngày nào anh ấy cũng tập gym một giờ."},{"cn":"健身可以让身体更结实。","pinyin":"Jiànshēn kěyǐ ràng shēntǐ gèng jiēshi.","vn":"Tập thể hình có thể giúp cơ thể khỏe mạnh hơn."},{"cn":"她最近开始健身了。","pinyin":"Tā zuìjìn kāishǐ jiànshēn le.","vn":"Gần đây cô ấy bắt đầu tập gym."}]},{"hanzi":"体重","pinyin":"tǐzhòng","pos":"dt.","vn":"thể trọng, cân nặng","examples":[{"cn":"他最近体重增加了不少。","pinyin":"Tā zuìjìn tǐzhòng zēngjiā le bùshǎo.","vn":"Gần đây cân nặng của anh ấy tăng lên khá nhiều."},{"cn":"我想通过运动控制体重。","pinyin":"Wǒ xiǎng tōngguò yùndòng kòngzhì tǐzhòng.","vn":"Tôi muốn kiểm soát cân nặng thông qua vận động."},{"cn":"你最近体重有变化吗？","pinyin":"Nǐ zuìjìn tǐzhòng yǒu biànhuà ma?","vn":"Gần đây cân nặng của bạn có thay đổi không?"}]},{"hanzi":"会员","pinyin":"huìyuán","pos":"dt.","vn":"hội viên, thành viên","examples":[{"cn":"我办了一张健身房的会员卡。","pinyin":"Wǒ bàn le yì zhāng jiànshēnfáng de huìyuán kǎ.","vn":"Tôi đã làm một thẻ hội viên phòng gym."},{"cn":"会员可以享受打折优惠。","pinyin":"Huìyuán kěyǐ xiǎngshòu dǎzhé yōuhuì.","vn":"Hội viên có thể được ưu đãi giảm giá."},{"cn":"这家店的会员越来越多了。","pinyin":"Zhè jiā diàn de huìyuán yuè lái yuè duō le.","vn":"Hội viên của cửa hàng này ngày càng nhiều."}]},{"hanzi":"饼干","pinyin":"bǐnggān","pos":"dt.","vn":"bánh quy","examples":[{"cn":"我包里有几块饼干。","pinyin":"Wǒ bāo lǐ yǒu jǐ kuài bǐnggān.","vn":"Trong túi tôi có vài cái bánh quy."},{"cn":"这种饼干味道不错。","pinyin":"Zhè zhǒng bǐnggān wèidào búcuò.","vn":"Loại bánh quy này vị khá ngon."},{"cn":"运动前吃点儿饼干补充体力。","pinyin":"Yùndòng qián chī diǎnr bǐnggān bǔchōng tǐlì.","vn":"Trước khi vận động ăn chút bánh quy để bổ sung thể lực."}]},{"hanzi":"酸奶","pinyin":"suānnǎi","pos":"dt.","vn":"sữa chua","examples":[{"cn":"我每天早上都喝一杯酸奶。","pinyin":"Wǒ měitiān zǎoshang dōu hē yì bēi suānnǎi.","vn":"Mỗi sáng tôi đều uống một cốc sữa chua."},{"cn":"这个牌子的酸奶很好喝。","pinyin":"Zhège páizi de suānnǎi hěn hǎohē.","vn":"Sữa chua của hãng này rất ngon."},{"cn":"健身后喝点酸奶对身体好。","pinyin":"Jiànshēn hòu hē diǎn suānnǎi duì shēntǐ hǎo.","vn":"Sau khi tập gym uống chút sữa chua tốt cho cơ thể."}]},{"hanzi":"果汁","pinyin":"guǒzhī","pos":"dt.","vn":"nước ép quả","examples":[{"cn":"她喜欢喝新鲜的果汁。","pinyin":"Tā xǐhuan hē xīnxiān de guǒzhī.","vn":"Cô ấy thích uống nước ép quả tươi."},{"cn":"我带了一瓶果汁。","pinyin":"Wǒ dài le yì píng guǒzhī.","vn":"Tôi đã mang theo một chai nước ép."},{"cn":"这家店的果汁很新鲜。","pinyin":"Zhè jiā diàn de guǒzhī hěn xīnxiān.","vn":"Nước ép quả của cửa hàng này rất tươi."}]},{"hanzi":"教练","pinyin":"jiàoliàn","pos":"dt.","vn":"huấn luyện viên","examples":[{"cn":"健身房的教练很专业。","pinyin":"Jiànshēnfáng de jiàoliàn hěn zhuānyè.","vn":"Huấn luyện viên của phòng gym rất chuyên nghiệp."},{"cn":"教练教了我们很多动作。","pinyin":"Jiàoliàn jiāo le wǒmen hěn duō dòngzuò.","vn":"Huấn luyện viên đã dạy chúng tôi nhiều động tác."},{"cn":"他想当一名篮球教练。","pinyin":"Tā xiǎng dāng yì míng lánqiú jiàoliàn.","vn":"Anh ấy muốn trở thành một huấn luyện viên bóng rổ."}]},{"hanzi":"动作","pinyin":"dòngzuò","pos":"dt.","vn":"động tác","examples":[{"cn":"这个动作需要多练习才能标准。","pinyin":"Zhège dòngzuò xūyào duō liànxí cái néng biāozhǔn.","vn":"Động tác này cần luyện tập nhiều mới chuẩn được."},{"cn":"教练把每个动作都讲得很清楚。","pinyin":"Jiàoliàn bǎ měi ge dòngzuò dōu jiǎng de hěn qīngchu.","vn":"Huấn luyện viên giảng giải rất rõ từng động tác."},{"cn":"她的动作做得非常标准。","pinyin":"Tā de dòngzuò zuò de fēicháng biāozhǔn.","vn":"Động tác của cô ấy làm rất chuẩn."}]},{"hanzi":"科学","pinyin":"kēxué","pos":"tt./dt.","vn":"khoa học","examples":[{"cn":"锻炼身体要讲科学。","pinyin":"Duànliàn shēntǐ yào jiǎng kēxué.","vn":"Rèn luyện thân thể phải khoa học."},{"cn":"他是一位科学家。","pinyin":"Tā shì yí wèi kēxuéjiā.","vn":"Ông ấy là một nhà khoa học."},{"cn":"这种饮食方式不太科学。","pinyin":"Zhè zhǒng yǐnshí fāngshì bú tài kēxué.","vn":"Phương thức ăn uống này không khoa học lắm."}]},{"hanzi":"受伤","pinyin":"shòushāng","pos":"dgt.","vn":"bị thương","examples":[{"cn":"他打球的时候受伤了。","pinyin":"Tā dǎqiú de shíhou shòushāng le.","vn":"Anh ấy bị thương khi đang chơi bóng."},{"cn":"运动前要热身，不然容易受伤。","pinyin":"Yùndòng qián yào rèshēn, bùrán róngyì shòushāng.","vn":"Trước khi vận động phải khởi động, không thì dễ bị thương."},{"cn":"他受伤后一直在休养。","pinyin":"Tā shòushāng hòu yìzhí zài xiūyǎng.","vn":"Sau khi bị thương anh ấy vẫn đang nghỉ dưỡng."}]},{"hanzi":"操场","pinyin":"cāochǎng","pos":"dt.","vn":"sân vận động, sân tập","examples":[{"cn":"同学们在操场上跑步。","pinyin":"Tóngxuémen zài cāochǎng shang pǎobù.","vn":"Các bạn học sinh đang chạy bộ trên sân vận động."},{"cn":"学校的操场很大。","pinyin":"Xuéxiào de cāochǎng hěn dà.","vn":"Sân vận động của trường rất rộng."},{"cn":"晚饭后他常去操场散步。","pinyin":"Wǎnfàn hòu tā cháng qù cāochǎng sànbù.","vn":"Sau bữa tối anh ấy thường đi dạo ở sân vận động."}]},{"hanzi":"其中","pinyin":"qízhōng","pos":"dt.","vn":"trong đó","examples":[{"cn":"这些学生中，其中一半是女生。","pinyin":"Zhèxiē xuésheng zhōng, qízhōng yíbàn shì nǚshēng.","vn":"Trong số các học sinh này, một nửa là học sinh nữ."},{"cn":"很多人喜欢运动，杨同乐就是其中之一。","pinyin":"Hěn duō rén xǐhuan yùndòng, Yáng Tónglè jiùshì qízhōng zhī yī.","vn":"Nhiều người thích vận động, Dương Đồng Lạc là một trong số đó."},{"cn":"这几本书里，其中一本很有意思。","pinyin":"Zhè jǐ běn shū lǐ, qízhōng yì běn hěn yǒuyìsi.","vn":"Trong mấy cuốn sách này, một cuốn rất thú vị."}]},{"hanzi":"之","pinyin":"zhī","pos":"trợ.","vn":"của (trợ từ chỉ sở hữu)","examples":[{"cn":"这是我最喜欢的运动之一。","pinyin":"Zhè shì wǒ zuì xǐhuan de yùndòng zhī yī.","vn":"Đây là một trong những môn thể thao tôi thích nhất."},{"cn":"长城是中国有名的建筑之一。","pinyin":"Chángchéng shì Zhōngguó yǒumíng de jiànzhù zhī yī.","vn":"Trường Thành là một trong những công trình nổi tiếng của Trung Quốc."},{"cn":"健康是人生最重要的事之一。","pinyin":"Jiànkāng shì rénshēng zuì zhòngyào de shì zhī yī.","vn":"Sức khỏe là một trong những việc quan trọng nhất của đời người."}]},{"hanzi":"火","pinyin":"huǒ","pos":"tt./dt.","vn":"nổi tiếng, hot; lửa","examples":[{"cn":"这家健身房最近特别火。","pinyin":"Zhè jiā jiànshēnfáng zuìjìn tèbié huǒ.","vn":"Phòng gym này gần đây rất hot."},{"cn":"这首歌火了很长时间。","pinyin":"Zhè shǒu gē huǒ le hěn cháng shíjiān.","vn":"Bài hát này nổi tiếng trong thời gian dài."},{"cn":"厨房里着火了，大家都跑出来了。","pinyin":"Chúfáng lǐ zháohuǒ le, dàjiā dōu pǎo chūlái le.","vn":"Nhà bếp bị cháy, mọi người đều chạy ra ngoài."}]},{"hanzi":"好处","pinyin":"hǎochù","pos":"dt.","vn":"lợi ích, điểm tốt","examples":[{"cn":"运动对身体有很多好处。","pinyin":"Yùndòng duì shēntǐ yǒu hěn duō hǎochù.","vn":"Vận động có nhiều lợi ích cho sức khỏe."},{"cn":"早睡早起的好处很多。","pinyin":"Zǎoshuì zǎoqǐ de hǎochù hěn duō.","vn":"Ngủ sớm dậy sớm có nhiều lợi ích."},{"cn":"这个方法有什么好处？","pinyin":"Zhège fāngfǎ yǒu shénme hǎochù?","vn":"Phương pháp này có lợi ích gì?"}]},{"hanzi":"设备","pinyin":"shèbèi","pos":"dt.","vn":"thiết bị","examples":[{"cn":"这家健身房的设备很全。","pinyin":"Zhè jiā jiànshēnfáng de shèbèi hěn quán.","vn":"Thiết bị của phòng gym này rất đầy đủ."},{"cn":"公司新买了一批设备。","pinyin":"Gōngsī xīn mǎi le yì pī shèbèi.","vn":"Công ty mới mua một loạt thiết bị."},{"cn":"这些设备需要定期检查。","pinyin":"Zhèxiē shèbèi xūyào dìngqī jiǎnchá.","vn":"Những thiết bị này cần được kiểm tra định kỳ."}]},{"hanzi":"全身","pinyin":"quánshēn","pos":"dt.","vn":"toàn thân","examples":[{"cn":"游泳可以锻炼全身。","pinyin":"Yóuyǒng kěyǐ duànliàn quánshēn.","vn":"Bơi lội có thể rèn luyện toàn thân."},{"cn":"运动后他全身都很累。","pinyin":"Yùndòng hòu tā quánshēn dōu hěn lèi.","vn":"Sau khi vận động toàn thân anh ấy đều mệt."},{"cn":"这项运动能让全身都得到锻炼。","pinyin":"Zhè xiàng yùndòng néng ràng quánshēn dōu dédào duànliàn.","vn":"Môn thể thao này có thể giúp toàn thân được rèn luyện."}]},{"hanzi":"准确","pinyin":"zhǔnquè","pos":"tt.","vn":"chính xác","examples":[{"cn":"他发音很准确。","pinyin":"Tā fāyīn hěn zhǔnquè.","vn":"Anh ấy phát âm rất chính xác."},{"cn":"教练帮助我把动作做得更准确。","pinyin":"Jiàoliàn bāngzhù wǒ bǎ dòngzuò zuò de gèng zhǔnquè.","vn":"Huấn luyện viên giúp tôi làm động tác chính xác hơn."},{"cn":"这个数字不太准确。","pinyin":"Zhège shùzì bú tài zhǔnquè.","vn":"Con số này không chính xác lắm."}]},{"hanzi":"仅仅","pinyin":"jǐnjǐn","pos":"phó.","vn":"chỉ, chỉ vừa","examples":[{"cn":"仅仅一个月，他就瘦了很多。","pinyin":"Jǐnjǐn yí ge yuè, tā jiù shòu le hěn duō.","vn":"Chỉ trong một tháng, anh ấy đã giảm cân khá nhiều."},{"cn":"这件事仅仅是开始。","pinyin":"Zhè jiàn shì jǐnjǐn shì kāishǐ.","vn":"Việc này chỉ mới là bắt đầu."},{"cn":"他仅仅用了十分钟就完成了。","pinyin":"Tā jǐnjǐn yòng le shí fēnzhōng jiù wánchéng le.","vn":"Anh ấy chỉ dùng mười phút là hoàn thành."}]},{"hanzi":"表扬","pinyin":"biǎoyáng","pos":"dgt.","vn":"khen ngợi","examples":[{"cn":"老师表扬了他的进步。","pinyin":"Lǎoshī biǎoyáng le tā de jìnbù.","vn":"Giáo viên đã khen ngợi sự tiến bộ của anh ấy."},{"cn":"教练表扬了我们这周的表现。","pinyin":"Jiàoliàn biǎoyáng le wǒmen zhè zhōu de biǎoxiàn.","vn":"Huấn luyện viên đã khen ngợi biểu hiện của chúng tôi tuần này."},{"cn":"他因为认真工作受到了表扬。","pinyin":"Tā yīnwèi rènzhēn gōngzuò shòudào le biǎoyáng.","vn":"Anh ấy được khen ngợi vì làm việc nghiêm túc."}]},{"hanzi":"进步","pinyin":"jìnbù","pos":"dgt./tt.","vn":"tiến bộ","examples":[{"cn":"他的中文进步很快。","pinyin":"Tā de Zhōngwén jìnbù hěn kuài.","vn":"Tiếng Trung của anh ấy tiến bộ rất nhanh."},{"cn":"坚持锻炼让他取得了很大的进步。","pinyin":"Jiānchí duànliàn ràng tā qǔdé le hěn dà de jìnbù.","vn":"Kiên trì rèn luyện giúp anh ấy có tiến bộ lớn."},{"cn":"这是一个很进步的想法。","pinyin":"Zhè shì yí ge hěn jìnbù de xiǎngfǎ.","vn":"Đây là một ý tưởng rất tiến bộ."}]},{"hanzi":"鼓励","pinyin":"gǔlì","pos":"dgt.","vn":"khuyến khích, động viên","examples":[{"cn":"教练鼓励我们坚持下去。","pinyin":"Jiàoliàn gǔlì wǒmen jiānchí xiàqù.","vn":"Huấn luyện viên động viên chúng tôi kiên trì tiếp tục."},{"cn":"父母一直鼓励他追求自己的梦想。","pinyin":"Fùmǔ yìzhí gǔlì tā zhuīqiú zìjǐ de mèngxiǎng.","vn":"Cha mẹ luôn khuyến khích anh ấy theo đuổi ước mơ của mình."},{"cn":"老师鼓励学生多提问。","pinyin":"Lǎoshī gǔlì xuésheng duō tíwèn.","vn":"Giáo viên khuyến khích học sinh đặt nhiều câu hỏi."}]},{"hanzi":"帅","pinyin":"shuài","pos":"tt.","vn":"đẹp trai, phong độ","examples":[{"cn":"他穿西装很帅。","pinyin":"Tā chuān xīzhuāng hěn shuài.","vn":"Anh ấy mặc vest rất đẹp trai."},{"cn":"坚持健身让他看起来更帅了。","pinyin":"Jiānchí jiànshēn ràng tā kàn qǐlái gèng shuài le.","vn":"Kiên trì tập gym khiến anh ấy trông đẹp trai hơn."},{"cn":"这个动作做得真帅。","pinyin":"Zhège dòngzuò zuò de zhēn shuài.","vn":"Động tác này làm thật đẹp mắt."}]},{"hanzi":"乒乓球","pinyin":"pīngpāngqiú","pos":"dt.","vn":"bóng bàn","examples":[{"cn":"他每周都打乒乓球。","pinyin":"Tā měi zhōu dōu dǎ pīngpāngqiú.","vn":"Hàng tuần anh ấy đều chơi bóng bàn."},{"cn":"乒乓球是中国很受欢迎的运动。","pinyin":"Pīngpāngqiú shì Zhōngguó hěn shòu huānyíng de yùndòng.","vn":"Bóng bàn là môn thể thao rất được yêu thích ở Trung Quốc."},{"cn":"我们学校有乒乓球队。","pinyin":"Wǒmen xuéxiào yǒu pīngpāngqiú duì.","vn":"Trường chúng tôi có đội bóng bàn."}]},{"hanzi":"队","pinyin":"duì","pos":"dt.","vn":"đội","examples":[{"cn":"他是校队的一名队员。","pinyin":"Tā shì xiàoduì de yì míng duìyuán.","vn":"Anh ấy là một thành viên của đội trường."},{"cn":"中国乒乓球队非常有名。","pinyin":"Zhōngguó pīngpāngqiú duì fēicháng yǒumíng.","vn":"Đội bóng bàn Trung Quốc rất nổi tiếng."},{"cn":"我们队赢了这场比赛。","pinyin":"Wǒmen duì yíng le zhè chǎng bǐsài.","vn":"Đội chúng tôi đã thắng trận đấu này."}]},{"hanzi":"项","pinyin":"xiàng","pos":"lượng.","vn":"hạng mục, mục","examples":[{"cn":"这次比赛有十个项目。","pinyin":"Zhè cì bǐsài yǒu shí ge xiàngmù.","vn":"Cuộc thi lần này có mười hạng mục."},{"cn":"他擅长很多项运动。","pinyin":"Tā shàncháng hěn duō xiàng yùndòng.","vn":"Anh ấy giỏi nhiều môn thể thao."},{"cn":"这是一项重要的工作。","pinyin":"Zhè shì yì xiàng zhòngyào de gōngzuò.","vn":"Đây là một công việc quan trọng."}]},{"hanzi":"赢得","pinyin":"yíngdé","pos":"dgt.","vn":"giành được","examples":[{"cn":"他们赢得了这次比赛的冠军。","pinyin":"Tāmen yíngdé le zhè cì bǐsài de guànjūn.","vn":"Họ đã giành được quán quân của cuộc thi lần này."},{"cn":"他的努力赢得了大家的尊重。","pinyin":"Tā de nǔlì yíngdé le dàjiā de zūnzhòng.","vn":"Sự nỗ lực của anh ấy đã giành được sự tôn trọng của mọi người."},{"cn":"这个产品赢得了很多顾客的喜爱。","pinyin":"Zhège chǎnpǐn yíngdé le hěn duō gùkè de xǐ'ài.","vn":"Sản phẩm này đã giành được sự yêu thích của nhiều khách hàng."}]},{"hanzi":"叫作","pinyin":"jiàozuò","pos":"dgt.","vn":"được gọi là","examples":[{"cn":"中国乒乓球队被叫作\"梦之队\"。","pinyin":"Zhōngguó pīngpāngqiú duì bèi jiàozuò \"Mèng Zhī Duì\".","vn":"Đội bóng bàn Trung Quốc được gọi là \"Đội của những giấc mơ\"."},{"cn":"这种花叫作玫瑰。","pinyin":"Zhè zhǒng huā jiàozuò méiguī.","vn":"Loại hoa này được gọi là hoa hồng."},{"cn":"他的这种做法叫作坚持不懈。","pinyin":"Tā de zhè zhǒng zuòfǎ jiàozuò jiānchí búxiè.","vn":"Cách làm này của anh ấy được gọi là sự kiên trì không ngừng."}]},{"hanzi":"梦","pinyin":"mèng","pos":"dt./dgt.","vn":"mơ, giấc mơ","examples":[{"cn":"他昨晚做了一个有趣的梦。","pinyin":"Tā zuówǎn zuò le yí ge yǒuqù de mèng.","vn":"Tối qua anh ấy đã có một giấc mơ thú vị."},{"cn":"每个人都有自己的梦。","pinyin":"Měi ge rén dōu yǒu zìjǐ de mèng.","vn":"Mỗi người đều có giấc mơ của riêng mình."},{"cn":"我梦见自己去了北京。","pinyin":"Wǒ mèng jiàn zìjǐ qù le Běijīng.","vn":"Tôi mơ thấy mình đã đến Bắc Kinh."}]},{"hanzi":"不断","pinyin":"búduàn","pos":"phó./dgt.","vn":"không ngừng","examples":[{"cn":"他不断努力，终于取得了成功。","pinyin":"Tā búduàn nǔlì, zhōngyú qǔdé le chénggōng.","vn":"Anh ấy không ngừng cố gắng, cuối cùng đã thành công."},{"cn":"队员们不断进行严格的训练。","pinyin":"Duìyuánmen búduàn jìnxíng yángé de xùnliàn.","vn":"Các thành viên đội không ngừng tiến hành huấn luyện nghiêm khắc."},{"cn":"科技在不断发展。","pinyin":"Kējì zài búduàn fāzhǎn.","vn":"Khoa học công nghệ không ngừng phát triển."}]},{"hanzi":"队员","pinyin":"duìyuán","pos":"dt.","vn":"thành viên đội","examples":[{"cn":"每个队员都很努力。","pinyin":"Měi ge duìyuán dōu hěn nǔlì.","vn":"Mỗi thành viên trong đội đều rất cố gắng."},{"cn":"他是球队里最年轻的队员。","pinyin":"Tā shì qiúduì lǐ zuì niánqīng de duìyuán.","vn":"Anh ấy là thành viên trẻ nhất trong đội."},{"cn":"队员们每天都要训练。","pinyin":"Duìyuánmen měitiān dōu yào xùnliàn.","vn":"Các thành viên đội ngày nào cũng phải tập luyện."}]},{"hanzi":"训练","pinyin":"xùnliàn","pos":"dgt.","vn":"huấn luyện, tập luyện","examples":[{"cn":"运动员每天都要训练。","pinyin":"Yùndòngyuán měitiān dōu yào xùnliàn.","vn":"Vận động viên ngày nào cũng phải tập luyện."},{"cn":"这是一次很严格的训练。","pinyin":"Zhè shì yí cì hěn yángé de xùnliàn.","vn":"Đây là một lần tập luyện rất nghiêm khắc."},{"cn":"教练安排了新的训练计划。","pinyin":"Jiàoliàn ānpái le xīn de xùnliàn jìhuà.","vn":"Huấn luyện viên đã sắp xếp kế hoạch tập luyện mới."}]},{"hanzi":"球队","pinyin":"qiúduì","pos":"dt.","vn":"đội bóng","examples":[{"cn":"这支球队很有实力。","pinyin":"Zhè zhī qiúduì hěn yǒu shílì.","vn":"Đội bóng này rất có thực lực."},{"cn":"他是这支球队的队长。","pinyin":"Tā shì zhè zhī qiúduì de duìzhǎng.","vn":"Anh ấy là đội trưởng của đội bóng này."},{"cn":"球队赢得了很多球迷的喜爱。","pinyin":"Qiúduì yíngdé le hěn duō qiúmí de xǐ'ài.","vn":"Đội bóng đã giành được sự yêu thích của nhiều người hâm mộ."}]},{"hanzi":"球迷","pinyin":"qiúmí","pos":"dt.","vn":"người hâm mộ bóng","examples":[{"cn":"他是一名忠实的球迷。","pinyin":"Tā shì yì míng zhōngshí de qiúmí.","vn":"Anh ấy là một người hâm mộ trung thành."},{"cn":"球迷们在现场为队员加油。","pinyin":"Qiúmímen zài xiànchǎng wèi duìyuán jiāyóu.","vn":"Các fan hâm mộ cổ vũ cho thành viên đội trực tiếp tại sân."},{"cn":"这支球队有很多球迷。","pinyin":"Zhè zhī qiúduì yǒu hěn duō qiúmí.","vn":"Đội bóng này có rất nhiều người hâm mộ."}]},{"hanzi":"梦想","pinyin":"mèngxiǎng","pos":"dt./dgt.","vn":"mơ ước, lý tưởng","examples":[{"cn":"他的梦想是成为一名运动员。","pinyin":"Tā de mèngxiǎng shì chéngwéi yì míng yùndòngyuán.","vn":"Mơ ước của anh ấy là trở thành một vận động viên."},{"cn":"每个人都应该有自己的梦想。","pinyin":"Měi ge rén dōu yīnggāi yǒu zìjǐ de mèngxiǎng.","vn":"Mỗi người đều nên có mơ ước riêng của mình."},{"cn":"他一直梦想着去中国留学。","pinyin":"Tā yìzhí mèngxiǎng zhe qù Zhōngguó liúxué.","vn":"Anh ấy luôn mơ ước được đi du học Trung Quốc."}]},{"hanzi":"大赛","pinyin":"dàsài","pos":"dt.","vn":"giải đấu lớn","examples":[{"cn":"他参加了世界大赛。","pinyin":"Tā cānjiā le shìjiè dàsài.","vn":"Anh ấy đã tham gia giải đấu lớn của thế giới."},{"cn":"这是一场重要的大赛。","pinyin":"Zhè shì yì chǎng zhòngyào de dàsài.","vn":"Đây là một giải đấu lớn quan trọng."},{"cn":"运动员们都希望能进入大赛。","pinyin":"Yùndòngyuánmen dōu xīwàng néng jìnrù dàsài.","vn":"Các vận động viên đều hy vọng có thể vào được giải đấu lớn."}]},{"hanzi":"赢","pinyin":"yíng","pos":"dgt.","vn":"thắng","examples":[{"cn":"我们队赢了这场比赛。","pinyin":"Wǒmen duì yíng le zhè chǎng bǐsài.","vn":"Đội chúng tôi đã thắng trận đấu này."},{"cn":"他想为球队赢下比赛。","pinyin":"Tā xiǎng wèi qiúduì yíng xià bǐsài.","vn":"Anh ấy muốn giành thắng lợi cho đội bóng."},{"cn":"这次他终于赢了。","pinyin":"Zhè cì tā zhōngyú yíng le.","vn":"Lần này cuối cùng anh ấy đã thắng."}]},{"hanzi":"连","pinyin":"lián","pos":"giới.","vn":"ngay cả, liền","examples":[{"cn":"他连早饭都没吃就去上班了。","pinyin":"Tā lián zǎofàn dōu méi chī jiù qù shàngbān le.","vn":"Anh ấy ngay cả bữa sáng cũng chưa ăn đã đi làm rồi."},{"cn":"连小孩子都喜欢打乒乓球。","pinyin":"Lián xiǎoháizi dōu xǐhuan dǎ pīngpāngqiú.","vn":"Ngay cả trẻ nhỏ cũng thích chơi bóng bàn."},{"cn":"这件事连他自己也没想到。","pinyin":"Zhè jiàn shì lián tā zìjǐ yě méi xiǎngdào.","vn":"Việc này ngay cả bản thân anh ấy cũng không ngờ tới."}]}],"grammar":[{"title":"固定格式 \"你×你的吧\"","explanation_vn":"Cấu trúc cố định \"你×你的吧\" biểu thị mỗi người làm việc của mình, không cần phải cùng làm một việc gì đó, thường dùng để từ chối một cách lịch sự.","examples":[{"cn":"您走您的吧，我一会儿还要去一趟健身房。","pinyin":"","vn":"Bạn cứ đi đi, tôi chút nữa còn phải đi phòng gym một chuyến."},{"cn":"你忙你的吧，我自己就能完成。","pinyin":"","vn":"Bạn cứ làm việc của bạn, tự tôi có thể hoàn thành được."},{"cn":"你们玩你们的吧，我今天想在家休息。","pinyin":"","vn":"Các bạn cứ chơi đi, hôm nay tôi muốn ở nhà nghỉ ngơi."}]},{"title":"固定短语 \"一A一B\"","explanation_vn":"Cụm từ cố định \"一A一B\" biểu thị sự đối xứng hoặc hai phương diện của một tình huống, trong đó A và B là các từ đơn âm tiết.","examples":[{"cn":"一来一回得半个小时，太浪费时间了。","pinyin":"","vn":"Đi một lượt về một lượt mất nửa giờ, quá lãng phí thời gian."},{"cn":"她说话的声音不大，但是一字一句说得很清楚。","pinyin":"","vn":"Giọng nói của cô ấy không lớn, nhưng từng chữ từng câu đều nói rất rõ ràng."},{"cn":"记者和运动员一问一答，谈到了很多比赛中的事情。","pinyin":"","vn":"Nhà báo và vận động viên một hỏi một đáp, nói đến nhiều việc trong trận đấu."}]},{"title":"兼语句 \"主语+表扬/批评+宾语1+动词+宾语2\"","explanation_vn":"Câu kiêm ngữ \"主语+表扬/批评+宾语1+动词+宾语2\" biểu thị việc đưa ra đánh giá về một việc mà ai đó đã làm.","examples":[{"cn":"教练也表扬他取得了很大的进步。","pinyin":"","vn":"Huấn luyện viên cũng khen ngợi anh ấy đã có tiến bộ lớn."},{"cn":"老师表扬白家月坚持每天学习中文。","pinyin":"","vn":"Giáo viên khen ngợi Bạch Gia Nguyệt kiên trì học tiếng Trung mỗi ngày."},{"cn":"经理批评他没有按时完成工作。","pinyin":"","vn":"Giám đốc phê bình anh ấy không hoàn thành công việc đúng giờ."}]},{"title":"递进复句 \"连……也/都……，……更……\"","explanation_vn":"Câu phức tăng tiến \"连……也/都……，……更……\" biểu thị việc nhấn mạnh một tình huống bằng cách đưa ra một ví dụ cực đoan.","examples":[{"cn":"连一些年龄比较大的老人都坚持打球，年轻人更是把它作为一种日常锻炼的方式。","pinyin":"","vn":"Ngay cả một số người già tuổi cao vẫn kiên trì chơi bóng, người trẻ càng coi đó là một cách rèn luyện hàng ngày."},{"cn":"我有时候连老师说的话也听不懂，听广播就更难了。","pinyin":"","vn":"Có lúc ngay cả lời giáo viên nói tôi cũng không hiểu, nghe radio thì càng khó hơn."},{"cn":"今天早上他连脸都没来得及洗，更没有时间准备早饭了。","pinyin":"","vn":"Sáng nay anh ấy ngay cả rửa mặt cũng không kịp, càng không có thời gian chuẩn bị bữa sáng."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"下班了！同乐，我今天正好要路过你们家那边，用不用我开车送你？","pinyin":""},{"speaker":"杨同乐","cn":"谢谢一雪姐，不过您走您的吧，我一会儿还要去一趟健身房。","pinyin":""},{"speaker":"王一雪","cn":"去健身房？你什么时候开始健身的？","pinyin":""},{"speaker":"杨同乐","cn":"我上个星期发现单位旁边新开了一家健身房。我最近体重增加了不少，正好想运动一下，就进去看了看。","pinyin":""},{"speaker":"王一雪","cn":"感觉怎么样？","pinyin":""},{"speaker":"杨同乐","cn":"挺不错的。当时正好有打折活动，我就办了一张会员卡。","pinyin":""}],"translation_vn":"Vương Nhất Tuyết: Tan làm rồi! Đồng Lạc, hôm nay mình vừa tiện đi qua khu nhà các bạn, có cần mình lái xe đưa bạn về không?\nDương Đồng Lạc: Cảm ơn chị Nhất Tuyết, nhưng chị cứ đi đi, em còn phải đi phòng gym một chuyến nữa.\nVương Nhất Tuyết: Đi phòng gym? Em bắt đầu tập gym từ khi nào vậy?\nDương Đồng Lạc: Tuần trước em phát hiện bên cạnh cơ quan mới mở một phòng gym. Gần đây cân nặng của em tăng lên khá nhiều, đúng lúc muốn vận động một chút, nên vào xem thử.\nVương Nhất Tuyết: Cảm thấy thế nào?\nDương Đồng Lạc: Khá tốt. Lúc đó đúng lúc có hoạt động giảm giá, em liền làm luôn một thẻ hội viên.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"杨同乐为什么拒绝了王一雪开车送他？","q_vn":"Vì sao Dương Đồng Lạc từ chối việc Vương Nhất Tuyết lái xe đưa về?","a_cn":"因为他一会儿还要去一趟健身房。","a_vn":"Vì anh còn phải đi phòng gym một chuyến nữa."},{"q_cn":"杨同乐是怎么开始健身的？","q_vn":"Dương Đồng Lạc đã bắt đầu tập gym như thế nào?","a_cn":"他发现单位旁边新开了一家健身房，正好最近体重增加了，就进去看了看，后来办了会员卡。","a_vn":"Anh phát hiện bên cạnh cơ quan mới mở một phòng gym, đúng lúc gần đây cân nặng tăng lên, nên vào xem thử, sau đó làm thẻ hội viên."},{"q_cn":"杨同乐为什么会办会员卡？","q_vn":"Vì sao Dương Đồng Lạc đã làm thẻ hội viên?","a_cn":"因为当时正好有打折活动。","a_vn":"Vì lúc đó đúng lúc có hoạt động giảm giá."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"同乐，你晚上不吃饭就去健身，不会饿吗？","pinyin":""},{"speaker":"杨同乐","cn":"我带了饼干、酸奶和果汁，一会儿吃完了再去。","pinyin":""},{"speaker":"王一雪","cn":"那你为什么不在家附近找健身房？吃完晚饭，休息一下再去，不是更好吗？","pinyin":""},{"speaker":"杨同乐","cn":"离我家最近的健身房也要坐两站公交车，一来一回得半个小时，太浪费时间了。","pinyin":""},{"speaker":"王一雪","cn":"确实。那这家健身房的教练怎么样？","pinyin":""},{"speaker":"杨同乐","cn":"教练很热情，也非常专业，动作讲得很清楚。","pinyin":""},{"speaker":"王一雪","cn":"听你这么一说，我也想试试了。我现在都是在家看着视频练，动作不一定标准。","pinyin":""},{"speaker":"杨同乐","cn":"好啊，那您也来吧。锻炼要科学，否则容易受伤。","pinyin":""}],"translation_vn":"Vương Nhất Tuyết: Đồng Lạc, tối không ăn cơm mà đi tập gym, không đói sao?\nDương Đồng Lạc: Em mang theo bánh quy, sữa chua và nước ép, chút nữa ăn xong rồi đi.\nVương Nhất Tuyết: Vậy sao em không tìm phòng gym gần nhà? Ăn tối xong, nghỉ ngơi một chút rồi đi, không tốt hơn sao?\nDương Đồng Lạc: Phòng gym gần nhà em nhất cũng phải đi hai trạm xe buýt, đi một lượt về một lượt mất nửa giờ, quá lãng phí thời gian.\nVương Nhất Tuyết: Đúng vậy. Vậy huấn luyện viên của phòng gym đó thế nào?\nDương Đồng Lạc: Huấn luyện viên rất nhiệt tình, cũng rất chuyên nghiệp, giảng động tác rất rõ ràng.\nVương Nhất Tuyết: Nghe em nói vậy, chị cũng muốn thử xem. Giờ chị chỉ toàn xem video ở nhà để tập, động tác chưa chắc đã chuẩn.\nDương Đồng Lạc: Được đó, vậy chị cũng đến đi. Rèn luyện phải khoa học, không thì dễ bị thương.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"杨同乐晚上健身前是怎么解决吃饭问题的？","q_vn":"Trước khi tập gym vào buổi tối Dương Đồng Lạc giải quyết vấn đề ăn uống như thế nào?","a_cn":"他带了饼干、酸奶和果汁，吃完再去健身。","a_vn":"Anh mang theo bánh quy, sữa chua và nước ép, ăn xong rồi mới đi tập gym."},{"q_cn":"杨同乐为什么不选择家附近的健身房？","q_vn":"Vì sao Dương Đồng Lạc không chọn phòng gym gần nhà?","a_cn":"因为离他家最近的健身房也要坐两站公交车，一来一回得半个小时，太浪费时间了。","a_vn":"Vì phòng gym gần nhà anh nhất cũng phải đi hai trạm xe buýt, đi về mất nửa giờ, quá lãng phí thời gian."},{"q_cn":"杨同乐提醒王一雪锻炼时要注意什么？","q_vn":"Dương Đồng Lạc nhắc nhở Vương Nhất Tuyết cần chú ý điều gì khi rèn luyện?","a_cn":"他提醒锻炼要科学，否则容易受伤。","a_vn":"Anh nhắc rằng rèn luyện phải khoa học, không thì dễ bị thương."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"有人爱在操场跑步，有人喜欢通过打球锻炼身体，还有一部分人愿意去健身房健身，杨同乐就是其中之一。","pinyin":""},{"speaker":"","cn":"杨同乐认为健身房火起来是因为它有很多好处——环境好、设备全，可以锻炼全身。另外，健身房里一般还有专业教练，能帮助大家把动作做准确，练习的效果也更好。","pinyin":""},{"speaker":"","cn":"仅仅经过一个月左右的锻炼，杨同乐就感觉自己的身体比以前更健康了。教练也表扬他取得了很大的进步，并鼓励他坚持下去，还说随着身体越来越好，人看起来也会更帅。","pinyin":""}],"translation_vn":"Có người thích chạy bộ ở sân vận động, có người thích rèn luyện thân thể qua chơi bóng, còn có một số người thích đến phòng gym tập luyện, Dương Đồng Lạc chính là một trong số đó.\nDương Đồng Lạc cho rằng phòng gym trở nên hot là vì nó có nhiều lợi ích—môi trường tốt, thiết bị đầy đủ, có thể rèn luyện toàn thân. Ngoài ra, trong phòng gym thường còn có huấn luyện viên chuyên nghiệp, có thể giúp mọi người làm động tác chính xác hơn, hiệu quả luyện tập cũng tốt hơn.\nChỉ sau khoảng một tháng rèn luyện, Dương Đồng Lạc đã cảm thấy cơ thể mình khỏe mạnh hơn trước. Huấn luyện viên cũng khen ngợi anh đã có tiến bộ lớn, và khuyến khích anh tiếp tục kiên trì, còn nói rằng khi cơ thể ngày càng tốt hơn, nhìn người cũng sẽ đẹp trai hơn.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"杨同乐认为健身房为什么会火起来？","q_vn":"Dương Đồng Lạc cho rằng vì sao phòng gym trở nên hot?","a_cn":"因为健身房环境好、设备全，可以锻炼全身，还有专业教练帮助大家把动作做准确。","a_vn":"Vì phòng gym có môi trường tốt, thiết bị đầy đủ, có thể rèn luyện toàn thân, lại có huấn luyện viên chuyên nghiệp giúp mọi người làm động tác chính xác."},{"q_cn":"经过一个月的锻炼，杨同乐有什么变化？","q_vn":"Sau một tháng rèn luyện, Dương Đồng Lạc có thay đổi gì?","a_cn":"他感觉自己的身体比以前更健康了，教练也表扬他取得了很大的进步。","a_vn":"Anh cảm thấy cơ thể mình khỏe mạnh hơn trước, huấn luyện viên cũng khen ngợi anh đã có tiến bộ lớn."},{"q_cn":"教练是怎么鼓励杨同乐的？","q_vn":"Huấn luyện viên đã động viên Dương Đồng Lạc như thế nào?","a_cn":"教练鼓励他坚持下去，还说随着身体越来越好，人看起来也会更帅。","a_vn":"Huấn luyện viên khuyến khích anh tiếp tục kiên trì, còn nói khi cơ thể ngày càng tốt hơn, nhìn người cũng sẽ đẹp trai hơn."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"中国乒乓球队非常有名，常在各项比赛中赢得第一名，被叫作\"梦之队\"。为了不断提高自己的水平，队员们每天都要进行严格的训练。正因为这样，球队才能在比赛中取得更好的成绩，获得更多球迷的喜爱。许多年轻的乒乓球运动员都有一个梦想，那就是进入国家队，参加世界大赛，为球队赢下比赛。","pinyin":""},{"speaker":"","cn":"在中国，除了专业运动员，喜欢打乒乓球的普通人也特别多。连一些年龄比较大的老人都坚持打球，年轻人更是把它作为一种日常锻炼的方式。可以说，乒乓球是中国人生活中最常见的运动之一。","pinyin":""}],"translation_vn":"Đội bóng bàn Trung Quốc rất nổi tiếng, thường giành được vị trí thứ nhất trong các cuộc thi, được gọi là \"Đội của những giấc mơ\". Để không ngừng nâng cao trình độ của mình, các thành viên đội ngày nào cũng phải tiến hành huấn luyện nghiêm khắc. Chính vì vậy, đội bóng mới có thể đạt được thành tích tốt hơn trong các cuộc thi, giành được sự yêu thích của nhiều người hâm mộ hơn. Nhiều vận động viên bóng bàn trẻ tuổi đều có một ước mơ, đó là được vào đội tuyển quốc gia, tham gia giải đấu lớn của thế giới, giành thắng lợi cho đội bóng.\nỞ Trung Quốc, ngoài các vận động viên chuyên nghiệp, những người bình thường thích chơi bóng bàn cũng rất nhiều. Ngay cả một số người già tuổi cao vẫn kiên trì chơi bóng, người trẻ càng coi đó là một cách rèn luyện hàng ngày. Có thể nói, bóng bàn là một trong những môn thể thao phổ biến nhất trong cuộc sống của người Trung Quốc.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"中国乒乓球队为什么被叫作\"梦之队\"？","q_vn":"Vì sao đội bóng bàn Trung Quốc được gọi là \"Đội của những giấc mơ\"?","a_cn":"因为他们非常有名，常在各项比赛中赢得第一名。","a_vn":"Vì họ rất nổi tiếng, thường giành được vị trí thứ nhất trong các cuộc thi."},{"q_cn":"许多年轻的乒乓球运动员有什么梦想？","q_vn":"Nhiều vận động viên bóng bàn trẻ tuổi có ước mơ gì?","a_cn":"他们的梦想是进入国家队，参加世界大赛，为球队赢下比赛。","a_vn":"Ước mơ của họ là được vào đội tuyển quốc gia, tham gia giải đấu lớn của thế giới, giành thắng lợi cho đội bóng."},{"q_cn":"乒乓球在中国普通人中的受欢迎程度如何？","q_vn":"Mức độ phổ biến của bóng bàn trong người dân bình thường ở Trung Quốc như thế nào?","a_cn":"喜欢打乒乓球的普通人特别多，连一些年龄比较大的老人都坚持打球，年轻人更是把它作为日常锻炼的方式。","a_vn":"Những người bình thường thích chơi bóng bàn rất nhiều, ngay cả một số người già tuổi cao vẫn kiên trì chơi bóng, người trẻ càng coi đó là cách rèn luyện hàng ngày."}]}]},{"id":18,"title_cn":"科技改变生活","title_pinyin":"","title_vn":"Công nghệ thay đổi cuộc sống","goals":["Có thể nghe hiểu và trao đổi về các chủ đề ứng dụng công nghệ mới, sự tiến bộ khoa học kỹ thuật làm thay đổi cuộc sống.","Có thể trình bày bằng lời hoặc bằng văn bản về cách quay video ngắn, quan điểm đối với video ngắn.","Hiểu được các hình thái kinh tế mới của Trung Quốc như xe đạp chia sẻ, video ngắn, kinh tế dịch vụ tận nhà."],"vocab":[{"hanzi":"猜","pinyin":"cāi","pos":"dgt.","vn":"đoán","examples":[{"cn":"你猜猜看，我手里拿的是什么？","pinyin":"Nǐ cāicai kàn, wǒ shǒu lǐ ná de shì shénme?","vn":"Bạn đoán xem, trong tay tôi đang cầm gì?"},{"cn":"我猜明天会下雨。","pinyin":"Wǒ cāi míngtiān huì xiàyǔ.","vn":"Tôi đoán ngày mai sẽ mưa."},{"cn":"他猜不出这个答案。","pinyin":"Tā cāi bu chū zhège dá'àn.","vn":"Anh ấy không đoán ra được câu trả lời này."}]},{"hanzi":"共享单车","pinyin":"gòngxiǎng dānchē","pos":"dt.","vn":"xe đạp chia sẻ (xe đạp công cộng)","examples":[{"cn":"现在很多城市都有共享单车。","pinyin":"Xiànzài hěn duō chéngshì dōu yǒu gòngxiǎng dānchē.","vn":"Hiện nay nhiều thành phố đều có xe đạp chia sẻ."},{"cn":"骑共享单车比坐公交车方便。","pinyin":"Qí gòngxiǎng dānchē bǐ zuò gōngjiāochē fāngbiàn.","vn":"Đi xe đạp chia sẻ tiện hơn đi xe buýt."},{"cn":"共享单车的费用很便宜。","pinyin":"Gòngxiǎng dānchē de fèiyong hěn piányi.","vn":"Phí sử dụng xe đạp chia sẻ rất rẻ."}]},{"hanzi":"出口","pinyin":"chūkǒu","pos":"dt.","vn":"cửa ra, lối ra","examples":[{"cn":"商场的出口在那边。","pinyin":"Shāngchǎng de chūkǒu zài nàbiān.","vn":"Lối ra của trung tâm thương mại ở đằng kia."},{"cn":"地铁站的出口有很多个。","pinyin":"Dìtiězhàn de chūkǒu yǒu hěn duō ge.","vn":"Ga tàu điện ngầm có rất nhiều lối ra."},{"cn":"请从这个出口离开。","pinyin":"Qǐng cóng zhège chūkǒu líkāi.","vn":"Xin hãy đi ra từ lối ra này."}]},{"hanzi":"推","pinyin":"tuī","pos":"dgt.","vn":"đẩy","examples":[{"cn":"他推着自行车走进了院子。","pinyin":"Tā tuīzhe zìxíngchē zǒu jìnle yuànzi.","vn":"Anh ấy đẩy xe đạp đi vào trong sân."},{"cn":"请帮我推一下这辆车。","pinyin":"Qǐng bāng wǒ tuī yíxià zhè liàng chē.","vn":"Hãy giúp tôi đẩy chiếc xe này một chút."},{"cn":"门太重了，我推不开。","pinyin":"Mén tài zhòng le, wǒ tuī bu kāi.","vn":"Cửa nặng quá, tôi đẩy không mở được."}]},{"hanzi":"对","pinyin":"duì","pos":"dgt.","vn":"hướng vào, chĩa vào","examples":[{"cn":"他对着镜子整理衣服。","pinyin":"Tā duìzhe jìngzi zhěnglǐ yīfu.","vn":"Anh ấy chỉnh lại quần áo trước gương."},{"cn":"请对着镜头笑一下。","pinyin":"Qǐng duìzhe jìngtóu xiào yíxià.","vn":"Xin hãy hướng vào máy quay và cười một chút."},{"cn":"她对着电脑说了半天话。","pinyin":"Tā duìzhe diànnǎo shuōle bàntiān huà.","vn":"Cô ấy hướng vào máy tính nói chuyện cả nửa ngày."}]},{"hanzi":"二维码","pinyin":"èrwéimǎ","pos":"dt.","vn":"mã QR","examples":[{"cn":"请扫一下这个二维码付款。","pinyin":"Qǐng sǎo yíxià zhège èrwéimǎ fùkuǎn.","vn":"Xin quét mã QR này để thanh toán."},{"cn":"现在到处都能看到二维码。","pinyin":"Xiànzài dàochù dōu néng kàndào èrwéimǎ.","vn":"Hiện nay ở đâu cũng có thể thấy mã QR."},{"cn":"我用手机扫了菜单上的二维码。","pinyin":"Wǒ yòng shǒujī sǎole càidān shàng de èrwéimǎ.","vn":"Tôi dùng điện thoại quét mã QR trên thực đơn."}]},{"hanzi":"注册","pinyin":"zhùcè","pos":"dgt.","vn":"đăng ký","examples":[{"cn":"使用这个App之前要先注册。","pinyin":"Shǐyòng zhège App zhīqián yào xiān zhùcè.","vn":"Trước khi dùng ứng dụng này cần phải đăng ký trước."},{"cn":"他用手机号码注册了一个账户。","pinyin":"Tā yòng shǒujī hàomǎ zhùcèle yí ge zhànghù.","vn":"Anh ấy dùng số điện thoại đăng ký một tài khoản."},{"cn":"注册过程很简单，几分钟就完成了。","pinyin":"Zhùcè guòchéng hěn jiǎndān, jǐ fēnzhōng jiù wánchéng le.","vn":"Quá trình đăng ký rất đơn giản, chỉ vài phút là xong."}]},{"hanzi":"费用","pinyin":"fèiyong","pos":"dt.","vn":"chi phí, phí","examples":[{"cn":"这次旅行的费用不便宜。","pinyin":"Zhè cì lǜxíng de fèiyong bù piányi.","vn":"Chi phí của chuyến du lịch này không rẻ."},{"cn":"骑车的费用比打车低多了。","pinyin":"Qíchē de fèiyong bǐ dǎchē dī duō le.","vn":"Phí đi xe đạp thấp hơn nhiều so với đi taxi."},{"cn":"学校会报销这部分费用。","pinyin":"Xuéxiào huì bàoxiāo zhè bùfen fèiyong.","vn":"Nhà trường sẽ thanh toán lại phần chi phí này."}]},{"hanzi":"说明","pinyin":"shuōmíng","pos":"dt./dgt.","vn":"thuyết minh, giải thích","examples":[{"cn":"请仔细看一下使用说明。","pinyin":"Qǐng zǐxì kàn yíxià shǐyòng shuōmíng.","vn":"Xin hãy xem kỹ hướng dẫn sử dụng."},{"cn":"老师给我们说明了这次考试的规则。","pinyin":"Lǎoshī gěi wǒmen shuōmíngle zhè cì kǎoshì de guīzé.","vn":"Thầy giáo đã giải thích cho chúng tôi quy định của kỳ thi này."},{"cn":"这份说明写得很清楚。","pinyin":"Zhè fèn shuōmíng xiě de hěn qīngchu.","vn":"Bản thuyết minh này viết rất rõ ràng."}]},{"hanzi":"办事","pinyin":"bànshì","pos":"dgt.","vn":"giải quyết công việc, xử lý việc","examples":[{"cn":"我明天要去银行办事。","pinyin":"Wǒ míngtiān yào qù yínháng bànshì.","vn":"Ngày mai tôi phải đi ngân hàng giải quyết việc."},{"cn":"他办事一向很认真。","pinyin":"Tā bànshì yíxiàng hěn rènzhēn.","vn":"Anh ấy làm việc luôn luôn rất nghiêm túc."},{"cn":"出去办事时记得带身份证。","pinyin":"Chūqù bànshì shí jìde dài shēnfènzhèng.","vn":"Khi ra ngoài giải quyết việc nhớ mang theo chứng minh thư."}]},{"hanzi":"差点儿","pinyin":"chàdiǎnr","pos":"phó.","vn":"suýt nữa, gần như","examples":[{"cn":"我今天差点儿迟到。","pinyin":"Wǒ jīntiān chàdiǎnr chídào.","vn":"Hôm nay tôi suýt nữa bị muộn."},{"cn":"他差点儿忘了带钱包。","pinyin":"Tā chàdiǎnr wàngle dài qiánbāo.","vn":"Anh ấy suýt quên mang ví tiền."},{"cn":"这件事差点儿就成功了。","pinyin":"Zhè jiàn shì chàdiǎnr jiù chénggōng le.","vn":"Việc này suýt nữa thì thành công."}]},{"hanzi":"拍","pinyin":"pāi","pos":"dgt.","vn":"chụp, quay","examples":[{"cn":"我们一起拍张照片吧。","pinyin":"Wǒmen yìqǐ pāi zhāng zhàopiàn ba.","vn":"Chúng ta cùng chụp một tấm ảnh nhé."},{"cn":"他用手机拍了一个短视频。","pinyin":"Tā yòng shǒujī pāile yí ge duǎn shìpín.","vn":"Anh ấy dùng điện thoại quay một video ngắn."},{"cn":"这部电影是在北京拍的。","pinyin":"Zhè bù diànyǐng shì zài Běijīng pāi de.","vn":"Bộ phim này được quay ở Bắc Kinh."}]},{"hanzi":"各个","pinyin":"gègè","pos":"đt./phó.","vn":"từng, mỗi","examples":[{"cn":"各个小组都完成了自己的任务。","pinyin":"Gègè xiǎozǔ dōu wánchéngle zìjǐ de rènwu.","vn":"Từng nhóm đều đã hoàn thành nhiệm vụ của mình."},{"cn":"这个消息很快传到了各个城市。","pinyin":"Zhège xiāoxi hěn kuài chuándàole gège chéngshì.","vn":"Tin tức này nhanh chóng truyền tới mọi thành phố."},{"cn":"各个学校的要求都不一样。","pinyin":"Gège xuéxiào de yāoqiú dōu bù yíyàng.","vn":"Yêu cầu của mỗi trường đều không giống nhau."}]},{"hanzi":"小组","pinyin":"xiǎozǔ","pos":"dt.","vn":"nhóm (nhỏ)","examples":[{"cn":"老师把我们分成了四个小组。","pinyin":"Lǎoshī bǎ wǒmen fēnchéngle sì ge xiǎozǔ.","vn":"Thầy giáo chia chúng tôi thành bốn nhóm nhỏ."},{"cn":"我们小组讨论得很热烈。","pinyin":"Wǒmen xiǎozǔ tǎolùn de hěn rèliè.","vn":"Nhóm chúng tôi thảo luận rất sôi nổi."},{"cn":"每个小组都要做一次报告。","pinyin":"Měi ge xiǎozǔ dōu yào zuò yí cì bàogào.","vn":"Mỗi nhóm đều phải làm một bài báo cáo."}]},{"hanzi":"讨论","pinyin":"tǎolùn","pos":"dgt.","vn":"thảo luận, bàn bạc","examples":[{"cn":"我们讨论了很久才决定下来。","pinyin":"Wǒmen tǎolùnle hěn jiǔ cái juédìng xiàlái.","vn":"Chúng tôi thảo luận rất lâu mới quyết định được."},{"cn":"大家正在讨论这个问题。","pinyin":"Dàjiā zhèngzài tǎolùn zhège wèntí.","vn":"Mọi người đang thảo luận vấn đề này."},{"cn":"老师让我们分组讨论作业。","pinyin":"Lǎoshī ràng wǒmen fēn zǔ tǎolùn zuòyè.","vn":"Thầy giáo cho chúng tôi chia nhóm thảo luận bài tập."}]},{"hanzi":"演","pinyin":"yǎn","pos":"dgt.","vn":"diễn, đóng (vai)","examples":[{"cn":"他在这部电影里演一个医生。","pinyin":"Tā zài zhè bù diànyǐng lǐ yǎn yí ge yīshēng.","vn":"Anh ấy đóng vai một bác sĩ trong bộ phim này."},{"cn":"这个节目是学生自己演的。","pinyin":"Zhège jiémù shì xuésheng zìjǐ yǎn de.","vn":"Tiết mục này do chính các học sinh diễn."},{"cn":"她演得非常自然。","pinyin":"Tā yǎn de fēicháng zìrán.","vn":"Cô ấy diễn rất tự nhiên."}]},{"hanzi":"厨师","pinyin":"chúshī","pos":"dt.","vn":"đầu bếp","examples":[{"cn":"这家餐厅的厨师手艺很好。","pinyin":"Zhè jiā cāntīng de chúshī shǒuyì hěn hǎo.","vn":"Đầu bếp của nhà hàng này có tay nghề rất tốt."},{"cn":"他从小就想当一名厨师。","pinyin":"Tā cóngxiǎo jiù xiǎng dāng yì míng chúshī.","vn":"Từ nhỏ anh ấy đã muốn trở thành một đầu bếp."},{"cn":"厨师正在厨房里做饭。","pinyin":"Chúshī zhèngzài chúfáng lǐ zuòfàn.","vn":"Đầu bếp đang nấu ăn trong nhà bếp."}]},{"hanzi":"各地","pinyin":"gèdì","pos":"dt.","vn":"các nơi, mọi miền","examples":[{"cn":"中国各地的美食都不一样。","pinyin":"Zhōngguó gèdì de měishí dōu bù yíyàng.","vn":"Món ăn ngon ở các nơi của Trung Quốc đều khác nhau."},{"cn":"各地的游客都来这里旅游。","pinyin":"Gèdì de yóukè dōu lái zhèlǐ lǚyóu.","vn":"Khách du lịch từ các nơi đều đến đây du lịch."},{"cn":"这个消息很快传到了各地。","pinyin":"Zhège xiāoxi hěn kuài chuándàole gèdì.","vn":"Tin tức này nhanh chóng truyền đến các nơi."}]},{"hanzi":"著名","pinyin":"zhùmíng","pos":"tt.","vn":"nổi tiếng","examples":[{"cn":"他是一位著名的作家。","pinyin":"Tā shì yí wèi zhùmíng de zuòjiā.","vn":"Anh ấy là một nhà văn nổi tiếng."},{"cn":"这是本地最著名的小吃。","pinyin":"Zhè shì běndì zuì zhùmíng de xiǎochī.","vn":"Đây là món ăn nhẹ nổi tiếng nhất của địa phương."},{"cn":"这座山很著名，每年都有很多游客。","pinyin":"Zhè zuò shān hěn zhùmíng, měi nián dōu yǒu hěn duō yóukè.","vn":"Ngọn núi này rất nổi tiếng, năm nào cũng có nhiều khách du lịch."}]},{"hanzi":"小吃","pinyin":"xiǎochī","pos":"dt.","vn":"món ăn nhẹ, đồ ăn vặt","examples":[{"cn":"这条街上有很多小吃。","pinyin":"Zhè tiáo jiē shàng yǒu hěn duō xiǎochī.","vn":"Trên con phố này có rất nhiều món ăn vặt."},{"cn":"我最喜欢吃北京的小吃。","pinyin":"Wǒ zuì xǐhuan chī Běijīng de xiǎochī.","vn":"Tôi thích nhất ăn món ăn vặt của Bắc Kinh."},{"cn":"这家小吃店生意很好。","pinyin":"Zhè jiā xiǎochī diàn shēngyì hěn hǎo.","vn":"Quán ăn vặt này buôn bán rất tốt."}]},{"hanzi":"互联网","pinyin":"hùliánwǎng","pos":"dt.","vn":"internet, mạng internet","examples":[{"cn":"互联网让人们的生活更方便了。","pinyin":"Hùliánwǎng ràng rénmen de shēnghuó gèng fāngbiàn le.","vn":"Internet làm cho cuộc sống của con người tiện lợi hơn."},{"cn":"这个视频被放到互联网上了。","pinyin":"Zhège shìpín bèi fàngdào hùliánwǎng shàng le.","vn":"Video này đã được đưa lên internet."},{"cn":"现在几乎每个人都离不开互联网。","pinyin":"Xiànzài jīhū měi ge rén dōu lí bu kāi hùliánwǎng.","vn":"Hiện nay hầu như ai cũng không thể thiếu internet."}]},{"hanzi":"点赞","pinyin":"diǎnzàn","pos":"dgt.","vn":"like, bấm thích","examples":[{"cn":"很多人给这个视频点赞。","pinyin":"Hěn duō rén gěi zhège shìpín diǎnzàn.","vn":"Rất nhiều người đã like video này."},{"cn":"我也给你点了一个赞。","pinyin":"Wǒ yě gěi nǐ diǎnle yí ge zàn.","vn":"Tôi cũng đã like cho bạn rồi."},{"cn":"这条消息已经有一千人点赞了。","pinyin":"Zhè tiáo xiāoxi yǐjīng yǒu yìqiān rén diǎnzàn le.","vn":"Tin này đã có một nghìn người like."}]},{"hanzi":"AI眼镜","pinyin":"AI yǎnjìng","pos":"dt.","vn":"kính AI (kính thông minh)","examples":[{"cn":"他买了一个AI眼镜。","pinyin":"Tā mǎile yí ge AI yǎnjìng.","vn":"Anh ấy đã mua một cái kính AI."},{"cn":"AI眼镜可以帮助我们翻译外语。","pinyin":"AI yǎnjìng kěyǐ bāngzhù wǒmen fānyì wàiyǔ.","vn":"Kính AI có thể giúp chúng ta dịch ngoại ngữ."},{"cn":"戴上AI眼镜就能看到更多信息。","pinyin":"Dàishàng AI yǎnjìng jiù néng kàndào gèng duō xìnxī.","vn":"Đeo kính AI lên thì có thể nhìn thấy nhiều thông tin hơn."}]},{"hanzi":"3D打印机","pinyin":"3D dǎyìnjī","pos":"dt.","vn":"máy in 3D","examples":[{"cn":"学校新买了一台3D打印机。","pinyin":"Xuéxiào xīn mǎile yì tái 3D dǎyìnjī.","vn":"Trường mới mua một chiếc máy in 3D."},{"cn":"他用3D打印机做了一个小玩具。","pinyin":"Tā yòng 3D dǎyìnjī zuòle yí ge xiǎo wánjù.","vn":"Anh ấy dùng máy in 3D làm một đồ chơi nhỏ."},{"cn":"3D打印机可以打印出很多种材料。","pinyin":"3D dǎyìnjī kěyǐ dǎyìn chū hěn duō zhǒng cáiliào.","vn":"Máy in 3D có thể in ra nhiều loại vật liệu."}]},{"hanzi":"上门","pinyin":"shàngmén","pos":"dgt.","vn":"đến tận nhà, đến nhà (phục vụ, thăm)","examples":[{"cn":"服务人员会上门帮忙维修。","pinyin":"Fúwù rényuán huì shàngmén bāngmáng wéixiū.","vn":"Nhân viên dịch vụ sẽ đến tận nhà giúp sửa chữa."},{"cn":"周末他打算去朋友家上门拜访。","pinyin":"Zhōumò tā dǎsuan qù péngyou jiā shàngmén bàifǎng.","vn":"Cuối tuần anh ấy định đến nhà bạn để thăm."},{"cn":"现在很多服务都可以上门完成。","pinyin":"Xiànzài hěn duō fúwù dōu kěyǐ shàngmén wánchéng.","vn":"Hiện nay nhiều dịch vụ đều có thể hoàn thành tại nhà."}]},{"hanzi":"到底","pinyin":"dàodǐ","pos":"phó.","vn":"rốt cuộc, cuối cùng (dùng nhấn mạnh trong câu hỏi)","examples":[{"cn":"你到底想说什么？","pinyin":"Nǐ dàodǐ xiǎng shuō shénme?","vn":"Rốt cuộc bạn muốn nói gì?"},{"cn":"这件事到底是怎么发生的？","pinyin":"Zhè jiàn shì dàodǐ shì zěnme fāshēng de?","vn":"Việc này rốt cuộc đã xảy ra như thế nào?"},{"cn":"他到底来不来？","pinyin":"Tā dàodǐ lái bu lái?","vn":"Rốt cuộc anh ấy có đến không?"}]},{"hanzi":"仅","pinyin":"jǐn","pos":"phó.","vn":"chỉ, mới","examples":[{"cn":"这件衣服仅卖五十元。","pinyin":"Zhè jiàn yīfu jǐn mài wǔshí yuán.","vn":"Chiếc áo này chỉ bán năm mươi đồng."},{"cn":"这项工作仅用了两天就完成了。","pinyin":"Zhè xiàng gōngzuò jǐn yòngle liǎng tiān jiù wánchéng le.","vn":"Công việc này chỉ mất hai ngày là hoàn thành."},{"cn":"全班仅有三个人没通过考试。","pinyin":"Quán bān jǐn yǒu sān ge rén méi tōngguò kǎoshì.","vn":"Cả lớp chỉ có ba người không đỗ kỳ thi."}]},{"hanzi":"多样","pinyin":"duōyàng","pos":"tt.","vn":"đa dạng, nhiều loại","examples":[{"cn":"这里的小吃种类很多样。","pinyin":"Zhèlǐ de xiǎochī zhǒnglèi hěn duōyàng.","vn":"Các loại món ăn vặt ở đây rất đa dạng."},{"cn":"服务内容越来越多样了。","pinyin":"Fúwù nèiróng yuè lái yuè duōyàng le.","vn":"Nội dung dịch vụ ngày càng đa dạng."},{"cn":"学生的兴趣非常多样。","pinyin":"Xuésheng de xìngqu fēicháng duōyàng.","vn":"Sở thích của học sinh rất đa dạng."}]},{"hanzi":"推出","pinyin":"tuīchū","pos":"dgt.","vn":"cho ra mắt, đưa ra","examples":[{"cn":"公司最近推出了一款新产品。","pinyin":"Gōngsī zuìjìn tuīchūle yì kuǎn xīn chǎnpǐn.","vn":"Công ty gần đây đã cho ra mắt một sản phẩm mới."},{"cn":"这家餐厅推出了新的菜单。","pinyin":"Zhè jiā cāntīng tuīchūle xīn de càidān.","vn":"Nhà hàng này đã đưa ra thực đơn mới."},{"cn":"学校推出了新的教学方法。","pinyin":"Xuéxiào tuīchūle xīn de jiàoxué fāngfǎ.","vn":"Nhà trường đã đưa ra phương pháp giảng dạy mới."}]},{"hanzi":"预约","pinyin":"yùyuē","pos":"dgt.","vn":"đặt hẹn trước","examples":[{"cn":"看病前最好先预约。","pinyin":"Kànbìng qián zuìhǎo xiān yùyuē.","vn":"Trước khi đi khám bệnh tốt nhất nên đặt hẹn trước."},{"cn":"我在网上预约了理发的时间。","pinyin":"Wǒ zài wǎngshàng yùyuēle lǐfà de shíjiān.","vn":"Tôi đã đặt hẹn thời gian cắt tóc trên mạng."},{"cn":"这家餐厅周末需要提前预约。","pinyin":"Zhè jiā cāntīng zhōumò xūyào tíqián yùyuē.","vn":"Nhà hàng này vào cuối tuần cần đặt hẹn trước."}]},{"hanzi":"取","pinyin":"qǔ","pos":"dgt.","vn":"lấy","examples":[{"cn":"我去银行取点儿钱。","pinyin":"Wǒ qù yínháng qǔ diǎnr qián.","vn":"Tôi đi ngân hàng lấy ít tiền."},{"cn":"请帮我去楼下取一下快递。","pinyin":"Qǐng bāng wǒ qù lóuxià qǔ yíxià kuàidì.","vn":"Hãy giúp tôi xuống dưới lấy bưu phẩm."},{"cn":"他已经把衣服从洗衣店取回来了。","pinyin":"Tā yǐjīng bǎ yīfu cóng xǐyīdiàn qǔ huílái le.","vn":"Anh ấy đã lấy quần áo từ tiệm giặt về."}]},{"hanzi":"原因","pinyin":"yuányīn","pos":"dt.","vn":"nguyên nhân","examples":[{"cn":"他没来上课的原因是生病了。","pinyin":"Tā méi lái shàngkè de yuányīn shì shēngbìng le.","vn":"Nguyên nhân anh ấy không đến lớp là bị bệnh."},{"cn":"这件事的原因还不清楚。","pinyin":"Zhè jiàn shì de yuányīn hái bù qīngchu.","vn":"Nguyên nhân của việc này vẫn chưa rõ."},{"cn":"由于各种原因，会议推迟了。","pinyin":"Yóuyú gè zhǒng yuányīn, huìyì tuīchí le.","vn":"Do nhiều nguyên nhân khác nhau, cuộc họp bị hoãn lại."}]},{"hanzi":"然而","pinyin":"rán'ér","pos":"liên.","vn":"nhưng mà, tuy nhiên","examples":[{"cn":"他很想去旅游，然而没有时间。","pinyin":"Tā hěn xiǎng qù lǚyóu, rán'ér méiyǒu shíjiān.","vn":"Anh ấy rất muốn đi du lịch, nhưng không có thời gian."},{"cn":"天气预报说今天晴天，然而却下起了雨。","pinyin":"Tiānqì yùbào shuō jīntiān qíngtiān, rán'ér què xiàqǐ le yǔ.","vn":"Dự báo thời tiết nói hôm nay nắng, nhưng lại đổ mưa."},{"cn":"这个办法看起来简单，然而做起来并不容易。","pinyin":"Zhège bànfǎ kàn qǐlái jiǎndān, rán'ér zuò qǐlái bìng bù róngyì.","vn":"Cách này trông có vẻ đơn giản, nhưng làm thì không dễ."}]},{"hanzi":"不必","pinyin":"búbì","pos":"phó.","vn":"không cần, không nhất thiết","examples":[{"cn":"你不必担心这件事。","pinyin":"Nǐ búbì dānxīn zhè jiàn shì.","vn":"Bạn không cần lo lắng về việc này."},{"cn":"这次会议不必所有人都参加。","pinyin":"Zhè cì huìyì búbì suǒyǒu rén dōu cānjiā.","vn":"Cuộc họp lần này không cần tất cả mọi người tham gia."},{"cn":"你不必这么客气。","pinyin":"Nǐ búbì zhème kèqi.","vn":"Bạn không cần phải khách sáo như vậy."}]},{"hanzi":"亲戚","pinyin":"qīnqi","pos":"dt.","vn":"người thân, bà con","examples":[{"cn":"过年的时候我们去亲戚家拜年。","pinyin":"Guònián de shíhou wǒmen qù qīnqi jiā bàinián.","vn":"Vào dịp tết chúng tôi đi chúc tết nhà người thân."},{"cn":"他有很多亲戚住在国外。","pinyin":"Tā yǒu hěn duō qīnqi zhù zài guówài.","vn":"Anh ấy có nhiều người thân sống ở nước ngoài."},{"cn":"这位亲戚经常来我家做客。","pinyin":"Zhè wèi qīnqi jīngcháng lái wǒ jiā zuòkè.","vn":"Người thân này thường đến nhà tôi chơi."}]},{"hanzi":"按","pinyin":"àn","pos":"giới./dgt.","vn":"theo, dựa theo","examples":[{"cn":"请按要求完成作业。","pinyin":"Qǐng àn yāoqiú wánchéng zuòyè.","vn":"Xin hãy hoàn thành bài tập theo yêu cầu."},{"cn":"大家按顺序排队上车。","pinyin":"Dàjiā àn shùnxù páiduì shàngchē.","vn":"Mọi người xếp hàng lên xe theo thứ tự."},{"cn":"我们按计划一步一步地进行。","pinyin":"Wǒmen àn jìhuà yí bù yí bù de jìnxíng.","vn":"Chúng tôi tiến hành từng bước theo kế hoạch."}]},{"hanzi":"提出","pinyin":"tíchū","pos":"dgt.","vn":"đề xuất, đưa ra","examples":[{"cn":"他在会上提出了一个新想法。","pinyin":"Tā zài huì shàng tíchūle yí ge xīn xiǎngfǎ.","vn":"Anh ấy đã đưa ra một ý tưởng mới trong cuộc họp."},{"cn":"顾客可以随时提出自己的要求。","pinyin":"Gùkè kěyǐ suíshí tíchū zìjǐ de yāoqiú.","vn":"Khách hàng có thể đưa ra yêu cầu của mình bất cứ lúc nào."},{"cn":"老师提出了几个问题让我们思考。","pinyin":"Lǎoshī tíchūle jǐ ge wèntí ràng wǒmen sīkǎo.","vn":"Thầy giáo đã đưa ra vài câu hỏi để chúng tôi suy nghĩ."}]},{"hanzi":"大大","pinyin":"dàdà","pos":"phó.","vn":"rất nhiều, đáng kể","examples":[{"cn":"新技术大大提高了工作效率。","pinyin":"Xīn jìshù dàdà tígāole gōngzuò xiàolǜ.","vn":"Công nghệ mới đã nâng cao đáng kể hiệu suất làm việc."},{"cn":"这个方法大大减少了成本。","pinyin":"Zhège fāngfǎ dàdà jiǎnshǎole chéngběn.","vn":"Cách này đã giảm đáng kể chi phí."},{"cn":"共享单车大大方便了人们的出行。","pinyin":"Gòngxiǎng dānchē dàdà fāngbiànle rénmen de chūxíng.","vn":"Xe đạp chia sẻ đã giúp việc đi lại của mọi người thuận tiện hơn rất nhiều."}]},{"hanzi":"现有","pinyin":"xiànyǒu","pos":"tt.","vn":"sẵn có, hiện có","examples":[{"cn":"我们先用现有的材料做一下试验。","pinyin":"Wǒmen xiān yòng xiànyǒu de cáiliào zuò yíxià shìyàn.","vn":"Chúng ta trước hãy dùng vật liệu sẵn có để làm thử nghiệm."},{"cn":"现有的服务人员还不够专业。","pinyin":"Xiànyǒu de fúwù rényuán hái búgòu zhuānyè.","vn":"Nhân viên dịch vụ hiện có vẫn chưa đủ chuyên nghiệp."},{"cn":"公司打算改进现有的产品。","pinyin":"Gōngsī dǎsuan gǎijìn xiànyǒu de chǎnpǐn.","vn":"Công ty có kế hoạch cải tiến sản phẩm hiện có."}]}],"grammar":[{"title":"\"数词+形容词+量词\"结构","explanation_vn":"Kết cấu \"số từ + tính từ + lượng từ\" mang ngữ điệu khoa trương, nhấn mạnh về mặt chủ quan mức độ lớn nhỏ của số lượng. Số từ thường dùng \"一\", tính từ thường là các từ đơn âm tiết như \"大, 小\", lượng từ thường là lượng từ danh từ tạm thời. Cấu trúc này thường được dùng trong văn nói.","examples":[{"cn":"快到那边那个出口时又推了一小段。","pinyin":"","vn":"Khi gần đến lối ra ở phía đó thì lại phải đẩy một đoạn ngắn."},{"cn":"今天早上我没吃饭就去上班，中午饿极了，吃了一大碗面条儿。","pinyin":"","vn":"Sáng nay tôi không ăn gì đã đi làm, đến trưa đói quá nên ăn một bát mì to."},{"cn":"我今天又收到了妈妈寄来的快递，打开一看，除了衣服外，里边还有一大包巧克力。","pinyin":"","vn":"Hôm nay tôi lại nhận được bưu phẩm mẹ gửi, mở ra xem thì ngoài quần áo ra, bên trong còn có một túi to sô-cô-la."}]},{"title":"被动句\"主语+让/叫+宾语+动词+其他成分\"","explanation_vn":"Câu bị động với cấu trúc \"chủ ngữ + 让/叫 + tân ngữ + động từ + thành phần khác\" dùng để biểu thị ý bị động. Chủ ngữ là đối tượng chịu tác động (bên bị), còn \"让\" hoặc \"叫\" dùng để dẫn ra chủ thể gây ra hành động (bên chủ động). Cấu trúc này thường dùng nhiều trong văn nói.","examples":[{"cn":"后来这个视频让我同学放到了互联网上。","pinyin":"","vn":"Sau đó video này đã bị bạn học của tôi đưa lên internet."},{"cn":"门叫小明给关上了。","pinyin":"","vn":"Cửa đã bị Tiểu Minh đóng lại."},{"cn":"不好意思，月饼都让我吃了。","pinyin":"","vn":"Xin lỗi, bánh trung thu đã bị tôi ăn hết rồi."}]},{"title":"语气副词\"到底\"","explanation_vn":"Phó từ ngữ khí \"到底\" dùng trong câu hỏi, biểu thị ý truy hỏi, muốn tìm hiểu rõ bản chất của vấn đề. Thường được dùng trong văn nói.","examples":[{"cn":"科技到底对世界产生了怎样的影响？","pinyin":"","vn":"Rốt cuộc khoa học công nghệ đã tạo ra ảnh hưởng như thế nào đối với thế giới?"},{"cn":"你们到底还来不来？","pinyin":"","vn":"Rốt cuộc các bạn còn đến hay không?"},{"cn":"你到底是怎么想的？为什么不同意？","pinyin":"","vn":"Rốt cuộc bạn nghĩ như thế nào? Tại sao lại không đồng ý?"}]},{"title":"转折复句\"……，然而……\"","explanation_vn":"Trong câu phức chuyển ý \"……，然而……\", từ \"然而\" được dùng ở đầu phân câu sau để biểu thị sự chuyển ý. Tình huống ở sau \"然而\" thường tạo thành sự đối lập với tình huống ở trước, hoặc không phù hợp với điều mong đợi ở trước đó.","examples":[{"cn":"由于工作等原因，她需要经常出差，然而又很担心猫的安全。","pinyin":"","vn":"Do công việc và các nguyên nhân khác, cô ấy cần phải đi công tác thường xuyên, nhưng lại rất lo lắng về sự an toàn của con mèo."},{"cn":"毕业旅行现在越来越流行，然而由于学生没什么社会和生活经验，可能会遇到各种问题。","pinyin":"","vn":"Du lịch tốt nghiệp hiện nay ngày càng phổ biến, nhưng vì học sinh chưa có nhiều kinh nghiệm xã hội và cuộc sống nên có thể gặp phải nhiều vấn đề khác nhau."},{"cn":"春天应该是花开的季节，然而由于前一段时间下大雪，现在花都没开。","pinyin":"","vn":"Mùa xuân đáng lẽ là mùa hoa nở, nhưng vì trước đó có một thời gian tuyết rơi lớn nên hiện tại hoa vẫn chưa nở."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"","cn":"周末下午，安妮骑共享单车到白家月、陈天中所在的学校，三人在学校咖啡馆聊天儿。","pinyin":""},{"speaker":"白家月","cn":"安妮，我们在这儿呢。","pinyin":""},{"speaker":"安妮","cn":"天中、家月，你们猜我是怎么过来的？","pinyin":""},{"speaker":"白家月","cn":"坐公交车吗？","pinyin":""},{"speaker":"安妮","cn":"我先坐的公交车，然后骑共享单车，快到那边那个出口时又推了一小段。","pinyin":""},{"speaker":"白家月","cn":"我看很多人都骑共享单车，我还没骑过呢。","pinyin":""},{"speaker":"陈天中","cn":"我骑过，很方便的。第一次骑的时候，你打开微信，对着共享单车上的二维码扫一下，在App上完成注册就可以了，怎么使用、费用标准什么的App上都有说明。","pinyin":""},{"speaker":"白家月","cn":"好啊！哪天我出去办事时也试试。","pinyin":""}],"translation_vn":"Chiều cuối tuần, An Ni đi xe đạp chia sẻ đến trường của Bạch Gia Nguyệt và Trần Thiên Trung, ba người ngồi nói chuyện ở quán cà phê trong trường.\nBạch Gia Nguyệt: An Ni, chúng tôi ở đây này.\nAn Ni: Thiên Trung, Gia Nguyệt, các bạn đoán xem tôi đến đây bằng cách nào?\nBạch Gia Nguyệt: Đi xe buýt à?\nAn Ni: Tôi trước tiên đi xe buýt, sau đó đi xe đạp chia sẻ, gần đến lối ra ở đằng kia thì lại phải đẩy một đoạn ngắn.\nBạch Gia Nguyệt: Tôi thấy rất nhiều người đi xe đạp chia sẻ, tôi vẫn chưa đi bao giờ.\nTrần Thiên Trung: Tôi đã đi rồi, rất tiện lợi. Lần đầu đi, bạn mở WeChat, hướng vào mã QR trên xe đạp chia sẻ quét một cái, hoàn thành đăng ký trên App là được, cách sử dụng, mức phí thế nào đều có hướng dẫn trên App.\nBạch Gia Nguyệt: Được đó! Hôm nào tôi ra ngoài giải quyết việc cũng thử xem.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"安妮是怎么到白家月、陈天中的学校的？","q_vn":"An Ni đã đến trường của Bạch Gia Nguyệt và Trần Thiên Trung bằng cách nào?","a_cn":"她先坐公交车，然后骑共享单车，快到出口时又推了一小段。","a_vn":"Cô ấy trước tiên đi xe buýt, sau đó đi xe đạp chia sẻ, khi gần đến lối ra thì lại đẩy xe một đoạn ngắn."},{"q_cn":"第一次使用共享单车要怎么做？","q_vn":"Lần đầu sử dụng xe đạp chia sẻ phải làm như thế nào?","a_cn":"要打开微信，对着共享单车上的二维码扫一下，在App上完成注册就可以了。","a_vn":"Phải mở WeChat, quét mã QR trên xe đạp chia sẻ, hoàn thành đăng ký trên App là được."},{"q_cn":"白家月骑过共享单车吗？她打算怎么做？","q_vn":"Bạch Gia Nguyệt đã từng đi xe đạp chia sẻ chưa? Cô ấy định làm gì?","a_cn":"她还没骑过，她打算哪天出去办事时也试试。","a_vn":"Cô ấy vẫn chưa đi bao giờ, cô ấy định hôm nào ra ngoài giải quyết việc thì sẽ thử."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"","cn":"安妮和白家月、陈天中在学校咖啡馆继续聊天儿。","pinyin":""},{"speaker":"安妮","cn":"差点儿忘了，我给你们看个短视频。","pinyin":""},{"speaker":"白家月","cn":"啊？你们拍的？真不错！","pinyin":""},{"speaker":"安妮","cn":"对！前段时间老师留了个作业，叫各个小组拍个短视频，介绍中国美食。我们小组讨论后决定，由AI小语演厨师，做出中国各地的著名小吃。拍完后，老师说很不错。","pinyin":""},{"speaker":"陈天中","cn":"嗯，语言也很幽默！","pinyin":""},{"speaker":"安妮","cn":"后来这个视频让我同学放到了互联网上，很多人都来点赞。","pinyin":""},{"speaker":"白家月","cn":"看来大家都喜欢这个视频。","pinyin":""},{"speaker":"安妮","cn":"后边我们打算拍第二个、第三个，让小语带大家到中国各地走一走、看一看。","pinyin":""},{"speaker":"陈天中","cn":"这样大家就能通过你们的视频了解中国了，我支持你们！","pinyin":""}],"translation_vn":"An Ni, Bạch Gia Nguyệt và Trần Thiên Trung tiếp tục nói chuyện ở quán cà phê trong trường.\nAn Ni: Suýt quên nữa, tôi cho các bạn xem một video ngắn.\nBạch Gia Nguyệt: Ồ? Các bạn quay đấy à? Hay thật!\nAn Ni: Đúng vậy! Trước đó thầy giáo giao một bài tập, bảo các nhóm quay một video ngắn giới thiệu món ăn Trung Quốc. Nhóm chúng tôi thảo luận rồi quyết định để AI Tiểu Ngữ đóng vai đầu bếp, làm ra các món ăn vặt nổi tiếng ở các nơi của Trung Quốc. Sau khi quay xong, thầy giáo nói rất hay.\nTrần Thiên Trung: Ừm, lời nói cũng rất hài hước nữa!\nAn Ni: Sau đó video này bị bạn học của tôi đưa lên internet, rất nhiều người vào like.\nBạch Gia Nguyệt: Xem ra mọi người đều thích video này.\nAn Ni: Sau này chúng tôi định quay cái thứ hai, thứ ba, để Tiểu Ngữ dẫn mọi người đi khắp các nơi ở Trung Quốc xem.\nTrần Thiên Trung: Như vậy mọi người có thể thông qua video của các bạn mà hiểu về Trung Quốc, tôi ủng hộ các bạn!","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"安妮他们的短视频是关于什么内容的？","q_vn":"Video ngắn của An Ni và nhóm nói về nội dung gì?","a_cn":"是关于中国美食的，由AI小语演厨师，做出中国各地的著名小吃。","a_vn":"Về món ăn Trung Quốc, do AI Tiểu Ngữ đóng vai đầu bếp, làm ra các món ăn vặt nổi tiếng ở các nơi của Trung Quốc."},{"q_cn":"这个视频后来怎么样了？","q_vn":"Video này sau đó thế nào?","a_cn":"被安妮的同学放到了互联网上，很多人都来点赞。","a_vn":"Bị bạn học của An Ni đưa lên internet, rất nhiều người vào like."},{"q_cn":"安妮他们以后还打算做什么？","q_vn":"Sau này An Ni và nhóm còn định làm gì?","a_cn":"他们打算拍第二个、第三个视频，让小语带大家到中国各地走一走、看一看。","a_vn":"Họ định quay video thứ hai, thứ ba, để Tiểu Ngữ dẫn mọi người đi khắp các nơi ở Trung Quốc xem."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"安妮骑共享单车到了白家月、陈天中的学校，三人从共享单车聊到AI眼镜和3D打印机，从绿色经济聊到上门经济。科技到底对世界产生了怎样的影响？他们都认为，科技确实改变了人们的生活。","pinyin":""},{"speaker":"","cn":"接着，安妮给大家看了她和同学们拍的短视频。安妮说，短视频是用手机拍的，他们装了一些免费的App，仅用几天就拍完了。视频里，小语做的小吃丰富多样，看起来好吃极了。短视频推出后，大家认为非常精彩，白家月和陈天中看后也特别喜欢，并且表示支持他们拍更多的视频。","pinyin":""}],"translation_vn":"An Ni đi xe đạp chia sẻ đến trường của Bạch Gia Nguyệt và Trần Thiên Trung, ba người nói chuyện từ xe đạp chia sẻ đến kính AI và máy in 3D, từ kinh tế xanh đến kinh tế dịch vụ tận nhà. Rốt cuộc khoa học công nghệ đã tạo ra ảnh hưởng như thế nào đối với thế giới? Họ đều cho rằng, khoa học công nghệ thực sự đã thay đổi cuộc sống của con người.\nTiếp theo, An Ni cho mọi người xem video ngắn mà cô và các bạn học đã quay. An Ni nói, video ngắn được quay bằng điện thoại, họ cài một số App miễn phí, chỉ mất vài ngày là quay xong. Trong video, các món ăn vặt do Tiểu Ngữ làm phong phú đa dạng, trông có vẻ rất ngon. Sau khi video ngắn được ra mắt, mọi người đều cho là rất xuất sắc, Bạch Gia Nguyệt và Trần Thiên Trung xem xong cũng đặc biệt thích, đồng thời tỏ ý ủng hộ họ quay thêm nhiều video nữa.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"三人聊天的话题都有哪些？","q_vn":"Chủ đề nói chuyện của ba người bao gồm những gì?","a_cn":"他们从共享单车聊到AI眼镜和3D打印机，又从绿色经济聊到上门经济。","a_vn":"Họ nói chuyện từ xe đạp chia sẻ đến kính AI và máy in 3D, rồi từ kinh tế xanh đến kinh tế dịch vụ tận nhà."},{"q_cn":"安妮他们的短视频是怎么拍出来的？","q_vn":"Video ngắn của An Ni và nhóm được quay như thế nào?","a_cn":"是用手机拍的，他们装了一些免费的App，仅用几天就拍完了。","a_vn":"Được quay bằng điện thoại, họ cài một số App miễn phí, chỉ mất vài ngày là quay xong."},{"q_cn":"白家月和陈天中看完视频后的反应是什么？","q_vn":"Phản ứng của Bạch Gia Nguyệt và Trần Thiên Trung sau khi xem video là gì?","a_cn":"他们特别喜欢这个视频，并且表示支持安妮他们拍更多的视频。","a_vn":"Họ đặc biệt thích video này, và tỏ ý ủng hộ An Ni và nhóm quay thêm nhiều video nữa."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"随着互联网技术的发展，现在又出现了一种新的服务方式——上门经济，就是预约者通过网上预约，让服务人员在合适的时间到家里或者约好的地点服务，服务内容有上门做饭、照顾小动物、取东西等。赵女士养了一只猫，由于工作等原因，她需要经常出差，然而又很担心猫的安全。有了上门服务后，她觉得方便多了，不必再找亲戚帮忙。每次出差，在网上预约并支付费用后，服务人员就会按她提出的要求上门照顾小猫，大大减轻了她的压力，赵女士也特别满意。","pinyin":""},{"speaker":"","cn":"当然，上门经济也有一些问题，特别是现有服务人员有些还不够专业，需要重新学习，提高服务质量。","pinyin":""}],"translation_vn":"Cùng với sự phát triển của công nghệ internet, hiện nay lại xuất hiện một hình thức dịch vụ mới - kinh tế dịch vụ tận nhà, tức là người đặt hẹn thông qua đặt hẹn trên mạng, để nhân viên dịch vụ đến nhà hoặc đến địa điểm đã hẹn trước vào thời gian thích hợp để phục vụ, nội dung dịch vụ có nấu ăn tại nhà, chăm sóc vật nuôi nhỏ, lấy đồ v.v. Cô Triệu nuôi một con mèo, do công việc và các nguyên nhân khác, cô cần phải đi công tác thường xuyên, nhưng lại rất lo lắng về sự an toàn của con mèo. Sau khi có dịch vụ tận nhà, cô cảm thấy tiện lợi hơn nhiều, không cần phải tìm người thân giúp đỡ nữa. Mỗi lần đi công tác, sau khi đặt hẹn trên mạng và trả phí, nhân viên dịch vụ sẽ đến nhà chăm sóc mèo con theo yêu cầu cô đưa ra, giảm nhẹ đáng kể áp lực cho cô, cô Triệu cũng rất hài lòng.\nTất nhiên, kinh tế dịch vụ tận nhà cũng có một số vấn đề, đặc biệt là một số nhân viên dịch vụ hiện có vẫn chưa đủ chuyên nghiệp, cần phải học lại, nâng cao chất lượng dịch vụ.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"什么是上门经济？","q_vn":"Kinh tế dịch vụ tận nhà là gì?","a_cn":"是预约者通过网上预约，让服务人员在合适的时间到家里或约好的地点服务的一种新服务方式。","a_vn":"Là một hình thức dịch vụ mới, trong đó người đặt hẹn thông qua đặt hẹn trên mạng, để nhân viên dịch vụ đến nhà hoặc địa điểm đã hẹn vào thời gian thích hợp để phục vụ."},{"q_cn":"赵女士为什么需要上门服务？","q_vn":"Tại sao cô Triệu cần dịch vụ tận nhà?","a_cn":"因为她经常出差，又很担心猫的安全，有了上门服务就不必再找亲戚帮忙照顾猫了。","a_vn":"Vì cô thường xuyên đi công tác và lo lắng về sự an toàn của con mèo, có dịch vụ tận nhà thì không cần tìm người thân giúp chăm mèo nữa."},{"q_cn":"上门经济目前存在什么问题？","q_vn":"Hiện nay kinh tế dịch vụ tận nhà đang gặp vấn đề gì?","a_cn":"现有服务人员有些还不够专业，需要重新学习，提高服务质量。","a_vn":"Một số nhân viên dịch vụ hiện có vẫn chưa đủ chuyên nghiệp, cần phải học lại để nâng cao chất lượng dịch vụ."}]}]},{"id":19,"title_cn":"他们都很棒","title_pinyin":"","title_vn":"Họ đều rất tuyệt","goals":["Có thể nghe hiểu và trao đổi về các chủ đề văn học, nghệ thuật.","Có thể giới thiệu bằng lời nói hoặc văn bản về một tác phẩm hoặc một loại hình nghệ thuật.","Hiểu biết về một trong những tinh hoa văn hóa Trung Quốc - Kinh kịch."],"vocab":[{"hanzi":"话剧","pinyin":"huàjù","pos":"dt.","vn":"kịch nói","examples":[{"cn":"这部话剧非常精彩。","pinyin":"Zhè bù huàjù fēicháng jīngcǎi.","vn":"Vở kịch nói này rất đặc sắc."},{"cn":"他是话剧演员。","pinyin":"Tā shì huàjù yǎnyuán.","vn":"Anh ấy là diễn viên kịch nói."},{"cn":"我们学校有话剧社。","pinyin":"Wǒmen xuéxiào yǒu huàjù shè.","vn":"Trường chúng tôi có câu lạc bộ kịch nói."}]},{"hanzi":"排","pinyin":"pái","pos":"dgt.","vn":"tập, diễn tập, xếp","examples":[{"cn":"他们正在排一个新节目。","pinyin":"Tāmen zhèngzài pái yí gè xīn jiémù.","vn":"Họ đang tập một tiết mục mới."},{"cn":"节目还没排好。","pinyin":"Jiémù hái méi pái hǎo.","vn":"Tiết mục vẫn chưa tập xong."},{"cn":"我们每天下午排练。","pinyin":"Wǒmen měitiān xiàwǔ páiliàn.","vn":"Chúng tôi tập luyện mỗi buổi chiều."}]},{"hanzi":"艺术","pinyin":"yìshù","pos":"dt.","vn":"nghệ thuật","examples":[{"cn":"她很喜欢艺术。","pinyin":"Tā hěn xǐhuan yìshù.","vn":"Cô ấy rất yêu thích nghệ thuật."},{"cn":"这是一种传统艺术。","pinyin":"Zhè shì yì zhǒng chuántǒng yìshù.","vn":"Đây là một loại nghệ thuật truyền thống."},{"cn":"他学的是艺术专业。","pinyin":"Tā xué de shì yìshù zhuānyè.","vn":"Anh ấy học chuyên ngành nghệ thuật."}]},{"hanzi":"内心","pinyin":"nèixīn","pos":"dt.","vn":"nội tâm, trong lòng","examples":[{"cn":"他内心很紧张。","pinyin":"Tā nèixīn hěn jǐnzhāng.","vn":"Trong lòng anh ấy rất căng thẳng."},{"cn":"我内心很感动。","pinyin":"Wǒ nèixīn hěn gǎndòng.","vn":"Trong lòng tôi rất cảm động."},{"cn":"她把内心的想法说了出来。","pinyin":"Tā bǎ nèixīn de xiǎngfǎ shuōle chūlái.","vn":"Cô ấy đã nói ra suy nghĩ trong lòng."}]},{"hanzi":"自信","pinyin":"zìxìn","pos":"tt./dt./dgt.","vn":"tự tin","examples":[{"cn":"他是一个很自信的人。","pinyin":"Tā shì yí gè hěn zìxìn de rén.","vn":"Anh ấy là một người rất tự tin."},{"cn":"你要对自己自信一些。","pinyin":"Nǐ yào duì zìjǐ zìxìn yìxiē.","vn":"Bạn nên tự tin hơn vào bản thân."},{"cn":"她的自信来自努力。","pinyin":"Tā de zìxìn láizì nǔlì.","vn":"Sự tự tin của cô ấy đến từ nỗ lực."}]},{"hanzi":"少年","pinyin":"shàonián","pos":"dt.","vn":"thiếu niên","examples":[{"cn":"他还是个少年。","pinyin":"Tā hái shì gè shàonián.","vn":"Anh ấy vẫn còn là một thiếu niên."},{"cn":"这是一部关于少年的电影。","pinyin":"Zhè shì yí bù guānyú shàonián de diànyǐng.","vn":"Đây là một bộ phim về thiếu niên."},{"cn":"少年时期很重要。","pinyin":"Shàonián shíqī hěn zhòngyào.","vn":"Thời kỳ thiếu niên rất quan trọng."}]},{"hanzi":"歌手","pinyin":"gēshǒu","pos":"dt.","vn":"ca sĩ","examples":[{"cn":"他是一位著名歌手。","pinyin":"Tā shì yí wèi zhùmíng gēshǒu.","vn":"Anh ấy là một ca sĩ nổi tiếng."},{"cn":"这位歌手唱得真好。","pinyin":"Zhè wèi gēshǒu chàng de zhēn hǎo.","vn":"Ca sĩ này hát hay thật."},{"cn":"我喜欢的歌手要开演唱会了。","pinyin":"Wǒ xǐhuan de gēshǒu yào kāi yǎnchànghuì le.","vn":"Ca sĩ mà tôi yêu thích sắp mở concert."}]},{"hanzi":"歌声","pinyin":"gēshēng","pos":"dt.","vn":"tiếng hát, giọng ca","examples":[{"cn":"她的歌声很美。","pinyin":"Tā de gēshēng hěn měi.","vn":"Giọng hát của cô ấy rất đẹp."},{"cn":"歌声传遍了全场。","pinyin":"Gēshēng chuánbiàn le quán chǎng.","vn":"Tiếng hát lan khắp cả khán phòng."},{"cn":"我喜欢他的歌声。","pinyin":"Wǒ xǐhuan tā de gēshēng.","vn":"Tôi thích giọng hát của anh ấy."}]},{"hanzi":"度假","pinyin":"dùjià","pos":"dgt.","vn":"nghỉ dưỡng, đi nghỉ","examples":[{"cn":"暑假我们去海边度假。","pinyin":"Shǔjià wǒmen qù hǎibiān dùjià.","vn":"Kỳ nghỉ hè chúng tôi đi nghỉ ở biển."},{"cn":"他们一家在度假村度假。","pinyin":"Tāmen yìjiā zài dùjiàcūn dùjià.","vn":"Gia đình họ đi nghỉ dưỡng ở khu resort."},{"cn":"这是一个度假的好地方。","pinyin":"Zhè shì yí gè dùjià de hǎo dìfāng.","vn":"Đây là một nơi nghỉ dưỡng tốt."}]},{"hanzi":"演员","pinyin":"yǎnyuán","pos":"dt.","vn":"diễn viên","examples":[{"cn":"他是一位优秀的演员。","pinyin":"Tā shì yí wèi yōuxiù de yǎnyuán.","vn":"Anh ấy là một diễn viên xuất sắc."},{"cn":"这些演员表演得很专业。","pinyin":"Zhèxiē yǎnyuán biǎoyǎn de hěn zhuānyè.","vn":"Những diễn viên này diễn rất chuyên nghiệp."},{"cn":"我想成为一名演员。","pinyin":"Wǒ xiǎng chéngwéi yì míng yǎnyuán.","vn":"Tôi muốn trở thành một diễn viên."}]},{"hanzi":"演唱","pinyin":"yǎnchàng","pos":"dgt.","vn":"biểu diễn ca hát","examples":[{"cn":"他为大家演唱了一首歌。","pinyin":"Tā wèi dàjiā yǎnchàngle yì shǒu gē.","vn":"Anh ấy đã hát một bài cho mọi người."},{"cn":"她演唱得非常投入。","pinyin":"Tā yǎnchàng de fēicháng tóurù.","vn":"Cô ấy hát rất nhập tâm."},{"cn":"这首歌由她首次演唱。","pinyin":"Zhè shǒu gē yóu tā shǒucì yǎnchàng.","vn":"Bài hát này do cô ấy hát lần đầu."}]},{"hanzi":"留下","pinyin":"liúxia","pos":"dgt.","vn":"để lại","examples":[{"cn":"这次旅行给我留下了美好的记忆。","pinyin":"Zhè cì lǜxíng gěi wǒ liúxiàle měihǎo de jìyì.","vn":"Chuyến đi này để lại cho tôi những kỷ niệm đẹp."},{"cn":"他给我留下了很深的印象。","pinyin":"Tā gěi wǒ liúxiàle hěn shēn de yìnxiàng.","vn":"Anh ấy để lại cho tôi ấn tượng rất sâu sắc."},{"cn":"请把地址留下。","pinyin":"Qǐng bǎ dìzhǐ liúxia.","vn":"Xin hãy để lại địa chỉ."}]},{"hanzi":"青年","pinyin":"qīngnián","pos":"dt.","vn":"thanh niên","examples":[{"cn":"他是一位青年演员。","pinyin":"Tā shì yí wèi qīngnián yǎnyuán.","vn":"Anh ấy là một diễn viên trẻ."},{"cn":"青年人应该多努力。","pinyin":"Qīngnián rén yīnggāi duō nǔlì.","vn":"Thanh niên nên nỗ lực nhiều hơn."},{"cn":"这是青年的责任。","pinyin":"Zhè shì qīngnián de zérèn.","vn":"Đây là trách nhiệm của thanh niên."}]},{"hanzi":"观众","pinyin":"guānzhòng","pos":"dt.","vn":"khán giả","examples":[{"cn":"观众都很喜欢这场演出。","pinyin":"Guānzhòng dōu hěn xǐhuan zhè chǎng yǎnchū.","vn":"Khán giả đều rất thích buổi diễn này."},{"cn":"剧场里坐满了观众。","pinyin":"Jùchǎng lǐ zuòmǎnle guānzhòng.","vn":"Khán giả ngồi đầy kín rạp hát."},{"cn":"观众为演员鼓掌。","pinyin":"Guānzhòng wèi yǎnyuán gǔzhǎng.","vn":"Khán giả vỗ tay cho diễn viên."}]},{"hanzi":"功课","pinyin":"gōngkè","pos":"dt.","vn":"bài học, sự chuẩn bị trước","examples":[{"cn":"去旅行前要先做做功课。","pinyin":"Qù lǜxíng qián yào xiān zuòzuo gōngkè.","vn":"Trước khi đi du lịch cần chuẩn bị trước."},{"cn":"他每天都认真做功课。","pinyin":"Tā měitiān dōu rènzhēn zuò gōngkè.","vn":"Anh ấy ngày nào cũng chăm chỉ làm bài tập."},{"cn":"我们要提前做好功课。","pinyin":"Wǒmen yào tíqián zuò hǎo gōngkè.","vn":"Chúng ta phải chuẩn bị trước đầy đủ."}]},{"hanzi":"转发","pinyin":"zhuǎnfā","pos":"dgt.","vn":"chuyển tiếp, đăng lại","examples":[{"cn":"他把消息转发给了我。","pinyin":"Tā bǎ xiāoxi zhuǎnfā gěile wǒ.","vn":"Anh ấy đã chuyển tiếp tin tức cho tôi."},{"cn":"这条新闻被很多人转发。","pinyin":"Zhè tiáo xīnwén bèi hěnduō rén zhuǎnfā.","vn":"Tin tức này được nhiều người chia sẻ lại."},{"cn":"请帮我转发一下这个文件。","pinyin":"Qǐng bāng wǒ zhuǎnfā yíxià zhège wénjiàn.","vn":"Làm ơn giúp tôi chuyển tiếp tài liệu này."}]},{"hanzi":"入口","pinyin":"rùkǒu","pos":"dt.","vn":"cửa vào, lối vào","examples":[{"cn":"我们在入口见面吧。","pinyin":"Wǒmen zài rùkǒu jiànmiàn ba.","vn":"Chúng ta gặp nhau ở lối vào nhé."},{"cn":"入口处有很多人排队。","pinyin":"Rùkǒu chù yǒu hěnduō rén páiduì.","vn":"Ở lối vào có nhiều người xếp hàng."},{"cn":"剧院的入口在左边。","pinyin":"Jùyuàn de rùkǒu zài zuǒbiān.","vn":"Lối vào nhà hát ở phía bên trái."}]},{"hanzi":"入","pinyin":"rù","pos":"dgt.","vn":"vào","examples":[{"cn":"他们入座后演出就开始了。","pinyin":"Tāmen rùzuò hòu yǎnchū jiù kāishǐ le.","vn":"Sau khi họ vào chỗ ngồi thì buổi diễn bắt đầu."},{"cn":"请大家按顺序入场。","pinyin":"Qǐng dàjiā àn shùnxù rùchǎng.","vn":"Xin mọi người vào sân theo thứ tự."},{"cn":"他深入研究了这个问题。","pinyin":"Tā shēnrù yánjiūle zhège wèntí.","vn":"Anh ấy đã nghiên cứu sâu vấn đề này."}]},{"hanzi":"指","pinyin":"zhǐ","pos":"dgt.","vn":"chỉ, chỉ vào","examples":[{"cn":"他指着节目表说了起来。","pinyin":"Tā zhǐzhe jiémùbiǎo shuōle qǐlái.","vn":"Anh ấy chỉ vào bảng chương trình và nói."},{"cn":"老师指着黑板讲解。","pinyin":"Lǎoshī zhǐzhe hēibǎn jiǎngjiě.","vn":"Thầy giáo chỉ vào bảng để giảng giải."},{"cn":"她指了指远处的山。","pinyin":"Tā zhǐlezhǐ yuǎnchù de shān.","vn":"Cô ấy chỉ về ngọn núi ở phía xa."}]},{"hanzi":"功夫","pinyin":"gōngfu","pos":"dt.","vn":"công phu, kỹ năng","examples":[{"cn":"这个演员功夫很深。","pinyin":"Zhège yǎnyuán gōngfu hěn shēn.","vn":"Diễn viên này có công phu rất sâu."},{"cn":"他从小练功夫。","pinyin":"Tā cóngxiǎo liàn gōngfu.","vn":"Anh ấy luyện công phu từ nhỏ."},{"cn":"学好一门语言要花功夫。","pinyin":"Xué hǎo yì mén yǔyán yào huā gōngfu.","vn":"Học tốt một ngôn ngữ cần bỏ công sức."}]},{"hanzi":"获奖","pinyin":"huòjiǎng","pos":"dgt.","vn":"đạt giải, được giải","examples":[{"cn":"他在比赛中获奖了。","pinyin":"Tā zài bǐsài zhōng huòjiǎng le.","vn":"Anh ấy đã đạt giải trong cuộc thi."},{"cn":"这部电影获奖无数。","pinyin":"Zhè bù diànyǐng huòjiǎng wúshù.","vn":"Bộ phim này đạt vô số giải thưởng."},{"cn":"获奖演员上台领奖。","pinyin":"Huòjiǎng yǎnyuán shàngtái lǐngjiǎng.","vn":"Diễn viên đạt giải lên nhận giải."}]},{"hanzi":"奖","pinyin":"jiǎng","pos":"dt.","vn":"giải thưởng","examples":[{"cn":"他得了一个大奖。","pinyin":"Tā déle yí gè dàjiǎng.","vn":"Anh ấy đã nhận được một giải lớn."},{"cn":"这是国家级的奖。","pinyin":"Zhè shì guójiā jí de jiǎng.","vn":"Đây là giải thưởng cấp quốc gia."},{"cn":"她很开心能获得这个奖。","pinyin":"Tā hěn kāixīn néng huòdé zhège jiǎng.","vn":"Cô ấy rất vui vì giành được giải này."}]},{"hanzi":"期待","pinyin":"qīdài","pos":"dgt.","vn":"mong đợi, kỳ vọng","examples":[{"cn":"我很期待这场演出。","pinyin":"Wǒ hěn qīdài zhè chǎng yǎnchū.","vn":"Tôi rất mong đợi buổi diễn này."},{"cn":"大家都期待着好消息。","pinyin":"Dàjiā dōu qīdàizhe hǎo xiāoxi.","vn":"Mọi người đều mong chờ tin tốt."},{"cn":"他期待能和你再见面。","pinyin":"Tā qīdài néng hé nǐ zài jiànmiàn.","vn":"Anh ấy mong được gặp lại bạn."}]},{"hanzi":"鼓掌","pinyin":"gǔzhǎng","pos":"dgt.","vn":"vỗ tay","examples":[{"cn":"观众们不停地鼓掌。","pinyin":"Guānzhòngmen bùtíng de gǔzhǎng.","vn":"Khán giả vỗ tay không ngừng."},{"cn":"演出结束后大家都鼓掌了。","pinyin":"Yǎnchū jiéshù hòu dàjiā dōu gǔzhǎng le.","vn":"Sau khi buổi diễn kết thúc, mọi người đều vỗ tay."},{"cn":"我们为他的表现鼓掌。","pinyin":"Wǒmen wèi tā de biǎoxiàn gǔzhǎng.","vn":"Chúng tôi vỗ tay cho màn thể hiện của anh ấy."}]},{"hanzi":"邀请","pinyin":"yāoqǐng","pos":"dgt.","vn":"mời","examples":[{"cn":"他邀请我去看京剧。","pinyin":"Tā yāoqǐng wǒ qù kàn jīngjù.","vn":"Anh ấy mời tôi đi xem Kinh kịch."},{"cn":"我们邀请了很多朋友。","pinyin":"Wǒmen yāoqǐngle hěnduō péngyou.","vn":"Chúng tôi đã mời rất nhiều bạn bè."},{"cn":"她接受了邀请。","pinyin":"Tā jiēshòule yāoqǐng.","vn":"Cô ấy đã nhận lời mời."}]},{"hanzi":"庆祝","pinyin":"qìngzhù","pos":"dgt.","vn":"ăn mừng, chúc mừng","examples":[{"cn":"大家一起庆祝演出成功。","pinyin":"Dàjiā yìqǐ qìngzhù yǎnchū chénggōng.","vn":"Mọi người cùng ăn mừng buổi diễn thành công."},{"cn":"我们庆祝他的生日。","pinyin":"Wǒmen qìngzhù tā de shēngrì.","vn":"Chúng tôi ăn mừng sinh nhật anh ấy."},{"cn":"全家人庆祝节日。","pinyin":"Quánjiārén qìngzhù jiérì.","vn":"Cả nhà ăn mừng ngày lễ."}]},{"hanzi":"点头","pinyin":"diǎntóu","pos":"dgt.","vn":"gật đầu","examples":[{"cn":"他点头表示同意。","pinyin":"Tā diǎntóu biǎoshì tóngyì.","vn":"Anh ấy gật đầu thể hiện sự đồng ý."},{"cn":"老师点了点头。","pinyin":"Lǎoshī diǎnle diǎn tóu.","vn":"Thầy giáo gật đầu một cái."},{"cn":"她点头笑了。","pinyin":"Tā diǎntóu xiàole.","vn":"Cô ấy gật đầu và mỉm cười."}]},{"hanzi":"作品","pinyin":"zuòpǐn","pos":"dt.","vn":"tác phẩm","examples":[{"cn":"这是他最有名的作品。","pinyin":"Zhè shì tā zuì yǒumíng de zuòpǐn.","vn":"Đây là tác phẩm nổi tiếng nhất của ông."},{"cn":"这部作品影响很大。","pinyin":"Zhè bù zuòpǐn yǐngxiǎng hěn dà.","vn":"Tác phẩm này có ảnh hưởng rất lớn."},{"cn":"我喜欢她的艺术作品。","pinyin":"Wǒ xǐhuan tā de yìshù zuòpǐn.","vn":"Tôi thích các tác phẩm nghệ thuật của cô ấy."}]},{"hanzi":"作者","pinyin":"zuòzhě","pos":"dt.","vn":"tác giả","examples":[{"cn":"这本书的作者是谁？","pinyin":"Zhè běn shū de zuòzhě shì shéi?","vn":"Tác giả của cuốn sách này là ai?"},{"cn":"作者介绍了当时的社会。","pinyin":"Zuòzhě jièshàole dāngshí de shèhuì.","vn":"Tác giả đã giới thiệu xã hội thời đó."},{"cn":"我想见见这位作者。","pinyin":"Wǒ xiǎng jiànjiàn zhè wèi zuòzhě.","vn":"Tôi muốn gặp tác giả này."}]},{"hanzi":"世纪","pinyin":"shìjì","pos":"dt.","vn":"thế kỷ","examples":[{"cn":"这是十三世纪的作品。","pinyin":"Zhè shì shísān shìjì de zuòpǐn.","vn":"Đây là tác phẩm của thế kỷ mười ba."},{"cn":"二十一世纪变化很快。","pinyin":"Èrshíyī shìjì biànhuà hěn kuài.","vn":"Thế kỷ hai mươi mốt thay đổi rất nhanh."},{"cn":"这座城市已有几个世纪的历史。","pinyin":"Zhè zuò chéngshì yǐ yǒu jǐ gè shìjì de lìshǐ.","vn":"Thành phố này đã có lịch sử vài thế kỷ."}]},{"hanzi":"读者","pinyin":"dúzhě","pos":"dt.","vn":"độc giả, người đọc","examples":[{"cn":"这本书受到很多读者的喜爱。","pinyin":"Zhè běn shū shòudào hěnduō dúzhě de xǐ'ài.","vn":"Cuốn sách này được nhiều độc giả yêu thích."},{"cn":"作者回答了读者的问题。","pinyin":"Zuòzhě huídále dúzhě de wèntí.","vn":"Tác giả đã trả lời câu hỏi của độc giả."},{"cn":"我是这本杂志的老读者。","pinyin":"Wǒ shì zhè běn zázhì de lǎo dúzhě.","vn":"Tôi là độc giả lâu năm của tạp chí này."}]},{"hanzi":"作家","pinyin":"zuòjiā","pos":"dt.","vn":"nhà văn","examples":[{"cn":"我想成为一名作家。","pinyin":"Wǒ xiǎng chéngwéi yì míng zuòjiā.","vn":"Tôi muốn trở thành một nhà văn."},{"cn":"这位作家写了很多小说。","pinyin":"Zhè wèi zuòjiā xiěle hěnduō xiǎoshuō.","vn":"Nhà văn này đã viết rất nhiều tiểu thuyết."},{"cn":"她是中国著名作家。","pinyin":"Tā shì Zhōngguó zhùmíng zuòjiā.","vn":"Bà ấy là nhà văn nổi tiếng của Trung Quốc."}]},{"hanzi":"版","pinyin":"bǎn","pos":"dt.","vn":"bản (in)","examples":[{"cn":"这是中文版的书。","pinyin":"Zhè shì Zhōngwén bǎn de shū.","vn":"Đây là cuốn sách bản tiếng Trung."},{"cn":"这本书出了新版。","pinyin":"Zhè běn shū chūle xīn bǎn.","vn":"Cuốn sách này đã ra bản mới."},{"cn":"我买的是英文版。","pinyin":"Wǒ mǎi de shì Yīngwén bǎn.","vn":"Cái tôi mua là bản tiếng Anh."}]},{"hanzi":"文章","pinyin":"wénzhāng","pos":"dt.","vn":"bài viết, văn chương","examples":[{"cn":"他写了一篇文章。","pinyin":"Tā xiěle yì piān wénzhāng.","vn":"Anh ấy đã viết một bài văn."},{"cn":"这篇文章写得很好。","pinyin":"Zhè piān wénzhāng xiě de hěn hǎo.","vn":"Bài viết này viết rất tốt."},{"cn":"我每天都读一篇文章。","pinyin":"Wǒ měitiān dōu dú yì piān wénzhāng.","vn":"Mỗi ngày tôi đều đọc một bài viết."}]},{"hanzi":"全部","pinyin":"quánbù","pos":"dt.","vn":"toàn bộ, tất cả","examples":[{"cn":"他把全部的钱都花了。","pinyin":"Tā bǎ quánbù de qián dōu huā le.","vn":"Anh ấy đã dùng hết toàn bộ số tiền."},{"cn":"这些是我全部的作品。","pinyin":"Zhèxiē shì wǒ quánbù de zuòpǐn.","vn":"Đây là toàn bộ các tác phẩm của tôi."},{"cn":"全部的工作已经完成。","pinyin":"Quánbù de gōngzuò yǐjīng wánchéng.","vn":"Toàn bộ công việc đã hoàn thành."}]},{"hanzi":"整理","pinyin":"zhěnglǐ","pos":"dgt.","vn":"sắp xếp, chỉnh lý","examples":[{"cn":"我在整理自己的照片。","pinyin":"Wǒ zài zhěnglǐ zìjǐ de zhàopiàn.","vn":"Tôi đang sắp xếp những bức ảnh của mình."},{"cn":"她把房间整理得很干净。","pinyin":"Tā bǎ fángjiān zhěnglǐ de hěn gānjìng.","vn":"Cô ấy đã dọn dẹp căn phòng rất sạch sẽ."},{"cn":"请帮我整理一下文件。","pinyin":"Qǐng bāng wǒ zhěnglǐ yíxià wénjiàn.","vn":"Làm ơn giúp tôi sắp xếp hồ sơ."}]},{"hanzi":"文字","pinyin":"wénzì","pos":"dt.","vn":"văn tự, chữ viết","examples":[{"cn":"这是一种古老的文字。","pinyin":"Zhè shì yì zhǒng gǔlǎo de wénzì.","vn":"Đây là một loại chữ viết cổ."},{"cn":"他用文字记录了旅行经历。","pinyin":"Tā yòng wénzì jìlùle lǜxíng jīnglì.","vn":"Anh ấy dùng văn tự ghi lại chuyến đi."},{"cn":"这篇文字写得很感人。","pinyin":"Zhè piān wénzì xiě de hěn gǎnrén.","vn":"Đoạn văn này viết rất cảm động."}]},{"hanzi":"图片","pinyin":"túpiàn","pos":"dt.","vn":"hình ảnh","examples":[{"cn":"这本书里有很多图片。","pinyin":"Zhè běn shū lǐ yǒu hěnduō túpiàn.","vn":"Trong cuốn sách này có nhiều hình ảnh."},{"cn":"他发了几张图片给我。","pinyin":"Tā fāle jǐ zhāng túpiàn gěi wǒ.","vn":"Anh ấy đã gửi cho tôi vài tấm ảnh."},{"cn":"这张图片拍得真美。","pinyin":"Zhè zhāng túpiàn pāi de zhēn měi.","vn":"Tấm hình này chụp thật đẹp."}]},{"hanzi":"报考","pinyin":"bàokǎo","pos":"dgt.","vn":"đăng ký dự thi","examples":[{"cn":"她报考了研究生。","pinyin":"Tā bàokǎole yánjiūshēng.","vn":"Cô ấy đã đăng ký thi nghiên cứu sinh."},{"cn":"我想报考这所大学。","pinyin":"Wǒ xiǎng bàokǎo zhè suǒ dàxué.","vn":"Tôi muốn đăng ký thi vào trường đại học này."},{"cn":"他报考了中文专业。","pinyin":"Tā bàokǎole Zhōngwén zhuānyè.","vn":"Anh ấy đăng ký thi chuyên ngành tiếng Trung."}]},{"hanzi":"文学","pinyin":"wénxué","pos":"dt.","vn":"văn học","examples":[{"cn":"她很喜欢中国文学。","pinyin":"Tā hěn xǐhuan Zhōngguó wénxué.","vn":"Cô ấy rất thích văn học Trung Quốc."},{"cn":"他学的是文学专业。","pinyin":"Tā xué de shì wénxué zhuānyè.","vn":"Anh ấy học chuyên ngành văn học."},{"cn":"这是一部文学名著。","pinyin":"Zhè shì yí bù wénxué míngzhù.","vn":"Đây là một tác phẩm văn học kinh điển."}]}],"proper_nouns":[{"hanzi":"国家大剧院","pinyin":"Guójiā Dàjùyuàn","vn":"Nhà hát Quốc gia (Trung Quốc)"},{"hanzi":"京剧","pinyin":"Jīngjù","vn":"Kinh kịch (Kinh kịch Trung Quốc)"},{"hanzi":"梅兰芳","pinyin":"Méi Lánfāng","vn":"Mai Lan Phương"},{"hanzi":"马可·波罗","pinyin":"Mǎkě·Bōluó","vn":"Marco Polo"},{"hanzi":"意大利","pinyin":"Yìdàlì","vn":"Ý"},{"hanzi":"马可·波罗游记","pinyin":"Mǎkě·Bōluó Yóujì","vn":"Marco Polo du ký"},{"hanzi":"东方旅行日记","pinyin":"Dōngfāng Lǚxíng Rìjì","vn":"Nhật ký du hành phương Đông"}],"grammar":[{"title":"选择复句\"不是……，就是……\"","explanation_vn":"Câu phức lựa chọn \"不是……，就是……\" biểu thị quan hệ lựa chọn, nghĩa là chọn một trong hai tình huống xảy ra (hoặc tình huống này, hoặc tình huống kia).","examples":[{"cn":"有时候不是忘词，就是忘记做动作。","pinyin":"","vn":"Có lúc không quên lời thì lại quên làm động tác."},{"cn":"周末的时候，小文不是在家看书，就是出去看演出。","pinyin":"","vn":"Vào cuối tuần, Tiểu Văn không ở nhà đọc sách thì cũng đi xem biểu diễn."},{"cn":"杨同乐最近很忙，不是去外地出差，就是在公司加班。","pinyin":"","vn":"Dương Đồng Lạc gần đây rất bận, không đi công tác xa thì cũng tăng ca ở công ty."}]},{"title":"固定格式\"动词+一×是一×\"","explanation_vn":"Cấu trúc cố định \"động từ + 一X是一X\" nhấn mạnh việc cố gắng làm được bao nhiêu trong điều kiện nhất định thì làm bấy nhiêu, không ép buộc phải hoàn thành ngay.","examples":[{"cn":"咱们先做做功课，提前了解下，能懂一点儿是一点儿。","pinyin":"","vn":"Chúng ta cứ chuẩn bị trước, tìm hiểu trước đã, hiểu được chút nào thì tốt chút đó."},{"cn":"虽然这本书很厚，但是我还是要看，看一页是一页，最后一定能看完。","pinyin":"","vn":"Dù cuốn sách này rất dày, nhưng tôi vẫn muốn đọc, đọc được trang nào thì tốt trang đó, cuối cùng chắc chắn sẽ đọc xong."},{"cn":"你能多吃一点儿是一点儿，这样身体才能好起来。","pinyin":"","vn":"Bạn ăn được thêm chút nào thì tốt chút đó, như vậy cơ thể mới khỏe lên được."}]},{"title":"\"把\"字句\"主语+把+宾语+动词+动量补语\"","explanation_vn":"\"主语+把+宾语+动词+动量补语\" là một dạng câu chữ \"把\", nhấn mạnh số lần hoặc tần suất của hành động tác động lên tân ngữ. \"Bổ ngữ động lượng\" là cấu trúc \"số từ + lượng từ động tác\", đứng sau động từ làm bổ ngữ.","examples":[{"cn":"因为李文他们提前把故事了解了一遍，所以差不多都看懂了。","pinyin":"","vn":"Vì Lý Văn và mọi người đã tìm hiểu trước câu chuyện một lượt, nên hầu như đều xem hiểu."},{"cn":"他把这个动作做了好几次，最后终于做对了。","pinyin":"","vn":"Anh ấy đã làm động tác này mấy lần, cuối cùng cũng làm đúng."},{"cn":"白家月又把这本书看了几遍，越看越喜欢。","pinyin":"","vn":"Bạch Gia Nguyệt lại đọc cuốn sách này thêm vài lần, càng đọc càng thích."}]},{"title":"\"把\"字句\"主语+把+宾语+动词+时量补语\"","explanation_vn":"\"主语+把+宾语+动词+时量补语\" là một dạng câu chữ \"把\", nhấn mạnh độ dài thời gian mà chủ ngữ thực hiện hành động tác động lên tân ngữ.","examples":[{"cn":"(我)到家后又把这本书看了两天。","pinyin":"","vn":"(Tôi) về nhà rồi lại đọc cuốn sách này mất hai ngày."},{"cn":"王老师把这个问题又讲了十分钟，大家才明白。","pinyin":"","vn":"Thầy Vương lại giảng vấn đề này thêm mười phút, mọi người mới hiểu."},{"cn":"陈天中把这个动作又练了一小时。","pinyin":"","vn":"Trần Thiên Trung lại luyện tập động tác này thêm một giờ."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"小雪，你们的话剧排好了吗？","pinyin":""},{"speaker":"刘小雪","cn":"差不多了，妈妈。艺术节周五下午开始，我内心还是有些紧张，有时候不是忘词，就是忘记做动作。","pinyin":""},{"speaker":"王一雪","cn":"没事，妈妈相信你一定可以。放松些，再自信些！","pinyin":""},{"speaker":"刘小雪","cn":"好的，我同学演少年歌手，他的歌声美极了。我演他的妈妈，不知道像不像呢。","pinyin":""},{"speaker":"王一雪","cn":"没问题的，努力做最好的自己就好。演出时，我和你爸都去给你加油。","pinyin":""},{"speaker":"刘小雪","cn":"好的，谢谢妈妈！","pinyin":""}],"translation_vn":"Vương Nhất Tuyết: Tiểu Tuyết, kịch nói của các con tập xong chưa?\nLưu Tiểu Tuyết: Gần xong rồi mẹ. Lễ hội nghệ thuật bắt đầu chiều thứ Sáu, trong lòng con vẫn còn hơi căng thẳng, lúc thì quên lời, lúc thì quên làm động tác.\nVương Nhất Tuyết: Không sao, mẹ tin con chắc chắn làm được. Thả lỏng hơn, tự tin hơn nữa!\nLưu Tiểu Tuyết: Vâng, bạn học của con đóng vai ca sĩ thiếu niên, giọng hát của bạn ấy hay vô cùng. Con đóng vai mẹ của bạn ấy, không biết có giống không.\nVương Nhất Tuyết: Không vấn đề gì, cố gắng làm tốt nhất bản thân là được. Lúc diễn, mẹ và bố sẽ đến cổ vũ cho con.\nLưu Tiểu Tuyết: Vâng, cảm ơn mẹ!","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"刘小雪为什么感到紧张？","q_vn":"Vì sao Lưu Tiểu Tuyết cảm thấy căng thẳng?","a_cn":"因为艺术节快到了，她有时候忘词，有时候忘记做动作，所以内心紧张。","a_vn":"Vì lễ hội nghệ thuật sắp đến, cô lúc quên lời, lúc quên làm động tác, nên trong lòng căng thẳng."},{"q_cn":"刘小雪在话剧里演什么角色？","q_vn":"Trong vở kịch, Lưu Tiểu Tuyết đóng vai gì?","a_cn":"她演少年歌手的妈妈。","a_vn":"Cô đóng vai người mẹ của ca sĩ thiếu niên."},{"q_cn":"演出当天，王一雪打算做什么？","q_vn":"Vào ngày biểu diễn, Vương Nhất Tuyết định làm gì?","a_cn":"她打算和丈夫一起去现场给刘小雪加油。","a_vn":"Bà định cùng chồng đến tận nơi cổ vũ cho Lưu Tiểu Tuyết."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"下周六晚上，我请大家去国家大剧院看京剧，怎么样？","pinyin":""},{"speaker":"安妮","cn":"好啊。我小时候在加拿大度假时，在宾馆的电视上看过一次，是梅兰芳等演员演的，演员们都非常棒，他们演唱得好听极了，给我留下的印象特别深。","pinyin":""},{"speaker":"李文","cn":"梅兰芳先生是中国著名京剧艺术家。咱们要看的这个京剧是青年演员们演的，要去看的观众也特别多。","pinyin":""},{"speaker":"陈天中","cn":"不知道我们能不能看懂。","pinyin":""},{"speaker":"白家月","cn":"咱们先做做功课，提前了解下，能懂一点儿是一点儿。","pinyin":""},{"speaker":"陈天中","cn":"对，我先去网上查资料，查完后也转发给你们。","pinyin":""},{"speaker":"安妮","cn":"谢谢天中！","pinyin":""},{"speaker":"李文","cn":"那我就在网上订票了，到时候咱们在大剧院入口见。","pinyin":""}],"translation_vn":"Lý Văn: Tối thứ Bảy tuần sau, tôi mời mọi người đi xem Kinh kịch ở Nhà hát Quốc gia, được không?\nAnni: Được đấy. Hồi nhỏ khi đi nghỉ ở Canada, tôi đã xem một lần trên truyền hình ở khách sạn, do Mai Lan Phương và các diễn viên khác diễn, các diễn viên đều rất tuyệt, họ hát hay cực kỳ, để lại cho tôi ấn tượng rất sâu.\nLý Văn: Ông Mai Lan Phương là nghệ sĩ Kinh kịch nổi tiếng của Trung Quốc. Vở Kinh kịch chúng ta sẽ xem lần này là do các diễn viên trẻ diễn, lượng khán giả đến xem cũng rất nhiều.\nTrần Thiên Trung: Không biết chúng ta có xem hiểu được không.\nBạch Gia Nguyệt: Chúng ta cứ chuẩn bị trước, tìm hiểu trước đã, hiểu được chút nào thì tốt chút đó.\nTrần Thiên Trung: Đúng vậy, tôi sẽ lên mạng tra tài liệu trước, tra xong sẽ chuyển cho các bạn.\nAnni: Cảm ơn Thiên Trung!\nLý Văn: Vậy tôi đặt vé trên mạng, lúc đó chúng ta gặp nhau ở lối vào nhà hát.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"安妮小时候在哪里看过京剧？","q_vn":"Hồi nhỏ Anni đã xem Kinh kịch ở đâu?","a_cn":"她在加拿大度假时，在宾馆的电视上看过一次京剧。","a_vn":"Khi đi nghỉ ở Canada, cô đã xem Kinh kịch một lần trên truyền hình khách sạn."},{"q_cn":"为了看懂京剧，他们打算怎么做？","q_vn":"Để xem hiểu Kinh kịch, họ định làm gì?","a_cn":"他们打算先做功课，提前了解剧情，陈天中还去网上查资料并转发给大家。","a_vn":"Họ định chuẩn bị trước, tìm hiểu nội dung, Trần Thiên Trung còn lên mạng tra tài liệu và chuyển cho mọi người."},{"q_cn":"他们约好在哪里见面？","q_vn":"Họ hẹn gặp nhau ở đâu?","a_cn":"他们约好在国家大剧院的入口见面。","a_vn":"Họ hẹn gặp nhau ở lối vào Nhà hát Quốc gia."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"周六晚上，李文等四人来到国家大剧院观看京剧演出。入座后，李文指着节目表说：\"这些演员很专业，功夫很深，在京剧比赛中获得很多奖，有的还是国家、国际大奖。我特别期待这场演出。\"","pinyin":""},{"speaker":"","cn":"演出开始后，他们看到演员们做的动作很难，但是做得都特别好，观众们不断鼓掌。因为李文他们提前把故事了解了一遍，所以差不多都看懂了。演出结束后，演员们邀请观众和他们一起庆祝演出成功。","pinyin":""},{"speaker":"","cn":"回来的路上，大家特别激动，觉得京剧很有意思，演员演得很精彩。李文点头说：\"是啊，以后咱们还来看。\"","pinyin":""}],"translation_vn":"Tối thứ Bảy, Lý Văn cùng ba người bạn đến Nhà hát Quốc gia xem biểu diễn Kinh kịch. Sau khi vào chỗ ngồi, Lý Văn chỉ vào bảng chương trình nói: \"Những diễn viên này rất chuyên nghiệp, công phu rất sâu, đã đạt nhiều giải trong các cuộc thi Kinh kịch, có người còn đạt giải cấp quốc gia, quốc tế. Tôi rất mong đợi buổi diễn này.\"\nSau khi buổi diễn bắt đầu, họ thấy các động tác của diễn viên rất khó nhưng đều làm rất tốt, khán giả vỗ tay không ngừng. Vì Lý Văn và mọi người đã tìm hiểu trước câu chuyện nên hầu như đều xem hiểu. Sau khi buổi diễn kết thúc, các diễn viên mời khán giả cùng ăn mừng thành công của buổi diễn.\nTrên đường về, mọi người đều rất xúc động, cảm thấy Kinh kịch rất thú vị, diễn viên diễn rất đặc sắc. Lý Văn gật đầu nói: \"Đúng vậy, sau này chúng ta sẽ còn đến xem nữa.\"","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"为什么李文特别期待这场演出？","q_vn":"Vì sao Lý Văn đặc biệt mong đợi buổi diễn này?","a_cn":"因为这些演员很专业，功夫很深，获得过很多国家、国际大奖。","a_vn":"Vì các diễn viên rất chuyên nghiệp, công phu sâu, đã đạt nhiều giải thưởng quốc gia, quốc tế."},{"q_cn":"他们为什么差不多都看懂了演出？","q_vn":"Vì sao họ gần như xem hiểu được buổi diễn?","a_cn":"因为他们提前把故事了解了一遍。","a_vn":"Vì họ đã tìm hiểu trước câu chuyện một lượt."},{"q_cn":"演出结束后发生了什么？","q_vn":"Sau khi buổi diễn kết thúc đã xảy ra điều gì?","a_cn":"演员们邀请观众一起庆祝演出成功，大家都很激动。","a_vn":"Các diễn viên mời khán giả cùng ăn mừng thành công của buổi diễn, mọi người đều rất xúc động."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"马可·波罗是意大利旅行家，在1275年和家人来到中国，在中国大约生活了17年，最后完成了一部作品——《马可·波罗游记》。在这部影响很大的作品中，作者向世界介绍了13世纪时的中国。","pinyin":""},{"speaker":"","cn":"作为读者，读完这部作品后，我也很想成为作家，更想来中国看看。来到中国后，我发现现在的中国和书里的中国已有很大不同。","pinyin":""},{"speaker":"","cn":"前两天，我去书店看到了中文版的《马可·波罗游记》，马上买了一本，到家后又把这本书看了两天。看完后，我决定把自己来中国后写的文章、日记等全部整理出来，完成一部文字加图片的作品——《东方旅行日记》，再次把中国介绍给世界。同时我也想继续学习中文和中国文化，报考中国语言文学专业的研究生。","pinyin":""}],"translation_vn":"Marco Polo là nhà du hành người Ý, năm 1275 ông cùng gia đình đến Trung Quốc, sống ở Trung Quốc khoảng 17 năm, cuối cùng hoàn thành một tác phẩm - \"Marco Polo du ký\". Trong tác phẩm có ảnh hưởng rất lớn này, tác giả đã giới thiệu với thế giới về Trung Quốc thế kỷ 13.\nLà một độc giả, sau khi đọc xong tác phẩm này, tôi cũng rất muốn trở thành nhà văn, càng muốn đến Trung Quốc xem thử. Sau khi đến Trung Quốc, tôi phát hiện Trung Quốc hiện nay đã rất khác so với Trung Quốc trong sách.\nHai ngày trước, tôi đến nhà sách thấy bản tiếng Trung của \"Marco Polo du ký\", liền mua ngay một cuốn, về nhà lại đọc cuốn sách này mất hai ngày. Đọc xong, tôi quyết định tập hợp lại toàn bộ những bài viết, nhật ký... mà mình viết sau khi đến Trung Quốc, hoàn thành một tác phẩm gồm chữ viết và hình ảnh - \"Nhật ký du hành phương Đông\", một lần nữa giới thiệu Trung Quốc với thế giới. Đồng thời tôi cũng muốn tiếp tục học tiếng Trung và văn hóa Trung Quốc, đăng ký thi nghiên cứu sinh chuyên ngành ngôn ngữ văn học Trung Quốc.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"马可·波罗写了一部什么作品？","q_vn":"Marco Polo đã viết tác phẩm nào?","a_cn":"他写了《马可·波罗游记》，向世界介绍了13世纪时的中国。","a_vn":"Ông viết \"Marco Polo du ký\", giới thiệu với thế giới về Trung Quốc thế kỷ 13."},{"q_cn":"作者来中国后发现了什么？","q_vn":"Sau khi đến Trung Quốc, tác giả phát hiện điều gì?","a_cn":"她发现现在的中国和书里的中国已有很大不同。","a_vn":"Cô phát hiện Trung Quốc hiện nay đã khác rất nhiều so với trong sách."},{"q_cn":"作者打算完成一部什么样的作品？","q_vn":"Tác giả định hoàn thành một tác phẩm như thế nào?","a_cn":"她打算把自己写的文章、日记整理出来，完成一部文字加图片的作品《东方旅行日记》。","a_vn":"Cô định tập hợp các bài viết, nhật ký của mình, hoàn thành tác phẩm gồm chữ và hình ảnh \"Nhật ký du hành phương Đông\"."}]}]},{"id":20,"title_cn":"看不完也读不完","title_pinyin":"","title_vn":"Xem không hết, đọc cũng không hết","goals":["Có thể nghe hiểu và trao đổi về các chủ đề đọc sách và du lịch.","Có thể trình bày bằng lời nói hoặc văn bản về đặc điểm của một địa điểm du lịch.","Hiểu biết cách du lịch tại Trung Quốc, trải nghiệm văn hóa Trung Quốc."],"vocab":[{"hanzi":"堵车","pinyin":"dǔchē","pos":"dgt.","vn":"tắc đường","examples":[{"cn":"路上堵车，我们差点儿晚了。","pinyin":"Lùshàng dǔchē, wǒmen chàdiǎnr wǎn le.","vn":"Trên đường tắc xe, chúng tôi suýt bị muộn."},{"cn":"早上下班高峰堵车很严重。","pinyin":"Zǎoshang xiàbān gāofēng dǔchē hěn yánzhòng.","vn":"Giờ cao điểm sáng tắc đường rất nghiêm trọng."},{"cn":"因为堵车，他迟到了半小时。","pinyin":"Yīnwèi dǔchē, tā chídàole bàn xiǎoshí.","vn":"Vì tắc đường, anh ấy đến muộn nửa giờ."}]},{"hanzi":"乘","pinyin":"chéng","pos":"dgt.","vn":"đi, đáp (tàu xe)","examples":[{"cn":"我们乘动车去杭州。","pinyin":"Wǒmen chéng dòngchē qù Hángzhōu.","vn":"Chúng tôi đi tàu cao tốc đến Hàng Châu."},{"cn":"他乘飞机去了北京。","pinyin":"Tā chéng fēijī qùle Běijīng.","vn":"Anh ấy đi máy bay đến Bắc Kinh."},{"cn":"晚了就改乘下一趟车。","pinyin":"Wǎnle jiù gǎi chéng xià yí tàng chē.","vn":"Muộn rồi thì đổi sang chuyến tàu sau."}]},{"hanzi":"难道","pinyin":"nándào","pos":"phó.","vn":"chẳng lẽ, lẽ nào","examples":[{"cn":"难道你不认识我了吗？","pinyin":"Nándào nǐ bú rènshi wǒ le ma?","vn":"Chẳng lẽ anh không nhận ra tôi sao?"},{"cn":"他没来，难道有什么事？","pinyin":"Tā méi lái, nándào yǒu shénme shì?","vn":"Anh ấy không đến, chẳng lẽ có việc gì chăng?"},{"cn":"难道我们应该放弃吗？","pinyin":"Nándào wǒmen yīnggāi fàngqì ma?","vn":"Chẳng lẽ chúng ta nên bỏ cuộc sao?"}]},{"hanzi":"无","pinyin":"wú","pos":"dgt.","vn":"không có","examples":[{"cn":"他买的是无座票。","pinyin":"Tā mǎi de shì wú zuò piào.","vn":"Vé anh ấy mua là vé không có chỗ ngồi."},{"cn":"这件事无关紧要。","pinyin":"Zhè jiàn shì wú guān jǐnyào.","vn":"Việc này không quan trọng."},{"cn":"他无话可说。","pinyin":"Tā wú huà kě shuō.","vn":"Anh ấy không có gì để nói."}]},{"hanzi":"动车","pinyin":"dòngchē","pos":"dt.","vn":"tàu cao tốc (động xa)","examples":[{"cn":"我们坐动车去苏州。","pinyin":"Wǒmen zuò dòngchē qù Sūzhōu.","vn":"Chúng tôi đi tàu cao tốc đến Tô Châu."},{"cn":"动车比大巴快多了。","pinyin":"Dòngchē bǐ dàbā kuài duōle.","vn":"Tàu cao tốc nhanh hơn xe khách nhiều."},{"cn":"动车票要提前订。","pinyin":"Dòngchē piào yào tíqián dìng.","vn":"Vé tàu cao tốc phải đặt trước."}]},{"hanzi":"车速","pinyin":"chēsù","pos":"dt.","vn":"tốc độ xe","examples":[{"cn":"这辆车的车速很快。","pinyin":"Zhè liàng chē de chēsù hěn kuài.","vn":"Tốc độ của chiếc xe này rất nhanh."},{"cn":"高速路上要控制车速。","pinyin":"Gāosù lù shàng yào kòngzhì chēsù.","vn":"Trên đường cao tốc phải kiểm soát tốc độ xe."},{"cn":"动车的车速比普通火车快。","pinyin":"Dòngchē de chēsù bǐ pǔtōng huǒchē kuài.","vn":"Tốc độ tàu cao tốc nhanh hơn tàu thường."}]},{"hanzi":"列","pinyin":"liè","pos":"lượng.","vn":"chuyến (tàu)","examples":[{"cn":"这列火车马上要开了。","pinyin":"Zhè liè huǒchē mǎshàng yào kāi le.","vn":"Chuyến tàu này sắp khởi hành."},{"cn":"那列动车晚点了。","pinyin":"Nà liè dòngchē wǎndiǎn le.","vn":"Chuyến tàu cao tốc đó bị trễ giờ."},{"cn":"下一列车十分钟后到。","pinyin":"Xià yí liè chē shí fēnzhōng hòu dào.","vn":"Chuyến tàu tiếp theo mười phút nữa sẽ đến."}]},{"hanzi":"晚餐","pinyin":"wǎncān","pos":"dt.","vn":"bữa tối","examples":[{"cn":"我们在车上吃晚餐。","pinyin":"Wǒmen zài chē shàng chī wǎncān.","vn":"Chúng tôi ăn tối trên tàu."},{"cn":"今天的晚餐很丰盛。","pinyin":"Jīntiān de wǎncān hěn fēngshèng.","vn":"Bữa tối hôm nay rất thịnh soạn."},{"cn":"我们约好一起吃晚餐。","pinyin":"Wǒmen yuē hǎo yìqǐ chī wǎncān.","vn":"Chúng tôi hẹn nhau cùng ăn tối."}]},{"hanzi":"夜","pinyin":"yè","pos":"dt./lượng.","vn":"đêm","examples":[{"cn":"夜里的西湖更美。","pinyin":"Yèlǐ de Xī Hú gèng měi.","vn":"Tây Hồ về đêm càng đẹp hơn."},{"cn":"我们在那里住了三夜。","pinyin":"Wǒmen zài nàlǐ zhùle sān yè.","vn":"Chúng tôi đã nghỉ ở đó ba đêm."},{"cn":"昨夜下了一场雨。","pinyin":"Zuóyè xiàle yì chǎng yǔ.","vn":"Đêm qua có một trận mưa."}]},{"hanzi":"大巴","pinyin":"dàbā","pos":"dt.","vn":"xe khách lớn","examples":[{"cn":"我们坐大巴去苏州。","pinyin":"Wǒmen zuò dàbā qù Sūzhōu.","vn":"Chúng tôi đi xe khách đến Tô Châu."},{"cn":"大巴车上人很多。","pinyin":"Dàbā chē shàng rén hěn duō.","vn":"Trên xe khách có rất nhiều người."},{"cn":"大巴票比动车票便宜。","pinyin":"Dàbā piào bǐ dòngchē piào piányi.","vn":"Vé xe khách rẻ hơn vé tàu cao tốc."}]},{"hanzi":"安检","pinyin":"ānjiǎn","pos":"dgt.","vn":"kiểm tra an ninh","examples":[{"cn":"我们安检完就去登机口。","pinyin":"Wǒmen ānjiǎn wán jiù qù dēngjī kǒu.","vn":"Chúng tôi kiểm tra an ninh xong là ra cổng lên máy bay."},{"cn":"机场安检很严格。","pinyin":"Jīchǎng ānjiǎn hěn yángé.","vn":"Kiểm tra an ninh ở sân bay rất nghiêm ngặt."},{"cn":"排队安检用了很长时间。","pinyin":"Páiduì ānjiǎn yòngle hěn cháng shíjiān.","vn":"Xếp hàng kiểm tra an ninh mất rất nhiều thời gian."}]},{"hanzi":"登机","pinyin":"dēngjī","pos":"dgt.","vn":"lên máy bay","examples":[{"cn":"现在开始登机了。","pinyin":"Xiànzài kāishǐ dēngjī le.","vn":"Bây giờ bắt đầu lên máy bay rồi."},{"cn":"请大家拿好登机牌登机。","pinyin":"Qǐng dàjiā náhǎo dēngjīpái dēngjī.","vn":"Xin mọi người cầm sẵn thẻ lên máy bay để lên máy bay."},{"cn":"我们还有半小时就登机了。","pinyin":"Wǒmen háiyǒu bàn xiǎoshí jiù dēngjī le.","vn":"Chúng tôi còn nửa giờ nữa là lên máy bay."}]},{"hanzi":"小说","pinyin":"xiǎoshuō","pos":"dt.","vn":"tiểu thuyết","examples":[{"cn":"我在读一本小说。","pinyin":"Wǒ zài dú yì běn xiǎoshuō.","vn":"Tôi đang đọc một cuốn tiểu thuyết."},{"cn":"这本小说很有名。","pinyin":"Zhè běn xiǎoshuō hěn yǒumíng.","vn":"Cuốn tiểu thuyết này rất nổi tiếng."},{"cn":"他写了很多小说。","pinyin":"Tā xiěle hěnduō xiǎoshuō.","vn":"Ông ấy đã viết rất nhiều tiểu thuyết."}]},{"hanzi":"航班","pinyin":"hángbān","pos":"dt.","vn":"chuyến bay","examples":[{"cn":"我们的航班几点起飞？","pinyin":"Wǒmen de hángbān jǐ diǎn qǐfēi?","vn":"Chuyến bay của chúng ta mấy giờ cất cánh?"},{"cn":"航班延误了两个小时。","pinyin":"Hángbān yánwùle liǎng gè xiǎoshí.","vn":"Chuyến bay bị trễ hai giờ."},{"cn":"这个航班直飞西安。","pinyin":"Zhège hángbān zhífēi Xī'ān.","vn":"Chuyến bay này bay thẳng đến Tây An."}]},{"hanzi":"值机","pinyin":"zhíjī","pos":"dgt.","vn":"làm thủ tục check-in","examples":[{"cn":"值机员在叫大家登机。","pinyin":"Zhíjīyuán zài jiào dàjiā dēngjī.","vn":"Nhân viên check-in đang gọi mọi người lên máy bay."},{"cn":"我们先去值机柜台办手续。","pinyin":"Wǒmen xiān qù zhíjī guìtái bàn shǒuxù.","vn":"Chúng tôi đi đến quầy check-in làm thủ tục trước."},{"cn":"网上值机很方便。","pinyin":"Wǎngshàng zhíjī hěn fāngbiàn.","vn":"Check-in online rất thuận tiện."}]},{"hanzi":"旅客","pinyin":"lǚkè","pos":"dt.","vn":"hành khách, du khách","examples":[{"cn":"去西安的旅客请登机。","pinyin":"Qù Xī'ān de lǚkè qǐng dēngjī.","vn":"Hành khách đi Tây An xin lên máy bay."},{"cn":"机场里有很多旅客。","pinyin":"Jīchǎng lǐ yǒu hěnduō lǚkè.","vn":"Trong sân bay có rất nhiều hành khách."},{"cn":"旅客们排队等候登机。","pinyin":"Lǚkèmen páiduì děnghòu dēngjī.","vn":"Các hành khách xếp hàng chờ lên máy bay."}]},{"hanzi":"牌","pinyin":"pái","pos":"dt.","vn":"thẻ, bảng","examples":[{"cn":"请拿好登机牌。","pinyin":"Qǐng náhǎo dēngjīpái.","vn":"Xin cầm sẵn thẻ lên máy bay."},{"cn":"门口有个指示牌。","pinyin":"Ménkǒu yǒu gè zhǐshìpái.","vn":"Ở cửa có một tấm bảng chỉ dẫn."},{"cn":"他挂了一个牌子。","pinyin":"Tā guàle yí gè páizi.","vn":"Anh ấy treo một cái bảng."}]},{"hanzi":"靠","pinyin":"kào","pos":"dgt.","vn":"dựa vào, kề sát","examples":[{"cn":"我的座位靠窗户。","pinyin":"Wǒ de zuòwèi kào chuānghu.","vn":"Chỗ ngồi của tôi ở sát cửa sổ."},{"cn":"他靠在椅子上睡着了。","pinyin":"Tā kào zài yǐzi shàng shuìzháo le.","vn":"Anh ấy dựa vào ghế rồi ngủ."},{"cn":"这家酒店靠近西湖。","pinyin":"Zhè jiā jiǔdiàn kàojìn Xī Hú.","vn":"Khách sạn này gần Tây Hồ."}]},{"hanzi":"窗户","pinyin":"chuānghu","pos":"dt.","vn":"cửa sổ","examples":[{"cn":"我喜欢靠窗户的座位。","pinyin":"Wǒ xǐhuan kào chuānghu de zuòwèi.","vn":"Tôi thích chỗ ngồi cạnh cửa sổ."},{"cn":"请把窗户打开。","pinyin":"Qǐng bǎ chuānghu dǎkāi.","vn":"Xin hãy mở cửa sổ ra."},{"cn":"窗户外面是美丽的风景。","pinyin":"Chuānghu wàimiàn shì měilì de fēngjǐng.","vn":"Bên ngoài cửa sổ là cảnh đẹp."}]},{"hanzi":"转机","pinyin":"zhuǎnjī","pos":"dgt.","vn":"chuyển chuyến bay (transit)","examples":[{"cn":"我们要在西安转机。","pinyin":"Wǒmen yào zài Xī'ān zhuǎnjī.","vn":"Chúng tôi phải chuyển chuyến bay ở Tây An."},{"cn":"转机比直飞便宜一些。","pinyin":"Zhuǎnjī bǐ zhífēi piányi yìxiē.","vn":"Chuyến bay transit rẻ hơn một chút so với bay thẳng."},{"cn":"转机时间只有一个小时。","pinyin":"Zhuǎnjī shíjiān zhǐyǒu yí gè xiǎoshí.","vn":"Thời gian transit chỉ có một giờ."}]},{"hanzi":"从中","pinyin":"cóngzhōng","pos":"phó.","vn":"từ trong đó","examples":[{"cn":"他们常去旅行，从中了解中国。","pinyin":"Tāmen cháng qù lǜxíng, cóngzhōng liǎojiě Zhōngguó.","vn":"Họ thường đi du lịch, từ đó hiểu thêm về Trung Quốc."},{"cn":"我从中学到了很多东西。","pinyin":"Wǒ cóngzhōng xuédàole hěnduō dōngxi.","vn":"Tôi đã học được nhiều điều từ trong đó."},{"cn":"从中可以看出他很认真。","pinyin":"Cóngzhōng kěyǐ kànchū tā hěn rènzhēn.","vn":"Từ đó có thể thấy anh ấy rất nghiêm túc."}]},{"hanzi":"总结","pinyin":"zǒngjié","pos":"dgt.","vn":"tổng kết","examples":[{"cn":"他们总结了几点旅行经验。","pinyin":"Tāmen zǒngjiéle jǐ diǎn lǜxíng jīngyàn.","vn":"Họ đã tổng kết vài kinh nghiệm du lịch."},{"cn":"老师让我们总结这节课的内容。","pinyin":"Lǎoshī ràng wǒmen zǒngjié zhè jié kè de nèiróng.","vn":"Thầy giáo yêu cầu chúng tôi tổng kết nội dung bài học."},{"cn":"我来总结一下今天的安排。","pinyin":"Wǒ lái zǒngjié yíxià jīntiān de ānpái.","vn":"Để tôi tổng kết lại kế hoạch hôm nay."}]},{"hanzi":"道路","pinyin":"dàolù","pos":"dt.","vn":"đường đi, con đường","examples":[{"cn":"这条道路很宽。","pinyin":"Zhè tiáo dàolù hěn kuān.","vn":"Con đường này rất rộng."},{"cn":"要了解目的地的道路交通。","pinyin":"Yào liǎojiě mùdìdì de dàolù jiāotōng.","vn":"Phải tìm hiểu giao thông đường bộ của điểm đến."},{"cn":"山上的道路不好走。","pinyin":"Shān shàng de dàolù bù hǎo zǒu.","vn":"Đường trên núi không dễ đi."}]},{"hanzi":"特点","pinyin":"tèdiǎn","pos":"dt.","vn":"đặc điểm","examples":[{"cn":"这个地方有什么特点？","pinyin":"Zhège dìfāng yǒu shénme tèdiǎn?","vn":"Nơi này có đặc điểm gì?"},{"cn":"每个城市都有自己的特点。","pinyin":"Měi gè chéngshì dōu yǒu zìjǐ de tèdiǎn.","vn":"Mỗi thành phố đều có đặc điểm riêng."},{"cn":"了解天气特点很重要。","pinyin":"Liǎojiě tiānqì tèdiǎn hěn zhòngyào.","vn":"Tìm hiểu đặc điểm thời tiết rất quan trọng."}]},{"hanzi":"所有","pinyin":"suǒyǒu","pos":"tt.","vn":"tất cả, toàn bộ","examples":[{"cn":"所有人都同意这个计划。","pinyin":"Suǒyǒu rén dōu tóngyì zhège jìhuà.","vn":"Tất cả mọi người đều đồng ý kế hoạch này."},{"cn":"这是我所有的钱。","pinyin":"Zhè shì wǒ suǒyǒu de qián.","vn":"Đây là tất cả số tiền của tôi."},{"cn":"所有问题都解决了。","pinyin":"Suǒyǒu wèntí dōu jiějué le.","vn":"Tất cả vấn đề đều đã được giải quyết."}]},{"hanzi":"意见","pinyin":"yìjiàn","pos":"dt.","vn":"ý kiến (thường chỉ sự bất đồng)","examples":[{"cn":"大家对这个计划没有意见。","pinyin":"Dàjiā duì zhège jìhuà méiyǒu yìjiàn.","vn":"Mọi người không có ý kiến gì về kế hoạch này."},{"cn":"他对我的安排有意见。","pinyin":"Tā duì wǒ de ānpái yǒu yìjiàn.","vn":"Anh ấy có ý kiến về cách sắp xếp của tôi."},{"cn":"请大家提提意见。","pinyin":"Qǐng dàjiā títi yìjiàn.","vn":"Xin mọi người đóng góp ý kiến."}]},{"hanzi":"细","pinyin":"xì","pos":"tt.","vn":"tỉ mỉ, nhỏ, mỏng","examples":[{"cn":"准备越细，烦恼越少。","pinyin":"Zhǔnbèi yuè xì, fánnǎo yuè shǎo.","vn":"Chuẩn bị càng kỹ, phiền toái càng ít."},{"cn":"他做事很细心。","pinyin":"Tā zuòshì hěn xìxīn.","vn":"Anh ấy làm việc rất cẩn thận."},{"cn":"这条线很细。","pinyin":"Zhè tiáo xiàn hěn xì.","vn":"Sợi dây này rất mỏng."}]},{"hanzi":"烦恼","pinyin":"fánnǎo","pos":"tt.","vn":"phiền não, lo lắng","examples":[{"cn":"他最近有点儿烦恼。","pinyin":"Tā zuìjìn yǒudiǎnr fánnǎo.","vn":"Gần đây anh ấy có chút phiền não."},{"cn":"不要为小事烦恼。","pinyin":"Bùyào wèi xiǎoshì fánnǎo.","vn":"Đừng phiền lòng vì những việc nhỏ."},{"cn":"准备充分可以减少烦恼。","pinyin":"Zhǔnbèi chōngfèn kěyǐ jiǎnshǎo fánnǎo.","vn":"Chuẩn bị đầy đủ có thể giảm bớt phiền não."}]},{"hanzi":"百分之","pinyin":"bǎifēnzhī","pos":"dt.","vn":"phần trăm","examples":[{"cn":"机票便宜了百分之四十。","pinyin":"Jīpiào piányile bǎifēnzhī sìshí.","vn":"Vé máy bay rẻ hơn bốn mươi phần trăm."},{"cn":"百分之九十的学生都通过了考试。","pinyin":"Bǎifēnzhī jiǔshí de xuésheng dōu tōngguòle kǎoshì.","vn":"Chín mươi phần trăm học sinh đã qua kỳ thi."},{"cn":"价格上涨了百分之十。","pinyin":"Jiàgé shàngzhǎngle bǎifēnzhī shí.","vn":"Giá đã tăng mười phần trăm."}]},{"hanzi":"节省","pinyin":"jiéshěng","pos":"dgt.","vn":"tiết kiệm","examples":[{"cn":"转机可以节省一些钱。","pinyin":"Zhuǎnjī kěyǐ jiéshěng yìxiē qián.","vn":"Transit có thể tiết kiệm một ít tiền."},{"cn":"我们要节省时间。","pinyin":"Wǒmen yào jiéshěng shíjiān.","vn":"Chúng ta phải tiết kiệm thời gian."},{"cn":"他很节省，很少乱花钱。","pinyin":"Tā hěn jiéshěng, hěn shǎo luàn huā qián.","vn":"Anh ấy rất tiết kiệm, ít khi tiêu tiền lung tung."}]},{"hanzi":"当","pinyin":"dàng","pos":"dgt.","vn":"coi như, xem như","examples":[{"cn":"把节省的钱当成大红包。","pinyin":"Bǎ jiéshěng de qián dàngchéng dà hóngbāo.","vn":"Coi số tiền tiết kiệm được như một bao lì xì lớn."},{"cn":"别把这件事当回事。","pinyin":"Bié bǎ zhè jiàn shì dàng huí shì.","vn":"Đừng xem việc này là chuyện lớn."},{"cn":"我把他当成好朋友。","pinyin":"Wǒ bǎ tā dàngchéng hǎo péngyou.","vn":"Tôi coi anh ấy như bạn tốt."}]},{"hanzi":"红包","pinyin":"hóngbāo","pos":"dt.","vn":"bao lì xì, tiền thưởng","examples":[{"cn":"过年的时候会收到红包。","pinyin":"Guònián de shíhou huì shōudào hóngbāo.","vn":"Vào ngày Tết sẽ nhận được bao lì xì."},{"cn":"公司给员工发了红包。","pinyin":"Gōngsī gěi yuángōng fāle hóngbāo.","vn":"Công ty đã phát bao lì xì cho nhân viên."},{"cn":"这笔钱就当是给自己的红包。","pinyin":"Zhè bǐ qián jiù dàng shì gěi zìjǐ de hóngbāo.","vn":"Số tiền này coi như là bao lì xì cho chính mình."}]},{"hanzi":"卷","pinyin":"juàn","pos":"lượng.","vn":"cuốn, quyển","examples":[{"cn":"读万卷书，行万里路。","pinyin":"Dú wàn juàn shū, xíng wàn lǐ lù.","vn":"Đọc vạn cuốn sách, đi vạn dặm đường."},{"cn":"这部书共有十卷。","pinyin":"Zhè bù shū gòng yǒu shí juàn.","vn":"Bộ sách này có tổng cộng mười cuốn."},{"cn":"他每年读很多卷书。","pinyin":"Tā měinián dú hěnduō juàn shū.","vn":"Mỗi năm anh ấy đọc rất nhiều cuốn sách."}]},{"hanzi":"里","pinyin":"lǐ","pos":"lượng.","vn":"lý (đơn vị đo chiều dài)","examples":[{"cn":"行万里路。","pinyin":"Xíng wàn lǐ lù.","vn":"Đi vạn dặm đường."},{"cn":"这里离城里有十里远。","pinyin":"Zhèlǐ lí chéng lǐ yǒu shí lǐ yuǎn.","vn":"Từ đây đến thành phố xa mười lý."},{"cn":"他走了几十里路。","pinyin":"Tā zǒule jǐshí lǐ lù.","vn":"Anh ấy đã đi mấy chục lý đường."}]},{"hanzi":"要是","pinyin":"yàoshi","pos":"liên.","vn":"nếu, nếu như","examples":[{"cn":"要是你同意，我们就出发。","pinyin":"Yàoshi nǐ tóngyì, wǒmen jiù chūfā.","vn":"Nếu bạn đồng ý, chúng ta sẽ xuất phát."},{"cn":"要是下雨，我们就不去了。","pinyin":"Yàoshi xiàyǔ, wǒmen jiù bú qù le.","vn":"Nếu trời mưa, chúng ta sẽ không đi nữa."},{"cn":"要是有时间，我想去旅行。","pinyin":"Yàoshi yǒu shíjiān, wǒ xiǎng qù lǜxíng.","vn":"Nếu có thời gian, tôi muốn đi du lịch."}]},{"hanzi":"少数","pinyin":"shǎoshù","pos":"dt.","vn":"số ít, thiểu số","examples":[{"cn":"只有少数人去过那里。","pinyin":"Zhǐyǒu shǎoshù rén qùguò nàlǐ.","vn":"Chỉ có một số ít người đã đến đó."},{"cn":"少数意见也要被尊重。","pinyin":"Shǎoshù yìjiàn yě yào bèi zūnzhòng.","vn":"Ý kiến thiểu số cũng cần được tôn trọng."},{"cn":"这是少数民族的传统节日。","pinyin":"Zhè shì shǎoshù mínzú de chuántǒng jiérì.","vn":"Đây là ngày lễ truyền thống của dân tộc thiểu số."}]},{"hanzi":"民族","pinyin":"mínzú","pos":"dt.","vn":"dân tộc","examples":[{"cn":"中国有五十六个民族。","pinyin":"Zhōngguó yǒu wǔshíliù gè mínzú.","vn":"Trung Quốc có năm mươi sáu dân tộc."},{"cn":"每个民族都有自己的文化。","pinyin":"Měi gè mínzú dōu yǒu zìjǐ de wénhuà.","vn":"Mỗi dân tộc đều có văn hóa riêng của mình."},{"cn":"他是少数民族。","pinyin":"Tā shì shǎoshù mínzú.","vn":"Anh ấy là người dân tộc thiểu số."}]},{"hanzi":"导游","pinyin":"dǎoyóu","pos":"dt./dgt.","vn":"hướng dẫn viên du lịch","examples":[{"cn":"导游向我们介绍了这里的历史。","pinyin":"Dǎoyóu xiàng wǒmen jièshàole zhèlǐ de lìshǐ.","vn":"Hướng dẫn viên đã giới thiệu cho chúng tôi lịch sử nơi này."},{"cn":"她是一名优秀的导游。","pinyin":"Tā shì yì míng yōuxiù de dǎoyóu.","vn":"Cô ấy là một hướng dẫn viên du lịch xuất sắc."},{"cn":"导游带我们参观了景点。","pinyin":"Dǎoyóu dài wǒmen cānguānle jǐngdiǎn.","vn":"Hướng dẫn viên đã đưa chúng tôi đi thăm các điểm du lịch."}]},{"hanzi":"解释","pinyin":"jiěshì","pos":"dgt.","vn":"giải thích","examples":[{"cn":"导游向他们解释了泼水节的意思。","pinyin":"Dǎoyóu xiàng tāmen jiěshìle Pōshuǐjié de yìsi.","vn":"Hướng dẫn viên giải thích cho họ ý nghĩa Lễ hội té nước."},{"cn":"请你解释一下这个词。","pinyin":"Qǐng nǐ jiěshì yíxià zhège cí.","vn":"Xin bạn giải thích giúp từ này."},{"cn":"他解释了自己迟到的原因。","pinyin":"Tā jiěshìle zìjǐ chídào de yuányīn.","vn":"Anh ấy đã giải thích lý do mình đến muộn."}]},{"hanzi":"泼","pinyin":"pō","pos":"dgt.","vn":"té, hắt (nước)","examples":[{"cn":"他们互相泼水庆祝节日。","pinyin":"Tāmen hùxiāng pōshuǐ qìngzhù jiérì.","vn":"Họ té nước lên nhau để chúc mừng lễ hội."},{"cn":"小心别把水泼在地上。","pinyin":"Xiǎoxīn bié bǎ shuǐ pō zài dì shàng.","vn":"Cẩn thận đừng làm đổ nước xuống đất."},{"cn":"泼水节上大家都很开心。","pinyin":"Pōshuǐjié shàng dàjiā dōu hěn kāixīn.","vn":"Trong Lễ hội té nước mọi người đều rất vui."}]},{"hanzi":"流利","pinyin":"liúlì","pos":"tt.","vn":"lưu loát, trôi chảy","examples":[{"cn":"他说中文很流利。","pinyin":"Tā shuō Zhōngwén hěn liúlì.","vn":"Anh ấy nói tiếng Trung rất lưu loát."},{"cn":"她能流利地对出下句。","pinyin":"Tā néng liúlì de duìchū xià jù.","vn":"Cô ấy có thể đối đáp câu sau một cách lưu loát."},{"cn":"经过练习，他的英语越来越流利。","pinyin":"Jīngguò liànxí, tā de Yīngyǔ yuè lái yuè liúlì.","vn":"Qua luyện tập, tiếng Anh của anh ấy ngày càng trôi chảy."}]}],"proper_nouns":[{"hanzi":"杭州","pinyin":"Hángzhōu","vn":"Hàng Châu"},{"hanzi":"西湖","pinyin":"Xī Hú","vn":"Tây Hồ"},{"hanzi":"苏州","pinyin":"Sūzhōu","vn":"Tô Châu"},{"hanzi":"苏州园林","pinyin":"Sūzhōu Yuánlín","vn":"Vườn cảnh Tô Châu"},{"hanzi":"老舍","pinyin":"Lǎoshě","vn":"Lão Xá"},{"hanzi":"唐诗","pinyin":"Tángshī","vn":"thơ Đường"},{"hanzi":"泼水节","pinyin":"Pōshuǐjié","vn":"Lễ hội té nước"},{"hanzi":"西双版纳","pinyin":"Xīshuāngbǎnnà","vn":"Tây Song Bản Nạp"},{"hanzi":"唐装","pinyin":"Tángzhuāng","vn":"trang phục nhà Đường"}],"grammar":[{"title":"语气副词\"难道\"","explanation_vn":"Phó từ ngữ khí \"难道\" có thể biểu thị ý suy đoán, cũng có thể dùng trong câu hỏi tu từ \"难道……吗？\" để nhấn mạnh ngữ khí khẳng định hoặc phủ định. Nếu là hình thức khẳng định thì biểu đạt ý phủ định; nếu là hình thức phủ định thì biểu đạt ý khẳng định.","examples":[{"cn":"难道你买的是无座票吗？","pinyin":"","vn":"Chẳng lẽ vé bạn mua là vé không có chỗ ngồi sao?"},{"cn":"车快开了他还没到，难道他不去了？","pinyin":"","vn":"Xe sắp chạy mà anh ấy vẫn chưa đến, chẳng lẽ anh ấy không đi nữa?"},{"cn":"难道我们不应该保护环境吗？","pinyin":"","vn":"Chẳng lẽ chúng ta không nên bảo vệ môi trường sao?"}]},{"title":"反问句：由疑问代词构成的反问句","explanation_vn":"Câu hỏi tu từ được cấu tạo từ các đại từ nghi vấn như \"谁、什么、怎么、哪里、为什么\"... có tác dụng nhấn mạnh ngữ khí. Nếu là hình thức khẳng định thì biểu đạt ý phủ định; nếu là hình thức phủ định thì biểu đạt ý khẳng định.","examples":[{"cn":"谁说不是呢？","pinyin":"","vn":"Ai nói không phải vậy chứ?"},{"cn":"这里离苏州这么近，我们为什么不去苏州玩玩呢？","pinyin":"","vn":"Ở đây cách Tô Châu gần vậy, tại sao chúng ta không đến Tô Châu chơi một chuyến?"},{"cn":"我们连手机都没有，怎么能查到这些信息啊？","pinyin":"","vn":"Chúng ta đến điện thoại cũng không có, làm sao mà tra được những thông tin này?"}]},{"title":"固定格式\"×就×（点儿）吧\"","explanation_vn":"Cấu trúc cố định \"X就X（点儿）吧\" biểu thị sự nhượng bộ, thỏa hiệp, nghĩa là tạm chấp nhận như vậy cũng được, không cần quá so đo. Thường dùng trong văn nói.","examples":[{"cn":"累就累点儿吧，花更少的钱去看更多的地方，很值得。","pinyin":"","vn":"Mệt thì mệt một chút vậy, bỏ ít tiền hơn để xem được nhiều nơi hơn, rất đáng."},{"cn":"我租的房子离公司有些远，我想，远就远点儿吧，至少房租便宜。","pinyin":"","vn":"Nhà tôi thuê cách công ty khá xa, tôi nghĩ, xa thì xa một chút vậy, ít nhất tiền thuê nhà rẻ."},{"cn":"慢就慢点儿吧，安全最重要。","pinyin":"","vn":"Chậm thì chậm một chút vậy, an toàn là quan trọng nhất."}]},{"title":"假设复句\"要是……，（就）……，否则……\"","explanation_vn":"\"要是……，（就）……，否则……\" là câu phức được cấu tạo từ giả thiết và kết quả. \"要是……，（就）……\" biểu thị trong điều kiện hoặc tình huống giả định nào đó, sẽ có hành động hoặc kết quả tương ứng; \"否则\" biểu thị nếu không như vậy thì sẽ dẫn đến kết quả khác.","examples":[{"cn":"你们要是想多了解中国，就不能只通过读书，还要多出门旅行，否则只能认识课本里的中国。","pinyin":"","vn":"Nếu các bạn muốn hiểu thêm về Trung Quốc, thì không thể chỉ thông qua đọc sách, mà còn phải đi du lịch nhiều hơn, nếu không thì chỉ có thể biết đến Trung Quốc trong sách giáo khoa."},{"cn":"要是出去的话，咱们就爬山，否则我哪儿都不去。","pinyin":"","vn":"Nếu đi ra ngoài thì chúng ta sẽ leo núi, nếu không thì tôi sẽ không đi đâu cả."},{"cn":"要是你同意的话，这个计划就通过，否则可能需要重新讨论。","pinyin":"","vn":"Nếu bạn đồng ý thì kế hoạch này sẽ được thông qua, nếu không thì có thể cần phải thảo luận lại."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"安妮","cn":"终于上车了，刚刚路上堵车，差点儿晚了。","pinyin":""},{"speaker":"白家月","cn":"没关系，晚了就改乘下一趟。天中，你坐哪儿？看你一直不坐下，我还在想，难道你买的是无座票吗？","pinyin":""},{"speaker":"陈天中","cn":"我的座位就在前边，我想先站这儿跟你们说说话。","pinyin":""},{"speaker":"安妮","cn":"动车车速也挺快啊！对了，这列车晚上七点多到杭州，咱们在车上吃晚餐，到站后就先去西湖吧，夜里的西湖更美。","pinyin":""},{"speaker":"陈天中","cn":"好！后天我们坐大巴去苏州，看苏州园林。","pinyin":""},{"speaker":"白家月","cn":"嗯。中国太大了！真是看也看不完啊。","pinyin":""}],"translation_vn":"Anni: Cuối cùng cũng lên tàu rồi, vừa nãy trên đường tắc xe, suýt nữa thì muộn.\nBạch Gia Nguyệt: Không sao, muộn thì đổi sang chuyến sau. Thiên Trung, bạn ngồi ở đâu? Thấy bạn cứ không ngồi xuống, tôi còn đang nghĩ, chẳng lẽ vé bạn mua là vé không có chỗ ngồi sao?\nTrần Thiên Trung: Chỗ của tôi ở phía trước, tôi muốn đứng đây nói chuyện với các bạn trước.\nAnni: Tốc độ tàu cao tốc cũng nhanh thật đấy! Đúng rồi, chuyến tàu này hơn bảy giờ tối sẽ đến Hàng Châu, chúng ta ăn tối trên tàu, đến nơi rồi thì đi Tây Hồ trước, Tây Hồ về đêm càng đẹp hơn.\nTrần Thiên Trung: Được! Ngày kia chúng ta đi xe khách đến Tô Châu, xem vườn cảnh Tô Châu.\nBạch Gia Nguyệt: Ừ. Trung Quốc rộng lớn quá! Xem thật không hết được.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"他们差点儿晚了的原因是什么？","q_vn":"Nguyên nhân họ suýt bị muộn là gì?","a_cn":"因为刚刚路上堵车了。","a_vn":"Vì vừa nãy trên đường bị tắc xe."},{"q_cn":"到站后他们打算先去哪里？为什么？","q_vn":"Sau khi đến nơi họ định đi đâu trước? Vì sao?","a_cn":"他们打算先去西湖，因为夜里的西湖更美。","a_vn":"Họ định đi Tây Hồ trước, vì Tây Hồ về đêm càng đẹp hơn."},{"q_cn":"后天他们计划做什么？","q_vn":"Ngày kia họ dự định làm gì?","a_cn":"他们计划坐大巴去苏州看苏州园林。","a_vn":"Họ dự định đi xe khách đến Tô Châu xem vườn cảnh Tô Châu."}]},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"安检完就等着登机了。你们在看什么？","pinyin":""},{"speaker":"白家月","cn":"我在读老舍的小说。","pinyin":""},{"speaker":"陈天中","cn":"我读的是一本中国历史书。","pinyin":""},{"speaker":"安妮","cn":"我读唐诗呢。几千年的中国文化，真是读也读不完。","pinyin":""},{"speaker":"李文","cn":"谁说不是呢？不过，现在咱们得去排队，航班的值机员在叫大家登机呢——","pinyin":""},{"speaker":"值机员","cn":"去西安的旅客开始登机，请拿好登机牌按顺序排队。","pinyin":""},{"speaker":"白家月","cn":"终于上来了，我的座位靠窗户。","pinyin":""},{"speaker":"安妮","cn":"我在最外边。这么多人，是不是跟咱们一样，都是去感受泼水节的啊？","pinyin":""},{"speaker":"李文","cn":"应该不是。很多人的目的地是西安，你别忘了，咱们是在西安转机，然后再飞西双版纳。","pinyin":""}],"translation_vn":"Lý Văn: Kiểm tra an ninh xong là chỉ chờ lên máy bay thôi. Các bạn đang xem gì vậy?\nBạch Gia Nguyệt: Tôi đang đọc tiểu thuyết của Lão Xá.\nTrần Thiên Trung: Tôi đang đọc một cuốn sách lịch sử Trung Quốc.\nAnni: Tôi đang đọc thơ Đường đây. Mấy nghìn năm văn hóa Trung Quốc, đọc thật không hết được.\nLý Văn: Ai nói không phải vậy chứ? Nhưng bây giờ chúng ta phải đi xếp hàng rồi, nhân viên check-in của chuyến bay đang gọi mọi người lên máy bay kìa—\n(Lời nhân viên check-in) Hành khách đi Tây An bắt đầu lên máy bay, xin cầm sẵn thẻ lên máy bay và xếp hàng theo thứ tự.\n……\nBạch Gia Nguyệt: Cuối cùng cũng lên được rồi, chỗ ngồi của tôi sát cửa sổ.\nAnni: Tôi ở ngoài cùng. Nhiều người thế này, có phải giống chúng ta, đều đi để trải nghiệm Lễ hội té nước không?\nLý Văn: Chắc là không phải đâu. Rất nhiều người có điểm đến là Tây An, bạn đừng quên, chúng ta là chuyển chuyến ở Tây An, sau đó mới bay tiếp đến Tây Song Bản Nạp.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"安妮在飞机上读什么？","q_vn":"Anni đọc gì trên máy bay?","a_cn":"她在读唐诗。","a_vn":"Cô ấy đang đọc thơ Đường."},{"q_cn":"他们这次旅行的最终目的地是哪里？","q_vn":"Điểm đến cuối cùng của chuyến đi này là đâu?","a_cn":"他们的最终目的地是西双版纳，在西安转机。","a_vn":"Điểm đến cuối cùng của họ là Tây Song Bản Nạp, họ chuyển chuyến ở Tây An."},{"q_cn":"安妮猜很多旅客是去做什么的？李文怎么回应？","q_vn":"Anni đoán nhiều hành khách đi để làm gì? Lý Văn trả lời thế nào?","a_cn":"安妮猜很多人是去感受泼水节的，但李文说应该不是，很多人的目的地是西安。","a_vn":"Anni đoán nhiều người đi để trải nghiệm Lễ hội té nước, nhưng Lý Văn nói chắc không phải, nhiều người có điểm đến là Tây An."}]},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"来中国留学后，白家月、安妮和陈天中常外出旅行，从中了解中国。他们还总结出几点旅行经验：","pinyin":""},{"speaker":"","cn":"第一，好计划是成功的一半。旅行前，要了解目的地天气、道路交通特点等，安排好每天的活动，保证所有人对计划都没意见。准备越细，烦恼越少。","pinyin":""},{"speaker":"","cn":"第二，节假日早点儿订机票、酒店和各种门票，否则很难订到。","pinyin":""},{"speaker":"","cn":"第三，转机会比直飞更便宜。此次去西双版纳，在西安转机，机票价格比直飞便宜了百分之四十多。虽然有些累，但累就累点儿吧，花更少的钱去看更多的地方，很值得，节省下来的钱就当是给自己的大\"红包\"了。","pinyin":""}],"translation_vn":"Sau khi đến Trung Quốc du học, Bạch Gia Nguyệt, Anni và Trần Thiên Trung thường đi du lịch, từ đó hiểu thêm về Trung Quốc. Họ còn tổng kết ra vài kinh nghiệm du lịch:\nThứ nhất, kế hoạch tốt là một nửa của thành công. Trước khi đi du lịch, phải tìm hiểu thời tiết, đặc điểm giao thông đường bộ của điểm đến, sắp xếp tốt hoạt động mỗi ngày, bảo đảm tất cả mọi người đều không có ý kiến gì về kế hoạch. Chuẩn bị càng kỹ, phiền toái càng ít.\nThứ hai, vào các ngày lễ nên đặt sớm vé máy bay, khách sạn và các loại vé tham quan, nếu không rất khó đặt được.\nThứ ba, chuyển chuyến bay sẽ rẻ hơn bay thẳng. Lần này đi Tây Song Bản Nạp, chuyển chuyến ở Tây An, giá vé máy bay rẻ hơn bay thẳng hơn bốn mươi phần trăm. Tuy có hơi mệt, nhưng mệt thì mệt một chút vậy, bỏ ít tiền hơn để xem được nhiều nơi hơn, rất đáng, số tiền tiết kiệm được coi như là bao \"lì xì\" lớn cho chính mình.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"文章提到的第一条旅行经验是什么？","q_vn":"Kinh nghiệm du lịch thứ nhất được nhắc đến trong bài là gì?","a_cn":"是好计划是成功的一半，旅行前要了解目的地情况并安排好活动。","a_vn":"Là kế hoạch tốt là một nửa của thành công, trước khi đi phải tìm hiểu tình hình điểm đến và sắp xếp tốt hoạt động."},{"q_cn":"为什么节假日要早点儿订票？","q_vn":"Vì sao vào ngày lễ cần đặt vé sớm?","a_cn":"因为节假日出行的人很多，不早点儿订很难订到机票、酒店和门票。","a_vn":"Vì vào ngày lễ nhiều người đi du lịch, không đặt sớm thì rất khó đặt được vé máy bay, khách sạn và vé tham quan."},{"q_cn":"他们这次去西双版纳为什么选择转机？","q_vn":"Vì sao lần này đi Tây Song Bản Nạp họ chọn chuyển chuyến bay?","a_cn":"因为转机比直飞便宜了百分之四十多，虽然累一点儿，但很值得。","a_vn":"Vì chuyển chuyến rẻ hơn bay thẳng hơn bốn mươi phần trăm, tuy có mệt một chút nhưng rất đáng."}]},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"王一飞常对她的学生说：\"读万卷书，行万里路。你们要是想多了解中国，就不能只通过读书，还要多出门旅行，否则只能认识课本里的中国。\"","pinyin":""},{"speaker":"","cn":"旅行，不仅能看到自然美景，还能近距离感受不同的历史文化。比如，白家月等人想了解少数民族泼水节，就去了西双版纳。泼水节上，导游向他们解释说，被泼的水越多，新的一年就会越健康、幸福。安妮喜欢唐诗，就来到了西安，在那里遇到身穿唐装的\"对诗人\"，对诗人说上句，游客就能流利地说出下句。安妮觉得在西安，唐诗活了。","pinyin":""},{"speaker":"","cn":"虽然已经去了很多地方，但是白家月他们觉得还不够。他们也认为，美丽中国，不只是在书中，更是在脚下。","pinyin":""}],"translation_vn":"Vương Nhất Phi thường nói với học sinh của mình: \"Đọc vạn cuốn sách, đi vạn dặm đường. Nếu các em muốn hiểu thêm về Trung Quốc, thì không thể chỉ thông qua đọc sách, mà còn phải đi du lịch nhiều hơn, nếu không thì chỉ có thể biết đến Trung Quốc trong sách giáo khoa.\"\nDu lịch không chỉ giúp nhìn thấy cảnh đẹp tự nhiên, mà còn có thể cảm nhận gần hơn các nền văn hóa lịch sử khác nhau. Ví dụ, Bạch Gia Nguyệt và mọi người muốn tìm hiểu Lễ hội té nước của dân tộc thiểu số, nên đã đến Tây Song Bản Nạp. Tại Lễ hội té nước, hướng dẫn viên giải thích với họ rằng, bị té càng nhiều nước thì năm mới sẽ càng khỏe mạnh, hạnh phúc. Anni thích thơ Đường, nên đã đến Tây An, ở đó gặp \"người đối thơ\" mặc trang phục nhà Đường, người đối thơ nói câu trước, du khách có thể đối lại câu sau một cách lưu loát. Anni cảm thấy ở Tây An, thơ Đường như sống lại.\nTuy đã đi nhiều nơi, nhưng Bạch Gia Nguyệt và mọi người vẫn cảm thấy chưa đủ. Họ cũng cho rằng, Trung Quốc tươi đẹp không chỉ ở trong sách, mà còn ở dưới chân mình.","audio_dialogue":"","audio_vocab":"","questions":[{"q_cn":"王一飞常对学生说什么道理？","q_vn":"Vương Nhất Phi thường nói với học sinh đạo lý gì?","a_cn":"她常说\"读万卷书，行万里路\"，要多出门旅行才能真正了解中国。","a_vn":"Bà thường nói \"đọc vạn cuốn sách, đi vạn dặm đường\", phải đi du lịch nhiều mới thực sự hiểu được Trung Quốc."},{"q_cn":"在泼水节上，导游解释了什么？","q_vn":"Tại Lễ hội té nước, hướng dẫn viên đã giải thích điều gì?","a_cn":"导游解释说，被泼的水越多，新的一年就会越健康、幸福。","a_vn":"Hướng dẫn viên giải thích rằng, bị té càng nhiều nước thì năm mới sẽ càng khỏe mạnh, hạnh phúc."},{"q_cn":"安妮在西安有什么特别的体验？","q_vn":"Anni có trải nghiệm đặc biệt gì ở Tây An?","a_cn":"她遇到了身穿唐装的对诗人，和对诗人对诗，觉得唐诗活了。","a_vn":"Cô gặp người đối thơ mặc trang phục nhà Đường, đối thơ cùng người đó, cảm thấy thơ Đường như sống lại."}]}]}],"pos_table":[{"pos_cn":"名词","pos_vn":"Danh từ","abbr":"dt."},{"pos_cn":"动词","pos_vn":"Động từ","abbr":"dgt."},{"pos_cn":"形容词","pos_vn":"Tính từ","abbr":"tt."},{"pos_cn":"代词","pos_vn":"Đại từ","abbr":"đt."},{"pos_cn":"副词","pos_vn":"Phó từ","abbr":"phó."},{"pos_cn":"介词","pos_vn":"Giới từ","abbr":"giới."},{"pos_cn":"连词","pos_vn":"Liên từ","abbr":"liên."},{"pos_cn":"助词","pos_vn":"Trợ từ","abbr":"trợ."},{"pos_cn":"数词","pos_vn":"Từ chỉ số đếm","abbr":"số."},{"pos_cn":"量词","pos_vn":"Lượng từ","abbr":"lượng."},{"pos_cn":"数量词","pos_vn":"Từ chỉ số lượng","abbr":"sl."},{"pos_cn":"叹词","pos_vn":"Từ cảm thán","abbr":"ct."},{"pos_cn":"拟声词","pos_vn":"Từ tượng thanh","abbr":"tượng."},{"pos_cn":"能愿动词","pos_vn":"Động từ năng nguyện","abbr":"đtnn."},{"pos_cn":"前缀","pos_vn":"Tiền tố","abbr":"ttố."},{"pos_cn":"后缀","pos_vn":"Hậu tố","abbr":"htố."}]};
